-- Source: database/functions/others/remove_image_records.sql
CREATE OR REPLACE FUNCTION public.remove_image_records(p_links text[])
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_row record; v_occasion bigint;
BEGIN
  IF COALESCE(array_length(p_links,1),0)=0 THEN RETURN; END IF;
  FOR v_row IN SELECT DISTINCT i.occasion,i.unit FROM public.images i
    WHERE i.link=ANY(p_links)
  LOOP
    IF v_row.occasion IS NOT NULL THEN
      IF NOT public.can_upload_occasion_media(v_row.occasion) THEN
        RAISE insufficient_privilege USING MESSAGE='occasion editor required';
      END IF;
    ELSIF v_row.unit IS NOT NULL AND NOT public.can_upload_unit_media(v_row.unit) THEN
      RAISE insufficient_privilege USING MESSAGE='unit editor required';
    END IF;
  END LOOP;

  FOR v_occasion IN SELECT DISTINCT i.occasion FROM public.images i
    WHERE i.link=ANY(p_links) AND i.occasion IS NOT NULL
  LOOP
    DELETE FROM public.images i
      WHERE i.link=ANY(p_links) AND i.occasion=v_occasion;
    PERFORM public.record_client_sync_commit_v1(
      v_occasion,'image.remove','content',jsonb_build_array(jsonb_build_object(
        'entityType','occasion_image','entityId','batch','operation','delete',
        'safeLabel','occasion media','changedFields',jsonb_build_array('link'))),
      ARRAY['occasion_config'],'[]'::jsonb,'[]'::jsonb,'user',NULL);
  END LOOP;

  DELETE FROM public.images i WHERE i.link=ANY(p_links);
END; $function$
;
REVOKE ALL ON FUNCTION public.remove_image_records(text[]) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.remove_image_records(text[]) TO service_role;
GRANT EXECUTE ON FUNCTION public.remove_image_records(text[]) TO authenticated;

-- Source: database/functions/eshop_orders/update_ticket_products_client_sync_v1.sql
CREATE OR REPLACE FUNCTION public.update_ticket_products_client_sync_v1(p_ticket bigint, p_products jsonb, p_command_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path = public,extensions
AS $function$
DECLARE v_actor uuid:=auth.uid(); v_occasion bigint; v_begin jsonb; v_hash text;
  v_users uuid[]; v_result jsonb;
BEGIN
  SELECT t.occasion INTO v_occasion FROM eshop.tickets t WHERE t.id=p_ticket;
  IF v_actor IS NULL OR v_occasion IS NULL OR p_products IS NULL
    OR jsonb_typeof(p_products)<>'array' OR jsonb_array_length(p_products)>1000
    OR octet_length(p_products::text)>1048576
    OR NOT public.can_write_orders(v_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='order editor required'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'ticket',p_ticket,'products',p_products)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,
    'inventory.ticket.products',v_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  SELECT COALESCE(array_agg(ou."user"),'{}'::uuid[]) INTO v_users
    FROM public.occasion_users ou
    WHERE ou.occasion=v_occasion AND ou.ticket=p_ticket;
  v_result:=public.update_ticket_products_internal_v1(p_ticket,p_products);
  RETURN public.complete_private_inventory_mutation_v1(p_command_id,v_occasion,
    'inventory.ticket.products',jsonb_build_array(jsonb_build_object(
      'entityType','ticket_products','entityId',p_ticket,'operation','update',
      'safeLabel','Ticket products','changedFields',jsonb_build_array(
        'products','allocations'))),v_users,v_result);
END; $function$
;
REVOKE ALL ON FUNCTION public.update_ticket_products_client_sync_v1(bigint,jsonb,uuid) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.update_ticket_products_client_sync_v1(bigint,jsonb,uuid) TO service_role;
GRANT EXECUTE ON FUNCTION public.update_ticket_products_client_sync_v1(bigint,jsonb,uuid) TO authenticated;

-- Source: database/functions/users/validate_occasion_user_csv_import_v1.sql
CREATE OR REPLACE FUNCTION public.validate_occasion_user_csv_import_v1(p_occasion_id bigint, p_rows jsonb, p_delete_user_ids jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
    v_unit_id bigint;
BEGIN
    SELECT o.unit INTO v_unit_id
      FROM public.occasions o
     WHERE o.id = p_occasion_id;
    IF v_unit_id IS NULL THEN
        RAISE EXCEPTION 'OCCASION_NOT_FOUND';
    END IF;
    IF NOT public.get_can_manage_occasion_users(p_occasion_id) THEN
        RAISE EXCEPTION 'NOT_AUTHORIZED';
    END IF;
    IF COALESCE(jsonb_typeof(p_rows), 'null') <> 'array'
       OR COALESCE(jsonb_typeof(p_delete_user_ids), 'null') <> 'array' THEN
        RAISE EXCEPTION 'INVALID_IMPORT_PAYLOAD';
    END IF;
    IF jsonb_array_length(p_rows) > 10000
       OR jsonb_array_length(p_delete_user_ids) > 10000 THEN
        RAISE EXCEPTION 'IMPORT_PAYLOAD_TOO_LARGE';
    END IF;
    IF EXISTS (
        SELECT 1 FROM jsonb_array_elements(p_rows) item
         WHERE jsonb_typeof(item) <> 'object'
            OR jsonb_typeof(item->'data') <> 'object'
    ) THEN
        RAISE EXCEPTION 'INVALID_IMPORT_ROW';
    END IF;
    IF EXISTS (
        SELECT 1 FROM jsonb_array_elements(p_rows) item
         WHERE NULLIF(btrim(item->'data'->>'email'), '') IS NULL
    ) THEN
        RAISE EXCEPTION 'EMAIL_REQUIRED';
    END IF;
    IF EXISTS (
        SELECT 1 FROM jsonb_array_elements(p_rows) item
         WHERE length(btrim(item->'data'->>'email')) > 254
            OR lower(btrim(item->'data'->>'email'))
               !~ '^[^[:space:]@]+@[^[:space:]@]+$'
            OR (
                item ? 'email_delivery'
                AND (
                    NULLIF(btrim(item->>'email_delivery'), '') IS NULL
                    OR length(btrim(item->>'email_delivery')) > 254
                    OR lower(btrim(item->>'email_delivery'))
                       !~ '^[^[:space:]@]+@[^[:space:]@]+$'
                )
            )
    ) THEN
        RAISE EXCEPTION 'INVALID_EMAIL';
    END IF;
    IF EXISTS (
        SELECT 1 FROM jsonb_array_elements(p_rows) item
         GROUP BY lower(btrim(item->'data'->>'email'))
        HAVING count(*) > 1
    ) THEN
        RAISE EXCEPTION 'DUPLICATE_ACCOUNT_EMAIL';
    END IF;
    IF EXISTS (
        SELECT 1 FROM jsonb_array_elements(p_rows) item
         WHERE NULLIF(item->>'user_id', '') IS NOT NULL
         GROUP BY item->>'user_id'
        HAVING count(*) > 1
    ) THEN
        RAISE EXCEPTION 'DUPLICATE_USER_ID';
    END IF;
    IF EXISTS (
        SELECT 1
          FROM jsonb_array_elements(p_rows) item
          JOIN jsonb_array_elements_text(p_delete_user_ids) deleted(id)
            ON deleted.id = item->>'user_id'
    ) THEN
        RAISE EXCEPTION 'CONFLICTING_IMPORT_OPERATION';
    END IF;
END;
$function$
;
REVOKE ALL ON FUNCTION public.validate_occasion_user_csv_import_v1(bigint,jsonb,jsonb) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.validate_occasion_user_csv_import_v1(bigint,jsonb,jsonb) TO service_role;

-- Source: database/functions/emails/legacy_template_delete.sql
-- Preserve the old signature, void response, error and narrower admission.
-- Mutation itself has one owner in delete_entity_email_template.
CREATE OR REPLACE FUNCTION public.delete_occasion_email_template(p_occasion_id bigint,p_code text)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
BEGIN
 IF NOT public.can_delete_legacy_occasion_email_template(p_occasion_id) THEN
   RAISE EXCEPTION 'User is not an editor for this occasion';
 END IF;
 PERFORM public.delete_entity_email_template('occasion',p_occasion_id,p_code);
END $$;

-- Source: database/functions/users/occasion_enrolment_internal.sql
CREATE OR REPLACE FUNCTION public.add_user_to_occasion_internal_v1(oc bigint, usr uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
    occasion_open         BOOLEAN;
    user_data             JSONB;
    user_exists           BOOLEAN;
    user_org              BIGINT;
    occasion_org          BIGINT;
    unit_id               BIGINT;

    -- Initialize flags (though SELECT INTO will overwrite these with NULL if no row found)
    unit_is_manager       BOOLEAN := false;
    unit_is_editor        BOOLEAN := false;
    unit_is_editor_view   BOOLEAN := false;

    is_privileged         BOOLEAN := false;
BEGIN
    -- 1. Retrieve the organization, the unit, and the open status of the occasion.
    SELECT organization, unit, is_open
      INTO occasion_org, unit_id, occasion_open
      FROM occasions
     WHERE id = oc;

    -- 2. Get the organization of the user.
    SELECT organization
      INTO user_org
      FROM user_info
     WHERE id = usr;

    -- 3. Ensure the user and the occasion belong to the same organization.
    IF user_org IS DISTINCT FROM occasion_org THEN
        RETURN jsonb_build_object(
                  'code', 403,
                  'message', 'User does not belong to the same organization as the occasion'
              );
    END IF;

    -- 4. Retrieve the unit-level role information from unit_users.
    SELECT is_manager, is_editor, is_editor_view
      INTO unit_is_manager, unit_is_editor, unit_is_editor_view
      FROM unit_users
     WHERE unit = unit_id AND "user" = usr;

    -- CRITICAL FIX: SELECT INTO sets variables to NULL if no row is found.
    -- We must ensure they are boolean FALSE to satisfy NOT NULL constraints later.
    unit_is_manager     := COALESCE(unit_is_manager, false);
    unit_is_editor      := COALESCE(unit_is_editor, false);
    unit_is_editor_view := COALESCE(unit_is_editor_view, false);

    -- 5. Define is_privileged.
    --    User is privileged if they have specific unit roles OR are an admin on the occasion.
    is_privileged := public.closed_occasion_enrolment_rule(unit_is_manager,unit_is_editor,unit_is_editor_view,
                     public.get_is_admin_on_occasion(oc));

    -- 6. Permission Check: Closed Occasions.
    --    If the occasion is not open, only privileged users can be added/modified.
    IF NOT occasion_open AND NOT is_privileged THEN
        RETURN jsonb_build_object('code', 403);
    END IF;

    -- 7. Retrieve the user info and build a JSON object merging any existing data.
    SELECT COALESCE(ui.data, '{}'::jsonb) || jsonb_build_object(
                'name', ui.name,
                'surname', ui.surname,
                'sex', ui.sex,
                'email', ui.email_readonly
           )
      INTO user_data
      FROM user_info ui
     WHERE ui.id = usr;

    -- 8. Check if the user already exists in the occasion_users table.
    SELECT EXISTS (
             SELECT 1
               FROM occasion_users
              WHERE occasion = oc AND "user" = usr
           ) INTO user_exists;

    IF user_exists THEN
        -- Update the existing row with the new data and the unit role flags.
        UPDATE occasion_users
           SET data           = user_data,
               is_manager     = unit_is_manager,
               is_editor      = unit_is_editor,
               is_editor_view = unit_is_editor_view,
               is_editor_order = unit_is_editor,
               is_editor_order_view = unit_is_editor_view
         WHERE occasion = oc AND "user" = usr;
    ELSE
        -- Insert a new row into occasion_users, using the unit-level role flags.
        INSERT INTO occasion_users (
            occasion,
            "user",
            created_at,
            is_editor,
            is_manager,
            is_editor_view,
            is_editor_order,
            is_editor_order_view,
            is_approved,
            is_approver,
            data,
            role
        )
        VALUES (
            oc,
            usr,
            now(),
            unit_is_editor,
            unit_is_manager,
            unit_is_editor_view,
            unit_is_editor,
            unit_is_editor_view,
            FALSE,
            FALSE,
            user_data,
            NULL
        );
    END IF;

    RETURN jsonb_build_object('code', 200);
END;
$function$
;
REVOKE ALL ON FUNCTION public.add_user_to_occasion_internal_v1(bigint,uuid) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.add_user_to_occasion_internal_v1(bigint,uuid) TO service_role;

-- Source: database/functions/others/legacy_occasion_catalogs.sql
-- External catalogue versions retain their distinct original payloads.
-- Their unit-only admission has one typed owner, separate from V212.

CREATE OR REPLACE FUNCTION public.get_all_occasions_for_edit(unit_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  occasion_data jsonb;
BEGIN
  -- Step 1: Verify that the unit exists
  IF NOT EXISTS (SELECT 1 FROM public.units WHERE id = unit_id) THEN
    RETURN jsonb_build_object(
      'code', 404,
      'message', 'Unit not found'
    );
  END IF;

  -- Step 2: Check if the caller is a manager or editor of the unit
  IF NOT public.can_read_legacy_unit_occasion_catalog(unit_id) THEN
    RETURN jsonb_build_object('code', 403);
  END IF;

  -- Step 3: Aggregate occasions for the unit including the first form for each occasion.
  SELECT jsonb_agg(
    jsonb_build_object(
      'id', o.id,
      'title', o.title,
      'created_at', o.created_at,
      'updated_at', o.updated_at,
      'data', o.data,
      'description', o.description,
      'is_hidden', o.is_hidden,
      'is_open', o.is_open,
      'start_time', o.start_time,
      'end_time', o.end_time,
      'link', o.link,
      'organization', o.organization,
      'services', o.services,
      'unit', o.unit,
      'features', o.features,
      'form', (
         SELECT jsonb_build_object(
           'id', f.id,
           'created_at', f.created_at,
           'data', f.data,
           'key', f.key,
           'occasion', f.occasion,
           'type', f.type,
           'is_open', f.is_open,
           'link', f.link,
           'blueprint', f.blueprint,
           'header', f.header,
           'header_off', f.header_off,
           'updated_at', f.updated_at
         )
         FROM public.forms f
         WHERE f.occasion = o.id
         ORDER BY f.id
         LIMIT 1
      )
    )
    ORDER BY o.start_time DESC
  )
  INTO occasion_data
  FROM public.occasions o
  WHERE o.unit = unit_id;

  -- Step 4: If no occasions were found, return an empty array.
  IF occasion_data IS NULL THEN
    occasion_data := '[]'::jsonb;
  END IF;

  -- Step 5: Return the aggregated JSON response with a 200 code.
  RETURN jsonb_build_object(
    'code', 200,
    'data', occasion_data
  );
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_all_occasions_for_edit_v182(unit_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  occasion_data jsonb;
BEGIN
  -- Step 1: Verify that the unit exists. If not, raise a 'not found' exception.
  IF NOT EXISTS (SELECT 1 FROM public.units WHERE id = unit_id) THEN
    RAISE EXCEPTION 'Unit not found' USING ERRCODE = 'PGRST001';
  END IF;

  -- Step 2: Check if the caller has sufficient permissions. If not, raise an 'insufficient privilege' exception.
  IF NOT public.can_read_legacy_unit_occasion_catalog(unit_id) THEN
    RAISE EXCEPTION 'Insufficient permissions for this unit' USING ERRCODE = '42501';
  END IF;

  -- Step 3: Aggregate occasions for the unit, including forms, order stats, and user data.
  SELECT jsonb_agg(
    jsonb_build_object(
      'id', o.id,
      'title', o.title,
      'created_at', o.created_at,
      'updated_at', o.updated_at,
      'data', o.data,
      'is_hidden', o.is_hidden,
      'is_open', o.is_open,
      'start_time', o.start_time,
      'end_time', o.end_time,
      'link', o.link,
      'organization', o.organization,
      'services', o.services,
      'unit', o.unit,
      'features', o.features,
      'stats', jsonb_build_object(
          'total', COALESCE(order_stats.total, 0),
          'storno', COALESCE(order_stats.storno, 0),
          'paid_or_sent', COALESCE(order_stats.paid_or_sent, 0),
          'ordered', COALESCE(order_stats.ordered, 0),
          'used', COALESCE(order_stats.used, 0),
          'users', COALESCE(user_stats.user_count, 0)
      ),
      'form', (
         -- This subquery fetches the first associated form for the occasion.
         SELECT jsonb_build_object(
           'id', f.id,
           'created_at', f.created_at,
           'data', f.data,
           'key', f.key,
           'occasion', f.occasion,
           'type', f.type,
           'is_open', f.is_open,
           'link', f.link,
           'blueprint', f.blueprint,
           'header', f.header,
           'header_off', f.header_off,
           'updated_at', f.updated_at
         )
         FROM public.forms f
         WHERE f.occasion = o.id
         ORDER BY f.id
         LIMIT 1
      )
    )
    ORDER BY o.start_time DESC
  )
  INTO occasion_data
  FROM public.occasions o
  LEFT JOIN (
      -- This subquery calculates all required order counts in a single pass over the orders table.
      SELECT
          occasion,
          COUNT(*) AS total,
          COUNT(*) FILTER (WHERE state = 'storno') AS storno,
          COUNT(*) FILTER (WHERE state IN ('paid', 'sent')) AS paid_or_sent,
          COUNT(*) FILTER (WHERE state = 'ordered') AS ordered,
          COUNT(*) FILTER (WHERE state = 'used') AS used
      FROM eshop.orders
      WHERE occasion IS NOT NULL
      GROUP BY occasion
  ) AS order_stats ON o.id = order_stats.occasion
  LEFT JOIN (
      -- New: This subquery aggregates occasion users and provides their count.
      SELECT
          occasion,
          COUNT(*) as user_count
      FROM public.occasion_users
      GROUP BY occasion
  ) AS user_stats ON o.id = user_stats.occasion
  WHERE o.unit = unit_id;

  -- Step 4: If no occasions were found, return an empty JSON array.
  IF occasion_data IS NULL THEN
    occasion_data := '[]'::jsonb;
  END IF;

  -- Step 5: Return the aggregated JSON data directly.
  RETURN occasion_data;
END;
$function$
;

-- Source: database/functions/scanning/legacy_scan_ticket_v2.sql
-- Retained scan_ticket_v2 response contract; technical authentication delegates
-- to the same live proof resolver as session bootstrap and participant lookup.
CREATE OR REPLACE FUNCTION public.scan_ticket_v2(scanned_id text, scanned_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
    ticket_row RECORD;
    order_json JSONB;
    products_json JSONB;
    spot_json JSONB;
    inventory_json JSONB; -- New variable for the inventory bundle
    order_id BIGINT;
    occasion_id BIGINT;
    expected_scan_code TEXT;
BEGIN
    -- 1. Check if the ticket exists
    SELECT *
      INTO ticket_row
    FROM eshop.tickets
    WHERE ticket_symbol = scanned_id
    LIMIT 1;

    IF ticket_row IS NULL THEN
        RETURN jsonb_build_object('code', 404, 'message', 'Ticket not found');
    END IF;

    -- 2. Retrieve the associated order ID
    SELECT opt."order" INTO order_id
    FROM eshop.order_product_ticket opt
    WHERE opt.ticket = ticket_row.id
    LIMIT 1;

    IF order_id IS NULL THEN
        RETURN jsonb_build_object('code', 404, 'message', 'Order for ticket not found');
    END IF;

    -- 3. Retrieve the occasion ID from the order
    SELECT o.occasion INTO occasion_id
    FROM eshop.orders o
    WHERE o.id = order_id
    LIMIT 1;

    IF occasion_id IS NULL THEN
        RETURN jsonb_build_object('code', 404, 'message', 'Occasion for order not found');
    END IF;

    -- 4. Retrieve the expected scan_code
    SELECT oh.secret
      INTO expected_scan_code
    FROM public.occasions_hidden oh
    JOIN public.occasions o ON o.occasion_hidden = oh.id
    WHERE o.id = occasion_id
    LIMIT 1;

    IF expected_scan_code IS NULL THEN
        RETURN jsonb_build_object(
            'code', 400,
            'message', 'Scan code not defined for this occasion'
        );
    END IF;

    -- 5. Validate the scanned_code
    IF NOT EXISTS(SELECT 1 FROM public.get_scanner_occasion_for_scan_code_internal(scanned_code) proof
      WHERE proof.id=occasion_id) THEN
        RETURN jsonb_build_object(
            'code', 401,
            'message', 'Scan code is not correct'
        );
    END IF;

    -- 6. Proceed with fetching all required details

    -- Fetch the order details as JSON
    SELECT row_to_json(o)
      INTO order_json
    FROM eshop.orders o
    WHERE o.id = order_id;

    -- Fetch the associated spot as JSON
    SELECT row_to_json(s)
      INTO spot_json
    FROM eshop.spots s
    WHERE s.order_product_ticket IN (
        SELECT opt.id
          FROM eshop.order_product_ticket opt
         WHERE opt.ticket = ticket_row.id
    )
    LIMIT 1;

    -- =================================================================
    -- NEW: Fetch the full inventory bundle associated with the ticket
    -- =================================================================
    WITH scanned_ticket_products AS (
        SELECT
            opt.id AS order_product_ticket_id,
            opt.product AS product_id
        FROM eshop.order_product_ticket opt
        WHERE opt.ticket = ticket_row.id
          AND opt.product IS NOT NULL
    ),
    scanned_ticket_inventory AS (
        SELECT
            s.id AS id,
            s.title AS title,
            s.state AS state,
            s.resource_slot AS resource_slot,
            s.resource AS resource,
            s.inventory_context AS inventory_context,
            ic.inventory_pool AS inventory_pool,
            stp.product_id
        FROM eshop.spots s
        JOIN scanned_ticket_products stp ON s.order_product_ticket = stp.order_product_ticket_id
        JOIN public.inventory_contexts ic ON s.inventory_context = ic.id
    ),
    products_data AS (
        SELECT
            jsonb_object_agg(p.id, jsonb_build_object(
                'id', p.id, 'title', p.title, 'description', p.description, 'price', p.price, 'data', p.data,
                'product_type', p.product_type, 'occasion', p.occasion, 'is_hidden', p.is_hidden,
                'currency_code', p.currency_code, 'title_short', p.title_short, 'order', p."order",
                'maximum', p.maximum, 'is_dynamically_available', is_product_dynamically_available(p.id)
            )) AS data
        FROM eshop.products p
        WHERE p.id IN (SELECT DISTINCT product_id FROM scanned_ticket_products)
    ),
    product_inventory_contexts_data AS (
        SELECT jsonb_object_agg(pic.id, to_jsonb(pic)) AS data
        FROM eshop.product_inventory_contexts pic
        WHERE (pic.inventory_context, pic.product) IN (
            SELECT DISTINCT inventory_context, product_id FROM scanned_ticket_inventory
        )
    ),
    contexts_data AS (
        SELECT
            jsonb_object_agg(ic.id, jsonb_build_object(
                'id', ic.id, 'order', ic."order", 'block_date', ic.block_date, 'title', ic.title,
                'data', ic.data, 'inventory_pool', ic.inventory_pool,
                'spots', (
                    SELECT COALESCE(jsonb_agg(to_jsonb(t) ORDER BY t.id), '[]'::jsonb)
                    FROM (
                        SELECT sti.id, sti.title, sti.state, sti.resource_slot, sti.resource, sti.product_id
                        FROM scanned_ticket_inventory sti
                        WHERE sti.inventory_context = ic.id
                    ) t
                )
            )) AS data
        FROM public.inventory_contexts ic
        WHERE ic.id IN (SELECT DISTINCT inventory_context FROM scanned_ticket_inventory)
    ),
    pools_data AS (
        SELECT jsonb_object_agg(p.id, jsonb_strip_nulls(jsonb_build_object(
            'id', p.id, 'data', p.data, 'title', p.title, 'description', p.description,
            'type', p.type, 'sellable_capacity', p.sellable_capacity, 'occasion', p.occasion
        ))) AS data
        FROM public.inventory_pools p
        WHERE p.id IN (SELECT DISTINCT inventory_pool FROM scanned_ticket_inventory)
    ),
    places_data AS (
        SELECT jsonb_object_agg(pl.id, to_jsonb(pl)) AS data
        FROM public.places pl
        JOIN (
            SELECT DISTINCT (ip.data->>'place_id')::bigint AS id
            FROM public.inventory_pools ip
            WHERE ip.id IN (SELECT DISTINCT inventory_pool FROM scanned_ticket_inventory)
              AND ip.data ? 'place_id' AND ip.data->>'place_id' IS NOT NULL
        ) AS place_ids ON pl.id = place_ids.id
    ),
    resources_data AS (
        SELECT jsonb_object_agg(r.id, to_jsonb(r)) AS data
        FROM public.resources r
        WHERE r.id IN (SELECT DISTINCT resource FROM scanned_ticket_inventory WHERE resource IS NOT NULL)
    )
    SELECT jsonb_build_object(
        'inventory_contexts', COALESCE((SELECT data FROM contexts_data), '{}'::jsonb),
        'inventory_pools', COALESCE((SELECT data FROM pools_data), '{}'::jsonb),
        'resources', COALESCE((SELECT data FROM resources_data), '{}'::jsonb),
        'products', COALESCE((SELECT data FROM products_data), '{}'::jsonb),
        'product_inventory_contexts', COALESCE((SELECT data FROM product_inventory_contexts_data), '{}'::jsonb),
        'places', COALESCE((SELECT data FROM places_data), '{}'::jsonb)
    )
    INTO inventory_json;

    -- This overwrites the simple products_json from before with the richer one from the bundle
    SELECT inventory_json->'products' INTO products_json;

    -- 7. Return the compiled JSONB response
    RETURN jsonb_build_object(
        'code', 200,
        'ticket', row_to_json(ticket_row),
        'order', order_json,
        'products', products_json,
        'spot', spot_json,
        'inventory', inventory_json -- Added the full inventory bundle
    );

EXCEPTION
    WHEN OTHERS THEN
        RETURN jsonb_build_object(
            'code', 500,
            'message', 'An unexpected error occurred: ' || SQLERRM
        );
END;
$function$
;

-- Source: database/functions/others/add_image_record.sql
CREATE OR REPLACE FUNCTION public.add_image_record(p_link text, p_occasion_id bigint, p_unit_id bigint)
RETURNS void
SECURITY DEFINER
LANGUAGE plpgsql
SET search_path = public, extensions
AS $$
DECLARE v_image_id bigint;
BEGIN
    -- Scope is an exclusive owner, never a caller-supplied unit that masks
    -- an unrelated occasion. Check it before any budget or metadata write.
    IF (p_unit_id IS NULL)=(p_occasion_id IS NULL) THEN
        RAISE insufficient_privilege USING MESSAGE='exactly one authorized image owner required';
    END IF;
    -- Permission Check
    IF p_unit_id IS NOT NULL THEN
        -- Unit Editor
        IF (SELECT public.can_upload_unit_media(p_unit_id)) IS NOT TRUE THEN
            RAISE EXCEPTION 'Permission denied: User is not an editor of this unit.';
        END IF;
    ELSIF p_occasion_id IS NOT NULL THEN
        -- Occasion Editor OR Occasion Order Editor
        IF public.can_upload_occasion_media(p_occasion_id) IS NOT TRUE THEN
             RAISE EXCEPTION 'Permission denied: User is not an editor/order-editor of this occasion.';
        END IF;
    ELSE
        RAISE EXCEPTION 'Entity ID (unit or occasion) must be provided.';
    END IF;

    PERFORM public.add_image_record_internal(p_link,p_occasion_id,p_unit_id);

END;
$$;

-- Source: database/functions/groups/add_user_group_members_client_sync_v1.sql
CREATE OR REPLACE FUNCTION public.add_user_group_members_client_sync_v1(p_occasion bigint,p_group bigint,p_users uuid[],p_command_id uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE actor uuid:=auth.uid(); begin_result jsonb; hash text; members jsonb; users uuid[]; v_version bigint; changed integer;
BEGIN
 PERFORM public.assert_canonical_mutation_write_release_internal_v1(p_occasion);
 IF cardinality(p_users)>5000 THEN RAISE invalid_parameter_value USING MESSAGE='too many members'; END IF;
 p_users:=ARRAY(SELECT DISTINCT id FROM unnest(p_users) id ORDER BY id);
 IF actor IS NULL OR cardinality(p_users) NOT BETWEEN 1 AND 5000 THEN
  RAISE invalid_parameter_value USING MESSAGE='invalid selected members'; END IF;
 IF NOT public.can_add_group_members(p_occasion,p_group) THEN
  RAISE insufficient_privilege USING MESSAGE='group editor required'; END IF;
 hash:=encode(extensions.digest(convert_to(jsonb_build_object('occasion',p_occasion,'group',p_group,'users',p_users)::text,'UTF8'),'sha256'),'hex');
 begin_result:=public.begin_client_mutation_v1(p_command_id,'profile.group.members.add',p_occasion,actor,hash);
 PERFORM public.lock_group_occasion_internal_v1(p_occasion);
 IF begin_result->>'disposition'='replay' THEN RETURN begin_result->'response'; END IF;
 PERFORM 1 FROM public.user_group_info WHERE id=p_group AND occasion=p_occasion FOR UPDATE;
 IF NOT FOUND THEN RAISE insufficient_privilege USING MESSAGE='group unavailable'; END IF;
 IF NOT public.can_add_group_members(p_occasion,p_group) THEN
  RAISE insufficient_privilege USING MESSAGE='group editor required'; END IF;
 SELECT jsonb_agg(jsonb_build_object('user_id',id,'is_admin',false)) INTO members FROM unnest(p_users) id;
 changed:=public.write_user_group_members_internal_v1(p_occasion,p_group,members,false);
 INSERT INTO public.client_aggregate_versions(aggregate_type,scope_type,scope_id,aggregate_id,version)
 VALUES('user_group','occasion',p_occasion,p_group::text,0) ON CONFLICT DO NOTHING;
 UPDATE public.client_aggregate_versions SET version=version+CASE WHEN changed>0 THEN 1 ELSE 0 END,updated_at=clock_timestamp()
 WHERE aggregate_type='user_group' AND scope_type='occasion' AND scope_id=p_occasion AND aggregate_id=p_group::text RETURNING version INTO v_version;
 IF changed=0 THEN RETURN public.complete_client_mutation_outcome_v1(p_command_id,'unchanged',200,
  jsonb_build_object('version',v_version,'group',public.get_user_group_command_data_v1(p_group))); END IF;
 SELECT array_agg("user") INTO users FROM public.user_groups WHERE "group"=p_group;
 RETURN public.complete_private_profile_mutation_v1(p_command_id,p_occasion,'profile.group.members.add',
  jsonb_build_array(jsonb_build_object('entityType','user_group','entityId',p_group,'operation','update','safeLabel','Group members',
    'changedFields',jsonb_build_array('participants'))),users,'{}','[]',
  jsonb_build_object('version',v_version,'group',public.get_user_group_command_data_v1(p_group)));
END $$;

-- Source: database/functions/users/add_user_to_occasion_client_sync_v1.sql
CREATE OR REPLACE FUNCTION public.add_user_to_occasion_client_sync_v1(p_occasion bigint, p_user uuid, p_command_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_actor uuid:=auth.uid(); v_begin jsonb; v_hash text; v_before jsonb;
  v_after jsonb; v_result jsonb; v_version bigint; v_replacements jsonb:='[]';
BEGIN
  IF v_actor IS NULL OR p_user IS NULL OR NOT (
    v_actor=p_user OR public.can_manage_occasion_participants(p_occasion)) THEN
    RAISE insufficient_privilege USING MESSAGE='occasion membership permission required';
  END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'occasion',p_occasion,'userId',p_user)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,
    'profile.membership.ensure',p_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  SELECT to_jsonb(ou) INTO v_before FROM public.occasion_users ou
    WHERE ou.occasion=p_occasion AND ou."user"=p_user FOR UPDATE;
  v_result:=public.add_user_to_occasion_internal_v1(p_occasion,p_user);
  IF COALESCE((v_result->>'code')::integer,500)<>200 THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'rejected',
      COALESCE((v_result->>'code')::integer,400),v_result); END IF;
  SELECT to_jsonb(ou) INTO v_after FROM public.occasion_users ou
    WHERE ou.occasion=p_occasion AND ou."user"=p_user;
  SELECT COALESCE(v.version,0) INTO v_version FROM (SELECT 1) seed
    LEFT JOIN public.client_aggregate_versions v
      ON v.aggregate_type='occasion_user' AND v.scope_type='occasion'
      AND v.scope_id=p_occasion AND v.aggregate_id=p_user::text;
  IF v_before IS NOT DISTINCT FROM v_after THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'unchanged',200,
      jsonb_build_object('version',v_version,'userId',p_user)); END IF;
  INSERT INTO public.client_aggregate_versions
    (aggregate_type,scope_type,scope_id,aggregate_id,version)
  VALUES ('occasion_user','occasion',p_occasion,p_user::text,1)
  ON CONFLICT (aggregate_type,scope_type,scope_id,aggregate_id) DO UPDATE
    SET version=public.client_aggregate_versions.version+1,
      updated_at=clock_timestamp() RETURNING version INTO v_version;
  IF v_actor=p_user THEN v_replacements:=jsonb_build_array(jsonb_build_object(
    'component','private_profile','userId',p_user,
    'payload',public.get_private_profile_payload_v1(p_occasion,p_user))); END IF;
  RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,
    'profile.membership.ensure','profile',jsonb_build_array(jsonb_build_object(
      'entityType','occasion_user','entityId',p_user,'operation',
      CASE WHEN v_before IS NULL THEN 'insert' ELSE 'update' END,
      'safeLabel','Occasion membership','changedFields',jsonb_build_array(
        'membership','rights'))),'{}',jsonb_build_array(jsonb_build_object(
          'component','private_profile','userId',p_user)),'[]',
    jsonb_build_object('version',v_version,'userId',p_user),
    '{}','[]','user',NULL,v_replacements);
END; $function$
;

