-- Source: database/functions/occasion_setup/blueprint_layout.sql
-- Unit-scoped preparation uses the existing ticket preview admission policy.
CREATE OR REPLACE FUNCTION public.admit_occasion_setup_blueprint_resources_v1(p_draft uuid,p_bytes bigint)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE d public.occasion_setup_drafts;
BEGIN
 SELECT * INTO d FROM public.occasion_setup_drafts WHERE id=p_draft;
 IF d.id IS NULL OR auth.uid() IS NULL OR NOT public.can_create_occasion(d.unit) THEN
  RAISE insufficient_privilege USING MESSAGE='Draft access denied'; END IF;
 IF d.data ? 'finalizedOccasion' OR p_bytes IS NULL OR p_bytes<=0 THEN RAISE invalid_parameter_value USING MESSAGE='Invalid draft preview'; END IF;
 PERFORM public.abuse_charge_v1(public.abuse_effective_rules_v1('ticket.preview',d.unit,d.organization),
  jsonb_build_object('actor',auth.uid(),'unit',d.unit,'organization',d.organization),jsonb_build_object('ticket.preview.payload.bytes',p_bytes));
 RETURN public.bound_document_data_v1('{}');
END $$;

-- Source: database/functions/abuse/documents.sql
CREATE OR REPLACE FUNCTION public.admit_ticket_preview_limits_v1(p_occasion bigint,p_bytes bigint,p_read_only boolean DEFAULT false)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE o public.occasions;
BEGIN
 IF p_read_only THEN
  IF NOT public.can_preview_ticket_readonly(p_occasion) THEN RETURN NULL; END IF;
  IF p_bytes IS NULL OR p_bytes<=0 THEN RAISE invalid_parameter_value USING MESSAGE='preview bytes required'; END IF;
  SELECT * INTO STRICT o FROM public.occasions WHERE id=p_occasion;
  PERFORM public.abuse_charge_v1(public.abuse_effective_rules_v1('ticket.preview',o.unit,o.organization),jsonb_build_object('actor',auth.uid(),'unit',o.unit,'organization',o.organization),jsonb_build_object('ticket.preview.payload.bytes',p_bytes));
 ELSIF NOT public.admit_ticket_preview_v1(p_occasion,p_bytes) THEN RETURN NULL; END IF;
 RETURN public.bound_document_data_v1('{}');
END $$;

-- Source: database/functions/eshop/analyze_new_order_spots.sql
CREATE OR REPLACE FUNCTION public.analyze_new_order_spots(
  p_spot_ids bigint[]
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions AS $$
DECLARE
  v_conflicts jsonb;
  v_new_order_items jsonb;
  v_occasion_id BIGINT;
  v_total numeric; v_currency text; v_order_form jsonb;
BEGIN
  -- =======================================================================
  -- 0. VALIDATION & SECURITY
  -- =======================================================================

  -- Handle empty input
  IF p_spot_ids IS NULL OR array_length(p_spot_ids, 1) IS NULL THEN
     RETURN jsonb_build_object('conflicts', '[]'::jsonb, 'new_order_items', '[]'::jsonb);
  END IF;

  -- Get Occasion ID from the first spot
  SELECT occasion INTO v_occasion_id
  FROM eshop.spots
  WHERE id = p_spot_ids[1];

  IF v_occasion_id IS NULL THEN
     RAISE EXCEPTION 'Spot ID % not found.', p_spot_ids[1];
  END IF;

  -- Consistency Check: Ensure all selected spots belong to the SAME occasion
  PERFORM 1
  FROM eshop.spots
  WHERE id = ANY(p_spot_ids)
  AND occasion != v_occasion_id;

  IF FOUND THEN
     RAISE EXCEPTION 'All selected spots must belong to the same occasion.';
  END IF;

  -- Permission Check: User must have "Order View" rights on this occasion
  IF public.can_read_orders(v_occasion_id) IS NOT TRUE THEN
     RAISE EXCEPTION 'Permission denied. User does not have view rights for occasion %.', v_occasion_id;
  END IF;

  IF (SELECT count(*) FROM eshop.spots WHERE id=ANY(p_spot_ids) AND occasion=v_occasion_id)<>cardinality(ARRAY(SELECT DISTINCT id FROM unnest(p_spot_ids) id)) THEN
    RAISE EXCEPTION 'BLUEPRINT_SPOT_SCOPE_MISMATCH'; END IF;
  PERFORM public.lock_blueprint_scope_internal(ARRAY[v_occasion_id]);
  PERFORM public.check_blueprint_selection_units_internal(p_spot_ids);

  -- =======================================================================
  -- 1. IDENTIFY CONFLICTS
  -- =======================================================================
  WITH impacted_base AS (
    SELECT
      s.id as spot_id,
      o.id as order_id,
      o.data as order_data,
      o.state as order_state,
      t.id as ticket_id,
      t.ticket_symbol
    FROM eshop.spots s
    JOIN eshop.order_product_ticket opt ON s.order_product_ticket = opt.id
    JOIN eshop.tickets t ON opt.ticket = t.id
    JOIN eshop.orders o ON opt.order = o.id
    WHERE s.id = ANY(p_spot_ids)
    -- Include any state that implies the spot is technically "occupied"
  ),
  impacted_enriched AS (
    -- Safely extract the specific ticket from JSON
    SELECT
      ib.*,
      (
        SELECT item
        FROM jsonb_array_elements(ib.order_data->'tickets') item
        WHERE (item->>'id')::bigint = ib.ticket_id
        LIMIT 1
      ) as ticket_json
    FROM impacted_base ib
  ),
  order_stats AS (
    -- Calculate if whole order is cancelled
    SELECT
      order_id,
      COUNT(DISTINCT ticket_id) as affected_ticket_count,
      COALESCE(jsonb_array_length(order_data->'tickets'), 0) as total_ticket_count
    FROM impacted_enriched
    GROUP BY order_id, order_data
  )
  SELECT jsonb_agg(
    jsonb_build_object(
      'order_id', ie.order_id,
      -- Extract individual fields as requested
      'email', ie.order_data->>'email',
      'name', ie.order_data->>'name',
      'surname', ie.order_data->>'surname',
      'note', ie.order_data->>'note',

      'ticket_id', ie.ticket_id,
      'ticket_symbol', ie.ticket_symbol,
      'is_fully_cancelled', (os.affected_ticket_count >= os.total_ticket_count AND os.total_ticket_count > 0),
      -- The products array from the JSON (Spot + Extras)
      'products', ie.ticket_json->'products',
      -- Sum the price (safely handle nulls)
      'total_price', (
         SELECT COALESCE(SUM((prod->>'price')::numeric), 0)
         FROM jsonb_array_elements(ie.ticket_json->'products') prod
      )
    )
  )
  INTO v_conflicts
  FROM impacted_enriched ie
  JOIN order_stats os ON ie.order_id = os.order_id;

  -- =======================================================================
  -- 2. PREPARE NEW ORDER ITEMS
  -- =======================================================================
  SELECT jsonb_agg(jsonb_build_object(
    'spot_id', s.id,
    'spot_title', s.title,
    'product_title', p.title,
    'price', p.price,
    'currency', p.currency_code
  ))
  INTO v_new_order_items
  FROM eshop.spots s
  LEFT JOIN eshop.products p ON s.product = p.id
  WHERE s.id = ANY(p_spot_ids);

  IF (SELECT count(DISTINCT item->>'currency') FROM jsonb_array_elements(coalesce(v_new_order_items,'[]')) item)>1 THEN RAISE EXCEPTION 'BLUEPRINT_CURRENCY_MISMATCH'; END IF;
  SELECT coalesce(sum((item->>'price')::numeric),0),min(item->>'currency') INTO v_total,v_currency FROM jsonb_array_elements(coalesce(v_new_order_items,'[]')) item;
  SELECT jsonb_build_object('key',f.key,'phone_prefixes',public.get_effective_form_data(f.id)->'phone_prefixes',
    'fields',coalesce((SELECT jsonb_agg(to_jsonb(ff) ORDER BY coalesce(ff."order",0),ff.id)
      FROM public.form_fields ff WHERE ff.form=f.id AND ff.is_required=true
      AND ff.is_hidden=false AND ff.type NOT IN ('ticket','spot','product_type')),'[]'::jsonb))
    INTO v_order_form FROM public.forms f WHERE f.occasion=v_occasion_id AND f.is_open=true
      AND f.blueprint=(SELECT blueprint FROM eshop.spots WHERE id=p_spot_ids[1])
      AND NOT EXISTS(SELECT 1 FROM eshop.spots WHERE id=ANY(p_spot_ids) AND blueprint IS DISTINCT FROM (SELECT blueprint FROM eshop.spots WHERE id=p_spot_ids[1]))
    ORDER BY f.type='ticket' DESC,f.id DESC LIMIT 1;
  RETURN jsonb_build_object(
    'conflicts', COALESCE(v_conflicts, '[]'::jsonb),
    'new_order_items', COALESCE(v_new_order_items, '[]'::jsonb),
    'total_price',v_total,'currency',v_currency,'order_form',v_order_form
  );
END;
$$;

-- Source: database/functions/others/authorize_image_deletion.sql
CREATE OR REPLACE FUNCTION public.authorize_image_deletion(p_links text[])
RETURNS TABLE(link text)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
  v_requested_count integer;
  v_found_count integer;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required.' USING ERRCODE = '42501';
  END IF;

  v_requested_count := cardinality(p_links);
  IF v_requested_count IS NULL OR v_requested_count < 1 OR v_requested_count > 50
     OR array_position(p_links, NULL) IS NOT NULL
     OR v_requested_count <> (SELECT count(DISTINCT requested) FROM unnest(p_links) AS requested) THEN
    RAISE EXCEPTION 'Image link batch must contain 1-50 unique non-null links.'
      USING ERRCODE = '22023';
  END IF;

  SELECT count(DISTINCT image.link) INTO v_found_count
  FROM public.images AS image
  WHERE image.link = ANY(p_links);

  IF v_found_count <> v_requested_count THEN
    RAISE EXCEPTION 'Every image link must exist.' USING ERRCODE = '42501';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.images AS image
    WHERE image.link = ANY(p_links)
      AND NOT (
        (image.unit IS NOT NULL AND public.can_upload_unit_media(image.unit))
        OR
        (image.occasion IS NOT NULL AND public.can_upload_occasion_media(image.occasion))
      )
  ) THEN
    RAISE EXCEPTION 'Permission denied for image deletion.' USING ERRCODE = '42501';
  END IF;

  IF EXISTS(SELECT 1 FROM public.blueprint_image_assets a WHERE a.url=ANY(p_links)) THEN
    RAISE insufficient_privilege USING MESSAGE='BLUEPRINT_IMAGE_IMMUTABLE'; END IF;

  RETURN QUERY
  SELECT DISTINCT image.link
  FROM public.images AS image
  WHERE image.link = ANY(p_links)
  ORDER BY image.link;
END;
$$;

-- Source: database/functions/blueprint/reviewed_migration_receipt.sql
-- Same canonical receipt implementation; runtime always preserves demo read-only.
CREATE OR REPLACE FUNCTION public.begin_client_mutation_reviewed_impl_internal(p_command_id uuid, p_command_name text, p_occasion bigint, p_actor_id uuid, p_request_sha256 text, p_reviewed_demo boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_receipt public.client_mutation_receipts%ROWTYPE; v_inserted integer;
BEGIN
  IF p_reviewed_demo AND public.is_demo_occasion(p_occasion) THEN
    IF NOT public.can_migrate_reviewed_legacy_blueprint(p_occasion) THEN
      RAISE insufficient_privilege USING MESSAGE='blueprint migration reviewer required'; END IF;
  ELSE PERFORM public.check_occasion_writable(p_occasion); END IF;
  IF p_command_id IS NULL OR p_actor_id IS NULL OR p_actor_id IS DISTINCT FROM auth.uid() THEN
    RAISE insufficient_privilege USING MESSAGE='authenticated command actor required';
  END IF;
  IF p_command_name !~ '^[a-z][a-z0-9_.]{2,95}$'
     OR p_request_sha256 !~ '^[0-9a-f]{64}$' THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid mutation receipt metadata';
  END IF;
  INSERT INTO public.client_mutation_receipts
    (command_id,command_name,occasion,actor_id,request_sha256)
  VALUES (p_command_id,p_command_name,p_occasion,p_actor_id,p_request_sha256)
  ON CONFLICT (command_id) DO NOTHING;
  GET DIAGNOSTICS v_inserted=ROW_COUNT;
  SELECT * INTO STRICT v_receipt FROM public.client_mutation_receipts
    WHERE command_id=p_command_id FOR UPDATE;
  IF v_receipt.command_name IS DISTINCT FROM p_command_name
     OR v_receipt.occasion IS DISTINCT FROM p_occasion
     OR v_receipt.actor_id IS DISTINCT FROM p_actor_id
     OR v_receipt.request_sha256 IS DISTINCT FROM p_request_sha256 THEN
    RAISE invalid_parameter_value USING MESSAGE='command id was already used with different request data';
  END IF;
  IF v_receipt.status='completed' THEN
    RETURN jsonb_build_object('disposition','replay','response',v_receipt.response);
  ELSIF v_receipt.status='expired' THEN
    RETURN jsonb_build_object('disposition','replay',
      'response',public.expired_client_mutation_response_v1(v_receipt));
  END IF;
  IF v_inserted<>1 THEN RAISE serialization_failure
    USING MESSAGE='incomplete mutation receipt cannot be resumed'; END IF;
  RETURN jsonb_build_object('disposition','claimed');
END; $function$;

-- Source: database/functions/units/begin_unit_client_mutation_v1.sql
CREATE OR REPLACE FUNCTION public.begin_unit_client_mutation_v1(p_command_id uuid, p_command_name text, p_unit bigint, p_actor_id uuid, p_request_sha256 text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path=public,extensions
AS $function$
DECLARE v_receipt public.client_mutation_receipts%ROWTYPE; v_inserted integer;
BEGIN
  IF p_actor_id IS NULL OR p_actor_id IS DISTINCT FROM auth.uid()
     OR p_command_id IS NULL OR p_unit IS NULL
     OR p_command_name !~ '^[a-z][a-z0-9_.]{2,95}$'
     OR p_request_sha256 !~ '^[0-9a-f]{64}$'
     OR NOT (CASE WHEN p_command_name IN ('occasion.create','occasion.setup.finalize')
       THEN public.can_create_occasion(p_unit)
       WHEN p_command_name='occasion.delete' THEN public.can_delete_occasion_in_unit(p_unit)
       WHEN p_command_name IN ('unit.information.save','unit.information.delete')
         THEN public.can_write_unit_information(p_unit)
       WHEN p_command_name IN ('unit.icon.save','unit.icon.delete')
         THEN public.can_write_unit_icons(p_unit)
       WHEN p_command_name='profile.unit_access.delete' THEN public.can_manage_unit_users(p_unit)
       WHEN p_command_name='unit.config.save' THEN public.can_manage_unit_configuration(p_unit)
       WHEN p_command_name='occasion.duplicate' THEN public.can_copy_occasion_target(p_unit)
       ELSE false END) THEN
    RAISE insufficient_privilege USING MESSAGE='invalid unit mutation receipt claim';
  END IF;
  INSERT INTO public.client_mutation_receipts
    (command_id,command_name,unit,actor_id,request_sha256)
  VALUES (p_command_id,p_command_name,p_unit,p_actor_id,p_request_sha256)
  ON CONFLICT (command_id) DO NOTHING;
  GET DIAGNOSTICS v_inserted=ROW_COUNT;
  SELECT * INTO STRICT v_receipt FROM public.client_mutation_receipts
    WHERE command_id=p_command_id FOR UPDATE;
  IF v_receipt.command_name IS DISTINCT FROM p_command_name
     OR v_receipt.occasion IS NOT NULL OR v_receipt.unit IS DISTINCT FROM p_unit
     OR v_receipt.actor_id IS DISTINCT FROM p_actor_id OR v_receipt.actor_client_id IS NOT NULL
     OR v_receipt.request_sha256 IS DISTINCT FROM p_request_sha256 THEN
    RAISE invalid_parameter_value USING MESSAGE='command id was already used with different request data';
  END IF;
  IF v_receipt.status='completed' THEN
    RETURN jsonb_build_object('disposition','replay','response',v_receipt.response);
  ELSIF v_receipt.status='expired' THEN
    RETURN jsonb_build_object('disposition','replay',
      'response',public.expired_client_mutation_response_v1(v_receipt));
  END IF;
  IF v_inserted<>1 THEN RAISE serialization_failure
    USING MESSAGE='incomplete mutation receipt cannot be resumed'; END IF;
  RETURN jsonb_build_object('disposition','claimed');
END; $function$
;

-- Source: database/functions/occasion_setup/drafts.sql
-- Run the canonical creator inside a rollback-only subtransaction. Its
-- complete configuration survives in a PL/pgSQL variable, but no occasion,
-- form, product, reminders or other rows escape into the normal application.
-- PostgreSQL sequences may advance; those IDs are draft-local references.
CREATE OR REPLACE FUNCTION public.build_occasion_setup_configuration(p_unit bigint, p_id uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions AS $$
DECLARE configuration jsonb; organization_id bigint;
  provisional_link text := 'draft-' || p_id::text;
BEGIN
  IF auth.uid() IS NULL OR NOT public.can_create_occasion(p_unit) THEN
    RAISE EXCEPTION 'Draft access denied' USING ERRCODE = '42501';
  END IF;
  SELECT organization INTO organization_id FROM public.units WHERE id = p_unit;
  BEGIN
    PERFORM public.update_occasion_internal_v1(jsonb_build_object(
      'unit',p_unit,'organization',organization_id,'title','',
      'link',provisional_link,'is_hidden',true,'is_open',false,
      'start_time',now()+interval '30 days','end_time',now()+interval '33 days'));
    SELECT item INTO configuration
      FROM jsonb_array_elements(public.get_occasion_setup_sources(p_unit)) item
      WHERE item->'occasion'->>'link' = provisional_link;
    IF configuration IS NULL THEN RAISE EXCEPTION 'Creation configuration missing'; END IF;
    RAISE EXCEPTION 'Rollback provisional creation' USING ERRCODE = 'ZX001';
  EXCEPTION WHEN SQLSTATE 'ZX001' THEN
    -- Variables retain their values while all writes in the block roll back.
    NULL;
  END;
  configuration := jsonb_set(configuration,'{occasion,link}','""'::jsonb);
  configuration := jsonb_set(configuration,'{forms}',coalesce((SELECT jsonb_agg(jsonb_set(f,'{link}','""'::jsonb))
    FROM jsonb_array_elements(configuration->'forms') f),'[]'::jsonb));
  RETURN configuration;
END $$;

-- Source: database/functions/users/reception_qr_login.sql
CREATE OR REPLACE FUNCTION public.cancel_reception_registration_v1(p_occasion bigint,p_user uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE v_r public.reception_registrations%rowtype; v_actor uuid:=auth.uid(); v_impacts jsonb;
BEGIN
  PERFORM public.lock_activity_aggregate_internal_v1(p_occasion);
  SELECT * INTO v_r FROM public.reception_registrations WHERE occasion=p_occasion AND "user"=p_user FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('code',404,'message','registration_unavailable'); END IF;
  IF NOT public.get_can_use_reception(p_occasion) OR NOT (public.can_manage_occasion_participants(p_occasion) OR (v_r.created_by=v_actor AND (v_r.status='cancelled' OR v_r.created_at>now()-interval '30 minutes'))) THEN
    RETURN jsonb_build_object('code',403,'message','registration_unavailable'); END IF;
  IF v_r.status='cancelled' THEN RETURN jsonb_build_object('code',200,'status',CASE WHEN v_r.auth_revoked_at IS NULL THEN 'domain_blocked_auth_revocation_pending' ELSE 'cancelled' END,'targetUser',p_user); END IF;
  IF NOT public.reception_rate_limit_v1('cancel') THEN RETURN jsonb_build_object('code',429,'message','rate_limited'); END IF;
  UPDATE public.reception_registrations SET status='cancelled',cancelled_by=v_actor,cancelled_at=now() WHERE occasion=p_occasion AND "user"=p_user;
  v_impacts:=public.remove_occasion_user_domain_internal_v1(p_occasion,p_user);
  INSERT INTO public.client_sync_private_scopes(component,occasion,user_id,source_revision)
  SELECT x->>'component',p_occasion,(x->>'userId')::uuid,1 FROM jsonb_array_elements(v_impacts) x ORDER BY x->>'component',x->>'userId'
  ON CONFLICT(component,occasion,user_id) DO UPDATE SET source_revision=public.client_sync_private_scopes.source_revision+1,updated_at=clock_timestamp();
  RETURN jsonb_build_object('code',200,'status','domain_blocked_auth_revocation_pending','targetUser',p_user);
END $$;

