-- Source: database/functions/synchronization/get_client_activity_v1.sql
CREATE OR REPLACE FUNCTION public.get_client_activity_v1(
  p_occasion bigint,
  p_from timestamptz,
  p_to timestamptz
) RETURNS jsonb
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public, extensions
AS $$
  WITH scope AS (
    SELECT
      o.unit,
      o.organization,
      coalesce(o.data->>'timezone', 'UTC') AS timezone,
      public.can_read_client_activity(p_occasion) AS can_read
    FROM public.occasions o
    WHERE o.id = p_occasion
  ),
  activity AS (
    SELECT
      (c.occurred_at AT TIME ZONE s.timezone)::date AS activity_day,
      count(*)::bigint AS action_count,
      sum(greatest(coalesce(items.item_count, 0), 1))::bigint
        AS changed_item_count,
      count(DISTINCT c.actor_id)::bigint AS active_actor_count
    FROM public.client_commits c
    CROSS JOIN scope s
    LEFT JOIN LATERAL (
      SELECT count(*)::bigint AS item_count
      FROM public.client_commit_items item
      WHERE item.commit_id = c.commit_id
    ) items ON true
    WHERE c.occurred_at >= p_from
      AND c.occurred_at < p_to
      AND c.occasion = p_occasion
    GROUP BY activity_day
  ),
  calendar AS (
    SELECT generated::date AS activity_day
    FROM scope s
    CROSS JOIN LATERAL generate_series(
      (p_from AT TIME ZONE s.timezone)::date,
      ((p_to - interval '1 microsecond') AT TIME ZONE s.timezone)::date,
      interval '1 day'
    ) generated
  )
  SELECT CASE
    WHEN p_from IS NULL
      OR p_to IS NULL
      OR p_to <= p_from
      OR p_to - p_from > interval '31 days'
      THEN jsonb_build_object('code', 400)
    WHEN NOT EXISTS (
      SELECT 1
      FROM scope s
      WHERE s.can_read
    ) THEN jsonb_build_object('code', 403)
    ELSE jsonb_build_object(
      'code', 200,
      'data', coalesce((
        SELECT jsonb_agg(
          jsonb_build_object(
            'day', c.activity_day,
            'actionCount', coalesce(a.action_count, 0),
            'changedItemCount', coalesce(a.changed_item_count, 0),
            'activeActorCount', coalesce(a.active_actor_count, 0)
          )
          ORDER BY c.activity_day
        )
        FROM calendar c
        LEFT JOIN activity a USING (activity_day)
      ), '[]'::jsonb)
    )
  END;
$$;

-- Source: database/functions/demo_occasions/catalog.sql
CREATE OR REPLACE FUNCTION public.get_demo_occasions(p_organization bigint)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,extensions AS $$
BEGIN
 IF auth.uid() IS NULL OR NOT EXISTS(SELECT 1 FROM public.user_info
   WHERE id=auth.uid() AND organization=p_organization) THEN
  RAISE insufficient_privilege USING MESSAGE='demo tenant access denied';
 END IF;
 RETURN jsonb_build_object(
  'hasOwnWork', EXISTS(SELECT 1 FROM public.occasions o
    WHERE o.organization=p_organization AND NOT public.is_demo_occasion(o.id)
     AND public.demo_own_work_rule(public.get_is_manager_on_unit(o.unit),public.get_is_editor_on_unit(o.unit),
      public.get_is_manager_on_occasion(o.id),public.get_is_editor_on_occasion(o.id)))
   OR EXISTS(SELECT 1 FROM public.occasion_setup_drafts d WHERE d.organization=p_organization
    AND public.can_create_occasion(d.unit)),
  'items', COALESCE((SELECT jsonb_agg(jsonb_build_object(
    'id',o.id,'link',o.link,'title',o.title,'demoKey',d.demo_key,
    'fixtureVersion',d.fixture_version,'description',d.description,
    'referenceAt',d.reference_at,'image',o.data->>'image',
    'start_time',o.start_time,'end_time',o.end_time,
    'data',jsonb_build_object('timezone',o.data->>'timezone'),
    'features',(SELECT jsonb_agg(jsonb_build_object(
      'code',feature->>'code','is_enabled',(feature->>'is_enabled')::boolean))
      FROM jsonb_array_elements(o.features) feature),
    'stats',(SELECT jsonb_build_object(
      'total',count(*),'storno',count(*) FILTER(WHERE state='storno'),
      'paid_or_sent',count(*) FILTER(WHERE state IN ('paid','sent')),
      'ordered',count(*) FILTER(WHERE state='ordered'),
      'used',count(*) FILTER(WHERE state='used'),
      'users',(SELECT count(*) FROM public.occasion_users ou
        LEFT JOIN public.organization_users org_u
          ON org_u."user"=ou."user" AND org_u.organization=p_organization
        WHERE ou.occasion=o.id AND org_u.is_hidden IS NOT TRUE))
      FROM eshop.tickets t WHERE t.occasion=o.id)) ORDER BY d.sort_order)
   FROM public.demo_occasions d JOIN public.occasions o ON o.id=d.occasion
   WHERE d.organization=p_organization AND d.is_listed),'[]'::jsonb));
END $$;

-- Source: database/functions/events/get_event_attendance_summary.sql
-- Public counts and caller-only attendance state. No participant identifiers.
CREATE OR REPLACE FUNCTION public.get_event_attendance_summary(p_events bigint[])
RETURNS TABLE(event bigint, participant_count bigint, is_signed_in boolean)
LANGUAGE sql STABLE SECURITY DEFINER
SET search_path = public, extensions
AS $function$
  SELECT e.id, count(eu."user"),
         COALESCE(bool_or(eu."user" = auth.uid()), false)
  FROM public.events e
  LEFT JOIN public.event_users eu ON eu.event = e.id
  WHERE e.id = ANY(p_events)
    AND public.event_attendance_read_rule(public.get_is_event_allowed(e.id),public.get_is_editor_view_on_occasion(e.occasion))
  GROUP BY e.id;
$function$;

-- Source: database/functions/events/get_event_feedback_export_for_edit.sql
CREATE OR REPLACE FUNCTION public.get_event_feedback_export_for_edit(
    p_occasion bigint
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions
AS $function$
DECLARE
    v_items JSONB;
BEGIN
    IF NOT public.can_read_schedule_feedback(p_occasion) THEN
        RETURN jsonb_build_object(
            'code', 403,
            'message', 'Insufficient permissions'
        );
    END IF;

    IF NOT public.get_is_event_feedback_enabled_on_occasion(p_occasion) THEN
        RETURN jsonb_build_object(
            'code', 404,
            'message', 'Feedback feature is not enabled for this occasion'
        );
    END IF;

    SELECT COALESCE(
        jsonb_agg(
            jsonb_build_object(
                'event_id', e.id,
                'event_title', e.title,
                'event_start_time', e.start_time,
                'event_end_time', e.end_time,
                'feedback_id', f.id,
                'created_at', f.created_at,
                'updated_at', f.updated_at,
                'rating', f.rating,
                'note', f.note,
                'user_name', NULLIF(
                    btrim(CONCAT_WS(' ', ui.name, ui.surname)), ''
                ),
                'is_anonymous', f."user" IS NULL
            )
            ORDER BY e.start_time ASC, e.title ASC, f.updated_at DESC
        ),
        '[]'::jsonb
    )
    INTO v_items
    FROM public.event_feedback f
    JOIN public.events e ON e.id = f.event
    LEFT JOIN public.user_info ui ON ui.id = f."user"
    WHERE f.occasion = p_occasion;

    RETURN jsonb_build_object('code', 200, 'data', v_items);
END;
$function$;

-- Source: database/functions/events/get_event_participants_for_edit.sql
CREATE OR REPLACE FUNCTION public.get_event_participants_for_edit(
  p_event bigint
)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public, extensions
AS $function$
DECLARE
  v_occasion bigint;
  v_participants jsonb;
BEGIN
  SELECT e.occasion
  INTO v_occasion
  FROM public.events e
  WHERE e.id = p_event;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('code', 404, 'message', 'Event not found');
  END IF;

  IF NOT public.can_read_schedule_participants(v_occasion) THEN
    RETURN jsonb_build_object('code', 403, 'message', 'Insufficient permissions');
  END IF;

  SELECT COALESCE(
    jsonb_agg(
      jsonb_build_object(
        'id', ui.id,
        'name', ui.name,
        'surname', ui.surname,
        'companion_parent', (SELECT uc."user" FROM public.user_companions uc WHERE uc.occasion=v_occasion AND uc.companion=ui.id
          AND EXISTS(SELECT 1 FROM public.event_users parent WHERE parent.event=p_event AND parent."user"=uc."user") LIMIT 1)
      )
      ORDER BY ui.surname, ui.name, ui.id
    ),
    '[]'::jsonb
  )
  INTO v_participants
  FROM public.event_users eu
  JOIN public.user_info ui ON ui.id = eu."user"
  WHERE eu.event = p_event;

  RETURN jsonb_build_object('code', 200, 'data', v_participants);
END;
$function$;

-- Source: database/functions/eshop_forms/get_form_by_link.sql
CREATE OR REPLACE FUNCTION public.get_form_bundle_internal(p_form_id bigint,p_allow_closed boolean DEFAULT false)
RETURNS JSON LANGUAGE plpgsql SECURITY INVOKER
SET search_path = public, extensions AS $$
DECLARE
    allData JSON;
    generated_secret UUID := gen_random_uuid();
    form_exists BOOLEAN;
    is_editor_view BOOLEAN := false;
    occ_id BIGINT;
BEGIN
    -- Check if the form exists
    SELECT EXISTS (
        SELECT 1
        FROM public.forms
        WHERE id = p_form_id
    ) INTO form_exists;

    IF NOT form_exists THEN
        RETURN jsonb_build_object(
            'code', 404,
            'message', 'Form does not exist.'
        );
    END IF;

    SELECT occasion INTO occ_id FROM public.forms WHERE id = p_form_id;
    IF public.is_demo_occasion(occ_id) AND NOT public.can_read_demo_occasion(occ_id) THEN
        RETURN jsonb_build_object('code',404,'message','Form does not exist.');
    END IF;
    is_editor_view := public.can_read_orders(occ_id);


    IF NOT p_allow_closed AND NOT is_editor_view AND NOT EXISTS (
        SELECT 1
        FROM public.forms
        WHERE id = p_form_id AND is_open = true
    ) THEN
        -- If the form is closed, retrieve only the 'header_off' message
        SELECT jsonb_build_object(
            'code', 400,
            'data', jsonb_build_object(
                'organizationIdentity', (SELECT CASE WHEN o.organization=u.organization THEN public.get_verified_unit_identity_internal(u.id) END FROM public.occasions o JOIN public.units u ON u.id=o.unit WHERE o.id=f.occasion),
                'header_off', f.header_off,
                'is_open', f.is_open
            )
        )
        INTO allData
        FROM public.forms f
        WHERE f.id = p_form_id;

        RETURN allData;
    END IF;

    -- If the form is open, retrieve the full form data including dynamic product availability
    SELECT jsonb_build_object(
        'code', 200,
        'data', jsonb_build_object(
            'demo_simulation', public.is_demo_occasion(f.occasion),
            'organizationIdentity', CASE WHEN o.organization=(SELECT organization FROM public.units WHERE id=o.unit) THEN public.get_verified_unit_identity_internal(o.unit) END,
            'capacity', public.get_form_capacity_snapshot_internal(f.id),
            'registrationMode',public.get_form_registration_mode_internal(f.id),
            'participant_capacity',f.participant_capacity,'waitlist_enabled',f.waitlist_enabled,
            'show_remaining_capacity',f.show_remaining_capacity,'waitlist_offer_duration_seconds',f.waitlist_offer_duration_seconds,
            'id', f.id,
            'link', f.link,
            'key', f.key,
            'created_at', f.created_at,
            'data', public.get_effective_form_data(f.id),
            'type', f.type,
            'title', f.title,
            'is_open', f.is_open,
            'header', f.header,
            'header_off', f.header_off,
            'occasion', jsonb_build_object(
                'id', o.id,
                'title', o.title,
                'features', o.features,
                'start_time', o.start_time
            ),
            'blueprint', CASE WHEN jsonb_path_exists(o.features,
                '$[*] ? (@.code == "blueprint" && @.is_enabled == true)') THEN f.blueprint END,
            'deadline_duration_seconds', f.deadline_duration_seconds,
            'account_number', ba.account_number,
            'secret', generated_secret,
            'fields', (
                SELECT jsonb_agg(
                    jsonb_build_object(
                        'id', ff.id,
                        'title', ff.title,
                        'description', ff.description,
                        'data', ff.data,
                        'type', ff.type,
                        'is_required', ff.is_required,
                        'is_hidden', ff.is_hidden,
                        'is_ticket_field', ff.is_ticket_field,
                        'order', ff."order",
                        'product_type_data', (
                            CASE
                                WHEN ff.product_type IS NOT NULL THEN
                                    jsonb_build_object(
                                        'id', pt.id,
                                        'title', pt.title,
                                        'description', pt.description,
                                        'type', pt.type,
                                        'data', pt.data,
                                        'occasion', pt.occasion,
                                        'products', (
                                            SELECT jsonb_agg(
                                                jsonb_build_object(
                                                    'id', p.id,
                                                    'title', p.title,
                                                    'description', p.description,
                                                    'price', p.price,
                                                    'currency_code', p.currency_code,
                                                    'data', p.data,
                                                    'order', p."order",
                                                    'ordered_count', (
                                                        SELECT count(*)
                                                        FROM eshop.order_product_ticket opt
                                                        WHERE opt.product = p.id
                                                    ),
                                                    'maximum', p.maximum,
                                                    'is_dynamically_available', is_product_dynamically_available(p.id)
                                                ) ORDER BY COALESCE(p."order", 0)
                                            )
                                            FROM eshop.products p
                                            WHERE p.product_type = pt.id
                                              AND NOT p.is_hidden
                                        )
                                    )
                                ELSE NULL
                            END
                        )
                    ) ORDER BY COALESCE(ff."order", 0)
                )
                FROM public.form_fields ff
                LEFT JOIN eshop.product_types pt ON ff.product_type = pt.id
                WHERE ff.form = f.id AND ff.is_hidden = false
            )
        )
    )
    INTO allData
    FROM public.forms f
    LEFT JOIN eshop.bank_accounts ba ON f.bank_account = ba.id
    LEFT JOIN public.occasions o ON f.occasion = o.id
    WHERE f.id = p_form_id;

    RETURN allData;
END;
$$;

-- Source: database/functions/eshop_forms/get_forms_by_link.sql
CREATE OR REPLACE FUNCTION public.get_forms_by_link(
    occasion_link TEXT
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
    v_occasion_id BIGINT;
    forms_data JSONB;
BEGIN
    -- Step 1: Resolve the occasion ID from the provided link.
    SELECT id
    INTO v_occasion_id
    FROM public.occasions
    WHERE id = public.resolve_occasion_link_internal(occasion_link)
      AND organization = (SELECT ui.organization FROM public.user_info ui WHERE ui.id = auth.uid());

    -- Step 2: If no occasion is found, throw a 'no_data_found' exception.
    IF v_occasion_id IS NULL THEN
        RAISE EXCEPTION 'Occasion not found for link: %', occasion_link USING ERRCODE = 'PGRST001'; -- Custom error for PostgREST
    END IF;

    -- Step 3: Verify if the user has editor rights for this occasion.
    -- If not, throw an 'insufficient_privilege' exception.
    IF NOT public.can_read_form_catalog(v_occasion_id) THEN
        RAISE EXCEPTION 'User is not authorized to view forms for this occasion.' USING ERRCODE = '42501'; -- insufficient_privilege
    END IF;

    -- Step 4: Aggregate forms for the occasion into a JSONB array.
    -- The order statistics are nested within a 'stats' JSON object.
    SELECT jsonb_agg(
        jsonb_build_object(
            'id', f.id,'participant_capacity',f.participant_capacity,'waitlist_enabled',f.waitlist_enabled,
            'show_remaining_capacity',f.show_remaining_capacity,'waitlist_offer_duration_seconds',f.waitlist_offer_duration_seconds,
            'capacity',public.get_form_capacity_snapshot_internal(f.id),'registrationMode',public.get_form_registration_mode_internal(f.id),
            'created_at', f.created_at,
            'title', f.title,
            'data', f.data,
            'key', f.key,
            'occasion', f.occasion,
            'type', f.type,
            'is_open', f.is_open,
            'link', f.link,
            'blueprint', f.blueprint,
            'updated_at', f.updated_at,
            'stats', jsonb_build_object(
                'total', COALESCE(order_stats.total, 0),
                'storno', COALESCE(order_stats.storno, 0),
                'paid_or_sent', COALESCE(order_stats.paid_or_sent, 0),
                'ordered', COALESCE(order_stats.ordered, 0)
            )
        ) ORDER BY f.created_at
    )
    INTO forms_data
    FROM public.forms f
    LEFT JOIN (
        -- This subquery calculates all required counts in a single pass over the orders table.
        SELECT
            (data->>'form')::uuid AS form_key,
            COUNT(*) AS total,
            COUNT(*) FILTER (WHERE state = 'storno') AS storno,
            COUNT(*) FILTER (WHERE state IN ('paid', 'sent')) AS paid_or_sent,
            COUNT(*) FILTER (WHERE state = 'ordered') AS ordered
        FROM eshop.orders
        WHERE data->>'form' IS NOT NULL -- Ensure the key exists before casting
        GROUP BY form_key
    ) AS order_stats ON f.key = order_stats.form_key
    WHERE f.occasion = v_occasion_id;

    -- Step 5: If no forms were found, ensure an empty JSON array is returned.
    IF forms_data IS NULL THEN
        forms_data := '[]'::jsonb;
    END IF;

    -- Step 6: Return the data directly.
    RETURN forms_data;
END;
$$;

-- Source: database/functions/groups/get_group_places_for_map_v1.sql
-- The map's authenticated occasion members retain their existing group-place
-- projection, scoped to one occasion and carrying the original place revision.
CREATE OR REPLACE FUNCTION public.get_group_places_for_map_v1(p_occasion bigint)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,extensions AS $$
BEGIN
 IF NOT public.can_read_group_places(p_occasion) THEN
  RAISE insufficient_privilege USING MESSAGE='occasion member required'; END IF;
 RETURN coalesce((SELECT jsonb_agg(jsonb_build_object('id',g.id,'title',g.title,'place',g.place,'places',
  jsonb_build_object('id',p.id,'occasion',p.occasion,'unit',p.unit,'title',p.title,'description',p.description,
    'coordinates',p.coordinates,'type',p.type,'is_hidden',p.is_hidden,'order',p."order",'icon',p.icon,'aggregate_version',coalesce(v.version,0))) ORDER BY g.id)
  FROM public.user_group_info g JOIN public.places p ON p.id=g.place AND p.occasion=g.occasion
  LEFT JOIN public.client_aggregate_versions v ON v.aggregate_type='place' AND v.scope_type='occasion' AND v.scope_id=p_occasion AND v.aggregate_id=p.id::text
  WHERE g.occasion=p_occasion AND (NOT public.is_demo_unit(p.unit) OR public.demo_unit_can_read(p.unit))),'[]'::jsonb);
END $$;

-- Source: database/functions/public_links/legacy_readers.sql
CREATE OR REPLACE FUNCTION public.get_inclusion_type_groups_by_link(p_occasion_link text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
SET search_path = public, extensions
AS $function$
DECLARE
    v_occasion_id bigint;
    v_occasion_data jsonb;
    v_groups_data jsonb;
    result jsonb;
BEGIN
    -- Find the occasion ID from the provided link.
    SELECT id INTO v_occasion_id FROM public.occasions WHERE id = public.resolve_occasion_link_internal(p_occasion_link);
    IF v_occasion_id IS NULL THEN
        RAISE EXCEPTION 'Occasion with link % not found.', p_occasion_link;
    END IF;

    -- Permission check to ensure the user can view data for this occasion.
    IF NOT can_read_orders(v_occasion_id) THEN
        RAISE EXCEPTION 'User is not authorized to view this occasion.';
    END IF;

    -- Get the occasion details.
    SELECT to_jsonb(o) INTO v_occasion_data FROM public.occasions o WHERE id = v_occasion_id;

    -- Aggregate all groups for the occasion, and for each group, aggregate its inclusion types.
    SELECT COALESCE(jsonb_agg(groups_with_types), '[]'::jsonb)
    INTO v_groups_data
    FROM (
        SELECT
            jsonb_build_object(
                'id', g.id,
                'created_at', g.created_at,
                'updated_at', g.updated_at,
                'title', g.title,
                'type', g.type,
                'occasion', g.occasion,
                'inclusion_types', (
                    SELECT COALESCE(jsonb_agg(
                        jsonb_build_object(
                            'id', t.id,
                            'created_at', t.created_at,
                            'updated_at', t.updated_at,
                            'title', t.title,
                            'inclusion_type_group', t.inclusion_type_group,
                            'data', t.data
                        ) ORDER BY t.created_at
                    ), '[]'::jsonb)
                    FROM public.inclusion_types t
                    WHERE t.inclusion_type_group = g.id
                )
            ) AS groups_with_types
        FROM public.inclusion_type_groups g
        WHERE g.occasion = v_occasion_id
        ORDER BY g.created_at
    ) AS subquery;

    -- Construct the final bundle.
    result := jsonb_build_object(
        'occasion', v_occasion_data,
        'groups', v_groups_data
    );

    RETURN result;
EXCEPTION
    WHEN OTHERS THEN
        RETURN jsonb_build_object('code', 500, 'message', SQLERRM);
END;
$function$;

-- Source: database/functions/information/get_information_editor_bundle_v1.sql
CREATE OR REPLACE FUNCTION public.get_information_editor_bundle_v1(p_occasion bigint, p_type text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path=public,extensions
AS $function$
DECLARE v_information jsonb;
BEGIN
  IF NOT public.can_read_information_editor_bundle(p_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='occasion editor view required';
  END IF;
  SELECT COALESCE(jsonb_agg(public.get_information_command_data_v1(i.id)||
    jsonb_build_object('aggregate_version',COALESCE(v.version,0))
    ORDER BY i."order" NULLS LAST,i.id),'[]'::jsonb) INTO v_information
  FROM public.information i LEFT JOIN public.client_aggregate_versions v
    ON v.aggregate_type='information' AND v.scope_type='occasion'
    AND v.scope_id=p_occasion AND v.aggregate_id=i.id::text
  WHERE i.occasion=p_occasion AND (CASE WHEN p_type IS NULL
    THEN NULLIF(i.type,'') IS NULL ELSE i.type=p_type END);
  RETURN jsonb_build_object('code',200,'information',v_information);
END; $function$
;

-- Source: database/functions/inventory/get_inventory_pool_bundle.sql
CREATE OR REPLACE FUNCTION public.get_inventory_pool_bundle(p_inventory_pool_id bigint)
RETURNS jsonb
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
    v_occasion_id bigint;
    v_pool_data jsonb;
    v_occasion_data jsonb;
    v_resources_data jsonb;
    v_contexts_data jsonb;
    v_places_data jsonb;
    v_products_data jsonb;
    v_product_inventory_contexts_data jsonb; -- New variable for the join table data
    result jsonb;
BEGIN
    -- Get occasion for permission check from the inventory pool
    SELECT occasion INTO v_occasion_id
    FROM public.inventory_pools
    WHERE id = p_inventory_pool_id;

    IF v_occasion_id IS NULL THEN
        RAISE EXCEPTION 'Inventory Pool not found.';
    END IF;

    -- Permission check
    IF NOT can_read_orders(v_occasion_id) THEN
        RAISE EXCEPTION 'User is not authorized to view this occasion.';
    END IF;

    -- Get the main inventory pool details
    SELECT to_jsonb(ip) INTO v_pool_data FROM public.inventory_pools ip WHERE ip.id = p_inventory_pool_id;

    -- Get the full occasion details
    SELECT to_jsonb(o) INTO v_occasion_data
    FROM public.occasions o
    WHERE o.id = v_occasion_id;

    -- Aggregate all resources for the pool, and for each resource, aggregate its slots.
    SELECT COALESCE(jsonb_agg(resources_with_slots), '[]'::jsonb)
    INTO v_resources_data
    FROM (
        SELECT
            jsonb_build_object(
                'id', r.id,
                'created_at', r.created_at,
                'updated_at', r.updated_at,
                'title', r.title,
                'description', r.description,
                'capacity', r.capacity,
                'booking_rules', r.booking_rules,
                'inventory_pool', r.inventory_pool,
                'place', r.place,
                'occasion', r.occasion,
                'unit', r.unit,
                'data', r.data,
                'aggregate_version', COALESCE((
                    SELECT av.version
                    FROM public.client_aggregate_versions av
                    WHERE av.aggregate_type = 'resource'
                      AND av.scope_type = 'occasion'
                      AND av.scope_id = v_occasion_id
                      AND av.aggregate_id = r.id::text
                ), 0),
                'slots', (
                    SELECT COALESCE(jsonb_agg(
                        jsonb_build_object(
                            'id', rs.id,
                            'resource', rs.resource,
                            'title', rs.title,
                            'data', rs.data
                        ) ORDER BY rs.id
                    ), '[]'::jsonb)
                    FROM public.resource_slots rs
                    WHERE rs.resource = r.id
                )
            ) AS resources_with_slots
        FROM public.resources r
        WHERE r.inventory_pool = p_inventory_pool_id
        ORDER BY r.title
    ) AS subquery;

    -- Aggregate all inventory contexts for the pool, sorted by the 'order' field
    SELECT COALESCE(jsonb_agg(to_jsonb(ic) ORDER BY ic.order), '[]'::jsonb)
    INTO v_contexts_data
    FROM public.inventory_contexts ic
    WHERE ic.inventory_pool = p_inventory_pool_id;

    -- Aggregate all places for the occasion
    SELECT COALESCE(jsonb_agg(to_jsonb(p) ORDER BY p.order), '[]'::jsonb)
    INTO v_places_data
    FROM public.places p
    WHERE p.occasion = v_occasion_id;

    -- MODIFICATION START
    -- Aggregate products that are linked to the inventory contexts of this specific pool.
    SELECT COALESCE(jsonb_agg(to_jsonb(pr)), '[]'::jsonb)
    INTO v_products_data
    FROM (
        SELECT DISTINCT pr.*
        FROM eshop.products pr
        JOIN eshop.product_inventory_contexts pic ON pr.id = pic.product
        JOIN public.inventory_contexts ic ON pic.inventory_context = ic.id
        WHERE ic.inventory_pool = p_inventory_pool_id
    ) pr;

    -- Aggregate the product <-> inventory_context join table entries for this pool's contexts.
    SELECT COALESCE(jsonb_agg(to_jsonb(pic)), '[]'::jsonb)
    INTO v_product_inventory_contexts_data
    FROM eshop.product_inventory_contexts pic
    JOIN public.inventory_contexts ic ON pic.inventory_context = ic.id
    WHERE ic.inventory_pool = p_inventory_pool_id;

    -- Construct the final bundle object, now including context-specific products and the join table data.
    result := jsonb_build_object(
        'pool', v_pool_data,
        'occasion', v_occasion_data,
        'resources', v_resources_data,
        'contexts', v_contexts_data,
        'places', v_places_data,
        'products', v_products_data,
        'product_inventory_contexts', v_product_inventory_contexts_data
        ,'aggregate_version', COALESCE((SELECT av.version
          FROM public.client_aggregate_versions av
          WHERE av.aggregate_type='inventory_pool' AND av.scope_type='occasion'
            AND av.scope_id=v_occasion_id
            AND av.aggregate_id=p_inventory_pool_id::text),0)
    );
    -- MODIFICATION END

    RETURN result;
EXCEPTION
    WHEN OTHERS THEN
        RETURN jsonb_build_object('code', 500, 'message', SQLERRM);
END;
$$ LANGUAGE plpgsql;

