-- Source: database/functions/map/get_map_editor_bundle_v1.sql
CREATE OR REPLACE FUNCTION public.get_map_editor_bundle_v1(p_occasion bigint)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path = public, extensions
AS $function$
  SELECT CASE WHEN public.can_read_map_editor_bundle(p_occasion) IS NOT TRUE
    THEN jsonb_build_object('code',403)
    ELSE jsonb_build_object(
      'code',200,
      'places',COALESCE((SELECT jsonb_agg(to_jsonb(p)||jsonb_build_object(
        'aggregate_version',COALESCE(v.version,0)) ORDER BY p."order" NULLS LAST,p.id)
        FROM public.places p LEFT JOIN public.client_aggregate_versions v
          ON v.aggregate_type='place' AND v.scope_type='occasion'
          AND v.scope_id=p_occasion AND v.aggregate_id=p.id::text
        WHERE p.occasion=p_occasion),'[]'::jsonb),
      'placeTypes',COALESCE((SELECT jsonb_agg(to_jsonb(t)||jsonb_build_object(
        'aggregate_version',COALESCE(v.version,0)) ORDER BY t."order" NULLS LAST,t.id)
        FROM public.place_types t LEFT JOIN public.client_aggregate_versions v
          ON v.aggregate_type='place_type' AND v.scope_type='occasion'
          AND v.scope_id=p_occasion AND v.aggregate_id=t.id::text
        WHERE t.occasion=p_occasion),'[]'::jsonb),
      'paths',COALESCE((SELECT jsonb_agg(to_jsonb(pg)||jsonb_build_object(
        'aggregate_version',COALESCE(v.version,0)) ORDER BY pg."order" NULLS LAST,pg.id)
        FROM public.path_groups pg LEFT JOIN public.client_aggregate_versions v
          ON v.aggregate_type='path' AND v.scope_type='occasion'
          AND v.scope_id=p_occasion AND v.aggregate_id=pg.id::text
        WHERE pg.occasion=p_occasion),'[]'::jsonb),
      'icons',COALESCE((SELECT jsonb_agg(to_jsonb(i)||jsonb_build_object(
        'aggregate_version',COALESCE(v.version,0)) ORDER BY i.link,i.id)
        FROM public.occasions o JOIN public.icons i ON i.organization=o.organization
          AND (i.unit=o.unit OR i.unit IS NULL)
        LEFT JOIN public.client_aggregate_versions v
          ON v.aggregate_type='icon' AND v.scope_type='unit'
          AND v.scope_id=o.unit AND v.aggregate_id=i.id::text
        WHERE o.id=p_occasion),'[]'::jsonb)) END;
$function$
;

-- Source: database/functions/eshop_bank_accounts/get_my_admin_bank_accounts.sql
CREATE OR REPLACE FUNCTION public.get_my_admin_bank_accounts()
RETURNS TABLE (
    id bigint,
    account_number text,
    account_number_human_readable text,
    title text,
    creditor_name text,
    type text,
    token_masked text,
    token_expiry_date timestamptz,
    supported_currencies text[],
    linked_units text[],
    last_fetch_time timestamptz,
    last_fio_fetch_time timestamptz,
    bank_sync jsonb
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions
AS $$
BEGIN
    RETURN QUERY
    SELECT
        ba.id,
        ba.account_number,
        ba.account_number_human_readable,
        ba.title,
        ba.creditor_name,
        ba.type,
        NULL::text as token_masked,
        CASE WHEN public.can_manage_bank_account(ba.id) THEN
          (public.get_bank_sync_connection(ba.id)->>'token_expiry_at')::timestamptz END as token_expiry_date,
        ba.supported_currencies,
        ARRAY(
            SELECT u.title 
            FROM eshop.unit_bank_accounts uba
            JOIN public.units u ON uba.unit = u.id
            WHERE uba.bank_account = ba.id
        ) as linked_units,
        ba.last_fetch_time,
        ba.last_fio_fetch_time,
        CASE WHEN public.can_manage_bank_account(ba.id) THEN
          public.get_bank_sync_connection(ba.id) END AS bank_sync
    FROM eshop.bank_accounts ba
    JOIN eshop.bank_account_users bau ON ba.id = bau.bank_account
    WHERE bau."user" = auth.uid() AND bau.is_admin = true
    AND ba.type != 'cash'
    ORDER BY ba.title;
END;
$$;

-- Source: database/functions/others/get_occasion_by_link.sql
-- Create a function to get occasion by link and check for active orders
CREATE OR REPLACE FUNCTION public.get_occasion_by_link(link_param text)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
    occ_record public.occasions;
    has_orders boolean;
    result jsonb;
BEGIN
    -- Legacy links may repeat across tenants after the canonical merge.
    -- This RPC supplies editor data, so resolve only inside the caller's tenant.
    SELECT o.* INTO occ_record
    FROM public.occasions o
    WHERE o.id = public.resolve_occasion_link_internal(link_param)
      AND o.organization = (
          SELECT ui.organization FROM public.user_info ui WHERE ui.id = auth.uid()
      );

    -- Return null if not found
    IF occ_record IS NULL THEN
        RETURN NULL;
    END IF;

    IF public.is_demo_occasion(occ_record.id) AND NOT public.can_read_demo_occasion(occ_record.id) THEN
        RAISE insufficient_privilege USING MESSAGE='Demo access denied';
    END IF;

    IF NOT public.can_read_occasion_editor_data(occ_record.id) THEN
        RAISE insufficient_privilege USING MESSAGE='occasion editor view required';
    END IF;

    -- 2. Check for active orders
    SELECT EXISTS (
        SELECT 1
        FROM eshop.orders
        WHERE occasion = occ_record.id
    ) INTO has_orders;

    -- 3. Merge the occasion record with the new boolean flag
    result := to_jsonb(occ_record) || jsonb_build_object('has_orders', has_orders);

    RETURN result;
END;
$$;

-- Source: database/functions/others/duplicate_occasion_client_sync_v1.sql
-- Return only authorized destinations. The navigation unit list does not carry
-- membership flags and may include units visible only through an occasion.
CREATE OR REPLACE FUNCTION public.get_occasion_copy_units(p_occasion bigint)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER
SET search_path = public, extensions AS $$
DECLARE v_org bigint; v_unit bigint;
BEGIN
  SELECT organization, unit INTO v_org, v_unit FROM public.occasions WHERE id=p_occasion;
  IF auth.uid() IS NULL OR v_unit IS NULL
     OR NOT public.can_copy_occasion_source(p_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='source unit manager required';
  END IF;
  RETURN COALESCE((SELECT jsonb_agg(jsonb_build_object(
    'id', u.id, 'title', u.title, 'organization', u.organization) ORDER BY u.title,u.id)
    FROM public.units u WHERE u.organization=v_org AND public.can_copy_occasion_target(u.id) AND NOT public.is_demo_unit(u.id)), '[]'::jsonb);
END; $$;

-- Source: database/functions/others/get_occasion_for_context.sql
-- Object-derived context, shared by participant and editor client readers.
CREATE OR REPLACE FUNCTION public.get_occasion_for_context_v1(p_occasion bigint)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER
SET search_path = public, extensions AS $$
DECLARE o public.occasions; privileged boolean;
BEGIN
 SELECT * INTO o FROM public.occasions WHERE id=p_occasion;
 IF NOT FOUND THEN RAISE insufficient_privilege USING MESSAGE='occasion unavailable'; END IF;
 privileged := public.can_read_occasion_editor_data(o.id);
 IF public.is_demo_occasion(o.id) AND NOT public.can_read_demo_occasion(o.id) THEN
   RAISE insufficient_privilege USING MESSAGE='occasion unavailable';
 END IF;
 IF privileged THEN
   RETURN to_jsonb(o);
 END IF;
 IF auth.uid() IS NOT NULL AND EXISTS(SELECT 1 FROM public.occasion_users
     WHERE occasion=o.id AND "user"=auth.uid()) THEN
   RETURN to_jsonb(o)-'occasion_hidden';
 END IF;
 IF o.is_hidden IS DISTINCT FROM false OR o.is_open IS DISTINCT FROM true THEN
   RAISE insufficient_privilege USING MESSAGE='occasion unavailable';
 END IF;
 RETURN jsonb_build_object('id',o.id,'title',o.title,'description',o.description,
   'link',o.link,'start_time',o.start_time,'end_time',o.end_time,
   'is_open',o.is_open,'is_hidden',false,'is_promoted',o.is_promoted,
   'organization',o.organization,'unit',o.unit,
   'data',jsonb_build_object('timezone',o.data->'timezone'));
END $$;

-- Source: database/functions/others/get_occasion_for_edit_v1.sql
-- Canonical merges can contain the same legacy occasion link in more than one
-- organization. Resolve the edit reader inside the authenticated user's tenant
-- before checking occasion-level permissions.
CREATE OR REPLACE FUNCTION public.get_occasion_for_edit_v1(p_link text)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path=public,extensions
AS $$
DECLARE
  v_occasion bigint;
  v_result jsonb;
BEGIN
  SELECT o.id
  INTO v_occasion
  FROM public.occasions o
  WHERE o.id = public.resolve_occasion_link_internal(p_link)
    AND o.organization = (
      SELECT ui.organization
      FROM public.user_info ui
      WHERE ui.id = auth.uid()
    );

  IF v_occasion IS NULL THEN
    RAISE invalid_parameter_value USING MESSAGE = 'occasion not found';
  END IF;

  IF NOT public.can_read_occasion_editor_data(v_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE = 'occasion editor view required';
  END IF;

  SELECT to_jsonb(o) || jsonb_build_object(
    'aggregate_version', COALESCE(v.version, 0)
  )
  INTO v_result
  FROM public.occasions o
  LEFT JOIN public.client_aggregate_versions v
    ON v.aggregate_type = 'occasion'
    AND v.scope_type = 'occasion'
    AND v.scope_id = o.id
    AND v.aggregate_id = o.id::text
  WHERE o.id = v_occasion;

  RETURN v_result;
END;
$$;

-- Source: database/functions/users/get_occasion_membership_for_edit_v1.sql
CREATE OR REPLACE FUNCTION public.get_occasion_membership_for_edit_v1(p_occasion bigint,p_user uuid)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,extensions AS $$
BEGIN
 IF auth.uid() IS NULL OR NOT(auth.uid()=p_user OR public.can_manage_occasion_participants(p_occasion)) THEN RAISE insufficient_privilege USING MESSAGE='profile owner or manager required'; END IF;
 RETURN (SELECT to_jsonb(ou)||jsonb_build_object('aggregate_version',coalesce(v.version,0)) FROM public.occasion_users ou LEFT JOIN public.client_aggregate_versions v ON v.aggregate_type='occasion_user' AND v.scope_type='occasion' AND v.scope_id=p_occasion AND v.aggregate_id=p_user::text WHERE ou.occasion=p_occasion AND ou."user"=p_user);
END $$;

-- Source: database/functions/occasion_setup/bank_accounts.sql
-- Draft editors see payment instructions, never credentials or account-admin
-- operations. Creating/linking accounts continues through the existing unit UI.
CREATE OR REPLACE FUNCTION public.get_occasion_setup_bank_accounts(p_id uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE d public.occasion_setup_drafts;
BEGIN
 SELECT * INTO d FROM public.occasion_setup_drafts WHERE id=p_id;
 IF NOT FOUND OR auth.uid() IS NULL OR NOT public.can_create_occasion(d.unit) THEN
  RAISE insufficient_privilege USING MESSAGE='Draft access denied'; END IF;
 RETURN jsonb_build_object('canManage',public.get_is_manager_on_unit(d.unit),'accounts',coalesce((
  SELECT jsonb_agg(jsonb_build_object('id',b.id,'title',b.title,
    'display',coalesce(nullif(b.account_number_human_readable,''),b.account_number),
    'currencies',b.supported_currencies,'priority',u.priority,'type',b.type,
    'bank_sync',(SELECT jsonb_build_object('state',c.state,'mode',c.mode)
      FROM eshop.bank_sync_connections c WHERE c.bank_account_id=b.id),
    'bank_sync_warning',public.bank_sync_warning(b.id),
    'fingerprint',public.occasion_setup_bank_fingerprint_internal(b.id)) ORDER BY u.priority,b.id)
  FROM eshop.unit_bank_accounts u JOIN eshop.bank_accounts b ON b.id=u.bank_account
  WHERE u.unit=d.unit AND b.type<>'CASH'),'[]'::jsonb));
END $$;

-- Source: database/functions/occasion_setup/blueprint_layout.sql
CREATE OR REPLACE FUNCTION public.get_occasion_setup_blueprint_resources(p_draft uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE d public.occasion_setup_drafts; doc jsonb; source_id bigint; resources jsonb; source_resources jsonb;
BEGIN
 SELECT * INTO d FROM public.occasion_setup_drafts WHERE id=p_draft;
 IF d.id IS NULL OR auth.uid() IS NULL OR NOT public.can_create_occasion(d.unit) THEN RAISE insufficient_privilege USING MESSAGE='Draft access denied'; END IF;
 source_id:=(d.data->>'sourceId')::bigint;
 IF source_id IS NOT NULL AND (NOT public.can_copy_occasion_source(source_id) OR NOT EXISTS(SELECT 1 FROM public.occasions WHERE id=source_id AND organization=d.organization)) THEN RAISE insufficient_privilege USING MESSAGE='Copy source denied'; END IF;
 doc:=coalesce(d.data#>'{blueprintLayoutDraft,layout}',jsonb_build_object(
  'schemaVersion',2,'symbolSetVersion',1,'canvas',jsonb_build_object('x',0,'y',0,'width',2400,'height',1600,'fill','#FFFFFFFF'),
  'styles','{}'::jsonb,'seatingDefaults','{}'::jsonb,'textPolicy',jsonb_build_object('language','und','direction','auto'),
  'nodes','[]'::jsonb,'sections','[]'::jsonb,'selectionUnits','[]'::jsonb,'attachments','[]'::jsonb,'presets','[]'::jsonb));
 IF doc->>'schemaVersion' IS DISTINCT FROM '2' THEN RAISE check_violation USING MESSAGE='BLUEPRINT_LAYOUT_MIGRATION_REQUIRED';END IF;
  resources:=public.blueprint_canonical_text_resources_internal(doc,NULL,p_draft,true);
  source_resources:=CASE WHEN source_id IS NULL THEN '{}'::jsonb ELSE public.blueprint_canonical_text_resources_internal(doc,source_id,NULL,true) END;
  resources:=resources||jsonb_build_object(
   'fontFamilies',coalesce(source_resources->'fontFamilies','{}')||(resources->'fontFamilies'),
   'textLayouts',coalesce(source_resources->'textLayouts','{}')||(resources->'textLayouts'),
   'numberSymbols',coalesce(source_resources->'numberSymbols','{}')||(resources->'numberSymbols'),
   'assets',public.blueprint_canonical_asset_resources_internal(doc,source_id,NULL)||public.blueprint_canonical_asset_resources_internal(doc,NULL,d.unit));
  RETURN public.bound_document_data_v1(jsonb_build_object('resources',resources));
END $$;

-- Source: database/functions/occasion_setup/communication.sql
CREATE OR REPLACE FUNCTION public.get_occasion_setup_communication(p_id uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE d public.occasion_setup_drafts; u public.units; manager boolean; version bigint; snapshot record;
BEGIN
 SELECT * INTO d FROM public.occasion_setup_drafts WHERE id=p_id;
 IF NOT FOUND OR auth.uid() IS NULL OR NOT public.can_create_occasion(d.unit) THEN
  RAISE insufficient_privilege USING MESSAGE='Draft access denied'; END IF;
 SELECT row_u,coalesce(v.version,0) AS aggregate_version INTO snapshot FROM public.units row_u
 LEFT JOIN public.client_aggregate_versions v ON v.aggregate_type='unit' AND v.scope_type='unit'
   AND v.scope_id=row_u.id AND v.aggregate_id=row_u.id::text WHERE row_u.id=d.unit;
 u:=snapshot.row_u; version:=snapshot.aggregate_version;
 manager:=public.get_is_manager_on_unit(d.unit);
 RETURN jsonb_build_object('canManage',manager,
  'firstEvent',NOT EXISTS(SELECT 1 FROM public.occasions WHERE unit=d.unit),
  'defaults',jsonb_build_object('replyTo',nullif(btrim(u.data->>'reply_to'),''),
    'tone',CASE WHEN u.data->>'communication_tone'='informal' THEN 'informal' ELSE 'formal' END,
    'remindersEnabled',coalesce((u.data->>'is_reminder_enabled')::boolean,true),
    'leadSeconds',coalesce((u.data->>'reminder_interval_seconds')::bigint,86400)),
  'unit',CASE WHEN manager THEN jsonb_build_object('id',u.id,'title',u.title,'data',u.data,'aggregate_version',coalesce(version,0)) ELSE NULL END);
END $$;

-- Source: database/functions/occasion_setup/drafts.sql
CREATE OR REPLACE FUNCTION public.get_occasion_setup_drafts(p_unit bigint)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions AS $$
BEGIN
  IF auth.uid() IS NULL OR NOT public.can_create_occasion(p_unit) THEN
    RAISE EXCEPTION 'Draft access denied' USING ERRCODE = '42501';
  END IF;
  RETURN COALESCE((SELECT jsonb_agg(to_jsonb(d) ORDER BY updated_at DESC)
    FROM public.occasion_setup_drafts d WHERE unit = p_unit), '[]'::jsonb);
END $$;

-- Source: database/functions/occasion_setup/sources.sql
-- Configuration only: no responses, orders, customers or reservation secrets.
CREATE OR REPLACE FUNCTION public.get_occasion_setup_sources(p_unit bigint)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions AS $$
BEGIN
  IF auth.uid() IS NULL OR NOT public.can_create_occasion(p_unit) THEN
    RAISE EXCEPTION 'Source access denied' USING ERRCODE = '42501';
  END IF;
  RETURN COALESCE((SELECT jsonb_agg(jsonb_build_object(
    'occasion', jsonb_build_object('id',o.id,'title',o.title,'link',o.link,
      'start_time',o.start_time,'end_time',o.end_time,'description',o.description,
      'data',o.data,'features',o.features,'is_open',false,'is_hidden',true),
    'forms', COALESCE((SELECT jsonb_agg(jsonb_build_object(
      'title',f.title,'link',f.link,'type',f.type,'data',f.data,'header',f.header,
      'header_off',f.header_off,'deadline_duration_seconds',f.deadline_duration_seconds,
      'is_open',false,'blueprint',f.blueprint,
      'fields',COALESCE((SELECT jsonb_agg(jsonb_build_object(
        'title',ff.title,'description',ff.description,'data',ff.data,'type',ff.type,
        'is_required',ff.is_required,'is_hidden',ff.is_hidden,'order',ff."order",
        'is_ticket_field',ff.is_ticket_field,
        'product_type_data',(SELECT jsonb_build_object('id',pt.id,'title',pt.title,
          'description',pt.description,'type',pt.type,'data',pt.data,
          'products',COALESCE((SELECT jsonb_agg(jsonb_build_object(
            'id',p.id,'title',p.title,'description',p.description,'price',p.price,
            'currency_code',p.currency_code,'maximum',p.maximum,'data',p.data,
            'is_hidden',p.is_hidden,'order',p."order") ORDER BY p."order",p.id)
            FROM eshop.products p WHERE p.product_type=pt.id),'[]'::jsonb))
          FROM eshop.product_types pt WHERE pt.id=ff.product_type)) ORDER BY ff."order",ff.id)
        FROM public.form_fields ff WHERE ff.form=f.id),'[]'::jsonb)) ORDER BY f.id)
      FROM public.forms f WHERE f.occasion=o.id),'[]'::jsonb),
    'blueprints',COALESCE((SELECT jsonb_agg(jsonb_build_object(
      'blueprintLayoutDraft',CASE WHEN b.layout IS NULL THEN NULL ELSE jsonb_build_object(
        'layout',b.layout,
        'seatBindings',coalesce((SELECT jsonb_agg(jsonb_build_object('nodeId',sb.node_id,'productId',spot.product,'title',spot.title,'groupNodeId',sb.group_node,'selectionUnitId',sb.selection_unit,'blocked',sb.blocked) ORDER BY sb.node_id)
          FROM eshop.blueprint_seat_bindings sb JOIN eshop.spots spot ON spot.id=sb.spot WHERE sb.blueprint=b.id),'[]'),
        'groupProducts',coalesce((SELECT jsonb_agg(jsonb_build_object('groupNodeId',gp.group_node,'productId',gp.product) ORDER BY gp.group_node) FROM eshop.blueprint_group_products gp WHERE gp.blueprint=b.id),'[]'),
        'areaBindings',coalesce((SELECT jsonb_agg(jsonb_build_object('nodeId',ab.node_id,'productId',ab.product,'inventoryContextId',ab.inventory_context) ORDER BY ab.node_id) FROM eshop.blueprint_area_bindings ab WHERE ab.blueprint=b.id),'[]')) END,
      'id',b.id,'title',b.title) ORDER BY b.id)
      FROM eshop.blueprints b WHERE b.occasion=o.id AND b.layout IS NOT NULL),'[]'::jsonb),
    'program',COALESCE((SELECT jsonb_agg(jsonb_build_object('title',e.title,
      'start_time',e.start_time,'end_time',e.end_time,'description',e.description))
      FROM public.events e WHERE e.occasion=o.id),'[]'::jsonb),
    'information',COALESCE((SELECT jsonb_agg(jsonb_build_object('title',i.title,
      'description',i.description,'type',i.type,'data',i.data) ORDER BY i."order",i.id)
      FROM public.information i WHERE i.occasion=o.id),'[]'::jsonb)
    ) ORDER BY o.start_time DESC,o.id DESC) FROM public.occasions o WHERE o.unit=p_unit),'[]'::jsonb);
END $$;

-- Source: database/functions/users/get_occasion_users_for_edit.sql
-- Historical SMTP invitation hints are a readonly compatibility projection, never canonical delivery evidence.
CREATE OR REPLACE FUNCTION public.get_occasion_sign_in_email_statuses(
  p_occasion bigint
)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
  v_result jsonb;
BEGIN
  IF NOT public.can_read_occasion_directory(p_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE = 'occasion editor required';
  END IF;

  WITH evidence AS (
    SELECT le.recipient_user AS "user",le.created_at AS sent_at
    FROM public.log_emails le
    JOIN public.email_templates et ON et.id::text = le.template
    WHERE le.occasion = p_occasion
      AND le.recipient_user IS NOT NULL
      AND et.code = 'SIGN_IN_CODE'
    UNION ALL
    SELECT m.recipient_user,m.accepted_at FROM public.email_messages m
    WHERE m.occasion=p_occasion AND (m.message_kind='sign_in' OR (m.message_kind='custom' AND m.code='TEAM_ACCESS_NOTICE'))
      AND m.recipient_user IS NOT NULL AND m.accepted_at IS NOT NULL
    UNION ALL
    SELECT i.accepted_by,m.accepted_at FROM public.occasion_team_invitations i
    JOIN public.email_messages m ON m.message_id=i.message_id
    WHERE i.occasion=p_occasion AND i.accepted_by IS NOT NULL AND m.accepted_at IS NOT NULL
  ), accepted AS (
    SELECT "user",count(*)::integer send_count,min(sent_at) first_sent_at,max(sent_at) last_sent_at FROM evidence GROUP BY "user"
  )
  SELECT COALESCE(
    jsonb_agg(to_jsonb(accepted) ORDER BY accepted."user"),
    '[]'::jsonb
  )
  INTO v_result
  FROM accepted;

  RETURN v_result;
END;
$$;

-- Source: database/functions/others/get_operator_access_v1.sql
-- Discovery remains broader than any one operation. Unit facts are evaluated
-- once per request, not once per occasion. Concrete capabilities use the same
-- SQL rule as the actual domain request; discovery never grants a write.
CREATE OR REPLACE FUNCTION public.get_operator_access_v1(
  p_organization bigint,p_unit bigint DEFAULT NULL,p_occasion bigint DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER
SET search_path=public,extensions AS $$
DECLARE v_result jsonb;
BEGIN
  IF auth.uid() IS NULL OR NOT EXISTS(SELECT 1 FROM public.user_info
    WHERE id=auth.uid() AND organization=p_organization) THEN
    RAISE insufficient_privilege USING MESSAGE='operator context unavailable';
  END IF;
  WITH unit_access AS MATERIALIZED (
    SELECT u.id,u.title,
      public.get_is_editor_on_unit(u.id) editor,
      public.get_is_manager_on_unit(u.id) manager,
      public.get_is_editor_view_on_unit(u.id) viewer
    FROM public.units u WHERE u.organization=p_organization
      AND (p_unit IS NULL OR u.id=p_unit)
  ), occasion_access AS MATERIALIZED (
    SELECT o.id,o.title,o.unit,
      public.ticket_layout_rule(true,u.editor) layout_reader
    FROM public.occasions o LEFT JOIN unit_access u ON u.id=o.unit
    WHERE o.organization=p_organization
      AND (p_unit IS NULL OR o.unit=p_unit)
      AND (p_occasion IS NULL OR o.id=p_occasion)
      AND public.operator_occasion_discovery_rule(u.editor,u.manager,u.viewer,
        public.get_is_manager_on_occasion(o.id),public.get_is_editor_on_occasion(o.id),
        public.get_is_editor_view_on_occasion(o.id),public.can_read_orders(o.id))
  ) SELECT jsonb_build_object(
    'units',coalesce((SELECT jsonb_agg(jsonb_build_object(
      'id',u.id,'title',u.title,'canCreateOccasions',
      public.occasion_create_rule(u.manager,u.editor)) ORDER BY u.id)
      FROM unit_access u WHERE public.unit_discovery_rule(u.editor,u.manager,u.viewer)),'[]'::jsonb),
    'occasions',coalesce((SELECT jsonb_agg(jsonb_build_object(
      'id',o.id,'title',o.title,'unitId',o.unit,
      'capabilities',jsonb_build_object('ticket_layouts.read',o.layout_reader)) ORDER BY o.id)
      FROM occasion_access o),'[]'::jsonb)) INTO v_result;
  RETURN v_result;
END $$;

-- Source: database/functions/abuse/documents.sql
CREATE OR REPLACE FUNCTION public.get_order_agreement_data_v1(p_order bigint)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE occ bigint;
BEGIN
 SELECT occasion INTO occ FROM eshop.orders WHERE id=p_order;
 IF occ IS NULL OR NOT (public.is_service_role() OR (auth.uid() IS NOT NULL AND public.can_write_orders(occ))) THEN
  RAISE insufficient_privilege USING MESSAGE='order document access denied'; END IF;
 PERFORM public.check_occasion_writable(occ);
 PERFORM public.admit_ticket_document_internal_v1(occ);
 RETURN public.bound_document_data_v1(public.get_order_details(p_order));
END $$;

-- Source: database/functions/eshop_orders/get_order_deletion_context_v1.sql
-- Public metadata only. Credentials stay in the service-role external-services RPC.
CREATE OR REPLACE FUNCTION public.get_order_deletion_context_v1(
  p_order bigint, p_command_id uuid DEFAULT NULL
) RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER
SET search_path = public, extensions AS $$
DECLARE
  v_occasion bigint; v_unit bigint; v_state text; v_vs bigint;
  v_command text; v_response jsonb;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE insufficient_privilege USING MESSAGE='unit manager, editor or organization admin required';
  END IF;
  -- Deletion removes the order, so a lost response is recovered from its receipt.
  IF p_command_id IS NOT NULL THEN
    SELECT CASE WHEN r.status='expired' THEN public.expired_client_mutation_response_v1(r)
      ELSE r.response END INTO v_response FROM public.client_mutation_receipts r
    JOIN public.occasions oc ON oc.id=r.occasion
    WHERE r.command_id=p_command_id AND r.actor_id=auth.uid()
      AND r.command_name='inventory.order.delete' AND r.status IN ('completed','expired')
      AND r.request_sha256=encode(extensions.digest(convert_to(
        jsonb_build_object('order',p_order)::text,'UTF8'),'sha256'),'hex')
      AND public.can_delete_orders(oc.id);
    IF FOUND THEN RETURN jsonb_build_object('response',v_response); END IF;
    IF EXISTS(SELECT 1 FROM public.client_mutation_receipts WHERE command_id=p_command_id) THEN
      RAISE insufficient_privilege USING MESSAGE='command id unavailable';
    END IF;
  END IF;
  SELECT o.occasion,oc.unit,o.state,pi.variable_symbol
    INTO v_occasion,v_unit,v_state,v_vs
  FROM eshop.orders o JOIN public.occasions oc ON oc.id=o.occasion
    LEFT JOIN eshop.payment_info pi ON pi.id=o.payment_info WHERE o.id=p_order;
  IF v_occasion IS NULL OR NOT public.can_delete_orders(v_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='unit manager, editor or organization admin required';
  END IF;
  PERFORM public.check_occasion_writable(v_occasion);
  IF v_state IN ('waitlisted','preparing_payment')
    OR EXISTS(SELECT 1 FROM eshop.waitlist_offers WHERE order_id=p_order)
    OR EXISTS(SELECT 1 FROM eshop.orders WHERE source_waitlist_order_id=p_order)
    OR EXISTS(SELECT 1 FROM eshop.waitlist_acceptance_attempts
      WHERE target_order_id=p_order OR source_order_id=p_order) THEN
    RAISE EXCEPTION 'ORDER_HAS_WAITLIST_HISTORY';
  END IF;
  -- Metadata reads do not charge. External deletion attempts share the order
  -- mutation burst budget before credentials/provider work; final SQL charges
  -- its own mutation and item count through the existing command boundary.
  IF p_command_id IS NOT NULL THEN
    PERFORM public.admit_order_mutation_v1(v_occasion,0);
  END IF;
  SELECT m.data->>'command_id' INTO v_command FROM public.email_messages m
    WHERE m.order_id=p_order AND m.code='TICKET_ORDER_CONFIRMATION'
    ORDER BY m.id DESC LIMIT 1;
  RETURN jsonb_build_object('hasFakturoid',EXISTS(
    SELECT 1 FROM eshop.external_services WHERE unit=v_unit AND type='FAKTUROID'),
    'commandId',v_command,'variableSymbol',v_vs);
END; $$;

-- Source: database/functions/emails/email_reporting.sql
CREATE OR REPLACE FUNCTION public.get_order_email_summaries(p_occasion bigint,p_orders bigint[]) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE v_summary jsonb;
BEGIN
 IF NOT coalesce(public.can_read_orders(p_occasion),false) THEN RAISE EXCEPTION 'email_read_denied'; END IF;
 IF EXISTS(SELECT 1 FROM eshop.orders WHERE id=ANY(p_orders) AND occasion<>p_occasion) THEN RAISE EXCEPTION 'email_scope_mismatch'; END IF;
 WITH messages AS (
 SELECT m.*,public.email_reporting_state(m) reporting_state FROM public.email_messages m WHERE m.order_id=ANY(p_orders) AND m.occasion=p_occasion
  AND workflow_state NOT IN ('cancelled','expired')),
 ranked AS (
 SELECT *,CASE WHEN reporting_state IN ('complaint','bounce','reject','rendering_failure','unknown','dead','suppressed','retry_wait','post_action_failed') THEN 0
 WHEN workflow_state IN ('pending','preparing','sending','blocked') AND target_time<=now() THEN 1
 WHEN workflow_state='accepted' THEN 2 ELSE 3 END rank FROM messages)
 SELECT coalesce(jsonb_object_agg(r.order_id,jsonb_build_object('state',r.reporting_state,'kind',r.message_kind,'message_id',r.message_id,'at',coalesce(r.clicked_at,r.opened_at,r.delivered_at,r.accepted_at,r.created_at),
 'scheduled_at',r.target_time,'attention_count',(SELECT count(*) FROM ranked n WHERE n.order_id=r.order_id AND rank=0),'loaded_at',now(),
 'messages',(SELECT coalesce(jsonb_agg(jsonb_build_object('kind',message_kind,'state',reporting_state,'at',coalesce(delivered_at,accepted_at,created_at)) ORDER BY created_at DESC),'[]') FROM ranked n WHERE n.order_id=r.order_id))
),'{}'::jsonb) INTO v_summary FROM (SELECT DISTINCT ON (order_id) * FROM ranked ORDER BY order_id,rank,created_at DESC,id DESC) r;
 RETURN v_summary;
END $$;

-- Source: database/functions/eshop/get_order_history.sql
CREATE OR REPLACE FUNCTION public.get_order_history(order_id bigint)
RETURNS jsonb SECURITY DEFINER
SET search_path = public, extensions AS $$
DECLARE
    v_occasion_id bigint;
    v_order_data jsonb;
    v_history_data jsonb;
    v_users_data jsonb;
BEGIN
    -- Retrieve the occasion associated with the order
    SELECT o.occasion, to_jsonb(o)
    INTO v_occasion_id, v_order_data
    FROM eshop.orders o
    WHERE o.id = order_id;

    -- Check if the order exists
    IF v_occasion_id IS NULL THEN
        RETURN jsonb_build_object('code', 404, 'message', 'Order not found');
    END IF;

    -- Verify if the current user is an editor for the order's occasion
    IF NOT can_read_orders(v_occasion_id) THEN
        RETURN jsonb_build_object('code', 403, 'message', 'User is not authorized to view this order history');
    END IF;

    -- Fetch history items for the order, ordered by creation date
    SELECT jsonb_agg(to_jsonb(h) || jsonb_build_object('order_symbol', v_order_data->>'order_symbol', 'order_sequence', v_order_data->'order_sequence') ORDER BY h.created_at)
    INTO v_history_data
    FROM eshop.orders_history h
    WHERE h. "order" = order_id;

    -- Fetch unique users who created the history items
    WITH user_ids AS (
        SELECT DISTINCT created_by
        FROM eshop.orders_history
        WHERE "order" = order_id AND created_by IS NOT NULL
    )
    SELECT jsonb_agg(u.*)
    INTO v_users_data
    FROM public.user_info u
    WHERE u.id IN (SELECT created_by FROM user_ids);

    -- Return the combined data
    RETURN jsonb_build_object(
        'code', 200,
        'data', jsonb_build_object(
            'order', COALESCE(v_order_data, '{}'::jsonb),
            'history', COALESCE(v_history_data, '[]'::jsonb),
            'users', COALESCE(v_users_data, '[]'::jsonb)
        )
    );
EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('code', 500, 'message', SQLERRM);
END;
$$ LANGUAGE plpgsql;

-- Source: database/functions/eshop_waitlist/order_overview_admin.sql
-- Authenticate the grid request before the service opens the encrypted link.
CREATE OR REPLACE FUNCTION public.get_order_overview_admin_context(p_order_id bigint)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE o eshop.orders;
BEGIN
 SELECT * INTO STRICT o FROM eshop.orders WHERE id=p_order_id;
 IF public.can_read_orders(o.occasion) IS NOT TRUE THEN
  RAISE insufficient_privilege USING MESSAGE='Order viewer required';
 END IF;
 RETURN jsonb_build_object('orderId',o.id,'recipient',o.data->>'email');
END $$;

-- Source: database/functions/public_links/legacy_readers.sql
CREATE OR REPLACE FUNCTION public.get_orders(form_link text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
SET search_path = public, extensions
AS $function$
DECLARE
    occasion_id BIGINT;
    spotsData JSONB;
    productsData JSONB;
    productTypesData JSONB;
    ticketsData JSONB;
    ordersData JSONB;
    orderProductTicketsData JSONB;
    paymentInfoData JSONB;
    formsData JSONB;
BEGIN
    -- Get the occasion_id based on the provided form_link
    SELECT occasion
    INTO occasion_id
    FROM public.forms
    WHERE id = public.resolve_form_link_internal(form_link);

    -- Check if form_link is valid
    IF occasion_id IS NULL THEN
        RETURN jsonb_build_object('code', 404, 'message', 'Form key does not exist or is not linked to an occasion');
    END IF;

    -- Authorization check
    IF (SELECT can_read_orders(occasion_id)) <> TRUE THEN
        RETURN jsonb_build_object('code', 403, 'message', 'User is not authorized to access this occasion');
    END IF;

    -- Fetch spots where order_product_ticket is not NULL
    SELECT jsonb_agg(jsonb_build_object(
        'id', s.id,
        'title', s.title,
        'product', s.product,
        'order_product_ticket', s.order_product_ticket,
        'state', CASE
            WHEN s.order_product_ticket IS NOT NULL THEN 'ordered'
            WHEN s.secret IS NOT NULL AND s.secret_expiration_time > now() THEN 'selected'
            ELSE 'available'
        END
    ))
    INTO spotsData
    FROM eshop.spots s
    WHERE s.occasion = occasion_id
      AND s.order_product_ticket IS NOT NULL;

    -- Fetch all products linked to the occasion
    SELECT jsonb_agg(jsonb_build_object(
        'id', p.id,
        'title', p.title,
        'price', p.price,
        'currency_code', p.currency_code,
        'type', pt.type,
        'description', pt.description
    ))
    INTO productsData
    FROM eshop.products p
    JOIN eshop.product_types pt ON pt.id = p.product_type
    WHERE pt.occasion = occasion_id;

    -- Fetch product types for the occasion
    SELECT jsonb_agg(jsonb_build_object(
        'id', pt.id,
        'type', pt.type,
        'title', pt.title,
        'description', pt.description
    ))
    INTO productTypesData
    FROM eshop.product_types pt
    WHERE pt.occasion = occasion_id;

    -- Fetch tickets linked to the occasion
    SELECT jsonb_agg(jsonb_build_object(
        'id', t.id,
        'created_at', t.created_at,
        'ticket_symbol', t.ticket_symbol,
        'state', t.state,
        'note', t.note,
        'note_hidden', t.note_hidden
    ))
    INTO ticketsData
    FROM eshop.tickets t
    WHERE t.occasion = occasion_id;

    -- Fetch orders linked to the occasion
    SELECT jsonb_agg(jsonb_build_object(
        'id', o.id,
        'created_at', o.created_at,
        'updated_at', o.updated_at,
        'price', o.price,
        'state', o.state,
        'currency_code', o.currency_code,
        'data', o.data,
        'payment_info', o.payment_info,
        'note_hidden', o.note_hidden
    ))
    INTO ordersData
    FROM eshop.orders o
    WHERE o.occasion = occasion_id;

    -- Extract order IDs from ordersData JSONB
    WITH order_ids AS (
        SELECT (order_obj->>'id')::BIGINT AS id
        FROM jsonb_array_elements(ordersData) order_obj
    )
    -- Fetch relevant order-product-ticket data based on extracted order IDs
    SELECT jsonb_agg(jsonb_build_object(
        'id', opt.id,
        'order', opt."order",
        'product', opt.product,
        'ticket', opt.ticket,
        'created_at', opt.created_at
    ))
    INTO orderProductTicketsData
    FROM eshop.order_product_ticket opt
    WHERE opt."order" IN (SELECT id FROM order_ids);

    -- Fetch payment information linked to the orders
    SELECT jsonb_agg(jsonb_build_object(
        'id', pi.id,
        'created_at', pi.created_at,
        'bank_account', pi.bank_account,
        'variable_symbol', pi.variable_symbol,
        'amount', pi.amount,
        'paid', pi.paid,
        'returned', pi.returned,
        'deadline', pi.deadline,
        'currency_code', pi.currency_code
    ))
    INTO paymentInfoData
    FROM eshop.payment_info pi
    WHERE pi.id IN (
        SELECT DISTINCT (order_obj->>'payment_info')::BIGINT
        FROM jsonb_array_elements(ordersData) order_obj
    );

    -- Fetch forms linked to the occasion
    SELECT jsonb_agg(jsonb_build_object(
        'id', f.id,
        'created_at', f.created_at,
        'data', f.data,
        'key', f.key,
        'occasion', f.occasion,
        'type', f.type,
        'deadline_duration_seconds', f.deadline_duration_seconds,
        'is_open', f.is_open,
        'link', f.link,
        'blueprint', f.blueprint,
        'header', f.header,
        'header_off', f.header_off,
        'updated_at', f.updated_at
    ))
    INTO formsData
    FROM public.forms f
    WHERE f.occasion = occasion_id;

    -- Return combined data, including the new product_types key
    RETURN jsonb_build_object(
        'code', 200,
        'data', jsonb_build_object(
            'spots', COALESCE(spotsData, '[]'::jsonb),
            'products', COALESCE(productsData, '[]'::jsonb),
            'product_types', COALESCE(productTypesData, '[]'::jsonb),
            'tickets', COALESCE(ticketsData, '[]'::jsonb),
            'orders', COALESCE(ordersData, '[]'::jsonb),
            'order_product_ticket', COALESCE(orderProductTicketsData, '[]'::jsonb),
            'payment_info', COALESCE(paymentInfoData, '[]'::jsonb),
            'forms', COALESCE(formsData, '[]'::jsonb)
        )
    );
END;
$function$;

-- Source: database/functions/eshop_orders/get_orders.sql
CREATE OR REPLACE FUNCTION public.get_orders(
    p_occasion_link TEXT,
    p_form_link TEXT DEFAULT NULL,
    p_options JSONB DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
    v_occasion_id BIGINT;
    v_form_id BIGINT;
    spotsData JSONB;
    productsData JSONB;
    productTypesData JSONB;
    ticketsData JSONB;
    ordersData JSONB;
    ordersHistoryData JSONB;
    orderProductTicketsData JSONB;
    paymentInfoData JSONB;
    formsData JSONB;
    usersData JSONB; -- ADDED: Variable for user info data
BEGIN
    -- This function retrieves order and reservation details for a given occasion.
    -- It can conditionally include related data like spots, history, and users.
    --
    -- 'include_orders_history': If true, it fetches 'orders_history' and the
    --                           associated 'users' who created those history records.

    -- 1. Input Validation: Ensure at least one link is provided.
    IF p_occasion_link IS NULL AND p_form_link IS NULL THEN
        RETURN jsonb_build_object('code', 400, 'message', 'Either occasion_link or form_link must be provided');
    END IF;

    -- 2. Determine occasion_id based on the provided link.
    IF p_occasion_link IS NOT NULL THEN
        SELECT id
        INTO v_occasion_id
        FROM public.occasions
        WHERE id = public.resolve_occasion_link_internal(p_occasion_link)
          AND organization = (SELECT ui.organization FROM public.user_info ui WHERE ui.id = auth.uid());
    ELSE
        SELECT occasion, id
        INTO v_occasion_id, v_form_id
        FROM public.forms
        WHERE id = public.resolve_form_link_internal(p_form_link)
          AND occasion IN (SELECT o.id FROM public.occasions o WHERE o.organization = (SELECT ui.organization FROM public.user_info ui WHERE ui.id = auth.uid()));
    END IF;

    -- 3. Check if a valid occasion was found.
    IF v_occasion_id IS NULL THEN
        RETURN jsonb_build_object('code', 404, 'message', 'The provided link is invalid or not linked to any occasion');
    END IF;

    -- 4. Authorization check.
    IF (SELECT can_read_orders(v_occasion_id)) <> TRUE THEN
        RETURN jsonb_build_object('code', 403, 'message', 'User is not authorized to access this occasion');
    END IF;

    -- Conditionally fetch spots based on p_options for optimization
    IF (p_options->>'include_spots')::BOOLEAN = TRUE THEN
        SELECT jsonb_agg(jsonb_build_object(
            'id', s.id,
            'title', s.title,
            'product', s.product,
            'order_product_ticket', s.order_product_ticket,
            'state', CASE
                WHEN s.order_product_ticket IS NOT NULL THEN 'ordered'
                WHEN s.secret IS NOT NULL AND s.secret_expiration_time > now() THEN 'selected'
                ELSE 'available'
            END
        ))
        INTO spotsData
        FROM eshop.spots s
        WHERE s.occasion = v_occasion_id
          AND s.order_product_ticket IS NOT NULL;
    END IF;

    -- Fetch all products linked to the occasion
    SELECT jsonb_agg(jsonb_build_object(
        'id', p.id,
        'title', p.title,
        'price', p.price,
        'currency_code', p.currency_code,
        'type', pt.type
    ))
    INTO productsData
    FROM eshop.products p
    JOIN eshop.product_types pt ON pt.id = p.product_type
    WHERE pt.occasion = v_occasion_id;

    -- Fetch product types for the occasion
    SELECT jsonb_agg(jsonb_build_object(
        'id', pt.id,
        'type', pt.type,
        'title', pt.title,
        'description', pt.description
    ))
    INTO productTypesData
    FROM eshop.product_types pt
    WHERE pt.occasion = v_occasion_id;

    -- Fetch tickets linked to the occasion
    SELECT jsonb_agg(jsonb_build_object(
        'id', t.id,
        'created_at', t.created_at,
        'updated_at', t.updated_at,
        'ticket_symbol', t.ticket_symbol,
        'state', t.state,
        'note', t.note,
        'note_hidden', t.note_hidden,
        'data', t.data
    ))
    INTO ticketsData
    FROM eshop.tickets t
    WHERE t.occasion = v_occasion_id;

    -- Fetch forms linked to the occasion
    SELECT jsonb_agg(jsonb_build_object(
        'id', f.id,
        'data', f.data,
        'key', f.key,
        'occasion', f.occasion,
        'type', f.type,
        'deadline_duration_seconds', f.deadline_duration_seconds,
        'participant_capacity',f.participant_capacity,
        'waitlist_enabled',f.waitlist_enabled,
        'show_remaining_capacity',f.show_remaining_capacity,
        'waitlist_offer_duration_seconds',f.waitlist_offer_duration_seconds,
        'capacity',public.get_form_capacity_snapshot_internal(f.id),
        'registrationMode',public.get_form_registration_mode_internal(f.id),
        'is_open', f.is_open,
        'link', f.link,
        'blueprint', f.blueprint,
        'title', f.title
    ))
    INTO formsData
    FROM public.forms f
    WHERE f.occasion = v_occasion_id;

    -- Ordinary orders need only activity/actions. Resolve ticket/offer lifecycles
    -- once only for orders that expose a full waitlist summary.
    WITH selected_orders AS MATERIALIZED (
        SELECT o.*, CASE WHEN o.state='waitlisted' OR o.source_waitlist_order_id IS NOT NULL
          OR EXISTS(SELECT 1 FROM eshop.waitlist_offers WHERE order_id=o.id)
          THEN public.get_waitlist_summary_internal(o.id)
          ELSE public.get_order_action_summary_internal(o.state)
        END AS waitlist_summary
        FROM eshop.orders o
        WHERE o.occasion = v_occasion_id
          AND (v_form_id IS NULL OR o.form = v_form_id)
    )
        SELECT jsonb_agg(jsonb_build_object(
            'id', o.id, 'order_symbol', o.order_symbol, 'order_sequence', o.order_sequence, 'created_at', o.created_at, 'updated_at', o.updated_at, 'price', o.price, 'state', o.state, 'currency_code', o.currency_code,
            'waitlistSummary',CASE WHEN o.state='waitlisted' OR o.source_waitlist_order_id IS NOT NULL
              OR EXISTS(SELECT 1 FROM eshop.waitlist_offers WHERE order_id=o.id)
              THEN o.waitlist_summary END,
            'isActive',(o.waitlist_summary->>'isActive')::boolean,
            'allowedActions',o.waitlist_summary->'allowedActions',
            'source_waitlist_order_id',o.source_waitlist_order_id,
            'form_id', o.form,
            'form', jsonb_build_object('id', o.form),
            'data', CASE
                WHEN (p_options->>'include_full_order_data')::BOOLEAN = TRUE THEN o.data || jsonb_build_object('tickets', public.order_tickets_with_seating_internal(o.id,o.data->'tickets'))
                ELSE jsonb_build_object('name', o.data->>'name', 'surname', o.data->>'surname', 'email', o.data->>'email')
            END,
            'payment_info', o.payment_info, 'note_hidden', o.note_hidden
        ))
        INTO ordersData
        FROM selected_orders o;

    -- Extract order IDs from the (potentially filtered) ordersData JSONB
    WITH order_ids AS (
        SELECT (order_obj->>'id')::BIGINT AS id
        FROM jsonb_array_elements(COALESCE(ordersData, '[]'::jsonb)) order_obj
    )
    -- Fetch relevant order-product-ticket data based on extracted order IDs
    SELECT jsonb_agg(jsonb_build_object('id', opt.id, 'order', opt."order", 'product', opt.product, 'ticket', opt.ticket))
    INTO orderProductTicketsData
    FROM eshop.order_product_ticket opt
    WHERE opt."order" IN (SELECT id FROM order_ids);

    -- Fetch payment information linked to the orders
    SELECT jsonb_agg(jsonb_build_object(
        'id', pi.id, 'bank_account', pi.bank_account, 'variable_symbol', pi.variable_symbol, 'amount', pi.amount, 'deposit_amount', pi.deposit_amount,
        'deposit_deadline', pi.deposit_deadline, 'paid', pi.paid, 'returned', pi.returned, 'deadline', pi.deadline, 'currency_code', pi.currency_code, 'data', pi.data,
        'bank_sync_warning', public.bank_sync_warning(pi.bank_account)
    ))
    INTO paymentInfoData
    FROM eshop.payment_info pi
    WHERE pi.id IN (
        SELECT DISTINCT (order_obj->>'payment_info')::BIGINT
        FROM jsonb_array_elements(COALESCE(ordersData, '[]'::jsonb)) order_obj
        WHERE order_obj->>'payment_info' IS NOT NULL
    );

    -- Conditionally fetch orders history and related users based on p_options
    IF (p_options->>'include_orders_history')::BOOLEAN = TRUE THEN
        -- First, fetch the history records
        WITH order_ids AS (
            SELECT (order_obj->>'id')::BIGINT AS id
            FROM jsonb_array_elements(COALESCE(ordersData, '[]'::jsonb)) order_obj
        )
        SELECT jsonb_agg(jsonb_build_object(
            'id', oh.id, 'created_at', oh.created_at, 'created_by', oh.created_by, 'data', oh.data,
            'order', oh."order", 'order_symbol', (SELECT o.order_symbol FROM eshop.orders o WHERE o.id=oh."order"), 'order_sequence', (SELECT o.order_sequence FROM eshop.orders o WHERE o.id=oh."order"), 'state', oh.state, 'price', oh.price, 'currency_code', oh.currency_code
        ))
        INTO ordersHistoryData
        FROM eshop.orders_history oh
        WHERE oh."order" IN (SELECT id FROM order_ids);

        -- Second, fetch the unique users who created those history records
        WITH user_ids AS (
            SELECT DISTINCT (history_obj->>'created_by')::UUID AS id
            FROM jsonb_array_elements(COALESCE(ordersHistoryData, '[]'::jsonb)) history_obj
            WHERE history_obj->>'created_by' IS NOT NULL
        )
        SELECT jsonb_agg(jsonb_build_object(
            'id', ui.id,
            'name', ui.name,
            'surname', ui.surname,
            'email_readonly', ui.email_readonly
        ))
        INTO usersData
        FROM public.user_info ui
        WHERE ui.id IN (SELECT id FROM user_ids);
    END IF;


    -- Return combined data
    RETURN jsonb_build_object(
        'code', 200,
        'occasion_id', v_occasion_id,
        'data', jsonb_build_object(
            'spots', COALESCE(spotsData, '[]'::jsonb),
            'products', COALESCE(productsData, '[]'::jsonb),
            'product_types', COALESCE(productTypesData, '[]'::jsonb),
            'tickets', COALESCE(ticketsData, '[]'::jsonb),
            'orders', COALESCE(ordersData, '[]'::jsonb),
            'order_product_ticket', COALESCE(orderProductTicketsData, '[]'::jsonb),
            'payment_info', COALESCE(paymentInfoData, '[]'::jsonb),
            'forms', COALESCE(formsData, '[]'::jsonb),
            'orders_history', COALESCE(ordersHistoryData, '[]'::jsonb),
            'users', COALESCE(usersData, '[]'::jsonb)
        )
    );
END;
$$;

-- Source: database/functions/organization/get_organization_admin.sql
CREATE OR REPLACE FUNCTION public.get_organization_admin(organization_id bigint)
RETURNS SETOF public.organizations
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions
AS $$
BEGIN
  -- Verify admin status
  IF public.can_manage_organization_settings(organization_id) THEN
    -- Return the organization record without server-only delivery secrets.
    RETURN QUERY
    SELECT o.id, o.created_at, o.updated_at,
      o.data - 'ONESIGNAL_REST_API_KEY', o.title, o.phone_prefixes
    FROM organizations o
    WHERE o.id = organization_id;
  ELSE
    -- Raise distinct exception or return nothing
    RAISE EXCEPTION 'Access Denied: User is not an admin of this organization.';
  END IF;
END;
$$;

-- Source: database/functions/eshop/get_product_for_authoring_v1.sql
CREATE OR REPLACE FUNCTION public.get_product_for_authoring_v1(p_product bigint)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE oc bigint;
BEGIN
 SELECT occasion INTO oc FROM eshop.products WHERE id=p_product;
 IF auth.uid() IS NULL OR oc IS NULL OR public.can_read_orders(oc) IS NOT TRUE THEN
  RAISE insufficient_privilege USING MESSAGE='order editor view required'; END IF;
 RETURN (SELECT jsonb_build_object('id',p.id,'occasion',p.occasion,'product_type',p.product_type,
  'title',p.title,'description',p.description,'price',p.price,'currency_code',p.currency_code,'data',p.data,
  'is_hidden',p.is_hidden,'order',p."order",'maximum',p.maximum,'aggregate_version',coalesce(v.version,0),
  'inventory_contexts',coalesce((SELECT jsonb_agg(jsonb_build_object('inventory_context_id',pic.inventory_context,'quantity',pic.quantity) ORDER BY pic.inventory_context)
    FROM eshop.product_inventory_contexts pic WHERE pic.product=p.id),'[]'))
 FROM eshop.products p LEFT JOIN public.client_aggregate_versions v ON v.aggregate_type='product' AND v.scope_type='occasion'
 AND v.scope_id=p.occasion AND v.aggregate_id=p.id::text WHERE p.id=p_product);
END $$;

-- Source: database/functions/eshop/get_products_and_types_for_occasion.sql
CREATE OR REPLACE FUNCTION public.get_products_and_types_for_edit(occasion_link text)
RETURNS json LANGUAGE plpgsql STABLE
SECURITY DEFINER
SET search_path = public, extensions AS $$
DECLARE
  product_types json;
  products json;
  inventory_pools_data json;
  inventory_contexts_data json;
  product_inventory_contexts_data json;
  forms_data json;
  occ_id bigint;
BEGIN
  -- Resolve occasion_id from the provided occasion_link
  SELECT id
    INTO occ_id
  FROM public.occasions
  WHERE id = public.resolve_occasion_link_internal(occasion_link)
    AND organization = (SELECT ui.organization FROM public.user_info ui WHERE ui.id = auth.uid());

  -- If the occasion link is invalid, raise an exception.
  IF occ_id IS NULL THEN
    RAISE EXCEPTION 'Occasion not found for link: %', occasion_link;
  END IF;

  -- Verify if the current user is an editor for the order's occasion
  IF NOT can_read_orders(occ_id) THEN
      RETURN jsonb_build_object('code', 403, 'message', 'User is not authorized to view this.');
  END IF;

-- Fetch all product types for the given occasion
  SELECT json_agg(
           json_build_object(
             'id', pt.id,
             'type', pt.type,
             'title', pt.title
           )
         )
    INTO product_types
  FROM eshop.product_types pt
  WHERE pt.occasion = occ_id;

  -- Fetch all products for the given occasion, including form IDs
  SELECT json_agg(
           json_build_object(
             'id', p.id,
            'aggregate_version',coalesce((SELECT version FROM public.client_aggregate_versions WHERE aggregate_type='product' AND scope_type='occasion' AND scope_id=p.occasion AND aggregate_id=p.id::text),0),
             'title', p.title,
             'description', p.description,
             'short_title', p.data->>'short_title',
             'product_type', p.product_type,
             'data', p.data,
             'price', p.price,
             'price_changes', (SELECT COALESCE(json_agg(pc ORDER BY pc.change_time,pc.id),'[]'::json)
               FROM eshop.planned_changes pc WHERE pc.subject_id=p.id AND pc.change_type='products.price' AND NOT pc.applied),
             'visibility_changes', (SELECT COALESCE(json_agg(pc ORDER BY pc.change_time,pc.id),'[]'::json)
               FROM eshop.planned_changes pc WHERE pc.subject_id=p.id AND pc.change_type='products.is_hidden' AND NOT pc.applied),
             'currency_code', p.currency_code,
             'is_hidden', p.is_hidden,
             'is_used_in_blueprint', EXISTS (SELECT 1 FROM eshop.spots s WHERE s.product=p.id AND s.occasion=occ_id),
             'order', p."order",
             'maximum', p.maximum,
             'form_ids', (
               SELECT COALESCE(json_agg(DISTINCT ff.form), '[]'::json)
               FROM public.form_fields ff
               WHERE ff.product_type = p.product_type
             ),
             'ordered_count', (
               SELECT count(*)
               FROM eshop.order_product_ticket opt
               WHERE opt.product = p.id
             ),
             'paid_count', (
               SELECT count(*)
               FROM eshop.order_product_ticket opt
               JOIN eshop.orders o ON o.id = opt.order
               WHERE opt.product = p.id
                 AND o.state = 'paid'
             ),
             'sent_count', (
               SELECT count(*)
               FROM eshop.order_product_ticket opt
               JOIN eshop.orders o ON o.id = opt.order
               WHERE opt.product = p.id
                 AND o.state = 'sent'
             )
           )
         )
    INTO products
  FROM eshop.products p
  WHERE p.product_type IN (
    SELECT pt.id
    FROM eshop.product_types pt
    WHERE pt.occasion = occ_id
  );

  -- Fetch all inventory pools for the occasion
  SELECT json_agg(ip.*)
  INTO inventory_pools_data
  FROM public.inventory_pools ip
  WHERE ip.occasion = occ_id;

  -- Fetch all inventory contexts for the occasion
  SELECT json_agg(ic.*)
  INTO inventory_contexts_data
  FROM public.inventory_contexts ic
  JOIN public.inventory_pools ip ON ic.inventory_pool = ip.id
  WHERE ip.occasion = occ_id;

  -- Fetch all links between products and inventory contexts for the occasion
  SELECT json_agg(pic.*)
  INTO product_inventory_contexts_data
  FROM eshop.product_inventory_contexts pic
  JOIN eshop.products p ON pic.product = p.id
  JOIN eshop.product_types pt ON p.product_type = pt.id
  WHERE pt.occasion = occ_id;

  -- Fetch only the id, title, and link for each form associated with the occasion
  SELECT json_agg(
           json_build_object(
             'id', f.id,
             'title', f.title,
             'link', f.link
           )
         )
    INTO forms_data
  FROM public.forms f
  WHERE f.occasion = occ_id;

  RETURN json_build_object(
    'server_time', clock_timestamp(),
    'price_waves', (SELECT COALESCE(json_agg(w ORDER BY w.change_time,w.id),'[]'::json)
      FROM eshop.product_price_waves w WHERE w.occasion=occ_id AND (w.change_time>clock_timestamp() OR
        EXISTS(SELECT 1 FROM eshop.planned_changes pc WHERE pc.wave_id=w.id AND NOT pc.applied))),
    'product_types', COALESCE(product_types, '[]'::json),
    'products', COALESCE(products, '[]'::json),
    'inventory_pools', COALESCE(inventory_pools_data, '[]'::json),
    'inventory_contexts', COALESCE(inventory_contexts_data, '[]'::json),
    'product_inventory_contexts', COALESCE(product_inventory_contexts_data, '[]'::json),
    'forms', COALESCE(forms_data, '[]'::json)
  );
END;
$$;

-- Source: database/functions/eshop_orders/get_products_for_ticket.sql
CREATE OR REPLACE FUNCTION public.get_products_for_ticket(
  ticket_id bigint
)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public, extensions AS $$
DECLARE
  v_occasion_id bigint;
  v_order_json jsonb;
  v_payment_info_json jsonb;
  v_ticket jsonb;
  v_latest_sent_at timestamptz;
  v_is_newer_available boolean := FALSE;
  v_order_id bigint;
  v_changes jsonb;
  reference_history_data jsonb;
BEGIN
  -- Find the order containing the ticket and LEFT JOIN its associated payment_info.
  SELECT
    o.id,
    o.occasion,
    to_jsonb(o),
    to_jsonb(pi)
  INTO
    v_order_id,
    v_occasion_id,
    v_order_json,
    v_payment_info_json
  FROM eshop.orders AS o
  LEFT JOIN eshop.payment_info AS pi ON o.payment_info = pi.id
  WHERE EXISTS (
    SELECT 1
    FROM   jsonb_array_elements(o.data->'tickets') AS t
    WHERE  (t->>'id')::bigint = ticket_id
  );

  -- Check if the order was found.
  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'code',    404,
      'message', 'Ticket not found'
    );
  END IF;

  -- Permission check.
  IF NOT can_read_orders(v_occasion_id) THEN
    RETURN jsonb_build_object(
      'code',    403,
      'message', 'Not authorized to view this ticket'
    );
  END IF;

  -- Extract the full JSON object for the specified ticket from the order's data.
  SELECT t
  INTO   v_ticket
  FROM   jsonb_array_elements(v_order_json->'data'->'tickets') AS t
  WHERE  (t->>'id')::bigint = ticket_id;

  v_changes := public.get_order_change_summary_v1(v_order_id);
  reference_history_data := v_changes->'referenceOrder';
  v_latest_sent_at := (v_changes->>'latestSentAt')::timestamptz;
  v_is_newer_available := (v_changes->>'hasChanges')::boolean;

  -- Build the simplified and comprehensive JSONB response object.
  RETURN jsonb_build_object(
    'code', 200,
    'data', jsonb_build_object(
      'ticket', v_ticket,
      'order', v_order_json,
      'payment_info', v_payment_info_json,
      'order_history', jsonb_build_object(
          'latest_sent_at', v_latest_sent_at,
          'is_newer_version_available', v_is_newer_available
      ),
      'reference_order_data', reference_history_data,
      'order_changes', v_changes
    )
  );
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object(
    'code',    500,
    'message', SQLERRM
  );
END;
$$;

-- Source: database/functions/eshop_orders/get_products_for_ticket_all_available.sql
CREATE OR REPLACE FUNCTION public.get_products_for_ticket_all_available(
  ticket_id bigint
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions AS $$
DECLARE
  v_occasion_id bigint;
  v_available   jsonb;
BEGIN
  -- find the ticket’s occasion
  SELECT occasion
  INTO   v_occasion_id
  FROM   eshop.tickets
  WHERE  id = ticket_id;

  IF NOT FOUND OR v_occasion_id IS NULL THEN
    RETURN jsonb_build_object(
      'code',    404,
      'message', 'Ticket not found'
    );
  END IF;

  IF NOT can_read_orders(v_occasion_id) THEN
    RETURN jsonb_build_object(
      'code',    403,
      'message', 'Not authorized'
    );
  END IF;

  -- aggregate all products for that occasion
  SELECT jsonb_agg(
           jsonb_build_object(
             'id',            p.id,
             'title',         p.title,
             'price',         p.price,
             'currency_code', p.currency_code,
             'type_title',    pt.title
           )
         )
  INTO   v_available
  FROM   eshop.products p
  LEFT JOIN eshop.product_types pt
    ON pt.id = p.product_type
  WHERE  p.occasion = v_occasion_id;

  RETURN jsonb_build_object(
    'code', 200,
    'data', COALESCE(v_available, '[]'::jsonb)
  );
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object(
    'code',    500,
    'message', SQLERRM
  );
END;
$$;

-- Source: database/functions/security/public_map_projection.sql
CREATE OR REPLACE FUNCTION public.get_public_client_sync_component_core_v1(p_component text, p_scope_type text, p_scope_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_revision bigint; v_payload jsonb; v_organization bigint; v_unit bigint; v_generated_at timestamptz;
BEGIN
  IF NOT public.can_materialize_public_occasion(p_scope_id) THEN
    RAISE insufficient_privilege USING MESSAGE='publisher or occasion editor required';
  END IF;
  IF p_scope_type <> 'occasion' OR NOT EXISTS (
    SELECT 1 FROM public.occasions WHERE id=p_scope_id AND NOT is_hidden
  ) THEN RAISE EXCEPTION 'scope is not publicly publishable'; END IF;
  SELECT source_revision,updated_at INTO v_revision,v_generated_at FROM public.client_sync_scopes
    WHERE component=p_component AND scope_type=p_scope_type AND scope_id=p_scope_id;
  v_revision := COALESCE(v_revision,0);

  CASE p_component
    WHEN 'occasion_config' THEN
      SELECT jsonb_build_object('id',o.id,'title',o.title,'startTime',o.start_time,
        'endTime',o.end_time,'isOpen',o.is_open,'features',o.features,'data',o.data,
        'services',o.services,'unitId',o.unit) INTO v_payload
      FROM public.occasions o WHERE o.id=p_scope_id AND NOT o.is_hidden;
    WHEN 'program_catalog' THEN
      SELECT jsonb_build_object(
        'events',COALESCE(jsonb_agg(DISTINCT jsonb_build_object('id',e.id,'title',e.title,
          'startTime',e.start_time,'endTime',e.end_time,'maxParticipants',e.max_participants,
          'description',e.description,'placeId',e.place,'type',e.type,'data',e.data,
          'order',e."order",'isGroupEvent',e.is_group_event,'splitForMenWomen',e.split_for_men_women)) FILTER (WHERE e.id IS NOT NULL),'[]'),
        'eventGroups',(SELECT COALESCE(jsonb_agg(jsonb_build_object('parentId',eg.event_parent,'childId',eg.event_child) ORDER BY eg.event_parent,eg.event_child),'[]') FROM public.event_groups eg JOIN public.events ep ON ep.id=eg.event_parent JOIN public.events ec ON ec.id=eg.event_child WHERE ep.occasion=p_scope_id AND ec.occasion=p_scope_id AND NOT ep.is_hidden AND NOT ec.is_hidden),
        'eventRoles',(SELECT COALESCE(jsonb_agg(jsonb_build_object('eventId',er.event,'roleId',er.role) ORDER BY er.event,er.role),'[]') FROM public.event_roles er JOIN public.events e2 ON e2.id=er.event WHERE e2.occasion=p_scope_id AND NOT e2.is_hidden),
        'eventSpeakers',(SELECT COALESCE(jsonb_agg(jsonb_build_object('eventId',es.event,'speakerId',es.speaker) ORDER BY es.event,es.speaker),'[]') FROM public.event_speakers es JOIN public.events e3 ON e3.id=es.event JOIN public.speakers sp ON sp.id=es.speaker WHERE e3.occasion=p_scope_id AND NOT e3.is_hidden AND NOT sp.is_hidden)
      ) INTO v_payload FROM public.events e WHERE e.occasion=p_scope_id AND NOT e.is_hidden;
    WHEN 'map_catalog' THEN
      SELECT o.organization,o.unit INTO v_organization,v_unit FROM public.occasions o WHERE o.id=p_scope_id;
      WITH visible_places AS (
        SELECT p.*,COALESCE(v.version,0) aggregate_version FROM public.places p
        LEFT JOIN public.client_aggregate_versions v ON v.aggregate_type='place'
          AND v.scope_type='occasion' AND v.scope_id=p_scope_id AND v.aggregate_id=p.id::text
        WHERE p.occasion=p_scope_id AND NOT p.is_hidden AND p.type IS DISTINCT FROM 'group'
      ), visible_types AS (
        SELECT pt.*,COALESCE(v.version,0) aggregate_version FROM public.place_types pt
        LEFT JOIN public.client_aggregate_versions v ON v.aggregate_type='place_type'
          AND v.scope_type='occasion' AND v.scope_id=p_scope_id AND v.aggregate_id=pt.id::text
        WHERE pt.occasion=p_scope_id AND NOT pt.is_hidden
      ), visible_paths AS (
        SELECT pg.*,COALESCE(v.version,0) aggregate_version FROM public.path_groups pg
        LEFT JOIN public.client_aggregate_versions v ON v.aggregate_type='path'
          AND v.scope_type='occasion' AND v.scope_id=p_scope_id AND v.aggregate_id=pg.id::text
        WHERE pg.occasion=p_scope_id AND NOT pg.is_hidden
      ), icon_ids AS (
        SELECT icon FROM visible_places WHERE icon IS NOT NULL UNION
        SELECT icon FROM visible_types WHERE icon IS NOT NULL UNION
        SELECT icon FROM visible_paths WHERE icon IS NOT NULL UNION
        SELECT i.id FROM visible_places p JOIN public.icons i
          ON i.organization=v_organization AND (i.unit=v_unit OR i.unit IS NULL)
          AND lower(btrim(i.link))=lower(btrim(p.type))
        WHERE p.type IS NOT NULL AND btrim(p.type)<>''
      ), missing AS (
        SELECT i.icon FROM icon_ids i LEFT JOIN public.icons x ON x.id=i.icon AND x.organization=v_organization
        WHERE x.id IS NULL
      )
      SELECT CASE WHEN EXISTS(SELECT 1 FROM missing) THEN NULL ELSE jsonb_build_object(
        'places',(SELECT COALESCE(jsonb_agg(jsonb_build_object('id',p.id,'title',p.title,'description',p.description,'type',p.type,'coordinates',p.coordinates,'order',p."order",'icon',p.icon,'aggregateVersion',p.aggregate_version) ORDER BY p."order",p.id),'[]') FROM visible_places p),
        'placeTypes',(SELECT COALESCE(jsonb_agg(jsonb_build_object('id',pt.id,'code',pt.code,'title',pt.title,'icon',pt.icon,'order',pt."order",'isDefault',pt.is_default,'aggregateVersion',pt.aggregate_version) ORDER BY pt."order",pt.id),'[]') FROM visible_types pt),
        'paths',(SELECT COALESCE(jsonb_agg(jsonb_build_object('id',pg.id,'title',pg.title,'pathData',pg.path_data,'data',pg.data,'icon',pg.icon,'order',pg."order",'aggregateVersion',pg.aggregate_version) ORDER BY pg."order",pg.id),'[]') FROM visible_paths pg),
        'icons',(SELECT COALESCE(jsonb_agg(jsonb_build_object('id',i.id,'link',i.link,'svg',i.data) ORDER BY i.id),'[]') FROM public.icons i JOIN icon_ids refs ON refs.icon=i.id)
      ) END INTO v_payload;
      IF v_payload IS NULL THEN RAISE EXCEPTION 'map_catalog has a dangling or foreign icon reference'; END IF;
    WHEN 'content_catalog' THEN
      SELECT jsonb_build_object(
        'information',(SELECT COALESCE(jsonb_agg(jsonb_build_object('id',i.id,'title',i.title,'description',i.description,'order',i."order",'type',i.type,'data',i.data,'aggregateVersion',COALESCE(v.version,0)) ORDER BY i."order",i.id),'[]') FROM public.information i LEFT JOIN public.client_aggregate_versions v ON v.aggregate_type='information' AND v.scope_type='occasion' AND v.scope_id=p_scope_id AND v.aggregate_id=i.id::text WHERE i.occasion=p_scope_id AND NOT i.is_hidden),
        'news',(SELECT COALESCE(jsonb_agg(jsonb_build_object('id',n.id,'message',n.message,'createdAt',n.created_at,'updatedAt',n.updated_at,'aggregateVersion',COALESCE(v.version,0)) ORDER BY n.created_at,n.id),'[]') FROM public.news n LEFT JOIN public.client_aggregate_versions v ON v.aggregate_type='news' AND v.scope_type='occasion' AND v.scope_id=p_scope_id AND v.aggregate_id=n.id::text WHERE n.occasion=p_scope_id),
        'speakers',(SELECT COALESCE(jsonb_agg(jsonb_build_object('id',s.id,'title',s.title,'subtitle',s.subtitle,'description',s.description,'image',s.image,'order',s."order",'data',s.data,'aggregateVersion',COALESCE(v.version,0)) ORDER BY s."order",s.id),'[]') FROM public.speakers s LEFT JOIN public.client_aggregate_versions v ON v.aggregate_type='speaker' AND v.scope_type='occasion' AND v.scope_id=p_scope_id AND v.aggregate_id=s.id::text WHERE s.occasion=p_scope_id AND NOT s.is_hidden),
        'topics',(SELECT COALESCE(jsonb_agg(jsonb_build_object('id',t.id,'title',t.title,'order',t."order",'aggregateVersion',COALESCE(v.version,0)) ORDER BY t."order",t.id),'[]') FROM public.speaker_topics t LEFT JOIN public.client_aggregate_versions v ON v.aggregate_type='speaker_topic' AND v.scope_type='occasion' AND v.scope_id=p_scope_id AND v.aggregate_id=t.id::text WHERE t.occasion=p_scope_id AND NOT t.is_hidden),
        'topicLinks',(SELECT COALESCE(jsonb_agg(jsonb_build_object('speakerId',l.speaker,'topicId',l.topic) ORDER BY l.speaker,l.topic),'[]') FROM public.speaker_topic_links l JOIN public.speakers s ON s.id=l.speaker JOIN public.speaker_topics t ON t.id=l.topic WHERE s.occasion=p_scope_id AND t.occasion=p_scope_id AND NOT s.is_hidden AND NOT t.is_hidden)
      ) INTO v_payload;
    WHEN 'unit_catalog' THEN
      SELECT jsonb_build_object('unit',jsonb_build_object('id',u.id,'title',u.title,'data',u.data,'features',u.features),
        'occasions',COALESCE(jsonb_agg(jsonb_build_object('id',o.id,'title',o.title,'link',o.link,'startTime',o.start_time,'endTime',o.end_time,'description',o.description,'isOpen',o.is_open,'isPromoted',o.is_promoted) ORDER BY o.start_time,o.id) FILTER (WHERE o.id IS NOT NULL),'[]')) INTO v_payload
      FROM public.occasions current_o JOIN public.units u ON u.id=current_o.unit
      LEFT JOIN public.occasions o ON o.unit=u.id AND NOT o.is_hidden
      WHERE current_o.id=p_scope_id GROUP BY u.id;
    WHEN 'live_public' THEN
      SELECT jsonb_build_object(
        'events',(SELECT COALESCE(jsonb_agg(jsonb_build_object('eventId',s.event,'participantCount',s.participant_count,'savedCount',s.saved_count,'remainingCapacity',s.remaining_capacity) ORDER BY s.event),'[]') FROM public.event_public_state s JOIN public.events e ON e.id=s.event WHERE s.occasion=p_scope_id AND NOT e.is_hidden),
        'cleaning',(SELECT COALESCE(jsonb_agg(jsonb_build_object('placeId',s.place,'status',s.status,'openReportCount',s.open_report_count) ORDER BY s.place),'[]') FROM public.cleaning_public_state s WHERE s.occasion=p_scope_id),
        'newsViews',public.get_news_view_counts_v1(p_scope_id)
      ) INTO v_payload;
    ELSE RAISE EXCEPTION 'unsupported public component %',p_component;
  END CASE;
  RETURN jsonb_build_object('protocol',1,'schema',1,'component',p_component,
    'scope',((SELECT organization FROM public.occasions WHERE id=p_scope_id))::text||'/'||p_scope_id::text,
    'revision',v_revision,'generatedAt',COALESCE(v_generated_at,'epoch'::timestamptz),'payload',v_payload);
END; $function$;

-- Source: database/functions/users/reception_qr_login.sql
CREATE OR REPLACE FUNCTION public.get_reception_occasion_users_v1(p_occasion bigint,p_query text DEFAULT '')
RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,extensions AS $$
SELECT CASE
  WHEN public.get_can_use_reception(p_occasion)
    AND (public.can_manage_occasion_participants(p_occasion))
  THEN COALESCE(jsonb_agg(jsonb_build_object(
    'userId',q.id,'name',q.name,'surname',q.surname,'email',q.email_readonly
  ) ORDER BY q.surname,q.name,q.email_readonly),'[]'::jsonb)
  ELSE '[]'::jsonb
END
FROM (
  SELECT ui.id,ui.name,ui.surname,ui.email_readonly
  FROM public.occasion_users ou
  JOIN public.user_info ui ON ui.id=ou."user"
  WHERE ou.occasion=p_occasion
    AND (COALESCE(btrim(p_query),'')=''
      OR public.f_unaccent(COALESCE(ui.name,'')||' '||COALESCE(ui.surname,'')||' '||COALESCE(ui.email_readonly,''))
        ILIKE '%'||public.f_unaccent(btrim(left(p_query,100)))||'%')
  ORDER BY ui.surname,ui.name,ui.email_readonly
  LIMIT 50
) q; $$;

-- Source: database/functions/eshop/get_report_ws.sql
CREATE OR REPLACE FUNCTION public.get_report_ws(occasion_link text)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER
SET search_path = public, extensions AS $$
DECLARE r jsonb; invalid_payment boolean;
BEGIN
  WITH scope AS MATERIALIZED (
    SELECT o.id, o.title FROM public.occasions o
    JOIN public.user_info u ON u.organization = o.organization AND u.id = auth.uid()
    WHERE o.id = public.resolve_occasion_link_internal(occasion_link) AND public.can_read_orders(o.id)
  ), orders_scope AS MATERIALIZED (
    SELECT o.* FROM eshop.orders o JOIN scope s ON s.id = o.occasion
  ), payments AS MATERIALIZED (
    SELECT p.* FROM eshop.payment_info p
    WHERE p.id IN (SELECT payment_info FROM orders_scope)
  ), invalid AS (
    SELECT EXISTS (SELECT 1 FROM payments p JOIN eshop.orders o ON o.payment_info = p.id
      WHERE o.occasion IS DISTINCT FROM (SELECT id FROM scope)
         OR o.currency_code IS DISTINCT FROM p.currency_code) AS value
  ), transactions_scope AS MATERIALIZED (
    SELECT t.* FROM eshop.transactions t JOIN payments p ON p.id=t.payment_info
    WHERE t.currency=p.currency_code
  ), order_days AS (
    SELECT (created_at AT TIME ZONE 'Europe/Prague')::date AS day,currency_code::text AS currency,count(*) AS count
    FROM orders_scope GROUP BY 1,2
  ), payment_days AS (
    SELECT date::date AS day,currency::text AS currency,
      coalesce(sum(amount) FILTER (WHERE amount>0),0)::text AS received,
      coalesce(-sum(amount) FILTER (WHERE amount<0),0)::text AS returned
    FROM transactions_scope GROUP BY 1,2
  ), manual AS (
    SELECT t.payment_info, sum(t.amount) FILTER (WHERE t.transaction_type = 'manual' AND t.amount > 0) AS received
    FROM eshop.transactions t JOIN payments p ON p.id=t.payment_info GROUP BY t.payment_info
  ), order_money AS (
    SELECT currency_code AS currency, sum(coalesce(price,0)) AS value
    FROM orders_scope GROUP BY currency_code
  ), payment_money AS (
    SELECT p.currency_code AS currency, sum(coalesce(p.paid,0)) AS received,
      sum(coalesce(p.returned,0)) AS returned, sum(coalesce(m.received,0)) AS manual,
      bool_or(p.deposit_amount IS NOT NULL) AS deposits,
      sum(CASE WHEN p.deposit_amount IS NOT NULL THEN least(coalesce(p.paid,0),p.deposit_amount) ELSE 0 END) AS deposit,
      sum(CASE WHEN p.deposit_amount IS NOT NULL THEN greatest(coalesce(p.paid,0)-p.deposit_amount,0) ELSE 0 END) AS beyond
    FROM payments p LEFT JOIN manual m ON m.payment_info=p.id GROUP BY p.currency_code
  ), money AS (
    SELECT coalesce(o.currency,p.currency)::text AS currency, coalesce(o.value,0) AS value,
      coalesce(p.received,0) AS received, coalesce(p.returned,0) AS returned,
      coalesce(p.manual,0) AS manual, coalesce(p.deposits,false) AS deposits,
      coalesce(p.deposit,0) AS deposit, coalesce(p.beyond,0) AS beyond
    FROM order_money o FULL JOIN payment_money p USING(currency)
  ), ticket_scope AS (
    SELECT t.* FROM eshop.tickets t JOIN scope s ON s.id=t.occasion
    WHERE EXISTS (SELECT 1 FROM eshop.order_product_ticket i WHERE i.ticket=t.id)
  ), valid_orders AS MATERIALIZED (
    SELECT * FROM orders_scope WHERE state IS DISTINCT FROM 'storno' AND state IS DISTINCT FROM 'waitlisted'
  ), valid_tickets AS MATERIALIZED (
    SELECT t.* FROM ticket_scope t
    WHERE t.state IS DISTINCT FROM 'storno' AND EXISTS (
      SELECT 1 FROM eshop.order_product_ticket i JOIN valid_orders o ON o.id=i."order"
      WHERE i.ticket=t.id
    )
  ), valid_order_days AS (
    SELECT (created_at AT TIME ZONE 'Europe/Prague')::date AS day,currency_code::text AS currency,count(*) AS count
    FROM valid_orders GROUP BY 1,2
  ), ticket_order_dates AS (
    SELECT DISTINCT ON (t.id) t.id,t.created_at,o.currency_code
    FROM ticket_scope t JOIN eshop.order_product_ticket i ON i.ticket=t.id
    JOIN orders_scope o ON o.id=i."order"
    ORDER BY t.id,o.created_at,o.id
  ), valid_ticket_order_dates AS (
    SELECT DISTINCT ON (t.id) t.id,t.created_at,o.currency_code
    FROM valid_tickets t JOIN eshop.order_product_ticket i ON i.ticket=t.id
    JOIN valid_orders o ON o.id=i."order"
    ORDER BY t.id,o.created_at,o.id
  ), ticket_days AS (
    SELECT (created_at AT TIME ZONE 'Europe/Prague')::date AS day,
      currency_code::text AS currency,count(*) AS count
    FROM ticket_order_dates GROUP BY 1,2
  ), valid_ticket_days AS (
    SELECT (created_at AT TIME ZONE 'Europe/Prague')::date AS day,
      currency_code::text AS currency,count(*) AS count
    FROM valid_ticket_order_dates GROUP BY 1,2
  ), order_states AS (
    SELECT coalesce(state,'unknown') AS state,count(*) AS count FROM orders_scope GROUP BY 1
  ), ticket_states AS (
    SELECT coalesce(state,'unknown') AS state,count(*) AS count FROM ticket_scope GROUP BY 1
  ), spots AS (
    SELECT count(*) AS total,count(*) FILTER (WHERE order_product_ticket IS NOT NULL) AS occupied,
      count(*) FILTER (WHERE order_product_ticket IS NULL) AS free
    FROM eshop.spots WHERE occasion IN (SELECT id FROM scope)
  ), products AS (
    SELECT p.id::text AS product_id,coalesce(p.title,'') AS product_title,
      pt.id::text AS type_id,pt.title AS type_title,count(*) AS confirmed_count
    FROM orders_scope o JOIN eshop.order_product_ticket i ON i."order"=o.id
    JOIN eshop.products p ON p.id=i.product LEFT JOIN eshop.product_types pt ON pt.id=p.product_type
    WHERE o.state IN ('paid','sent','used') GROUP BY p.id,pt.id
  ), warnings AS (
    SELECT 'missing_order_price' AS code,count(*) AS count FROM orders_scope WHERE price IS NULL AND state IS DISTINCT FROM 'waitlisted' HAVING count(*)>0
    UNION ALL SELECT 'transaction_currency_mismatch',count(*) FROM eshop.transactions t JOIN payments p ON p.id=t.payment_info WHERE t.currency<>p.currency_code HAVING count(*)>0
    UNION ALL SELECT 'negative_other_received',count(*) FROM money WHERE received-manual<0 HAVING count(*)>0
  )
  SELECT jsonb_build_object(
    'schema_version',1,'occasion',jsonb_build_object('id',s.id::text,'title',coalesce(s.title,'')),
    'generated_at',to_char(statement_timestamp() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
    'spots',(SELECT to_jsonb(spots) FROM spots),
    'orders',jsonb_build_object('total',(SELECT count(*) FROM orders_scope),'by_state',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY state) FROM order_states x),'[]'::jsonb)),
    'tickets',jsonb_build_object('total',(SELECT count(*) FROM ticket_scope),'by_state',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY state) FROM ticket_states x),'[]'::jsonb)),
    'valid',jsonb_build_object(
      'orders',jsonb_build_object('total',(SELECT count(*) FROM valid_orders),'by_state',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY state) FROM (SELECT coalesce(state,'unknown') AS state,count(*) AS count FROM valid_orders GROUP BY 1) x),'[]'::jsonb)),
      'tickets',jsonb_build_object('total',(SELECT count(*) FROM valid_tickets),'by_state',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY state) FROM (SELECT coalesce(state,'unknown') AS state,count(*) AS count FROM valid_tickets GROUP BY 1) x),'[]'::jsonb)),
      'ticket_days',coalesce((SELECT jsonb_agg(to_jsonb(d) ORDER BY day,currency) FROM valid_ticket_days d),'[]'::jsonb),
      'order_days',coalesce((SELECT jsonb_agg(to_jsonb(d) ORDER BY day,currency) FROM valid_order_days d),'[]'::jsonb)
    ),
    'money_by_currency',coalesce((SELECT jsonb_agg(jsonb_build_object(
      'currency',currency,'current_order_value',value::text,'received',received::text,'returned',returned::text,
      'net_received',(received-returned)::text,'manual_received',manual::text,'other_received',(received-manual)::text,
      'has_deposits',deposits,'deposit_received_gross',deposit::text,'beyond_deposit_received_gross',beyond::text
    ) ORDER BY currency) FROM money),'[]'::jsonb),
    'timeline',jsonb_build_object(
      'order_timezone','Europe/Prague','payment_date_basis','transaction_date',
      'tickets',coalesce((SELECT jsonb_agg(to_jsonb(d) ORDER BY day,currency) FROM ticket_days d),'[]'::jsonb),
      'orders',coalesce((SELECT jsonb_agg(to_jsonb(d) ORDER BY day) FROM order_days d),'[]'::jsonb),
      'payments',coalesce((SELECT jsonb_agg(to_jsonb(d) ORDER BY day,currency) FROM payment_days d),'[]'::jsonb)
    ),
    'products',coalesce((SELECT jsonb_agg(to_jsonb(p) ORDER BY type_id,product_id) FROM products p),'[]'::jsonb),
    'warnings',coalesce((SELECT jsonb_agg(to_jsonb(w) ORDER BY code) FROM warnings w),'[]'::jsonb)
  ), invalid.value INTO r,invalid_payment FROM scope s CROSS JOIN invalid;
  IF r IS NULL THEN RETURN jsonb_build_object('code',403,'message','Report unavailable or access denied.'); END IF;
  IF invalid_payment THEN RETURN jsonb_build_object('code',409,'message','Report payment allocation is inconsistent.'); END IF;
  RETURN jsonb_build_object('code',200,'data',public.format_occasion_report_text(r),'report',r);
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('code',500,'message','Report could not be generated.');
END;
$$;

-- Source: database/functions/public_links/legacy_readers.sql
CREATE OR REPLACE FUNCTION public.get_reservations(p_occasion_link text, p_form_link text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
SET search_path = public, extensions
AS $function$
DECLARE
    v_occasion_id BIGINT;
    v_form_key UUID;
    spotsData JSONB;
    productsData JSONB;
    productTypesData JSONB;
    ticketsData JSONB;
    ordersData JSONB;
    orderProductTicketsData JSONB;
    paymentInfoData JSONB;
    formsData JSONB;
BEGIN
    -- 1. Input Validation: Ensure at least one link is provided.
    IF p_occasion_link IS NULL AND p_form_link IS NULL THEN
        RETURN jsonb_build_object('code', 400, 'message', 'Either occasion_link or form_link must be provided');
    END IF;

    -- 2. Determine occasion_id based on the provided link.
    -- occasion_link has priority.
    IF p_occasion_link IS NOT NULL THEN
        SELECT id
        INTO v_occasion_id
        FROM public.occasions
        WHERE id = public.resolve_occasion_link_internal(p_occasion_link);
    ELSE -- If occasion_link is NULL, use form_link
        SELECT occasion, key
        INTO v_occasion_id, v_form_key
        FROM public.forms
        WHERE id = public.resolve_form_link_internal(p_form_link);
    END IF;

    -- 3. Check if a valid occasion was found.
    IF v_occasion_id IS NULL THEN
        RETURN jsonb_build_object('code', 404, 'message', 'The provided link is invalid or not linked to any occasion');
    END IF;

    -- 4. Authorization check.
    IF (SELECT can_read_orders(v_occasion_id)) <> TRUE THEN
        RETURN jsonb_build_object('code', 403, 'message', 'User is not authorized to access this occasion');
    END IF;

    -- Fetch spots where order_product_ticket is not NULL
    SELECT jsonb_agg(jsonb_build_object(
        'id', s.id,
        'title', s.title,
        'product', s.product,
        'order_product_ticket', s.order_product_ticket,
        'state', CASE
            WHEN s.order_product_ticket IS NOT NULL THEN 'ordered'
            WHEN s.secret IS NOT NULL AND s.secret_expiration_time > now() THEN 'selected'
            ELSE 'available'
        END
    ))
    INTO spotsData
    FROM eshop.spots s
    WHERE s.occasion = v_occasion_id
      AND s.order_product_ticket IS NOT NULL;

    -- Fetch all products linked to the occasion
    SELECT jsonb_agg(jsonb_build_object(
        'id', p.id,
        'title', p.title,
        'price', p.price,
        'currency_code', p.currency_code,
        'type', pt.type,
        'description', pt.description
    ))
    INTO productsData
    FROM eshop.products p
    JOIN eshop.product_types pt ON pt.id = p.product_type
    WHERE pt.occasion = v_occasion_id;

    -- Fetch product types for the occasion
    SELECT jsonb_agg(jsonb_build_object(
        'id', pt.id,
        'type', pt.type,
        'title', pt.title,
        'description', pt.description
    ))
    INTO productTypesData
    FROM eshop.product_types pt
    WHERE pt.occasion = v_occasion_id;

    -- Fetch tickets linked to the occasion
    SELECT jsonb_agg(jsonb_build_object(
        'id', t.id,
        'created_at', t.created_at,
        'ticket_symbol', t.ticket_symbol,
        'state', t.state,
        'note', t.note,
        'note_hidden', t.note_hidden
    ))
    INTO ticketsData
    FROM eshop.tickets t
    WHERE t.occasion = v_occasion_id;

    -- Fetch forms linked to the occasion
    SELECT jsonb_agg(jsonb_build_object(
        'id', f.id,
        'created_at', f.created_at,
        'data', f.data,
        'key', f.key,
        'occasion', f.occasion,
        'type', f.type,
        'deadline_duration_seconds', f.deadline_duration_seconds,
        'is_open', f.is_open,
        'link', f.link,
        'blueprint', f.blueprint,
        'title', f.title,
        'header', f.header,
        'header_off', f.header_off,
        'updated_at', f.updated_at
    ))
    INTO formsData
    FROM public.forms f
    WHERE f.occasion = v_occasion_id;

    -- Fetch orders - this is the conditional part.
    -- If v_form_key is not NULL, it means we are filtering by form.
    IF v_form_key IS NOT NULL THEN
        SELECT jsonb_agg(jsonb_build_object(
            'id', o.id,
            'created_at', o.created_at,
            'updated_at', o.updated_at,
            'price', o.price,
            'state', o.state,
            'currency_code', o.currency_code,
            'data', o.data,
            'payment_info', o.payment_info,
            'note_hidden', o.note_hidden
        ))
        INTO ordersData
        FROM eshop.orders o
        WHERE o.occasion = v_occasion_id
          AND o.data->>'form' = v_form_key::TEXT; -- Filter by the form's key
    ELSE
        -- Original query if not filtering by form
        SELECT jsonb_agg(jsonb_build_object(
            'id', o.id,
            'created_at', o.created_at,
            'updated_at', o.updated_at,
            'price', o.price,
            'state', o.state,
            'currency_code', o.currency_code,
            'data', o.data,
            'payment_info', o.payment_info,
            'note_hidden', o.note_hidden
        ))
        INTO ordersData
        FROM eshop.orders o
        WHERE o.occasion = v_occasion_id;
    END IF;

    -- Extract order IDs from the (potentially filtered) ordersData JSONB
    WITH order_ids AS (
        SELECT (order_obj->>'id')::BIGINT AS id
        FROM jsonb_array_elements(COALESCE(ordersData, '[]'::jsonb)) order_obj
    )
    -- Fetch relevant order-product-ticket data based on extracted order IDs
    SELECT jsonb_agg(jsonb_build_object(
        'id', opt.id,
        'order', opt."order",
        'product', opt.product,
        'ticket', opt.ticket,
        'created_at', opt.created_at
    ))
    INTO orderProductTicketsData
    FROM eshop.order_product_ticket opt
    WHERE opt."order" IN (SELECT id FROM order_ids);

    -- Fetch payment information linked to the orders
    SELECT jsonb_agg(jsonb_build_object(
        'id', pi.id,
        'created_at', pi.created_at,
        'bank_account', pi.bank_account,
        'variable_symbol', pi.variable_symbol,
        'amount', pi.amount,
        'paid', pi.paid,
        'returned', pi.returned,
        'deadline', pi.deadline,
        'currency_code', pi.currency_code,
        'data', pi.data
    ))
    INTO paymentInfoData
    FROM eshop.payment_info pi
    WHERE pi.id IN (
        SELECT DISTINCT (order_obj->>'payment_info')::BIGINT
        FROM jsonb_array_elements(COALESCE(ordersData, '[]'::jsonb)) order_obj
        WHERE order_obj->>'payment_info' IS NOT NULL
    );

    -- Return combined data
    RETURN jsonb_build_object(
        'code', 200,
        'data', jsonb_build_object(
            'spots', COALESCE(spotsData, '[]'::jsonb),
            'products', COALESCE(productsData, '[]'::jsonb),
            'product_types', COALESCE(productTypesData, '[]'::jsonb),
            'tickets', COALESCE(ticketsData, '[]'::jsonb),
            'orders', COALESCE(ordersData, '[]'::jsonb),
            'order_product_ticket', COALESCE(orderProductTicketsData, '[]'::jsonb),
            'payment_info', COALESCE(paymentInfoData, '[]'::jsonb),
            'forms', COALESCE(formsData, '[]'::jsonb)
        )
    );
END;
$function$;

-- Source: database/functions/eshop_orders/get_scan_code.sql
CREATE OR REPLACE FUNCTION get_scan_code(
    occasion_link TEXT
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
    occasion_id BIGINT;
    current_scan_code TEXT;
BEGIN
    -- 1. Retrieve occasion_id using occasion_link
    SELECT id
    INTO occasion_id
    FROM public.occasions
    WHERE id = public.resolve_occasion_link_internal(occasion_link);

    -- 2. Check if occasion_link is valid
    IF occasion_id IS NULL THEN
        RETURN jsonb_build_object(
            'code', 404,
            'message', 'Occasion link does not exist.'
        );
    END IF;

    -- 3. Verify if the user is an editor on the occasion
    IF NOT can_read_orders(occasion_id) THEN
        RETURN jsonb_build_object(
            'code', 403,
            'message', 'User is not authorized to view scan code for this occasion.'
        );
    END IF;

    -- 4. Retrieve the scan_code from the occasions_hidden table via the foreign key
    SELECT oh.secret
    INTO current_scan_code
    FROM public.occasions_hidden oh
    JOIN public.occasions o ON o.occasion_hidden = oh.id
    WHERE o.id = occasion_id
    LIMIT 1;

    -- 4.a. Handle case where scan_code is not found
    IF current_scan_code IS NULL THEN
        RETURN jsonb_build_object(
            'code', 404,
            'message', 'Scan code not found for the specified occasion.'
        );
    END IF;

    -- 5. Return the scan_code
    RETURN jsonb_build_object(
        'code', 200,
        'message', 'Scan code retrieved successfully.',
        'scan_code', current_scan_code
    );

EXCEPTION
    WHEN OTHERS THEN
        -- Handle any unexpected exceptions
        RETURN jsonb_build_object(
            'code', 500,
            'message', 'An unexpected error occurred.',
            'detail', SQLERRM
        );
END;
$$;

-- Source: database/functions/speakers/get_speakers_editor_bundle_v1.sql
CREATE OR REPLACE FUNCTION public.get_speakers_editor_bundle_v1(p_occasion bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path = public, extensions
AS $function$
DECLARE v_speakers jsonb; v_topics jsonb;
BEGIN
  IF NOT public.can_read_speakers_editor(p_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='occasion editor view required';
  END IF;
  SELECT COALESCE(jsonb_agg(q.value ORDER BY q.sort_order,q.sort_title),'[]'::jsonb)
    INTO v_speakers FROM (
    SELECT s."order" sort_order,s.title sort_title,
      to_jsonb(s)||jsonb_build_object(
        'aggregate_version',COALESCE(v.version,0),
        'topics',COALESCE((SELECT jsonb_agg(l.topic ORDER BY l.topic)
          FROM public.speaker_topic_links l WHERE l.speaker=s.id),'[]'::jsonb),
        'events',COALESCE((SELECT jsonb_agg(jsonb_build_object(
          'id',e.id,'title',e.title,'start_time',e.start_time,
          'end_time',e.end_time,'max_participants',e.max_participants,
          'occupied',(SELECT count(*) FROM public.event_users eu WHERE eu.event=e.id),
          'is_counseling_slot',COALESCE((e.data->>'is_counseling_slot')::boolean,false),
          'aggregate_version',COALESCE(ev.version,0)) ORDER BY e.start_time,e.id)
          FROM public.event_speakers es JOIN public.events e ON e.id=es.event
          LEFT JOIN public.client_aggregate_versions ev ON ev.aggregate_type='event'
            AND ev.scope_type='occasion' AND ev.scope_id=p_occasion
            AND ev.aggregate_id=e.id::text WHERE es.speaker=s.id),'[]'::jsonb)
      ) value
    FROM public.speakers s LEFT JOIN public.client_aggregate_versions v
      ON v.aggregate_type='speaker' AND v.scope_type='occasion'
      AND v.scope_id=p_occasion AND v.aggregate_id=s.id::text
    WHERE s.occasion=p_occasion
  ) q;
  SELECT COALESCE(jsonb_agg(to_jsonb(t)||jsonb_build_object(
      'aggregate_version',COALESCE(v.version,0)) ORDER BY t."order",t.title,t.id),
      '[]'::jsonb) INTO v_topics
  FROM public.speaker_topics t LEFT JOIN public.client_aggregate_versions v
    ON v.aggregate_type='speaker_topic' AND v.scope_type='occasion'
    AND v.scope_id=p_occasion AND v.aggregate_id=t.id::text
  WHERE t.occasion=p_occasion;
  RETURN jsonb_build_object('code',200,'data',jsonb_build_object(
    'speakers',v_speakers,'speaker_topics',v_topics));
END; $function$
;

-- Source: database/functions/speakers/get_speakers_for_edit.sql
CREATE OR REPLACE FUNCTION public.get_speakers_for_edit(p_occasion BIGINT)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
    v_speakers JSONB;
    v_topics   JSONB;
BEGIN
    -- Admin read: all speakers and topics, including hidden.
    IF NOT public.can_read_speakers_editor(p_occasion) THEN
        RETURN jsonb_build_object('code', 403);
    END IF;

    -- Speakers (all columns) + competence topic ids + linked events with
    -- occupancy. Ordered by "order", title.
    SELECT COALESCE(jsonb_agg(q.sp ORDER BY q.sp_order, q.sp_title), '[]'::jsonb)
    INTO v_speakers
    FROM (
        SELECT
            to_jsonb(s) || jsonb_build_object(
                'topics', COALESCE((
                    SELECT jsonb_agg(stl.topic ORDER BY stl.topic)
                    FROM public.speaker_topic_links stl
                    WHERE stl.speaker = s.id
                ), '[]'::jsonb),
                'events', COALESCE((
                    SELECT jsonb_agg(jsonb_build_object(
                        'id',                 e.id,
                        'title',              e.title,
                        'start_time',         e.start_time,
                        'end_time',           e.end_time,
                        'max_participants',   e.max_participants,
                        'occupied',           (SELECT count(*) FROM public.event_users eu WHERE eu.event = e.id),
                        'is_counseling_slot', COALESCE((e.data->>'is_counseling_slot')::boolean, FALSE)
                    ) ORDER BY e.start_time)
                    FROM public.event_speakers es
                    JOIN public.events e ON e.id = es.event
                    WHERE es.speaker = s.id
                ), '[]'::jsonb)
            ) AS sp,
            s."order" AS sp_order,
            s.title   AS sp_title
        FROM public.speakers s
        WHERE s.occasion = p_occasion
    ) q;

    -- Full topic catalog, including hidden.
    SELECT COALESCE(jsonb_agg(to_jsonb(t) ORDER BY t."order", t.title), '[]'::jsonb)
    INTO v_topics
    FROM public.speaker_topics t
    WHERE t.occasion = p_occasion;

    RETURN jsonb_build_object(
        'code', 200,
        'data', jsonb_build_object(
            'speakers',       v_speakers,
            'speaker_topics', v_topics
        )
    );
END;
$$;

-- Source: database/functions/inventory/get_spot_management_bundle.sql
CREATE OR REPLACE FUNCTION get_spot_management_bundle(p_inventory_pool_id bigint)
RETURNS jsonb
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
    v_occasion_id bigint;
    v_spots_data jsonb;
    v_inventory_contexts_data jsonb;
    v_resources_data jsonb;
    v_resource_slots_data jsonb;
    v_order_product_tickets_data jsonb;
    v_orders_data jsonb;
    result jsonb;
BEGIN
    -- Get occasion for permission check from the inventory pool
    SELECT occasion INTO v_occasion_id
    FROM public.inventory_pools
    WHERE id = p_inventory_pool_id;

    IF v_occasion_id IS NULL THEN
        RAISE EXCEPTION 'Inventory Pool not found.';
    END IF;

    -- Permission check (assuming a similar function exists for order view)
    IF NOT can_read_orders(v_occasion_id) THEN
        RAISE EXCEPTION 'User is not authorized to view this occasion.';
    END IF;

    -- Aggregate all inventory_contexts for the pool
    SELECT COALESCE(jsonb_agg(to_jsonb(ic) ORDER BY ic.block_date), '[]'::jsonb)
    INTO v_inventory_contexts_data
    FROM public.inventory_contexts ic
    WHERE ic.inventory_pool = p_inventory_pool_id;

    -- Aggregate all spots that belong to any context within the specified pool
    SELECT COALESCE(jsonb_agg(to_jsonb(s) ORDER BY s.id), '[]'::jsonb)
    INTO v_spots_data
    FROM eshop.spots s
    WHERE s.inventory_context IN (
        SELECT id FROM public.inventory_contexts WHERE inventory_pool = p_inventory_pool_id
    );

    -- Aggregate all resources for the pool
    SELECT COALESCE(jsonb_agg(to_jsonb(r) ORDER BY r.title), '[]'::jsonb)
    INTO v_resources_data
    FROM public.resources r
    WHERE r.inventory_pool = p_inventory_pool_id;

    -- Aggregate all resource slots for all resources within the pool
    SELECT COALESCE(jsonb_agg(to_jsonb(rs) ORDER BY rs.id), '[]'::jsonb)
    INTO v_resource_slots_data
    FROM public.resource_slots rs
    WHERE rs.resource IN (
        SELECT id FROM public.resources WHERE inventory_pool = p_inventory_pool_id
    );

    -- NEW: Aggregate all order_product_tickets related to the spots in the pool
    SELECT COALESCE(jsonb_agg(to_jsonb(opt) ORDER BY opt.id), '[]'::jsonb)
    INTO v_order_product_tickets_data
    FROM eshop.order_product_ticket opt
    WHERE opt.id IN (
        SELECT DISTINCT s.order_product_ticket
        FROM eshop.spots s
        WHERE s.inventory_context IN (
            SELECT id FROM public.inventory_contexts WHERE inventory_pool = p_inventory_pool_id
        ) AND s.order_product_ticket IS NOT NULL
    );

    -- NEW: Aggregate all orders related to those order_product_tickets
    SELECT COALESCE(jsonb_agg(to_jsonb(o) ORDER BY o.id), '[]'::jsonb)
    INTO v_orders_data
    FROM eshop.orders o
    WHERE o.id IN (
        SELECT DISTINCT opt."order"
        FROM eshop.order_product_ticket opt
        WHERE opt.id IN (
            SELECT DISTINCT s.order_product_ticket
            FROM eshop.spots s
            WHERE s.inventory_context IN (
                SELECT id FROM public.inventory_contexts WHERE inventory_pool = p_inventory_pool_id
            ) AND s.order_product_ticket IS NOT NULL
        ) AND opt."order" IS NOT NULL
    );

    -- Construct the final bundle object with the new data
    result := jsonb_build_object(
        'spots', v_spots_data,
        'inventory_contexts', v_inventory_contexts_data,
        'resources', v_resources_data,
        'resource_slots', v_resource_slots_data,
        'order_product_tickets', v_order_product_tickets_data, -- Added
        'orders', v_orders_data  -- Added
    );

    RETURN result;
EXCEPTION
    WHEN OTHERS THEN
        -- A more robust error handling for production
        RETURN jsonb_build_object('code', 500, 'message', SQLERRM);
END;
$$ LANGUAGE plpgsql;

-- Source: database/functions/abuse/documents.sql
-- Authorization, resource selection and admission happen before the existing
-- expensive read. The transport never supplies an actor, Unit or Organization.
CREATE OR REPLACE FUNCTION public.get_ticket_document_data_v1(p_ticket bigint)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE occ bigint;
BEGIN
 SELECT occasion INTO occ FROM eshop.tickets WHERE id=p_ticket;
 IF occ IS NULL OR NOT (public.is_service_role() OR (auth.uid() IS NOT NULL AND public.can_read_orders(occ))) THEN
  RAISE insufficient_privilege USING MESSAGE='ticket document access denied'; END IF;
 PERFORM public.admit_ticket_document_internal_v1(occ);
 RETURN public.bound_document_data_v1(public.get_ticket_details_for_generating(p_ticket));
END $$;

-- Source: database/functions/others/get_ticket_layout_for_authoring_v1.sql
-- Minimal authoring projection. No orders, buyers, QR or hold secrets.
CREATE OR REPLACE FUNCTION public.get_ticket_layout_for_authoring_v1(p_occasion bigint)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE result jsonb;
BEGIN
 IF NOT public.can_read_ticket_layout(p_occasion) THEN
  RAISE insufficient_privilege USING MESSAGE='unit editor required'; END IF;
 SELECT jsonb_build_object('occasion',o.id,'aggregate_version',coalesce(v.version,0),
  'schemaVersion',3,'appearance',coalesce((SELECT jsonb_build_object('layout',f->'layout',
    'background',f->'background','ticket_type',f->'ticket_type') FROM jsonb_array_elements(o.features) f WHERE f->>'code'='ticket'),'{}'),
  'images',coalesce((SELECT jsonb_agg(i.link ORDER BY i.id) FROM public.images i WHERE i.occasion=o.id OR i.unit=o.unit),'[]'))
 INTO result FROM public.occasions o LEFT JOIN public.client_aggregate_versions v
 ON v.aggregate_type='occasion' AND v.scope_type='occasion' AND v.scope_id=o.id AND v.aggregate_id=o.id::text
 WHERE o.id=p_occasion;
 RETURN result;
END $$;

-- Source: database/functions/eshop_transactions/get_transactions_for_order.sql
CREATE OR REPLACE FUNCTION public.get_transactions_for_order(order_id bigint)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
  v_occasion_id bigint;
BEGIN

  SELECT occasion INTO v_occasion_id FROM eshop.orders WHERE id = order_id;
  IF NOT can_read_orders(v_occasion_id) THEN
    RAISE EXCEPTION 'User is not authorized to view transactions for this occasion.' USING ERRCODE = 'P0001';
  END IF;

  RETURN (
    SELECT jsonb_build_object(
      'order_state', o.state,
      'payment_info', (
        SELECT to_jsonb(pi)
        FROM eshop.payment_info pi
        WHERE pi.id = o.payment_info
      ),
      'transactions', COALESCE((
        SELECT jsonb_agg(
            to_jsonb(t) || jsonb_build_object('createdByName',
                trim(both from COALESCE(ui.name, '') || ' ' || COALESCE(ui.surname, ''))
            )
        )
        FROM eshop.transactions t
        LEFT JOIN public.user_info ui ON t.created_by = ui.id
        WHERE t.payment_info = o.payment_info
      ), '[]'::jsonb)
    )
    FROM eshop.orders o
    WHERE o.id = order_id
  );
END;
$$;

-- Source: database/functions/eshop_transactions/get_transactions_for_order_all_available.sql
CREATE OR REPLACE FUNCTION public.get_transactions_for_order_all_available(payment_info_id bigint)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
    bank_acc bigint;
BEGIN
    SELECT pi.bank_account INTO bank_acc
    FROM eshop.payment_info pi
    WHERE pi.id = payment_info_id
    LIMIT 1;

    IF NOT EXISTS (SELECT 1 FROM public.demo_occasions demo_bank WHERE demo_bank.bank_account=bank_acc AND public.can_read_orders(demo_bank.occasion)) THEN
        PERFORM public.check_is_admin_for_bank_account(bank_acc);
    END IF;

    RETURN (
        SELECT jsonb_agg(t ORDER BY t.date DESC)
        FROM eshop.transactions t
        WHERE t.bank_account_id = (
            SELECT pi.bank_account
            FROM eshop.payment_info pi
            WHERE pi.id = payment_info_id
        )
        AND t.payment_info IS NULL
    );
END;
$$;

-- Source: database/functions/abuse/policy.sql
CREATE OR REPLACE FUNCTION public.get_unit_abuse_policy_v1(p_unit bigint) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE v_org bigint;
BEGIN
 IF auth.uid() IS NULL OR NOT public.can_read_unit_abuse_policy(p_unit) THEN
  RAISE insufficient_privilege USING MESSAGE='unit editor required'; END IF;
 SELECT organization INTO v_org FROM public.units WHERE id=p_unit;
 RETURN jsonb_build_object('creation',public.abuse_effective_rules_v1('occasion.creation',p_unit,v_org),
 'draft',public.abuse_effective_rules_v1('occasion.draft',p_unit,v_org),
 'usage',coalesce((SELECT jsonb_agg(jsonb_build_object('rule',u.rule_key,'amount',u.amount,'bucketAt',u.bucket_at,'expiresAt',u.expires_at))
 FROM public.abuse_budget_usage u JOIN public.abuse_policy_rules r USING(rule_key)
 WHERE u.expires_at>statement_timestamp() AND ((r.scope_kind='unit' AND u.scope_id=p_unit::text)
 OR (r.scope_kind='actor' AND u.scope_id=auth.uid()::text))),'[]'::jsonb));
END $$;

-- Source: database/functions/organization/unit_app_landing.sql
-- The landing occasion belongs to the organization, not to each unit.
CREATE OR REPLACE FUNCTION public.get_unit_app_landing(p_unit bigint)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
  v_org bigint;
  v_data jsonb;
  v_occasion bigint;
  v_title text;
  v_admin boolean;
BEGIN
  SELECT organization INTO v_org FROM public.units WHERE id = p_unit;
  v_admin := public.can_manage_unit_app_landing(p_unit);
  IF v_org IS NULL OR NOT public.can_read_unit_app_landing(p_unit) THEN
    RAISE insufficient_privilege USING MESSAGE = 'Access denied';
  END IF;
  SELECT data INTO v_data FROM public.organizations WHERE id = v_org;
  v_occasion := (v_data->>'DEFAULT_OCCASION')::bigint;
  SELECT title INTO v_title FROM public.occasions
    WHERE id = v_occasion AND organization = v_org;
  RETURN jsonb_build_object('enabled', coalesce((v_data->>'IS_APP_SUPPORTED')::boolean, false),
    'occasion_id', v_occasion, 'occasion_title', v_title, 'can_manage', v_admin);
END;
$$;

-- Source: database/functions/units/get_unit_edit_data_v1.sql
CREATE OR REPLACE FUNCTION public.get_unit_edit_data_v1(p_unit bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path = public, extensions
AS $function$
DECLARE v_result jsonb; v_version bigint;
BEGIN
  IF auth.uid() IS NULL OR NOT public.can_manage_unit_configuration(p_unit) THEN
    RAISE insufficient_privilege USING MESSAGE='unit manager required'; END IF;
  v_result:=public.get_unit_edit_data(p_unit);
  SELECT COALESCE(v.version,0) INTO v_version
    FROM (SELECT 1) seed LEFT JOIN public.client_aggregate_versions v
      ON v.aggregate_type='unit' AND v.scope_type='unit'
      AND v.scope_id=p_unit AND v.aggregate_id=p_unit::text;
  RETURN jsonb_set(v_result,'{unit}',(v_result->'unit')||
    jsonb_build_object('aggregate_version',v_version));
END; $function$
;

-- Source: database/functions/others/get_unit_for_edit.sql
CREATE OR REPLACE FUNCTION public.get_unit_for_edit(unit_id bigint) RETURNS jsonb
LANGUAGE plpgsql STABLE
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
    unit_data jsonb;
BEGIN
    -- Check if the current user is authorized (editor or manager) for the provided unit
    IF NOT public.can_read_unit_occasion_catalog(unit_id) THEN
        RETURN jsonb_build_object('code', 403);
    END IF;

    -- Retrieve the unit data as jsonb
    SELECT jsonb_build_object(
        'id', id,
        'title', title,
        'data', data,
        'features', features,
        'organization', organization,
        'aggregate_version', coalesce((SELECT v.version FROM public.client_aggregate_versions v
          WHERE v.aggregate_type='unit' AND v.scope_type='unit' AND v.scope_id=unit_id
          AND v.aggregate_id=unit_id::text),0)
    ) INTO unit_data
    FROM units
    WHERE id = unit_id;

    -- Return the unit data with a 200 code
    RETURN jsonb_build_object('code', 200, 'data', unit_data);
END;
$$;

-- Source: database/functions/information/unit_information.sql
CREATE OR REPLACE FUNCTION public.get_unit_information_for_edit_v1(p_unit bigint,p_type text DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,extensions AS $$
BEGIN
 IF auth.uid() IS NULL OR NOT public.can_read_unit_information(p_unit) THEN
  RAISE insufficient_privilege USING MESSAGE='unit editor view required'; END IF;
 IF p_type='game' THEN RAISE invalid_parameter_value USING MESSAGE='unit games unsupported'; END IF;
 RETURN coalesce((SELECT jsonb_agg(to_jsonb(i)||jsonb_build_object('aggregate_version',coalesce(v.version,0)) ORDER BY i.id)
 FROM public.information i LEFT JOIN public.client_aggregate_versions v ON v.aggregate_type='information'
 AND v.scope_type='unit' AND v.scope_id=p_unit AND v.aggregate_id=i.id::text
 WHERE i.unit=p_unit AND i.occasion IS NULL AND i.information_hidden IS NULL
 AND coalesce(i.type,'')=coalesce(p_type,'')),'[]');
END $$;

-- Source: database/functions/organization_verification/profile_commands.sql
CREATE OR REPLACE FUNCTION public.get_unit_legal_profile(p_unit bigint)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE p public.unit_legal_profiles; org bigint; admin boolean; result jsonb;
BEGIN
 SELECT organization INTO org FROM public.units WHERE id=p_unit;
 admin:=coalesce(public.check_is_admin_of_organization(org),false);
 IF auth.uid() IS NULL OR org IS NULL OR NOT public.can_read_unit_legal_profile(p_unit) THEN
  RAISE EXCEPTION 'Legal profile access denied' USING ERRCODE='42501';
 END IF;
 SELECT * INTO p FROM public.unit_legal_profiles WHERE unit_id=p_unit;
 result:=jsonb_build_object('unitId',p_unit,'revision',coalesce(p.revision,0),'status',coalesce(p.status,'unverified'),
 'legalName',coalesce(p.legal_name,''),'countryCode',coalesce(p.country_code,''),
 'registrationNumber',coalesce(p.registration_number,''),'vatId',coalesce(p.vat_id,''),
 'address',jsonb_build_object('street',coalesce(p.street,''),'city',coalesce(p.city,''),'postalCode',coalesce(p.postal_code,'')),
 'contactEmail',coalesce(p.contact_email,''),'phone',coalesce(p.phone,''),'website',coalesce(p.website,''),
 'submittedAt',p.submitted_at,'verifiedAt',CASE WHEN p.status='verified' AND p.reviewed_organization_id=org THEN p.reviewed_at END,
 'feedbackToApplicant',CASE WHEN p.reviewed_organization_id=org THEN p.feedback_to_applicant END);
 IF admin AND p.reviewed_organization_id=org THEN
  result:=result||jsonb_build_object('reviewNote',p.review_note,'reviewSource',p.review_source);
 END IF;
 RETURN jsonb_build_object('code',200,'profile',result);
END $$;

-- Source: database/functions/groups/group_editor_read.sql
CREATE OR REPLACE FUNCTION public.get_user_group_editor_bundle_v1(p_occasion bigint,p_group_id bigint)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public, extensions AS $$
BEGIN
 IF auth.uid() IS NULL OR NOT public.can_read_group_editor(p_occasion,p_group_id) THEN
