    current_user_id UUID := auth.uid();
BEGIN
 RETURN public.get_user_groups_for_context_internal_v1(p_occasion_id,
   public.get_is_editor_on_occasion(p_occasion_id),public.get_is_editor_view_on_occasion(p_occasion_id),
