-- Source: database/functions/groups/get_user_groups_editor_bundle_v1.sql
CREATE OR REPLACE FUNCTION public.get_user_groups_editor_bundle_v1(p_occasion bigint, p_type text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path=public,extensions
AS $function$
DECLARE v_groups jsonb; v_places jsonb; v_game_definitions jsonb;
BEGIN
  IF public.can_read_groups_editor(p_occasion) IS NOT TRUE THEN
    RAISE insufficient_privilege USING MESSAGE='occasion editor view required';
  END IF;
  SELECT COALESCE(jsonb_agg(public.get_user_group_command_data_v1(g.id)||
    jsonb_build_object('aggregate_version',COALESCE(v.version,0))
    ORDER BY g.title,g.id),'[]'::jsonb) INTO v_groups
  FROM public.user_group_info g LEFT JOIN public.client_aggregate_versions v
    ON v.aggregate_type='user_group' AND v.scope_type='occasion'
    AND v.scope_id=p_occasion AND v.aggregate_id=g.id::text
  WHERE g.occasion=p_occasion AND (p_type IS NULL AND g.type IS NULL OR g.type=p_type);
  SELECT COALESCE(jsonb_agg(to_jsonb(p)||jsonb_build_object(
    'aggregate_version',COALESCE(v.version,0)) ORDER BY p."order" NULLS LAST,p.title),
    '[]'::jsonb) INTO v_places FROM public.places p
  LEFT JOIN public.client_aggregate_versions v ON v.aggregate_type='place'
    AND v.scope_type='occasion' AND v.scope_id=p_occasion
    AND v.aggregate_id=p.id::text
  WHERE p.occasion=p_occasion AND NOT p.is_hidden
    AND p.coordinates->'latLng'->>'lat' IS NOT NULL
    AND p.coordinates->'latLng'->>'lng' IS NOT NULL;
  IF p_type='game' THEN
    SELECT jsonb_object_agg(i.id,i.title) INTO v_game_definitions
    FROM public.information i WHERE i.occasion=p_occasion AND i.type='game';
  END IF;
  RETURN jsonb_build_object('groups',v_groups,'places',v_places,
    'game_definitions',v_game_definitions);
END; $function$
;

-- Source: database/functions/users/get_user_info_for_users.sql
CREATE OR REPLACE FUNCTION public.get_user_info_for_users(user_ids uuid[], oc bigint)
RETURNS jsonb
SECURITY definer
SET search_path = public, extensions
AS $$
DECLARE
  companions jsonb;
BEGIN
  -- Check if the user is a manager, editor, or approver for the occasion
  IF (SELECT public.can_read_participant_contacts(oc)) <> TRUE THEN
      RETURN jsonb_build_object('code', 403);
  END IF;

  -- Aggregate the user information as JSON
  SELECT jsonb_agg(
    jsonb_build_object(
      'id', ui.id,
      'created_at', ui.created_at,
      'updated_at', ui.updated_at,
      'email_readonly', ui.email_readonly,
      'name', ui.name,
      'surname', ui.surname,
      'sex', ui.sex,
      'phone', ui.phone,
      'data', ui.data,
      'birth_date', ui.birth_date,
      'companion_parent', (
        SELECT jsonb_build_object(
          'id', parent_ui.id,
          'created_at', parent_ui.created_at,
          'updated_at', parent_ui.updated_at,
          'email_readonly', parent_ui.email_readonly,
          'name', parent_ui.name,
          'surname', parent_ui.surname,
          'sex', parent_ui.sex,
          'phone', parent_ui.phone,
          'data', parent_ui.data,
          'birth_date', parent_ui.birth_date
        )
        FROM public.user_info parent_ui
        WHERE parent_ui.id = uc."user"
      )
    )
  ) INTO companions
  FROM public.user_info ui
  LEFT JOIN public.user_companions uc ON ui.id = uc.companion AND uc.occasion=oc
  WHERE ui.id = ANY(user_ids);

  -- If no companions are found, return an empty array
  IF companions IS NULL THEN
    companions := '[]'::jsonb;
  END IF;

  RETURN jsonb_build_object(
    'code', 200,
    'data', companions
  );
END;
$$ LANGUAGE plpgsql;

-- Source: database/functions/eshop_waitlist/email_context.sql
CREATE OR REPLACE FUNCTION public.get_waitlist_email_context_v1(p_operation text,p_payload jsonb,p_actor uuid DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE fid bigint; f public.forms; occ public.occasions; contexts jsonb; r jsonb; o eshop.orders;
BEGIN
 PERFORM public.require_client_sync_service_role_v1();
 IF p_operation='register' THEN SELECT id INTO fid FROM public.forms WHERE key=(p_payload->>'form')::uuid;
 ELSIF p_operation='send' THEN fid:=(p_payload->>'formId')::bigint;
 ELSE RAISE EXCEPTION 'Invalid email context operation'; END IF;
 SELECT * INTO STRICT f FROM public.forms WHERE id=fid; SELECT * INTO STRICT occ FROM public.occasions WHERE id=f.occasion;
 IF p_operation='send' AND NOT public.order_editor_membership_as_actor_internal(p_actor,occ.id) THEN
  RAISE insufficient_privilege USING MESSAGE='Order editor required'; END IF;
 contexts:='[]';
 IF p_operation='register' THEN contexts:=jsonb_build_array(jsonb_build_object('recipient',p_payload->>'email','organization',occ.organization,
  'occasion',occ.id,'unit',occ.unit,'occasionTitle',occ.title,'participantCount',jsonb_array_length(p_payload->'tickets'),'formLink',f.link));
 ELSE
  FOR r IN SELECT * FROM jsonb_array_elements(p_payload->'recipients') LOOP
   SELECT * INTO STRICT o FROM eshop.orders WHERE id=(r->>'orderId')::bigint AND form=fid;
   contexts:=contexts||jsonb_build_array(jsonb_build_object('orderId',o.id,'recipient',o.data->>'email','organization',occ.organization,
   'occasion',occ.id,'unit',occ.unit,'occasionTitle',occ.title,'orderSymbol',o.order_symbol,
   'participantCount',(SELECT count(*) FROM public.get_order_tickets_internal(o.id)),
   'offeredCount',(r->>'count')::integer,'formLink',f.link,'expiresAt',p_payload->>'expiresAt'));
  END LOOP;
 END IF;
 RETURN contexts;
END $$;

-- Source: database/functions/eshop_waitlist/capabilities.sql
CREATE OR REPLACE FUNCTION public.get_waitlist_order_detail(p_order_id bigint)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE o eshop.orders;
BEGIN
 SELECT * INTO STRICT o FROM eshop.orders WHERE id=p_order_id;
 IF NOT public.can_read_orders(o.occasion) THEN RAISE insufficient_privilege USING MESSAGE='Order viewer required'; END IF;
 RETURN jsonb_build_object('orderId',o.id,'sourceOrderId',o.source_waitlist_order_id,
 'occasionTitle',(SELECT title FROM public.occasions WHERE id=o.occasion),'waitlistSummary',public.get_waitlist_summary_internal(o.id),
 'capacity',public.get_form_capacity_snapshot_internal(o.form),
 'tickets',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',p.id,'displayName',public.get_waitlist_ticket_display_name_internal(o.form,p.data,CASE WHEN (SELECT count(*) FROM public.get_order_tickets_internal(o.id))=1 THEN o.data ELSE '{}'::jsonb END),'createdAt',p.created_at,'waitlistQueueAt',p.waitlist_queue_at,'answers',public.extract_ticket_answers_internal(o.form,p.data),
  'lifecycle',public.get_effective_waitlist_ticket_lifecycle_internal(p.id)) ORDER BY created_at,id),'[]') FROM public.get_order_tickets_internal(o.id) p),
 'offers',(SELECT coalesce(jsonb_agg(to_jsonb(w)||jsonb_build_object('slots',(SELECT coalesce(jsonb_agg((to_jsonb(s)-'ticket_id')||jsonb_build_object('ticketId',s.ticket_id)),'[]') FROM eshop.waitlist_offer_slots s WHERE offer_id=w.id)) ORDER BY created_at),'[]')
 FROM eshop.waitlist_offers w WHERE order_id=o.id),
 'linkedOrders',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'orderSymbol',order_symbol,'state',state)),'[]') FROM eshop.orders WHERE source_waitlist_order_id=o.id));
END $$;

-- Source: database/functions/users/import_occasion_users_from_csv.sql
CREATE OR REPLACE FUNCTION public.import_occasion_users_from_csv_apply_v1(
    p_occasion_id bigint,
    p_rows jsonb,
    p_delete_user_ids jsonb DEFAULT '[]'::jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
    v_unit_id bigint;
    v_organization_id bigint;
    v_row jsonb;
    v_data_patch jsonb;
    v_services_patch jsonb;
    v_group_assignments jsonb := '[]'::jsonb;
    v_user_id uuid;
    v_email text;
    v_delivery_email text;
    v_existing_email text;
    v_has_delivery_email boolean;
    v_response jsonb;
    v_is_occasion_member boolean;
    v_created integer := 0;
    v_updated integer := 0;
    v_deleted integer := 0;
    v_global_before jsonb;
BEGIN
    SELECT o.unit, u.organization
      INTO v_unit_id, v_organization_id
      FROM public.occasions o
      JOIN public.units u ON u.id = o.unit
     WHERE o.id = p_occasion_id;

    IF v_unit_id IS NULL THEN
        RAISE EXCEPTION 'OCCASION_NOT_FOUND';
    END IF;

    IF NOT public.get_can_manage_occasion_users(p_occasion_id) THEN
        RAISE EXCEPTION 'NOT_AUTHORIZED';
    END IF;

    IF COALESCE(jsonb_typeof(p_rows), 'null') <> 'array'
       OR COALESCE(jsonb_typeof(p_delete_user_ids), 'null') <> 'array' THEN
        RAISE EXCEPTION 'INVALID_IMPORT_PAYLOAD';
    END IF;
    IF jsonb_array_length(p_rows) > 10000
       OR jsonb_array_length(p_delete_user_ids) > 10000 THEN
        RAISE EXCEPTION 'IMPORT_PAYLOAD_TOO_LARGE';
    END IF;

    IF EXISTS (
        SELECT 1 FROM jsonb_array_elements(p_rows) item
         WHERE jsonb_typeof(item) <> 'object'
            OR jsonb_typeof(item->'data') <> 'object'
    ) THEN
        RAISE EXCEPTION 'INVALID_IMPORT_ROW';
    END IF;
    IF EXISTS (
        SELECT 1 FROM jsonb_array_elements(p_rows) item
         WHERE NULLIF(btrim(item->'data'->>'email'), '') IS NULL
    ) THEN
        RAISE EXCEPTION 'EMAIL_REQUIRED';
    END IF;
    IF EXISTS (
        SELECT 1 FROM jsonb_array_elements(p_rows) item
         WHERE length(btrim(item->'data'->>'email')) > 254
            OR lower(btrim(item->'data'->>'email'))
               !~ '^[^[:space:]@]+@[^[:space:]@]+$'
            OR (
                item ? 'email_delivery'
                AND (
                    NULLIF(btrim(item->>'email_delivery'), '') IS NULL
                    OR length(btrim(item->>'email_delivery')) > 254
                    OR lower(btrim(item->>'email_delivery'))
                       !~ '^[^[:space:]@]+@[^[:space:]@]+$'
                )
            )
    ) THEN
        RAISE EXCEPTION 'INVALID_EMAIL';
    END IF;
    IF EXISTS (
        SELECT 1
          FROM jsonb_array_elements(p_rows) item
         GROUP BY lower(btrim(item->'data'->>'email'))
        HAVING count(*) > 1
    ) THEN
        RAISE EXCEPTION 'DUPLICATE_ACCOUNT_EMAIL';
    END IF;
    IF EXISTS (
        SELECT 1
          FROM jsonb_array_elements(p_rows) item
         WHERE NULLIF(item->>'user_id', '') IS NOT NULL
         GROUP BY item->>'user_id'
        HAVING count(*) > 1
    ) THEN
        RAISE EXCEPTION 'DUPLICATE_USER_ID';
    END IF;
    IF EXISTS (
        SELECT 1
          FROM jsonb_array_elements(p_rows) item
          JOIN jsonb_array_elements_text(p_delete_user_ids) deleted(id)
            ON deleted.id = item->>'user_id'
    ) THEN
        RAISE EXCEPTION 'CONFLICTING_IMPORT_OPERATION';
    END IF;

    -- Serialize all CSV imports for one occasion. The group RPC uses the same
    -- lock, which is transaction-reentrant for this session.
    PERFORM pg_catalog.pg_advisory_xact_lock(p_occasion_id);
    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended(
            'user-sign-in-email:' || v_organization_id::text, 0
        )
    );

    FOR v_row IN SELECT value FROM jsonb_array_elements(p_rows)
    LOOP
        IF COALESCE(jsonb_typeof(v_row), 'null') <> 'object'
           OR COALESCE(jsonb_typeof(v_row->'data'), 'null') <> 'object' THEN
            RAISE EXCEPTION 'INVALID_IMPORT_ROW';
        END IF;

        v_data_patch := v_row->'data';
        v_email := lower(btrim(v_data_patch->>'email'));
        v_has_delivery_email := v_row ? 'email_delivery';
        v_delivery_email := lower(btrim(COALESCE(
            v_row->>'email_delivery', v_data_patch->>'email'
        )));
        IF v_email IS NULL OR v_email = '' THEN
            RAISE EXCEPTION 'EMAIL_REQUIRED';
        END IF;
        IF v_delivery_email IS NULL OR v_delivery_email = '' THEN
            RAISE EXCEPTION 'DELIVERY_EMAIL_REQUIRED';
        END IF;

        v_user_id := NULLIF(v_row->>'user_id', '')::uuid;
        v_is_occasion_member := false;

        IF v_user_id IS NULL THEN
            -- Resolve against the occasion first. This makes a retry or a
            -- stale client safe: add_user_to_occasion must never replace an
            -- existing occasion row with profile data.
            SELECT ou."user"
              INTO v_user_id
              FROM public.occasion_users ou
              JOIN public.user_info ui ON ui.id = ou."user"
             WHERE ou.occasion = p_occasion_id
               AND lower(btrim(COALESCE(ui.email_readonly,
                                        ou.data->>'email'))) = v_email
             ORDER BY ou.created_at
             LIMIT 1;

            v_is_occasion_member := v_user_id IS NOT NULL;

            -- A CSV create may also refer to an organization user who simply
            -- is not on this occasion yet. Reuse that identity before creating
            -- a new Auth user.
            IF v_user_id IS NULL THEN
                SELECT ui.id
                  INTO v_user_id
                 FROM public.user_info ui
                 WHERE ui.organization = v_organization_id
                   AND lower(btrim(ui.email_readonly)) = v_email
                 ORDER BY ui.created_at
                 LIMIT 1;
            END IF;

            IF v_user_id IS NULL AND EXISTS (
                SELECT 1 FROM public.user_info ui
                 WHERE ui.organization = v_organization_id
                   AND lower(btrim(ui.email_readonly)) = v_email
            ) THEN
                -- The client assigns deterministic +N account emails for a
                -- CSV batch. Reassigning one here would make a later retry
                -- point at a different person. Without a stable external ID,
                -- reject the stale/colliding input instead of guessing identity.
                RAISE EXCEPTION 'ACCOUNT_EMAIL_ALREADY_EXISTS';
            END IF;

            IF v_user_id IS NULL THEN
                SELECT au.id
                  INTO v_user_id
                  FROM auth.users au
                 WHERE lower(au.email) = lower(v_organization_id::text || '+' || v_email)
                 ORDER BY au.created_at
                 LIMIT 1;
            END IF;

            IF v_user_id IS NULL THEN
                v_user_id := public.create_user_in_organization_with_data_pure(
                    v_organization_id,
                    v_email,
                    NULLIF(v_delivery_email, v_email),
                    encode(gen_random_bytes(16), 'hex'),
                    v_data_patch
                );
            ELSIF NOT EXISTS (
                SELECT 1 FROM public.user_info ui WHERE ui.id = v_user_id
            ) THEN
                INSERT INTO public.user_info (
                    id, organization, email_readonly, email_delivery, data,
                    name, surname, sex
                ) VALUES (
                    v_user_id,
                    v_organization_id,
                    v_email,
                    v_delivery_email,
                    v_data_patch,
                    v_data_patch->>'name',
                    v_data_patch->>'surname',
                    v_data_patch->>'sex'
                );
            END IF;

            IF v_is_occasion_member THEN
                v_updated := v_updated + 1;
            ELSE
                v_response := public.add_user_to_occasion_internal_v1(p_occasion_id, v_user_id);
                IF COALESCE((v_response->>'code')::integer, 500) <> 200 THEN
                    RAISE EXCEPTION 'ADD_USER_TO_OCCASION_FAILED: %',
                        COALESCE(v_response->>'message',
                                 'code ' || (v_response->>'code'));
                END IF;
                v_created := v_created + 1;
            END IF;
        ELSE
            SELECT lower(btrim(COALESCE(ui.email_readonly, ou.data->>'email')))
              INTO v_existing_email
              FROM public.occasion_users ou
              JOIN public.user_info ui ON ui.id = ou."user"
             WHERE ou.occasion = p_occasion_id
               AND ou."user" = v_user_id;

            IF NOT FOUND THEN
                RAISE EXCEPTION 'USER_NOT_ON_OCCASION';
            END IF;
            IF v_existing_email IS DISTINCT FROM v_email THEN
                RAISE EXCEPTION 'USER_EMAIL_MISMATCH';
            END IF;
            v_updated := v_updated + 1;
        END IF;

        SELECT to_jsonb(ui) INTO v_global_before FROM public.user_info ui WHERE id=v_user_id FOR UPDATE;
        UPDATE public.user_info ui
           SET data = COALESCE(ui.data, '{}'::jsonb)
                      || public.get_user_profile_data_patch(v_data_patch),
               email_delivery = CASE
                   WHEN v_has_delivery_email
                       THEN NULLIF(v_delivery_email, v_email)
                   ELSE ui.email_delivery
               END,
               name = CASE WHEN v_data_patch ? 'name'
                           THEN v_data_patch->>'name' ELSE ui.name END,
               surname = CASE WHEN v_data_patch ? 'surname'
                              THEN v_data_patch->>'surname' ELSE ui.surname END,
               sex = CASE WHEN v_data_patch ? 'sex'
                          THEN v_data_patch->>'sex' ELSE ui.sex END,
               phone = CASE WHEN v_data_patch ? 'phone'
                            THEN v_data_patch->>'phone' ELSE ui.phone END,
               birth_date = CASE WHEN v_data_patch ? 'birthDate'
                                 THEN NULLIF(v_data_patch->>'birthDate', '')::date
                                 ELSE ui.birth_date END
         WHERE ui.id = v_user_id;

        PERFORM public.publish_user_profile_change_internal_v1(v_user_id,p_occasion_id,v_global_before);

        IF v_row ? 'services' THEN
            IF COALESCE(jsonb_typeof(v_row->'services'), 'null') <> 'object' THEN
                RAISE EXCEPTION 'INVALID_SERVICES_PATCH';
            END IF;
            v_services_patch := v_row->'services';
        ELSE
            v_services_patch := NULL;
        END IF;

        UPDATE public.occasion_users ou
           SET data = COALESCE(ou.data, '{}'::jsonb) || v_data_patch,
               services = CASE
                   WHEN v_services_patch IS NULL THEN ou.services
                   ELSE COALESCE(ou.services, '{}'::jsonb) || v_services_patch
               END
         WHERE ou.occasion = p_occasion_id
           AND ou."user" = v_user_id;

        IF v_row ? 'group_title' THEN
            v_group_assignments := v_group_assignments || jsonb_build_array(
                jsonb_build_object(
                    'user_id', v_user_id,
                    'group_title', v_row->>'group_title'
                )
            );
        END IF;
    END LOOP;

    FOR v_user_id IN
        SELECT value::uuid FROM jsonb_array_elements_text(p_delete_user_ids)
    LOOP
        IF NOT EXISTS (
            SELECT 1 FROM public.occasion_users ou
             WHERE ou.occasion = p_occasion_id AND ou."user" = v_user_id
        ) THEN
            RAISE EXCEPTION 'DELETE_USER_NOT_ON_OCCASION';
        END IF;
        PERFORM public.remove_occasion_user_domain_internal_v1(p_occasion_id,v_user_id);
        v_deleted := v_deleted + 1;
    END LOOP;

    IF jsonb_array_length(v_group_assignments) > 0 THEN
        PERFORM public.import_user_group_assignments_internal_v1(
            p_occasion_id,
            v_group_assignments
        );
    END IF;

    RETURN jsonb_build_object(
        'code', 200,
        'created', v_created,
        'updated', v_updated,
        'deleted', v_deleted,
        'groups', jsonb_array_length(v_group_assignments)
    );
END;
$$;

-- Source: database/functions/groups/adjacent_group_lifecycle.sql
-- Adjacent lifecycle owners: only group lock/version seam corrections.
CREATE OR REPLACE FUNCTION public.import_profiles_client_sync_v1(p_occasion bigint, p_command_id uuid, p_rows jsonb, p_delete_user_ids jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO public, extensions
AS $function$
DECLARE v_actor uuid:=auth.uid(); v_begin jsonb; v_hash text; v_unit bigint;
  v_result jsonb; v_before_users uuid[]; v_after_users uuid[]; v_current_users uuid[];
  v_event_ids bigint[]; v_group_ids bigint[]; v_private_impacts jsonb;
  v_publishable boolean; v_actor_replacements jsonb:='[]'::jsonb; v_before_state jsonb; v_after_state jsonb; v_old_impacts jsonb;
BEGIN
  SELECT o.unit,NOT o.is_hidden INTO v_unit,v_publishable
    FROM public.occasions o WHERE o.id=p_occasion;
  IF v_actor IS NULL OR NOT public.get_can_manage_occasion_users(p_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='profile import permission required'; END IF;
  IF p_rows IS NULL OR jsonb_typeof(p_rows)<>'array'
    OR p_delete_user_ids IS NULL OR jsonb_typeof(p_delete_user_ids)<>'array'
    OR jsonb_array_length(p_rows)>10000 OR jsonb_array_length(p_delete_user_ids)>10000
    OR octet_length(p_rows::text)+octet_length(p_delete_user_ids::text)>8388608 THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid profile import'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object('occasion',p_occasion,
    'rows',p_rows,'deleteUserIds',p_delete_user_ids)::text,'UTF8'),'sha256'),'hex');
  PERFORM 1 FROM public.user_info ui WHERE ui.id=ANY(ARRAY(
    SELECT (r->>'user_id')::uuid FROM jsonb_array_elements(p_rows) r
    WHERE nullif(r->>'user_id','') IS NOT NULL))
    OR lower(btrim(ui.email_readonly))=ANY(ARRAY(
      SELECT lower(btrim(r#>>'{data,email}')) FROM jsonb_array_elements(p_rows) r))
    ORDER BY ui.id FOR UPDATE;
  v_begin:=public.begin_client_mutation_v1(p_command_id,'profile.users.import',
    p_occasion,v_actor,v_hash);
  PERFORM public.lock_activity_aggregate_internal_v1(p_occasion);
  IF NOT public.get_can_manage_occasion_users(p_occasion) THEN RAISE insufficient_privilege USING MESSAGE='profile import permission required'; END IF;
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  PERFORM pg_catalog.pg_advisory_xact_lock(p_occasion);
  PERFORM 1 FROM public.user_group_info g WHERE g.occasion=p_occasion
    ORDER BY g.id FOR UPDATE;
  v_before_state:=public.profile_group_import_state_internal_v1(p_occasion);
  SELECT COALESCE(array_agg(ou."user"),'{}'::uuid[]) INTO v_before_users
    FROM public.occasion_users ou WHERE ou.occasion=p_occasion;
  SELECT COALESCE(array_agg(DISTINCT e.id),'{}'::bigint[]) INTO v_event_ids
    FROM public.events e LEFT JOIN public.event_users eu ON eu.event=e.id
    LEFT JOIN public.event_users_saved es ON es.event=e.id
    WHERE e.occasion=p_occasion AND (eu."user"=ANY(ARRAY(SELECT value::uuid
      FROM jsonb_array_elements_text(p_delete_user_ids))) OR
      es."user"=ANY(ARRAY(SELECT value::uuid
      FROM jsonb_array_elements_text(p_delete_user_ids))));
  SELECT COALESCE(array_agg(DISTINCT ug."group"),'{}'::bigint[]) INTO v_group_ids
    FROM public.user_groups ug JOIN public.user_group_info g ON g.id=ug."group"
    JOIN public.user_info ui ON ui.id=ug."user"
    WHERE g.occasion=p_occasion AND (ug."user"=ANY(ARRAY(SELECT value::uuid
      FROM jsonb_array_elements_text(p_delete_user_ids))) OR ug."user"=ANY(
      COALESCE((SELECT array_agg((row->>'user_id')::uuid)
        FROM jsonb_array_elements(p_rows) row
        WHERE NULLIF(row->>'user_id','') IS NOT NULL),'{}'::uuid[])) OR
      lower(btrim(ui.email_readonly))=ANY(COALESCE((SELECT array_agg(
        lower(btrim(row#>>'{data,email}'))) FROM jsonb_array_elements(p_rows) row),
        '{}'::text[])));
  v_old_impacts:=public.group_profile_impacts_internal_v1(p_occasion,ARRAY(
    SELECT DISTINCT id FROM (
      SELECT value::uuid id FROM jsonb_array_elements_text(p_delete_user_ids)
      UNION SELECT ug."user" FROM public.user_groups ug WHERE ug."group"=ANY(v_group_ids)
      UNION SELECT ou."user" FROM public.occasion_users ou JOIN public.user_info ui ON ui.id=ou."user" WHERE ou.occasion=p_occasion AND (ou."user"=ANY(ARRAY(SELECT (row->>'user_id')::uuid FROM jsonb_array_elements(p_rows) row WHERE NULLIF(row->>'user_id','') IS NOT NULL)) OR lower(btrim(ui.email_readonly))=ANY(ARRAY(SELECT lower(btrim(row#>>'{data,email}')) FROM jsonb_array_elements(p_rows) row)))
    ) impacted));
  v_private_impacts:=public.remove_user_activity_internal_v1(p_occasion,ARRAY(SELECT value::uuid FROM jsonb_array_elements_text(p_delete_user_ids)));
  v_result:=public.import_occasion_users_from_csv_internal_v1(
    p_occasion,p_rows,p_delete_user_ids);
  IF COALESCE((v_result->>'code')::integer,500)<>200 THEN
    RAISE data_exception USING MESSAGE=COALESCE(v_result->>'message','profile import failed');
  END IF;
  v_after_state:=public.profile_group_import_state_internal_v1(p_occasion);
  IF v_before_state=v_after_state THEN RETURN public.complete_client_mutation_outcome_v1(p_command_id,'unchanged',200,v_result); END IF;
  SELECT COALESCE(array_agg(ou."user"),'{}'::uuid[]) INTO v_after_users
    FROM public.occasion_users ou WHERE ou.occasion=p_occasion;
  SELECT COALESCE(array_agg(DISTINCT ou."user" ORDER BY ou."user"),'{}'::uuid[])
    INTO v_current_users FROM public.occasion_users ou
    JOIN public.user_info ui ON ui.id=ou."user"
    WHERE ou.occasion=p_occasion AND (ou."user"=ANY(COALESCE((SELECT array_agg(
      (row->>'user_id')::uuid) FROM jsonb_array_elements(p_rows) row
      WHERE NULLIF(row->>'user_id','') IS NOT NULL),'{}'::uuid[])) OR
      lower(btrim(COALESCE(ui.email_readonly,ou.data->>'email')))=ANY(COALESCE((
        SELECT array_agg(lower(btrim(row#>>'{data,email}')))
        FROM jsonb_array_elements(p_rows) row),'{}'::text[])) OR
      NOT ou."user"=ANY(v_before_users));
  SELECT ARRAY(SELECT DISTINCT id FROM unnest(v_group_ids||COALESCE((
    SELECT array_agg(DISTINCT ug."group") FROM public.user_groups ug
    JOIN public.user_group_info g ON g.id=ug."group"
    WHERE g.occasion=p_occasion AND ug."user"=ANY(v_current_users)),
    '{}'::bigint[])) id ORDER BY id) INTO v_group_ids;
  SELECT ARRAY(SELECT DISTINCT id FROM unnest(v_current_users||COALESCE((
    SELECT array_agg(DISTINCT ug."user") FROM public.user_groups ug
    WHERE ug."group"=ANY(v_group_ids)),'{}'::uuid[])) id
    JOIN public.occasion_users ou ON ou.occasion=p_occasion AND ou."user"=id
    ORDER BY id) INTO v_current_users;
  INSERT INTO public.client_aggregate_versions
    (aggregate_type,scope_type,scope_id,aggregate_id,version)
  SELECT 'occasion_user','occasion',p_occasion,id::text,1
    FROM unnest(v_current_users) id
  ON CONFLICT (aggregate_type,scope_type,scope_id,aggregate_id) DO UPDATE
    SET version=public.client_aggregate_versions.version+1,
      updated_at=clock_timestamp();
  INSERT INTO public.client_aggregate_versions
    (aggregate_type,scope_type,scope_id,aggregate_id,version)
  SELECT 'user_group','occasion',p_occasion,key,1 FROM jsonb_each(v_after_state->'groups') WHERE value IS DISTINCT FROM v_before_state->'groups'->key
  ON CONFLICT (aggregate_type,scope_type,scope_id,aggregate_id) DO UPDATE
    SET version=public.client_aggregate_versions.version+1,
      updated_at=clock_timestamp();
  DELETE FROM public.client_aggregate_versions v WHERE v.aggregate_type='occasion_user'
    AND v.scope_type='occasion' AND v.scope_id=p_occasion
    AND v.aggregate_id=ANY(ARRAY(SELECT value FROM jsonb_array_elements_text(
      p_delete_user_ids)));
  v_private_impacts:=v_private_impacts||v_old_impacts||public.group_profile_impacts_internal_v1(p_occasion,v_current_users);
  SELECT COALESCE(jsonb_agg(x ORDER BY x->>'component',x->>'userId'),'[]') INTO v_private_impacts FROM (SELECT DISTINCT value x FROM jsonb_array_elements(v_private_impacts) WHERE EXISTS(SELECT 1 FROM public.occasion_users WHERE occasion=p_occasion AND "user"=(value->>'userId')::uuid)) current_impacts;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(v_private_impacts) x WHERE x->>'component'='private_profile' AND x->>'userId'=v_actor::text) THEN v_actor_replacements:=jsonb_build_array(
    jsonb_build_object('component','private_profile','userId',v_actor,
      'payload',public.get_private_profile_payload_v1(p_occasion,v_actor))); END IF;
  RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,
    'profile.users.import','profile',jsonb_build_array(jsonb_build_object(
      'entityType','occasion_user','entityId',NULL,'operation','import',
      'safeLabel','Profile CSV import','changedFields',jsonb_build_array('profiles','services','groups'))),
    CASE WHEN cardinality(v_event_ids)>0 AND v_publishable
      THEN ARRAY['live_public'] ELSE '{}'::text[] END,
    v_private_impacts,CASE WHEN cardinality(v_event_ids)>0 AND v_publishable
      THEN COALESCE((SELECT jsonb_agg(jsonb_build_object(
        'component','live_public','entityId',id)) FROM unnest(v_event_ids) id),'[]'::jsonb)
      ELSE '[]'::jsonb END,v_result,'{}','[]','user',NULL,v_actor_replacements);
END; $function$
;

-- Source: database/functions/users/import_user_group_assignments.sql
CREATE OR REPLACE FUNCTION public.import_user_group_assignments_internal_v1(
    p_occasion_id bigint,
    p_assignments jsonb
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
    v_assignment record;
    v_group_id bigint;
    v_group_title text;
    v_keep_admin boolean;
    v_unit_id bigint;
BEGIN
    SELECT o.unit INTO v_unit_id
    FROM public.occasions o
    WHERE o.id = p_occasion_id;

    IF v_unit_id IS NULL THEN
        RAISE EXCEPTION 'OCCASION_NOT_FOUND';
    END IF;

    IF NOT public.can_import_group_assignments(p_occasion_id) THEN
        RAISE EXCEPTION 'NOT_AUTHORIZED';
    END IF;

    IF COALESCE(jsonb_typeof(p_assignments), 'null') <> 'array' THEN
        RAISE EXCEPTION 'INVALID_ASSIGNMENTS';
    END IF;

    -- Serialize imports for one occasion so normalized group titles cannot be
    -- created twice by concurrent CSV imports.
    PERFORM pg_catalog.pg_advisory_xact_lock(p_occasion_id);

    FOR v_assignment IN
        SELECT assignment.user_id, assignment.group_title
        FROM jsonb_to_recordset(p_assignments)
            AS assignment(user_id uuid, group_title text)
    LOOP
        IF v_assignment.user_id IS NULL OR NOT EXISTS (
            SELECT 1
            FROM public.occasion_users ou
            WHERE ou.occasion = p_occasion_id
              AND ou."user" = v_assignment.user_id
        ) THEN
            RAISE EXCEPTION 'USER_NOT_ON_OCCASION';
        END IF;

        v_group_title := NULLIF(btrim(v_assignment.group_title), '');
        v_group_id := NULL;
        v_keep_admin := false;

        IF v_group_title IS NOT NULL THEN
            SELECT ugi.id
            INTO v_group_id
            FROM public.user_group_info ugi
            WHERE ugi.occasion = p_occasion_id
              AND ugi.type IS NULL
              AND lower(btrim(ugi.title)) = lower(v_group_title)
            ORDER BY ugi.id
            LIMIT 1;

            IF v_group_id IS NULL THEN
                INSERT INTO public.user_group_info (occasion, title)
                VALUES (p_occasion_id, v_group_title)
                RETURNING id INTO v_group_id;
            ELSE
                SELECT COALESCE(ug.is_admin, false)
                INTO v_keep_admin
                FROM public.user_groups ug
                WHERE ug."user" = v_assignment.user_id
                  AND ug."group" = v_group_id;

                v_keep_admin := COALESCE(v_keep_admin, false);
            END IF;
        END IF;

        DELETE FROM public.user_groups ug
        USING public.user_group_info ugi
        WHERE ug."group" = ugi.id
          AND ug."user" = v_assignment.user_id
          AND ugi.occasion = p_occasion_id
          AND ugi.type IS NULL;

        IF v_group_id IS NOT NULL THEN
            INSERT INTO public.user_groups ("user", "group", is_admin)
            VALUES (v_assignment.user_id, v_group_id, v_keep_admin);
        END IF;
    END LOOP;
END;
$$;

-- Source: database/functions/occasion_setup/drafts.sql
CREATE OR REPLACE FUNCTION public.initialize_occasion_setup_draft_defaults(p_id uuid, p_expected_revision bigint)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions AS $$
DECLARE d public.occasion_setup_drafts; configuration jsonb; policy jsonb;
BEGIN
  SELECT * INTO d FROM public.occasion_setup_drafts WHERE id = p_id FOR UPDATE;
  IF NOT FOUND OR auth.uid() IS NULL OR NOT public.can_create_occasion(d.unit) THEN
    RAISE EXCEPTION 'Draft access denied' USING ERRCODE = '42501';
  END IF;
  IF d.data ? 'defaultConfiguration' THEN RETURN to_jsonb(d); END IF;
  IF d.revision IS DISTINCT FROM p_expected_revision THEN
    RAISE EXCEPTION 'Draft changed in another session' USING ERRCODE = '40001';
  END IF;
  policy:=public.abuse_effective_rules_v1('occasion.draft',d.unit,d.organization);
  PERFORM public.admit_occasion_draft_v1(auth.uid(),d.unit,d.organization,0,false,true,policy);
  configuration := public.build_occasion_setup_configuration(d.unit,p_id);
  UPDATE public.occasion_setup_drafts SET data =
    jsonb_build_object('defaultConfiguration',configuration,
      'formDraft',configuration->'forms'->0,'formDefaultsFollowEvent',true)
    || d.data, revision = revision+1, updated_at=now()
    WHERE id=p_id RETURNING * INTO d;
  PERFORM public.admit_occasion_draft_v1(auth.uid(),d.unit,d.organization,octet_length(d.data::text),false,false,policy);
  RETURN to_jsonb(d);
END $$;

-- Source: database/functions/users/reception_qr_login.sql
CREATE OR REPLACE FUNCTION public.issue_reception_login_qr_v1(p_occasion bigint,p_user uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE v_token text; v_hash text; v_actor uuid:=auth.uid();
  v_manual text; v_manual_hash text; v_manual_bytes bytea; v_alphabet constant text:='23456789ABCDEFGHJKLMNPQRSTUVWXYZ';
BEGIN
  IF NOT public.get_can_use_reception(p_occasion) THEN RETURN jsonb_build_object('code',403,'message','reception_unavailable'); END IF;
  IF NOT public.reception_rate_limit_v1('issue') THEN RETURN jsonb_build_object('code',429,'message','rate_limited'); END IF;
  IF NOT EXISTS(SELECT 1 FROM public.occasion_users ou WHERE ou.occasion=p_occasion AND ou."user"=p_user)
    OR NOT (public.can_manage_occasion_participants(p_occasion) OR EXISTS(
      SELECT 1 FROM public.reception_registrations r
      WHERE r.occasion=p_occasion AND r."user"=p_user AND r.status='active'
        AND r.created_by=v_actor AND r.created_at>now()-interval '30 minutes')) THEN
    RETURN jsonb_build_object('code',403,'message','registration_unavailable'); END IF;
  v_token:=translate(encode(gen_random_bytes(32),'base64'),E'+/=\n','-_'); v_hash:=encode(digest(v_token,'sha256'),'hex');
  v_manual_bytes:=gen_random_bytes(8);
  SELECT string_agg(substr(v_alphabet,(get_byte(v_manual_bytes,i)%32)+1,1),'') INTO v_manual FROM generate_series(0,7) i;
  v_manual_hash:=encode(digest(v_manual,'sha256'),'hex');
  INSERT INTO public.user_login_qr_credentials(occasion,"user",token_hash,manual_token_hash,manual_expires_at,created_by)
  VALUES(p_occasion,p_user,v_hash,v_manual_hash,now()+interval '30 minutes',v_actor)
  ON CONFLICT(occasion,"user") DO UPDATE SET token_hash=excluded.token_hash,manual_token_hash=excluded.manual_token_hash,
    manual_expires_at=excluded.manual_expires_at,created_by=excluded.created_by,rotated_at=now(),revoked_at=NULL,last_used_at=NULL,use_count=0;
  RETURN jsonb_build_object('code',200,'payload','festapp-login:v1:'||p_occasion::text||':'||v_token,
    'manualCode',left(v_manual,4)||'-'||right(v_manual,4));
END $$;

-- Source: database/functions/eshop_bank_accounts/link_bank_account_to_unit.sql
CREATE OR REPLACE FUNCTION public.link_bank_account_to_unit(
    p_bank_account_id bigint,
    p_unit_id bigint,
    p_priority int,
    p_hard boolean DEFAULT false
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
    v_conflict_data jsonb;
    v_is_reordering boolean;
BEGIN
    PERFORM public.check_bank_account_writable(p_bank_account_id);
    v_is_reordering := EXISTS (
        SELECT 1 FROM eshop.unit_bank_accounts
        WHERE unit = p_unit_id AND bank_account = p_bank_account_id
    );
    IF p_priority IS NULL OR v_is_reordering THEN
        IF NOT public.can_manage_unit_bank_accounts(p_unit_id) THEN
            RAISE insufficient_privilege USING MESSAGE='User is not manager.';
        END IF;
    ELSIF NOT public.can_link_bank_account_to_unit(p_bank_account_id,p_unit_id) THEN
        RAISE EXCEPTION 'User is not an admin of this bank account or manager of the target unit.' USING ERRCODE='42501';
    END IF;

    IF p_priority IS NULL THEN
        -- Unlink Logic

        -- Dependency Check (unless hard)
        IF NOT p_hard THEN
            WITH TargetAcc AS (
                SELECT unnest(supported_currencies) as curr FROM eshop.bank_accounts WHERE id = p_bank_account_id
            ),
            OtherAccs AS (
                SELECT unnest(ba.supported_currencies) as curr
                FROM eshop.unit_bank_accounts uba
                JOIN eshop.bank_accounts ba ON uba.bank_account = ba.id
                WHERE uba.unit = p_unit_id AND uba.bank_account != p_bank_account_id
            ),
            LostCurrencies AS (
                SELECT curr FROM TargetAcc
                EXCEPT
                SELECT curr FROM OtherAccs
            ),
            ConflictingForms AS (
                SELECT DISTINCT f.title as form_title, f.link as form_link, p.currency_code, o.title as occasion_title
                FROM public.forms f
                JOIN public.occasions o ON f.occasion = o.id
                JOIN public.form_fields ff ON ff.form = f.id
                JOIN eshop.product_types pt ON ff.product_type = pt.id
                JOIN eshop.products p ON p.product_type = pt.id
                JOIN eshop.products p2 ON ff.product_type = p2.product_type
                WHERE o.unit = p_unit_id
                  AND f.is_open = true
                  -- AND p.is_hidden = false -- Removed is_hidden check? Original SQL had it. Let's keep it tight.
                  AND p.currency_code IN (SELECT curr FROM LostCurrencies)
            )
            SELECT jsonb_agg(jsonb_build_object('form', form_title, 'link', form_link, 'currency', currency_code, 'occasion', occasion_title))
            INTO v_conflict_data
            FROM ConflictingForms;

            IF v_conflict_data IS NOT NULL THEN
                 RAISE EXCEPTION '%', jsonb_build_object(
                    'code', 'LINK_DEPENDENCY_ERROR',
                    'message', 'Cannot unlink bank account because some active forms depend on its currency support.',
                    'conflicts', v_conflict_data
                 )::text;
            END IF;
        END IF;

        DELETE FROM eshop.unit_bank_accounts
        WHERE unit = p_unit_id AND bank_account = p_bank_account_id;
    ELSE
        -- Link or Update Priority
        IF v_is_reordering THEN
            UPDATE eshop.unit_bank_accounts
            SET priority = p_priority
            WHERE unit = p_unit_id AND bank_account = p_bank_account_id;
        ELSE
            INSERT INTO eshop.unit_bank_accounts (unit, bank_account, priority)
            VALUES (p_unit_id, p_bank_account_id, p_priority);

        END IF;
    END IF;
END;
$$;

-- Source: database/functions/activities/canonical_activity_lifecycle.sql
CREATE OR REPLACE FUNCTION public.lock_activity_editor_internal_v1(p_occasion bigint)
RETURNS bigint LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE v bigint;
BEGIN
 v:=public.lock_activity_aggregate_internal_v1(p_occasion);
 IF auth.uid() IS NULL OR NOT public.can_write_activity_plan(p_occasion) THEN RAISE insufficient_privilege USING MESSAGE='occasion editor required'; END IF;
 RETURN v;
END $$;

-- Source: database/functions/blueprint/migrate_reviewed_legacy_layout.sql
CREATE OR REPLACE FUNCTION public.migrate_blueprint_layout_reviewed_internal(p_source text,p_source_sha text,p_blueprint jsonb,p_command_id uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE b eshop.blueprints; source jsonb; current_source jsonb; c jsonb; s eshop.spots; old_object jsonb; old_group text;
 effective_changes jsonb:='[]'; expected_node uuid; expected_group uuid; request_hash text; started jsonb; result jsonb; before_spots jsonb; after_spots jsonb; users uuid[];
BEGIN
 IF p_source_sha !~ '^[0-9a-f]{64}$' OR encode(extensions.digest(convert_to(p_source,'UTF8'),'sha256'),'hex') IS DISTINCT FROM p_source_sha THEN
  RAISE check_violation USING MESSAGE='BLUEPRINT_MIGRATION_SOURCE_HASH_MISMATCH'; END IF;
 source:=p_source::jsonb;
 SELECT * INTO b FROM eshop.blueprints WHERE id=(p_blueprint->>'id')::bigint;
 IF b.id IS NULL OR (source->>'id')::bigint IS DISTINCT FROM b.id OR (source->>'occasion')::bigint IS DISTINCT FROM b.occasion
  OR (p_blueprint->>'occasion')::bigint IS DISTINCT FROM b.occasion
  OR p_blueprint->>'title' IS DISTINCT FROM coalesce(b.title,'') THEN RAISE check_violation USING MESSAGE='BLUEPRINT_MIGRATION_SCOPE_MISMATCH'; END IF;
 IF auth.uid() IS NULL OR NOT public.can_migrate_reviewed_legacy_blueprint(b.occasion) THEN
  RAISE insufficient_privilege USING MESSAGE='blueprint migration reviewer required'; END IF;
 request_hash:=encode(extensions.digest(convert_to(jsonb_build_object('sourceSha',p_source_sha,'request',p_blueprint)::text,'UTF8'),'sha256'),'hex');
 started:=public.begin_client_mutation_reviewed_impl_internal(p_command_id,'inventory.blueprint.migrate',b.occasion,auth.uid(),request_hash,true);
 IF started->>'disposition'='replay' THEN RETURN started->'response'; END IF;
 PERFORM public.lock_blueprint_scope_internal(ARRAY[b.occasion]);
 SELECT * INTO b FROM eshop.blueprints WHERE id=b.id FOR UPDATE;
 IF b.layout IS NOT NULL OR b.layout_revision<>0 OR (p_blueprint->>'expected_layout_revision')::bigint IS DISTINCT FROM 0
  OR EXISTS(SELECT 1 FROM eshop.blueprint_seat_bindings WHERE blueprint=b.id) THEN
  RAISE check_violation USING MESSAGE='BLUEPRINT_MIGRATION_INITIAL_LAYOUT_REQUIRED'; END IF;
 -- Match canonical writer lock order and freeze only stable commercial facts.
 PERFORM 1 FROM eshop.products WHERE occasion=b.occasion ORDER BY id FOR UPDATE;
 PERFORM 1 FROM public.inventory_pools WHERE id IN(SELECT ic.inventory_pool FROM public.inventory_contexts ic
  JOIN eshop.product_inventory_contexts pic ON pic.inventory_context=ic.id JOIN eshop.products p ON p.id=pic.product WHERE p.occasion=b.occasion) ORDER BY id FOR UPDATE;
 PERFORM 1 FROM public.inventory_contexts WHERE id IN(SELECT pic.inventory_context FROM eshop.product_inventory_contexts pic JOIN eshop.products p ON p.id=pic.product WHERE p.occasion=b.occasion) ORDER BY id FOR UPDATE;
 PERFORM 1 FROM eshop.spots WHERE blueprint=b.id ORDER BY id FOR UPDATE;
 current_source:=public.blueprint_legacy_migration_source_internal(b.id);
 IF current_source IS DISTINCT FROM source THEN RAISE check_violation USING MESSAGE='BLUEPRINT_MIGRATION_REVIEW_STALE'; END IF;
 IF jsonb_array_length(coalesce(p_blueprint->'areaBindingChanges','[]'))<>0 OR
  jsonb_array_length(coalesce(p_blueprint#>'{layout,selectionUnits}','[]'))<>0 OR
  jsonb_array_length(coalesce(p_blueprint->'seatChanges','[]'))<>(SELECT count(*) FROM eshop.spots WHERE blueprint=b.id) THEN
  RAISE check_violation USING MESSAGE='BLUEPRINT_MIGRATION_BINDING_SET_MISMATCH'; END IF;
 SELECT coalesce(jsonb_agg(to_jsonb(spot) ORDER BY spot.id),'[]') INTO before_spots FROM eshop.spots spot WHERE spot.blueprint=b.id;
 FOR c IN SELECT value FROM jsonb_array_elements(coalesce(p_blueprint->'seatChanges','[]')) LOOP
  SELECT * INTO s FROM eshop.spots WHERE id=(c->>'spotId')::bigint AND blueprint=b.id AND occasion=b.occasion;
  IF s.id IS NULL OR c->>'operation' IS DISTINCT FROM 'upsert' OR c->>'selectionUnitId' IS NOT NULL OR
   (c->>'productId')::bigint IS DISTINCT FROM s.product OR c->>'title' IS DISTINCT FROM coalesce(s.title,'') OR
   (c->>'blocked')::boolean IS DISTINCT FROM coalesce(s.state='black',false) THEN
   RAISE check_violation USING MESSAGE='BLUEPRINT_MIGRATION_SPOT_FACTS_CHANGED'; END IF;
  expected_node:=extensions.uuid_generate_v5('6ba7b811-9dad-11d1-80b4-00c04fd430c8',format('festapp:occasion:%s:blueprint:%s:spot:%s',b.occasion,b.id,s.id));
  SELECT obj INTO old_object FROM jsonb_array_elements(coalesce(b.objects,'[]')) obj WHERE obj->>'type'='spot' AND (obj->>'id')::bigint=s.id;
  IF old_object IS NULL THEN RAISE check_violation USING MESSAGE='BLUEPRINT_MIGRATION_LEGACY_SPOT_MISSING'; END IF;
  old_group:=old_object->>'group';expected_group:=NULL;
  IF old_group IS NOT NULL AND EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(b.groups,'[]')) grp WHERE grp->>'id'=old_group) THEN
   expected_group:=extensions.uuid_generate_v5('6ba7b811-9dad-11d1-80b4-00c04fd430c8',format('festapp:occasion:%s:blueprint:%s:group:%s',b.occasion,b.id,old_group)); END IF;
  IF (c->>'nodeId')::uuid IS DISTINCT FROM expected_node OR (c->>'groupNodeId')::uuid IS DISTINCT FROM expected_group THEN
   RAISE check_violation USING MESSAGE='BLUEPRINT_MIGRATION_GROUP_MAPPING_CHANGED'; END IF;
  effective_changes:=effective_changes||jsonb_build_array(c||jsonb_build_object('title',s.title));
  INSERT INTO eshop.blueprint_seat_bindings(blueprint,node_id,spot,selection_unit,group_node,blocked)
   VALUES(b.id,expected_node,s.id,NULL,expected_group,(c->>'blocked')::boolean);
 END LOOP;
 -- Seeded metadata permits the unchanged protected seats to pass the same
 -- canonical aggregate owner used by every runtime save.
 result:=public.save_blueprint_layout_impl_internal((p_blueprint-'title')||jsonb_build_object('seatChanges',effective_changes),true);
 SELECT coalesce(jsonb_agg(to_jsonb(spot) ORDER BY spot.id),'[]') INTO after_spots FROM eshop.spots spot WHERE spot.blueprint=b.id;
 IF before_spots IS DISTINCT FROM after_spots THEN RAISE check_violation USING MESSAGE='BLUEPRINT_MIGRATION_LIVE_FACTS_CHANGED'; END IF;
 SELECT coalesce(array_agg(DISTINCT ou."user"),'{}') INTO users FROM public.occasion_users ou WHERE ou.occasion=b.occasion;
 result:=result||jsonb_build_object('migrationSourceSha256',p_source_sha);
 RETURN public.complete_private_inventory_mutation_v1(p_command_id,b.occasion,'inventory.blueprint.migrate',
  jsonb_build_array(jsonb_build_object('entityType','blueprint','entityId',b.id,'operation','update','safeLabel','Reviewed blueprint layout migration','changedFields',jsonb_build_array('layout','bindings'))),users,result);
END $$;

-- Source: database/functions/groups/group_place_move.sql
CREATE OR REPLACE FUNCTION public.move_place_client_sync_v1(p_occasion bigint, p_place_id bigint, p_command_id uuid, p_expected_version bigint, p_lat double precision, p_lng double precision)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_actor uuid:=auth.uid(); v_version bigint; v_begin jsonb; v_hash text;
  v_place public.places%ROWTYPE; v_commit jsonb; v_public jsonb; v_response jsonb;
  v_is_publishable boolean; v_affects_public boolean; v_group bigint; v_impacts jsonb:='[]'; v_replacements jsonb:='[]';
BEGIN
 PERFORM public.assert_canonical_mutation_write_release_internal_v1(p_occasion);
  SELECT p.* INTO v_place FROM public.places p
    WHERE p.id=p_place_id AND p.occasion=p_occasion;
  IF NOT FOUND THEN RAISE invalid_parameter_value USING MESSAGE='place not found'; END IF;
  IF v_actor IS NULL OR p_lat IS NULL OR p_lng IS NULL OR p_lat NOT BETWEEN -90 AND 90 OR p_lng NOT BETWEEN -180 AND 180
    OR NOT public.can_move_map_place(p_occasion,p_place_id) THEN
    RAISE insufficient_privilege USING MESSAGE='place move permission required';
  END IF;
  SELECT NOT o.is_hidden INTO v_is_publishable FROM public.occasions o WHERE o.id=p_occasion;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object('occasion',p_occasion,
    'placeId',p_place_id,'expectedVersion',p_expected_version,'lat',p_lat,'lng',p_lng)::text,
    'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,'map.place.move',p_occasion,
    v_actor,v_hash);
  PERFORM public.lock_group_occasion_internal_v1(p_occasion);
  SELECT p.* INTO v_place FROM public.places p WHERE p.id=p_place_id AND p.occasion=p_occasion FOR UPDATE;
  IF NOT FOUND THEN RAISE invalid_parameter_value USING MESSAGE='place not found'; END IF;
  IF v_actor IS NULL OR p_lat IS NULL OR p_lng IS NULL OR p_lat NOT BETWEEN -90 AND 90 OR p_lng NOT BETWEEN -180 AND 180
    OR NOT public.can_move_map_place(p_occasion,p_place_id) THEN
    RAISE insufficient_privilege USING MESSAGE='place move permission required';
  END IF;
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  IF v_place.type='group' AND v_place.is_hidden THEN
    SELECT id INTO v_group FROM public.user_group_info WHERE occasion=p_occasion AND place=p_place_id ORDER BY id LIMIT 1;
    PERFORM public.assert_group_place_owner_internal_v1(p_occasion,v_group,p_place_id,false);
  END IF;
  INSERT INTO public.client_aggregate_versions
    (aggregate_type,scope_type,scope_id,aggregate_id,version)
  VALUES ('place','occasion',p_occasion,p_place_id::text,0) ON CONFLICT DO NOTHING;
  SELECT version INTO v_version FROM public.client_aggregate_versions
    WHERE aggregate_type='place' AND scope_type='occasion' AND scope_id=p_occasion
      AND aggregate_id=p_place_id::text FOR UPDATE;
  IF p_expected_version IS DISTINCT FROM v_version THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,
      'conflict',409,jsonb_build_object('version',v_version,'place',
        to_jsonb(v_place)||jsonb_build_object('aggregate_version',v_version)));
  END IF;
  IF v_place.coordinates=jsonb_build_object('latLng',jsonb_build_object('lat',p_lat,'lng',p_lng)) THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,
      'unchanged',200,jsonb_build_object('version',v_version,'place',
        to_jsonb(v_place)||jsonb_build_object('aggregate_version',v_version)));
  END IF;
  UPDATE public.places SET coordinates=jsonb_build_object('latLng',
    jsonb_build_object('lat',p_lat,'lng',p_lng)),updated_at=clock_timestamp()
    WHERE id=p_place_id RETURNING * INTO v_place;
  UPDATE public.client_aggregate_versions SET version=version+1,
    updated_at=clock_timestamp() WHERE aggregate_type='place'
    AND scope_type='occasion' AND scope_id=p_occasion AND aggregate_id=p_place_id::text
    RETURNING version INTO v_version;
  IF v_group IS NOT NULL THEN
    UPDATE public.client_aggregate_versions SET version=version+1,updated_at=clock_timestamp()
      WHERE aggregate_type='user_group' AND scope_type='occasion' AND scope_id=p_occasion AND aggregate_id=v_group::text;
  END IF;
  v_impacts:=public.group_profile_impacts_internal_v1(p_occasion,ARRAY(SELECT DISTINCT ug."user" FROM public.user_groups ug JOIN public.user_group_info g ON g.id=ug."group" WHERE g.occasion=p_occasion AND g.place=p_place_id));
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(v_impacts) x WHERE x->>'userId'=v_actor::text) THEN
    v_replacements:=jsonb_build_array(jsonb_build_object('component','private_profile','userId',v_actor,'payload',public.get_private_profile_payload_v1(p_occasion,v_actor)));
  END IF;
  v_affects_public:=NOT v_place.is_hidden;
  RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,
    'map.place.move','map',
    jsonb_build_array(jsonb_build_object('entityType','place','entityId',p_place_id,
      'operation','update','safeLabel',left(v_place.title,240),
      'changedFields',jsonb_build_array('coordinates'))),
    CASE WHEN v_is_publishable AND v_affects_public THEN ARRAY['map_catalog']
      ELSE '{}'::text[] END,v_impacts,'[]',
    jsonb_build_object('version',v_version,'place',to_jsonb(v_place)||
      jsonb_build_object('aggregate_version',v_version)),'{}','[]','user',NULL,v_replacements);
END; $function$
;

-- Source: database/functions/scanning/sessions.sql
CREATE OR REPLACE FUNCTION public.open_scanner_session(p_scan_code text DEFAULT NULL,p_occasion bigint DEFAULT NULL,p_device_name text DEFAULT 'Hlavní vstup')
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE oc public.occasions; s public.scanner_sessions; cfg public.scanner_settings; token text; origin text; sec text;
BEGIN
 IF NOT public.check_scan_attempt_budget_v1(p_occasion) THEN RETURN jsonb_build_object('code',429,'reason','abuse_limit_exceeded','retry_after_ms',30000,'server_time',now()); END IF;
 IF p_scan_code IS NOT NULL THEN
  SELECT * INTO oc FROM public.get_scanner_occasion_for_scan_code_internal(p_scan_code) LIMIT 1;
  -- record assignment above must match the occasion row exactly
  origin:='scan_link'; sec:=p_scan_code;
 ELSE
  PERFORM public.scanner_require_settings_editor_internal(p_occasion);
  SELECT * INTO oc FROM public.occasions WHERE id=p_occasion; origin:='authenticated';
 END IF;
 IF oc.id IS NULL THEN PERFORM public.admit_scan_access_v1(NULL,false); RETURN jsonb_build_object('code',401,'reason','invalid_scan_code','server_time',now()); END IF;
 IF NOT public.admit_scan_access_v1(oc.id,true) THEN RETURN jsonb_build_object('code',429,'reason','abuse_limit_exceeded','server_time',now()); END IF;
 INSERT INTO public.scanner_settings(occasion_id,config) VALUES(oc.id,public.scanner_default_settings_internal(oc.id)) ON CONFLICT DO NOTHING;
 SELECT * INTO cfg FROM public.scanner_settings WHERE occasion_id=oc.id FOR SHARE;
 token:=encode(gen_random_bytes(32),'hex');
 INSERT INTO public.scanner_sessions(occasion_id,actor_user_id,access_origin,token_hash,scan_secret_hash,epoch,device_name,expires_at,offline_until)
 VALUES(oc.id,CASE WHEN origin='authenticated' THEN auth.uid() END,origin,encode(digest(token,'sha256'),'hex'),encode(digest(sec,'sha256'),'hex'),cfg.epoch,left(p_device_name,80),now()+interval '12 hours',
 now()+make_interval(hours=>CASE WHEN (cfg.config#>>'{offline,enabled}')::boolean THEN (cfg.config#>>'{offline,max_hours}')::integer ELSE 0 END)) RETURNING * INTO s;
 RETURN jsonb_build_object('code',200,'server_time',now(),'data',jsonb_build_object('session_id',s.id,'token',token,'occasion_id',oc.id,'organization_id',oc.organization,
 'title',oc.title,'epoch',s.epoch,'expires_at',s.expires_at,'offline_until',s.offline_until,'settings_revision',cfg.revision,'settings',cfg.config,'device_name',s.device_name,
 'capabilities',jsonb_build_object('search_tickets',(cfg.config#>>'{manual_search,tickets}')::boolean,'search_users',(cfg.config#>>'{manual_search,users}')::boolean,
 'settings',public.scanner_can_manage_settings_internal(oc.id),'event_history',auth.uid() IS NOT NULL AND public.can_write_orders(oc.id),'offline',(cfg.config#>>'{offline,enabled}')::boolean)));
END $$;

-- Source: database/functions/blueprint/preview_blueprint_swap.sql
-- SQL work is deliberately rolled back after capturing the authoritative result.
-- The existing financial owner is executed; preview maintains no alternate maths.
CREATE OR REPLACE FUNCTION public.preview_blueprint_swap(p_spot_1 bigint,p_spot_2 bigint)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE ids bigint[]; order_ids bigint[]; before_orders jsonb; sides jsonb; result jsonb; occ bigint;
BEGIN
 SELECT min(occasion) INTO occ FROM eshop.spots WHERE id IN(p_spot_1,p_spot_2);
 IF occ IS NULL THEN RAISE insufficient_privilege USING MESSAGE='order editor required'; END IF;
 IF public.can_write_orders(occ) IS NOT TRUE THEN RAISE insufficient_privilege USING MESSAGE='order editor required'; END IF;
 PERFORM public.lock_blueprint_scope_internal(ARRAY[occ]);
 ids:=public.blueprint_selection_unit_spots_internal(p_spot_1)||public.blueprint_selection_unit_spots_internal(p_spot_2);
 SELECT array_agg(DISTINCT opt."order") INTO order_ids FROM eshop.spots s JOIN eshop.order_product_ticket opt ON opt.id=s.order_product_ticket WHERE s.id=ANY(ids);
 PERFORM public.lock_order_capacity_scope_internal(order_ids);
 SELECT coalesce(jsonb_object_agg(id::text,price),'{}') INTO before_orders FROM eshop.orders WHERE id=ANY(order_ids);
 SELECT coalesce(jsonb_agg(jsonb_build_object('spotId',s.id,'title',s.title,'orderId',o.id,'ticketId',opt.ticket,
  'customer',jsonb_build_object('name',o.data->>'name','surname',o.data->>'surname','email',o.data->>'email')) ORDER BY s.id),'[]')
 INTO sides FROM eshop.spots s LEFT JOIN eshop.order_product_ticket opt ON opt.id=s.order_product_ticket LEFT JOIN eshop.orders o ON o.id=opt."order" WHERE s.id=ANY(ids);
 BEGIN
  PERFORM public.swap_spot_tickets_internal_v1(p_spot_1,p_spot_2);
  SELECT jsonb_build_object('code',200,'spotIds',to_jsonb(ids),'sides',sides,'orders',coalesce(jsonb_agg(jsonb_build_object(
   'orderId',id,'beforeAmount',(before_orders->>id::text)::numeric,'afterAmount',price,
   'delta',price-(before_orders->>id::text)::numeric,'currencyCode',currency_code) ORDER BY id),'[]')) INTO result FROM eshop.orders WHERE id=ANY(order_ids);
  RAISE SQLSTATE 'BP001' USING MESSAGE='rollback successful swap preview';
 EXCEPTION WHEN SQLSTATE 'BP001' THEN NULL;
 WHEN OTHERS THEN result:=jsonb_build_object('code',409,'reason',SQLERRM,'issues',jsonb_build_array(jsonb_build_object('reason',SQLERRM)));
 END;
 RETURN result;
END $$;

-- Source: database/functions/occasion_setup/invitations.sql
CREATE OR REPLACE FUNCTION public.preview_occasion_setup_invitations(p_id uuid,p_emails text[])
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE d public.occasion_setup_drafts; emails text[]; event_id bigint; event_link text; event_title text; recipients jsonb; org_data jsonb;
BEGIN
 SELECT * INTO d FROM public.occasion_setup_drafts WHERE id=p_id;
 IF NOT FOUND OR auth.uid() IS NULL OR NOT public.can_create_occasion(d.unit) THEN
  RAISE insufficient_privilege USING MESSAGE='Draft access denied'; END IF;
 IF NOT public.get_is_manager_on_unit(d.unit) THEN RETURN jsonb_build_object('canManage',false,'recipients','[]'::jsonb); END IF;
 IF p_emails IS NULL THEN
  IF d.data ? 'finalizedOccasion' AND d.data->'sendTeamInvitations' IS DISTINCT FROM 'true'::jsonb THEN
   RAISE invalid_parameter_value USING MESSAGE='Invitation sending not confirmed'; END IF;
  IF jsonb_typeof(coalesce(d.data->'teamInviteEmails','[]'::jsonb)) IS DISTINCT FROM 'array' THEN
   RAISE invalid_parameter_value USING MESSAGE='Invalid invitation emails'; END IF;
  p_emails:=ARRAY(SELECT jsonb_array_elements_text(coalesce(d.data->'teamInviteEmails','[]'::jsonb)));
 END IF;
 emails:=public.normalize_occasion_setup_invite_emails(p_emails);
 event_id:=(d.data->>'finalizedOccasion')::bigint;
 IF event_id IS NOT NULL THEN SELECT link,title INTO event_link,event_title FROM public.occasions WHERE id=event_id AND unit=d.unit AND organization=d.organization;
 ELSE event_link:=d.data->>'link'; event_title:=d.data->>'title'; END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('email',e,'kind',CASE WHEN EXISTS(
   SELECT 1 FROM public.unit_users uu WHERE uu.unit=d.unit AND uu."user"=ui.id) THEN 'member'
   WHEN ui.id IS NOT NULL THEN 'account' ELSE 'new' END,
   'role',public.occasion_setup_invitation_role(d.data->'teamInviteRoles',e),
   'alreadyEditor',coalesce((SELECT ou.is_editor OR ou.is_manager OR (ou.is_editor_view AND public.occasion_setup_invitation_role(d.data->'teamInviteRoles',e)='read_only') FROM public.occasion_users ou
      WHERE ou.occasion=event_id AND ou."user"=ui.id),false)) ORDER BY e),'[]')
 INTO recipients FROM unnest(emails) e LEFT JOIN public.user_info ui
 ON ui.organization=d.organization AND lower(btrim(ui.email_readonly))=e;
 SELECT jsonb_build_object('APP_NAME',data->>'APP_NAME','DEFAULT_URL',data->>'DEFAULT_URL') INTO org_data FROM public.organizations WHERE id=d.organization;
 RETURN jsonb_build_object('canManage',true,'sendConfirmed',d.data->'sendTeamInvitations'='true'::jsonb,'recipients',recipients,'event',jsonb_build_object(
   'id',event_id,'link',event_link,'title',event_title,'unit',d.unit,'organization',d.organization),
   'organizationData',org_data);
END $$;

-- Source: database/functions/activities/canonical_activity_lifecycle.sql
CREATE OR REPLACE FUNCTION public.publish_activities_client_sync_v1(p_occasion bigint,p_command_id uuid,p_expected_version bigint,p_activities_data jsonb,p_history_data jsonb,p_parent_history_id bigint)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE actor uuid:=auth.uid(); b jsonb; v bigint; latest bigint; graph jsonb; history jsonb; old_graph jsonb; previous_history jsonb; hid bigint; live_changed boolean; deleted int; impacts jsonb; replacements jsonb:='[]'; users uuid[];
BEGIN
 PERFORM public.assert_canonical_mutation_write_release_internal_v1(p_occasion);
 IF actor IS NULL OR NOT public.can_write_activity_plan(p_occasion) THEN RAISE insufficient_privilege USING MESSAGE='occasion editor required'; END IF;
 IF p_activities_data IS NULL OR jsonb_typeof(p_activities_data)<>'array' OR p_history_data IS NULL OR jsonb_typeof(p_history_data)<>'object' OR octet_length(p_activities_data::text)>2097152 OR octet_length(p_history_data::text)>2097152 THEN RAISE invalid_parameter_value USING MESSAGE='invalid activities aggregate'; END IF;
 b:=public.begin_client_mutation_v1(p_command_id,'activities.publish',p_occasion,actor,encode(extensions.digest(jsonb_build_object('occasion',p_occasion,'expectedVersion',p_expected_version,'activities',p_activities_data,'history',p_history_data,'parentHistoryId',p_parent_history_id)::text,'sha256'),'hex'));
 v:=public.lock_activity_editor_internal_v1(p_occasion);
 IF b->>'disposition'='replay' THEN RETURN b->'response'; END IF;
 SELECT id,activities_data INTO latest,previous_history FROM public.activity_history WHERE occasion_id=p_occasion AND history_type='PUBLISH' ORDER BY id DESC LIMIT 1;
 IF p_expected_version IS DISTINCT FROM v OR p_parent_history_id IS DISTINCT FROM latest THEN RETURN public.complete_client_mutation_outcome_v1(p_command_id,'conflict',409,jsonb_build_object('version',v,'latestPublishId',latest,'historyId',latest)); END IF;
 graph:=public.normalize_activity_graph_internal_v1(p_occasion,p_activities_data,true);
 IF graph IS DISTINCT FROM public.activity_history_graph_internal_v1(p_occasion,p_history_data-'_consume_autosave') THEN RETURN public.complete_client_mutation_outcome_v1(p_command_id,'rejected',400,jsonb_build_object('version',v,'latestPublishId',latest,'reason','graph_history_mismatch')); END IF;
 history:=public.activity_graph_history_internal_v1(graph); old_graph:=public.current_activity_graph_internal_v1(p_occasion);
 live_changed:=graph IS DISTINCT FROM old_graph OR latest IS NULL;
 IF NOT live_changed AND public.activity_history_graph_internal_v1(p_occasion,previous_history)=graph THEN
  deleted:=public.consume_selected_activity_draft_internal_v1(p_occasion,actor,latest,p_history_data->'_consume_autosave',graph);
  IF deleted=0 THEN RETURN public.complete_client_mutation_outcome_v1(p_command_id,'unchanged',200,jsonb_build_object('version',v,'historyId',latest,'latestPublishId',latest,'draftId',(SELECT id FROM public.activity_history WHERE occasion_id=p_occasion AND user_id=actor AND history_type='AUTOSAVE' ORDER BY id DESC LIMIT 1),'draftConsumed',false)); END IF;
  RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,'activities.publish','activities',jsonb_build_array(jsonb_build_object('entityType','activity_draft','entityId',NULL,'operation','delete','changedFields',jsonb_build_array('draft'))),'{}','[]','[]',jsonb_build_object('version',v,'historyId',latest,'latestPublishId',latest,'draftId',NULL,'draftConsumed',true));
 END IF;
 SELECT ARRAY(SELECT DISTINCT (x->>'user')::uuid FROM jsonb_array_elements(old_graph||graph) a,LATERAL jsonb_array_elements(a->'assignments') x WHERE x->>'user' IS NOT NULL UNION SELECT actor) INTO users;
 PERFORM public.replace_activities_graph_internal_v1(p_occasion,graph);
 hid:=public.write_activity_history_internal_v1(p_occasion,actor,history,'PUBLISH',latest,'Published via application');
 deleted:=public.consume_selected_activity_draft_internal_v1(p_occasion,actor,latest,p_history_data->'_consume_autosave',graph);
 UPDATE public.client_aggregate_versions SET version=version+1,updated_at=clock_timestamp() WHERE aggregate_type='activities' AND scope_type='occasion' AND scope_id=p_occasion AND aggregate_id=p_occasion::text RETURNING version INTO v;
 SELECT COALESCE(jsonb_agg(jsonb_build_object('component','private_activity','userId',u) ORDER BY u),'[]') INTO impacts FROM unnest(users) u JOIN public.occasion_users ou ON ou.occasion=p_occasion AND ou."user"=u;
 replacements:=jsonb_build_array(jsonb_build_object('component','private_activity','userId',actor,'payload',(public.get_my_events_and_activities(p_occasion,true)->'data')));
 PERFORM public.retain_activity_history_internal_v1(p_occasion);
 RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,'activities.publish','activities',jsonb_build_array(jsonb_build_object('entityType','activities','entityId',p_occasion,'operation','publish','changedFields',jsonb_build_array('graph','history'))),'{}',impacts,'[]',jsonb_build_object('version',v,'historyId',hid,'latestPublishId',hid,'draftId',(SELECT id FROM public.activity_history WHERE occasion_id=p_occasion AND user_id=actor AND history_type='AUTOSAVE' ORDER BY id DESC LIMIT 1),'draftConsumed',deleted>0,'activities',graph),'{}','[]','user',NULL,replacements);
END $$;

-- Source: database/functions/news/publish_news_client_sync_v1.sql
CREATE OR REPLACE FUNCTION public.publish_news_client_sync_v1(p_occasion bigint, p_add_to_news boolean, p_news_message text, p_send_notification boolean, p_notification_heading text, p_notification_content text, p_recipients jsonb, p_command_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_notification uuid; v_actor uuid:=auth.uid(); v_organization bigint; v_begin jsonb; v_hash text;
  v_id bigint; v_version bigint:=0; v_entity jsonb; v_items jsonb:='[]'::jsonb;
  v_is_publishable boolean; v_response jsonb; v_required_revision bigint;
BEGIN
  IF v_actor IS NULL OR NOT public.can_write_news(p_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='occasion editor required'; END IF;
  SELECT o.organization,NOT o.is_hidden INTO v_organization,v_is_publishable
    FROM public.occasions o WHERE o.id=p_occasion;
  IF v_organization IS NULL OR NOT COALESCE(p_add_to_news,false)
      AND NOT COALESCE(p_send_notification,false)
    OR p_add_to_news AND (p_news_message IS NULL
      OR octet_length(p_news_message) NOT BETWEEN 1 AND 524288)
    OR p_send_notification AND (p_notification_content IS NULL
      OR octet_length(p_notification_content)>65536
      OR octet_length(COALESCE(p_notification_heading,''))>2048
      OR p_recipients IS NOT NULL AND (jsonb_typeof(p_recipients)<>'array'
        OR jsonb_array_length(p_recipients)>5000
        OR EXISTS (SELECT 1 FROM jsonb_array_elements(p_recipients) value
          WHERE jsonb_typeof(value)<>'string'
            OR octet_length(value#>>'{}')>512))) THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid news publication'; END IF;
  IF COALESCE(p_add_to_news,false) AND COALESCE(p_send_notification,false)
      AND NOT v_is_publishable THEN
    RAISE invalid_parameter_value
      USING MESSAGE='news push requires a publicly publishable occasion';
  END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'occasion',p_occasion,'addToNews',p_add_to_news,'newsMessage',p_news_message,
    'sendNotification',p_send_notification,'notificationHeading',p_notification_heading,
    'notificationContent',p_notification_content,'recipients',p_recipients)::text,
    'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,'content.news.publish',
    p_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  IF coalesce(p_send_notification,false) THEN PERFORM public.charge_notification_intent_v1(p_occasion,v_actor,p_recipients,p_notification_heading,p_notification_content); END IF;
  IF COALESCE(p_add_to_news,false) THEN
    INSERT INTO public.news(message,created_by,occasion)
      VALUES (p_news_message,v_actor,p_occasion) RETURNING id INTO v_id;
    v_version:=1;
    INSERT INTO public.client_aggregate_versions
      (aggregate_type,scope_type,scope_id,aggregate_id,version)
    VALUES ('news','occasion',p_occasion,v_id::text,v_version);
    SELECT to_jsonb(n)||jsonb_build_object('aggregate_version',v_version)
      INTO v_entity FROM public.news n WHERE n.id=v_id;
    v_items:=v_items||jsonb_build_array(jsonb_build_object(
      'entityType','news','entityId',v_id,'operation','insert','safeLabel','News',
      'changedFields',jsonb_build_array('message')));
  END IF;
  IF COALESCE(p_send_notification,false) THEN
    v_items:=v_items||jsonb_build_array(jsonb_build_object(
      'entityType','notification','entityId',NULL,'operation','publish',
      'safeLabel','Notification','changedFields',jsonb_build_array('delivery_request')));
  END IF;

  -- A notification-only test has no news publication to wait for.
  IF COALESCE(p_send_notification,false) AND NOT COALESCE(p_add_to_news,false) THEN
    INSERT INTO public.log_notifications
      (occasion,organization,user_id,"to",heading,content,data,abuse_admitted_at)
    VALUES (p_occasion,v_organization,v_actor,p_recipients,
      p_notification_heading,p_notification_content,jsonb_build_object('path','news'),statement_timestamp()) RETURNING id INTO v_notification;
    PERFORM public.dispatch_log_notification_v1(v_notification);
  END IF;

  v_response:=public.complete_client_mutation_applied_v1(p_command_id,p_occasion,
    'content.news.publish','content',v_items,
    CASE WHEN COALESCE(p_add_to_news,false) AND v_is_publishable
      THEN ARRAY['content_catalog'] ELSE '{}'::text[] END,'[]','[]',
    jsonb_build_object('version',v_version,'news',v_entity,
      'notificationQueued',COALESCE(p_send_notification,false)));

  IF COALESCE(p_add_to_news,false) AND COALESCE(p_send_notification,false) THEN
    SELECT c.resulting_revision INTO v_required_revision
    FROM public.client_commit_components c
    WHERE c.commit_id=(v_response#>>'{mutation,commitId}')::uuid
      AND c.component='content_catalog' AND c.scope_type='occasion'
      AND c.scope_id=p_occasion AND c.user_id IS NULL;
    IF v_required_revision IS NULL THEN
      RAISE EXCEPTION 'news publication did not produce a content revision';
    END IF;
    INSERT INTO public.news_notification_outbox
      (command_id,occasion,organization,user_id,required_content_revision,
       "to",heading,content,data,abuse_admitted_at)
    VALUES (p_command_id,p_occasion,v_organization,v_actor,v_required_revision,
      p_recipients,p_notification_heading,p_notification_content,
      jsonb_build_object('path','news'),statement_timestamp());
  END IF;
  RETURN v_response;
END; $function$;

-- Source: database/functions/eshop/release_blueprint_holds_client_sync_v1.sql
-- Administrative release of temporary holds. Buyers still use select_spot.
CREATE OR REPLACE FUNCTION public.release_blueprint_holds_client_sync_v1(
 p_spots bigint[], p_command_id uuid
) RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path='' AS $$
DECLARE actor uuid:=auth.uid(); occ bigint; ids bigint[]; bp bigint; started jsonb; users uuid[]; fingerprint text;
BEGIN
 IF actor IS NULL OR coalesce(cardinality(p_spots),0)=0 OR cardinality(p_spots)>256 THEN
  RAISE insufficient_privilege USING MESSAGE='order editor required'; END IF;
 SELECT min(b.occasion),min(s.blueprint) INTO occ,bp FROM eshop.spots s JOIN eshop.blueprints b ON b.id=s.blueprint WHERE s.id=ANY(p_spots);
 IF occ IS NULL OR public.can_write_orders(occ) IS NOT TRUE OR
  (SELECT count(*) FROM eshop.spots WHERE id=ANY(p_spots) AND blueprint=bp) <>
  cardinality(ARRAY(SELECT DISTINCT x FROM unnest(p_spots) x)) THEN
  RAISE insufficient_privilege USING MESSAGE='order editor required'; END IF;
 PERFORM public.lock_blueprint_scope_internal(ARRAY[occ]);
 PERFORM public.check_occasion_writable(occ);
 fingerprint:=encode(extensions.digest(convert_to(jsonb_build_object('spots',p_spots)::text,'UTF8'),'sha256'),'hex');
 started:=public.begin_client_mutation_v1(p_command_id,'inventory.blueprint.holds.release',occ,actor,fingerprint);
 IF started->>'disposition'='replay' THEN RETURN started->'response'; END IF;
 SELECT array_agg(DISTINCT member ORDER BY member) INTO ids FROM unnest(p_spots) requested
 CROSS JOIN LATERAL unnest(public.blueprint_selection_unit_spots_internal(requested)) member;
 PERFORM 1 FROM eshop.spots WHERE id=ANY(ids) ORDER BY id FOR UPDATE;
 IF EXISTS(SELECT 1 FROM eshop.spots WHERE id=ANY(ids) AND (blueprint IS DISTINCT FROM bp OR order_product_ticket IS NOT NULL)) THEN
  RAISE check_violation USING MESSAGE='Spot is already ordered'; END IF;
 SELECT coalesce(array_agg(ou."user"),'{}'::uuid[]) INTO users FROM public.occasion_users ou WHERE ou.occasion=occ;
 UPDATE eshop.spots SET secret=NULL,secret_expiration_time=NULL,updated_at=now()
 WHERE id=ANY(ids) AND order_product_ticket IS NULL;
 RETURN public.complete_profile_inventory_membership_mutation_v1(p_command_id,occ,'inventory.blueprint.holds.release',
  jsonb_build_array(jsonb_build_object('entityType','spot','entityId',NULL,'operation','update','safeLabel','Temporary reservation released','changedFields',jsonb_build_array('reservation'))),
  users,jsonb_build_object('spotIds',to_jsonb(ids)));
END $$;

-- Source: database/functions/eshop_orders/replace_blueprint_order_client_sync_v1.sql
CREATE OR REPLACE FUNCTION public.replace_blueprint_order_client_sync_v1(
  p_spot_ids bigint[],p_input_data jsonb,p_command_id uuid
) RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = public, extensions AS $$
DECLARE v_actor uuid:=auth.uid(); v_occasion bigint; v_begin jsonb; v_hash text;
  v_prepare jsonb; v_result jsonb; v_before_users uuid[];
BEGIN
  PERFORM public.lock_blueprint_scope_internal(ARRAY(SELECT DISTINCT occasion FROM eshop.spots WHERE id=ANY(p_spot_ids)));
  SELECT min(s.occasion) INTO v_occasion FROM eshop.spots s
    WHERE s.id=ANY(p_spot_ids);
  IF v_actor IS NULL OR v_occasion IS NULL OR cardinality(p_spot_ids)=0
    OR (SELECT count(*) FROM eshop.spots s
      WHERE s.id=ANY(p_spot_ids) AND s.occasion=v_occasion)
      <>cardinality(ARRAY(SELECT DISTINCT id FROM unnest(p_spot_ids) id))
    OR NOT public.can_write_orders(v_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='order editor required'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'spots',p_spot_ids,'input',p_input_data)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,
    'inventory.order.replace',v_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN public.project_local_payment_reference_order_internal(v_begin->'response'); END IF;
  SELECT COALESCE(array_agg(ou."user"),'{}'::uuid[]) INTO v_before_users
    FROM public.occasion_users ou WHERE ou.occasion=v_occasion;
  BEGIN
    v_prepare:=public.confirm_blueprint_order_change_internal_v1(
      p_spot_ids,p_input_data);
    IF COALESCE((v_prepare->>'success')::boolean,false) IS NOT TRUE THEN
      RAISE check_violation USING MESSAGE='replacement preparation rejected',
        DETAIL=v_prepare::text; END IF;
    v_result:=public.create_ticket_order_internal_v1(v_prepare->'orderDetails');
    IF COALESCE((v_result->>'code')::integer,500)<>200 THEN
      RAISE check_violation USING MESSAGE='replacement order rejected',
        DETAIL=v_result::text; END IF;
  EXCEPTION WHEN check_violation THEN
    RETURN public.complete_client_mutation_outcome_v1(
      p_command_id,'rejected',400,COALESCE(v_result,v_prepare,
        jsonb_build_object('message','order replacement rejected')));
  END;
  PERFORM public.enqueue_ticket_order_confirmation_v1(
    p_command_id,v_occasion,v_result,
    COALESCE(p_input_data->>'lang',v_prepare#>>'{orderDetails,lang}'));
  RETURN public.complete_profile_inventory_membership_mutation_v1(
    p_command_id,v_occasion,'inventory.order.replace',
    jsonb_build_array(jsonb_build_object('entityType','order',
      'entityId',v_result#>>'{order,id}','operation','insert',
      'safeLabel','Blueprint order replacement','changedFields',jsonb_build_array(
        'cancellations','tickets','products','allocations','membership'))),
    v_before_users,v_result);
END; $$;

-- Source: database/functions/groups/replace_group_assignments_client_sync_v1.sql
CREATE OR REPLACE FUNCTION public.replace_group_assignments_client_sync_v1(p_occasion bigint, p_command_id uuid, p_assignments jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO public, extensions
AS $function$
DECLARE v_actor uuid:=auth.uid(); v_begin jsonb; v_hash text; v_unit bigint;
  v_before jsonb; v_after jsonb; v_changed bigint[];
  v_group_ids bigint[]; v_impacted_users uuid[]; v_private_impacts jsonb;
  v_actor_replacements jsonb:='[]'::jsonb;
BEGIN
 PERFORM public.assert_canonical_mutation_write_release_internal_v1(p_occasion);
  SELECT o.unit INTO v_unit FROM public.occasions o WHERE o.id=p_occasion;
  IF v_actor IS NULL OR NOT public.can_import_group_assignments(p_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='group import permission required'; END IF;
  IF p_assignments IS NULL OR jsonb_typeof(p_assignments)<>'array'
    OR jsonb_array_length(p_assignments)>10000
    OR octet_length(p_assignments::text)>2097152 THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid group assignments'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object('occasion',p_occasion,
    'assignments',p_assignments)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,'profile.groups.import',
    p_occasion,v_actor,v_hash);
  PERFORM public.lock_group_occasion_internal_v1(p_occasion);
  IF NOT public.can_import_group_assignments(p_occasion) THEN RAISE insufficient_privilege USING MESSAGE='group import permission required'; END IF;
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  PERFORM pg_catalog.pg_advisory_xact_lock(p_occasion);
  PERFORM 1 FROM public.user_group_info g WHERE g.occasion=p_occasion
    AND g.type IS NULL ORDER BY g.id FOR UPDATE;
  SELECT COALESCE(array_agg(DISTINCT ug."group"),'{}'::bigint[])
    INTO v_group_ids FROM public.user_groups ug JOIN public.user_group_info g
      ON g.id=ug."group" JOIN jsonb_to_recordset(p_assignments)
      x(user_id uuid,group_title text) ON x.user_id=ug."user"
    WHERE g.occasion=p_occasion AND g.type IS NULL;
  SELECT COALESCE(array_agg(DISTINCT members."user"),'{}'::uuid[])
    INTO v_impacted_users FROM public.user_groups members
    WHERE members."group"=ANY(v_group_ids);
  SELECT COALESCE(jsonb_object_agg(g.id,public.get_user_group_command_data_v1(g.id)-'aggregate_version'),'{}') INTO v_before FROM public.user_group_info g WHERE g.occasion=p_occasion AND g.type IS NULL;
  PERFORM public.import_user_group_assignments_internal_v1(
    p_occasion,p_assignments);
  SELECT COALESCE(jsonb_object_agg(g.id,public.get_user_group_command_data_v1(g.id)-'aggregate_version'),'{}') INTO v_after FROM public.user_group_info g WHERE g.occasion=p_occasion AND g.type IS NULL;
  IF v_before=v_after THEN RETURN public.complete_client_mutation_outcome_v1(p_command_id,'unchanged',200,jsonb_build_object('assignments',jsonb_array_length(p_assignments))); END IF;
  SELECT ARRAY(SELECT key::bigint FROM jsonb_each(v_after) WHERE value IS DISTINCT FROM v_before->key ORDER BY key::bigint) INTO v_changed;
  SELECT ARRAY(SELECT DISTINCT id FROM unnest(v_group_ids||COALESCE((
    SELECT array_agg(ug."group") FROM public.user_groups ug
    JOIN public.user_group_info g ON g.id=ug."group"
    JOIN jsonb_to_recordset(p_assignments) x(user_id uuid,group_title text)
      ON x.user_id=ug."user" WHERE g.occasion=p_occasion AND g.type IS NULL),
    '{}'::bigint[])) id ORDER BY id) INTO v_group_ids;
  SELECT ARRAY(SELECT DISTINCT id FROM unnest(v_impacted_users||COALESCE((
    SELECT array_agg(members."user") FROM public.user_groups members
    WHERE members."group"=ANY(v_group_ids)),'{}'::uuid[])) id ORDER BY id)
    INTO v_impacted_users;
  INSERT INTO public.client_aggregate_versions
    (aggregate_type,scope_type,scope_id,aggregate_id,version)
  SELECT 'user_group','occasion',p_occasion,id::text,1 FROM unnest(v_changed) id
  ON CONFLICT (aggregate_type,scope_type,scope_id,aggregate_id) DO UPDATE
    SET version=public.client_aggregate_versions.version+1,
      updated_at=clock_timestamp();
  v_private_impacts:=public.group_profile_impacts_internal_v1(p_occasion,v_impacted_users);
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(v_private_impacts) x WHERE x->>'userId'=v_actor::text) THEN v_actor_replacements:=jsonb_build_array(
    jsonb_build_object('component','private_profile','userId',v_actor,
      'payload',public.get_private_profile_payload_v1(p_occasion,v_actor))); END IF;
  RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,
    'profile.groups.import','profile',jsonb_build_array(jsonb_build_object(
      'entityType','user_group_membership','entityId',NULL,'operation','import',
      'safeLabel','Group assignment import','changedFields',jsonb_build_array('memberships'))),
    '{}',v_private_impacts,'[]',jsonb_build_object(
      'assignments',jsonb_array_length(p_assignments)),
    '{}','[]','user',NULL,v_actor_replacements);
END; $function$
;

-- Source: database/functions/emails/email_domain.sql
CREATE OR REPLACE FUNCTION public.reset_password_and_enqueue_email(p_user uuid,p_password text,p_occasion bigint,p_sealed jsonb,p_content_hash text,p_dedupe text,p_expires timestamptz)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE v_answer jsonb; v_context jsonb; v_email text; v_result jsonb; v_existing public.email_messages; v_password_version text;
BEGIN
 -- Reuse the existing hierarchical permission check, including elevated-account protections.
 IF auth.uid() IS NULL OR NOT coalesce(public.get_can_reset_user_password(p_user),false) THEN RAISE EXCEPTION 'password_reset_denied'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('sign-in:'||p_user::text||':'||p_occasion::text,0));
 -- Team invitations never own a password transition, including older clients.
 PERFORM 1 FROM public.occasion_users WHERE occasion=p_occasion AND "user"=p_user FOR SHARE;
 IF EXISTS(SELECT 1 FROM public.occasion_users WHERE occasion=p_occasion AND "user"=p_user
   AND (is_editor OR is_editor_view OR is_manager)) THEN
  RAISE insufficient_privilege USING MESSAGE='Team invitations cannot reset account passwords'; END IF;
 SELECT * INTO v_existing FROM public.email_messages WHERE recipient_user=p_user AND occasion=p_occasion AND message_kind='sign_in' AND (dedupe_key=p_dedupe OR (workflow_state IN ('pending','preparing','sending','retry_wait','unknown','accepted') AND expires_at>now())) ORDER BY id DESC LIMIT 1;
 IF v_existing.id IS NOT NULL THEN
  RETURN jsonb_build_object('message_id',v_existing.message_id,'replayed',true);
 END IF;
 IF NOT EXISTS(SELECT 1 FROM public.occasion_users WHERE occasion=p_occasion AND "user"=p_user) THEN RAISE EXCEPTION 'user_not_in_occasion'; END IF;
 v_answer:=public.reset_user_password(p_user,p_password);
 IF v_answer->>'code'<>'200' THEN RAISE EXCEPTION 'password_reset_denied'; END IF;
 SELECT jsonb_build_object('organization',organization,'occasion',id,'unit',unit,'recipient_user',p_user) INTO v_context FROM public.occasions WHERE id=p_occasion;
 v_email:=public.get_user_delivery_email(p_user);
 SELECT encode(extensions.digest(encrypted_password,'sha256'),'hex') INTO v_password_version FROM auth.users WHERE id=p_user;
 v_result:=public.enqueue_email('sign_in',v_context,v_email,jsonb_build_object('password_version',v_password_version,'content_hash',p_content_hash),p_dedupe,'SIGN_IN_CODE',now(),p_expires);
 UPDATE public.email_messages SET prepared=p_sealed,prepared_hash=encode(extensions.digest(p_sealed::text,'sha256'),'hex'),prepared_at=now() WHERE message_id=(v_result->>'message_id')::uuid;
 PERFORM public.admit_email_intent_v1((SELECT id FROM public.email_messages WHERE message_id=(v_result->>'message_id')::uuid),true);
 RETURN v_result;
END $$;

-- Source: database/functions/speakers/delete_counseling_slot.sql
-- Guard used by both legacy and client-sync single-slot deletion paths.
-- It locks the target event and only resolves an occasion when the event is a
-- generated counseling slot linked to the speaker selected in the editor.
CREATE OR REPLACE FUNCTION public.resolve_counseling_slot_delete_occasion_internal_v1(
  p_speaker BIGINT,
  p_event BIGINT
)
RETURNS BIGINT
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
  v_occasion BIGINT;
BEGIN
  SELECT s.occasion INTO v_occasion
  FROM public.speakers s
  WHERE s.id = p_speaker;

  IF v_occasion IS NULL THEN
    RETURN NULL;
  END IF;
  IF auth.uid() IS NULL OR NOT public.can_write_speakers(v_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE = 'occasion editor required';
  END IF;

  PERFORM public.lock_event_deletion_scope_internal_v1(v_occasion,ARRAY[p_event]);
  PERFORM 1
  FROM public.events e
  JOIN public.event_speakers es
    ON es.event = e.id AND es.speaker = p_speaker
  WHERE e.id = p_event
    AND e.occasion = v_occasion
    AND COALESCE((e.data->>'is_counseling_slot')::BOOLEAN, FALSE)
  FOR UPDATE OF e;

  IF NOT FOUND THEN
    RETURN NULL;
  END IF;
  RETURN v_occasion;
END;
$$;

-- Source: database/functions/eshop_waitlist/order_overview_access.sql
-- Called only by trusted Edge after authentication. A view capability can never resolve write scope.
CREATE OR REPLACE FUNCTION public.resolve_customer_order_access_v1(p_token text,p_order_id bigint,p_offer_id uuid,
 p_command_id uuid,p_delivery jsonb DEFAULT NULL,p_actor uuid DEFAULT NULL,p_reissue boolean DEFAULT false)
RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE o eshop.orders; f public.forms; occ public.occasions; c eshop.waitlist_capabilities; s eshop.order_overview_sources;
BEGIN
 PERFORM public.require_client_sync_service_role_v1();
 IF p_offer_id IS NOT NULL THEN
  IF p_order_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM eshop.waitlist_offers WHERE id=p_offer_id AND order_id=p_order_id) THEN RAISE EXCEPTION 'INVALID_CAPABILITY'; END IF;
  SELECT order_id INTO p_order_id FROM eshop.waitlist_offers WHERE id=p_offer_id;
 END IF;
 SELECT * INTO STRICT o FROM eshop.orders WHERE id=p_order_id AND source_waitlist_order_id IS NULL FOR UPDATE;
 SELECT * INTO STRICT f FROM public.forms WHERE id=o.form AND occasion=o.occasion;
 SELECT * INTO STRICT occ FROM public.occasions WHERE id=o.occasion;
 IF p_reissue THEN
  IF NOT EXISTS(SELECT 1 FROM eshop.waitlist_capabilities WHERE order_id=o.id AND kind='manage' AND form_id=f.id AND organization_id=occ.organization) THEN RAISE EXCEPTION 'INVALID_CAPABILITY'; END IF;
  IF NOT public.can_write_orders_as_actor_internal(p_actor,occ.id) THEN
   RAISE insufficient_privilege USING MESSAGE='Order editor required'; END IF;
 ELSE
  IF o.state<>'waitlisted' OR NOT EXISTS(SELECT 1 FROM public.get_order_tickets_internal(o.id) WHERE state='waitlisted') THEN RAISE EXCEPTION 'INVALID_CAPABILITY'; END IF;
  SELECT * INTO c FROM eshop.waitlist_capabilities WHERE token_hash=encode(extensions.digest(p_token,'sha256'),'hex')
   AND order_id=o.id AND form_id=f.id AND organization_id=occ.organization AND revoked_at IS NULL
   AND (expires_at IS NULL OR expires_at>statement_timestamp())
   AND ((p_offer_id IS NULL AND kind='manage') OR (kind='offer' AND offer_id=p_offer_id));
  IF p_token IS NULL OR length(p_token)<>64 OR c.token_hash IS NULL OR (p_offer_id IS NOT NULL AND NOT EXISTS(
   SELECT 1 FROM eshop.waitlist_offers w JOIN eshop.waitlist_offer_slots x ON x.offer_id=w.id
   WHERE w.id=p_offer_id AND w.order_id=o.id AND w.form_id=f.id AND w.expires_at>statement_timestamp() AND x.outcome='pending')) THEN
   RAISE EXCEPTION 'INVALID_CAPABILITY'; END IF;
 END IF;
 -- Command replay precedes rotation. It never resurrects a revoked/expired generation.
 SELECT src.* INTO s FROM eshop.order_overview_sources src JOIN eshop.waitlist_capabilities cap USING(token_hash)
 WHERE cap.order_id=o.id AND cap.kind='order_view' AND cap.revoked_at IS NULL
 AND cap.expires_at>statement_timestamp() AND src.expires_at=cap.expires_at
 AND (NOT p_reissue OR src.command_id=p_command_id) ORDER BY src.created_at DESC LIMIT 1;
 IF s.token_hash IS NULL AND p_delivery IS NOT NULL THEN
  IF p_reissue AND EXISTS(SELECT 1 FROM eshop.orders_history WHERE "order"=o.id
   AND data->>'action'='order_overview_reissued' AND data->>'commandId'=p_command_id::text) THEN
   RAISE EXCEPTION 'OVERVIEW_REISSUE_REQUIRED'; END IF;
  IF NOT p_reissue AND EXISTS(SELECT 1 FROM eshop.waitlist_capabilities WHERE order_id=o.id AND kind='order_view') THEN
   RAISE EXCEPTION 'OVERVIEW_REISSUE_REQUIRED'; END IF;
  IF p_reissue THEN UPDATE eshop.waitlist_capabilities SET revoked_at=statement_timestamp() WHERE order_id=o.id AND kind='order_view' AND revoked_at IS NULL; END IF;
  PERFORM public.issue_order_overview_internal(o.id,p_delivery,p_command_id);
  IF p_reissue THEN INSERT INTO eshop.orders_history("order",state,data) VALUES(o.id,o.state,
   jsonb_build_object('action','order_overview_reissued','commandId',p_command_id,'actor',p_actor)); END IF;
  SELECT * INTO s FROM eshop.order_overview_sources WHERE command_id=p_command_id;
 END IF;
 RETURN jsonb_build_object('code',200,'orderId',o.id,'formLink',f.link,'organization',occ.organization,'occasion',occ.id,'unit',occ.unit,
  'orderSymbol',o.order_symbol,
  'email',(SELECT jsonb_build_object('message_id',message_id,'workflow_state',workflow_state) FROM public.email_messages WHERE dedupe_key='order-overview:'||p_command_id::text AND order_id=o.id),
  'recipient',o.data->>'email','occasionTitle',occ.title,'participantCount',(SELECT count(*) FROM public.get_order_tickets_internal(o.id)),
  'webLink',(SELECT data->>'DEFAULT_URL' FROM public.organizations WHERE id=occ.organization),
  'source',CASE WHEN s.token_hash IS NOT NULL THEN jsonb_build_object('sealed',s.sealed,'contentHash',s.content_hash,'tokenHash',s.token_hash,'expiresAt',s.expires_at) END);
END $$;

-- Source: database/functions/users/reception_qr_login.sql
CREATE OR REPLACE FUNCTION public.revoke_reception_login_qr_v1(p_occasion bigint,p_user uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE v_actor uuid:=auth.uid();
BEGIN
  IF NOT public.get_can_use_reception(p_occasion) THEN
    RETURN jsonb_build_object('code',403,'message','reception_unavailable');
  END IF;
  IF NOT public.reception_rate_limit_v1('revoke') THEN
    RETURN jsonb_build_object('code',429,'message','rate_limited');
  END IF;
  IF NOT EXISTS(
    SELECT 1 FROM public.reception_registrations r
    WHERE r.occasion=p_occasion AND r."user"=p_user AND r.status='active'
      AND ((r.created_by=v_actor AND r.created_at>now()-interval '30 minutes')
        OR public.can_manage_occasion_participants(p_occasion))
  ) THEN
    RETURN jsonb_build_object('code',403,'message','registration_unavailable');
  END IF;
  UPDATE public.user_login_qr_credentials
  SET revoked_at=now()
  WHERE occasion=p_occasion AND "user"=p_user AND revoked_at IS NULL;
  RETURN jsonb_build_object('code',200,'status','revoked');
END $$;

-- Source: database/functions/activities/canonical_activity_lifecycle.sql
CREATE OR REPLACE FUNCTION public.save_activity_draft_client_sync_v1(p_occasion bigint,p_command_id uuid,p_expected_version bigint,p_history_data jsonb,p_parent_history_id bigint)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE actor uuid:=auth.uid(); b jsonb; v bigint; latest bigint; draft public.activity_history%rowtype; graph jsonb; history jsonb; result jsonb; hid bigint;
BEGIN
 PERFORM public.assert_canonical_mutation_write_release_internal_v1(p_occasion);
 IF actor IS NULL OR NOT public.can_write_activity_plan(p_occasion) THEN RAISE insufficient_privilege USING MESSAGE='occasion editor required'; END IF;
 IF p_history_data IS NULL OR jsonb_typeof(p_history_data)<>'object' OR octet_length(p_history_data::text)>2097152 THEN RAISE invalid_parameter_value USING MESSAGE='invalid draft'; END IF;
 b:=public.begin_client_mutation_v1(p_command_id,'activities.draft.save',p_occasion,actor,encode(extensions.digest(jsonb_build_object('occasion',p_occasion,'expectedVersion',p_expected_version,'history',p_history_data,'parent',p_parent_history_id)::text,'sha256'),'hex'));
 v:=public.lock_activity_editor_internal_v1(p_occasion);
 IF b->>'disposition'='replay' THEN RETURN b->'response'; END IF;
 SELECT id INTO latest FROM public.activity_history WHERE occasion_id=p_occasion AND history_type='PUBLISH' ORDER BY id DESC LIMIT 1;
 IF p_expected_version IS DISTINCT FROM v OR p_parent_history_id IS DISTINCT FROM latest THEN RETURN public.complete_client_mutation_outcome_v1(p_command_id,'conflict',409,jsonb_build_object('version',v,'latestPublishId',latest)); END IF;
 graph:=public.activity_history_graph_internal_v1(p_occasion,p_history_data-'_consume_autosave'); history:=public.activity_graph_history_internal_v1(graph);
 SELECT * INTO draft FROM public.activity_history WHERE occasion_id=p_occasion AND user_id=actor AND history_type='AUTOSAVE' ORDER BY id DESC LIMIT 1;
 result:=jsonb_build_object('version',v,'latestPublishId',latest,'draftId',draft.id,'draftParentHistoryId',latest);
 IF draft.id IS NOT NULL AND draft.activities_data=history AND draft.parent_history_id IS NOT DISTINCT FROM latest THEN RETURN public.complete_client_mutation_outcome_v1(p_command_id,'unchanged',200,result); END IF;
 hid:=public.write_activity_history_internal_v1(p_occasion,actor,history,'AUTOSAVE',latest,NULL);
 PERFORM public.retain_activity_history_internal_v1(p_occasion);
 RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,'activities.draft.save','activities',jsonb_build_array(jsonb_build_object('entityType','activity_draft','entityId',hid,'operation',CASE WHEN draft.id IS NULL THEN 'insert' ELSE 'update' END,'changedFields',jsonb_build_array('draft'))),'{}','[]','[]',result||jsonb_build_object('draftId',hid));
END $$;

-- Source: database/functions/activities/legacy_activity_facades.sql
CREATE OR REPLACE FUNCTION public.save_activity_history(
 p_occasion_id bigint,p_activities_data jsonb,p_history_type text,p_parent_history_id bigint,p_note text DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE version bigint; result jsonb; canonical_history jsonb;
BEGIN
 IF auth.uid() IS NULL OR NOT coalesce(public.can_write_activity_plan(p_occasion_id),false) THEN
  RETURN jsonb_build_object('code',403); END IF;
 IF p_history_type IS DISTINCT FROM 'AUTOSAVE' THEN
  RETURN jsonb_build_object('code',426,'message','Upgrade required for atomic activity publication'); END IF;
 version:=public.lock_activity_editor_internal_v1(p_occasion_id);
 canonical_history:=public.activity_graph_history_internal_v1(
  public.activity_history_graph_internal_v1(p_occasion_id,p_activities_data));
 result:=public.save_activity_draft_client_sync_v1(p_occasion_id,extensions.gen_random_uuid(),version,canonical_history,p_parent_history_id);
 RETURN jsonb_build_object('code',result->'code','message',result->>'status','data',
  jsonb_build_object('historyId',result#>'{data,draftId}',
   'created_at',(SELECT created_at FROM public.activity_history WHERE id=(result#>>'{data,draftId}')::bigint),
   'latest_publish_id',result#>'{data,latestPublishId}'));
END $$;

-- Source: database/functions/blueprint/save.sql
CREATE OR REPLACE FUNCTION public.save_blueprint_layout_impl_internal(p_blueprint jsonb,p_reviewed_demo boolean)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE b eshop.blueprints; c jsonb; binding eshop.blueprint_seat_bindings; s eshop.spots;
 node uuid; group_id uuid; unit_id uuid; product_id bigint; spot_id bigint; blocked_value boolean; assignment_mode text;
 pool public.inventory_pools; capacity_int bigint;
 node_index jsonb; unit_index jsonb; seat_count bigint; text_ids text[]:='{}';
 doc jsonb:=p_blueprint->'layout'; result jsonb; expected bigint; issue text; all_seats uuid[]; supplied uuid[];
BEGIN
 IF nullif(p_blueprint->>'id','') IS NULL THEN
  IF public.can_write_blueprints((p_blueprint->>'occasion')::bigint) IS NOT TRUE THEN
   RAISE insufficient_privilege USING MESSAGE='blueprint editor required'; END IF;
  INSERT INTO eshop.blueprints(occasion,organization,title) SELECT id,organization,p_blueprint->>'title' FROM public.occasions WHERE id=(p_blueprint->>'occasion')::bigint RETURNING * INTO b;
 ELSE
  SELECT * INTO b FROM eshop.blueprints WHERE id=(p_blueprint->>'id')::bigint;
  PERFORM 1 FROM eshop.products WHERE occasion=b.occasion ORDER BY id FOR UPDATE;
  SELECT * INTO b FROM eshop.blueprints WHERE id=(p_blueprint->>'id')::bigint FOR UPDATE;
 END IF;
 IF b.id IS NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='BLUEPRINT_NOT_FOUND'; END IF;
 IF p_reviewed_demo AND public.is_demo_occasion(b.occasion) THEN
  IF NOT public.can_migrate_reviewed_legacy_blueprint(b.occasion) THEN RAISE insufficient_privilege USING MESSAGE='blueprint migration reviewer required'; END IF;
 ELSE
 IF public.can_write_blueprints(b.occasion) IS NOT TRUE THEN RAISE insufficient_privilege USING MESSAGE='blueprint editor required'; END IF;
 END IF;
 IF p_reviewed_demo AND public.is_demo_occasion(b.occasion) THEN
  IF b.layout IS NOT NULL THEN RAISE check_violation USING MESSAGE='BLUEPRINT_MIGRATION_INITIAL_LAYOUT_REQUIRED'; END IF;
 ELSE PERFORM public.check_occasion_writable(b.occasion); END IF;
 expected:=(p_blueprint->>'expected_layout_revision')::bigint;
 IF expected IS NULL OR expected<>b.layout_revision THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='BLUEPRINT_REVISION_CONFLICT'; END IF;
 PERFORM public.validate_blueprint_layout_internal(doc);
  PERFORM public.check_blueprint_text_resources_internal(doc,b.occasion);
  text_ids:=public.blueprint_text_resource_ids_internal(doc,b.occasion);
  IF jsonb_typeof(p_blueprint->'textResourceIds') IS DISTINCT FROM 'array'
    OR EXISTS(SELECT 1 FROM jsonb_array_elements(p_blueprint->'textResourceIds') id WHERE jsonb_typeof(id)<>'string')
    OR (SELECT coalesce(array_agg(id ORDER BY id),'{}'::text[]) FROM jsonb_array_elements_text(p_blueprint->'textResourceIds') id) IS DISTINCT FROM text_ids
    THEN RAISE check_violation USING MESSAGE='BLUEPRINT_TEXT_RESOURCE_REFS_MISMATCH'; END IF;

 PERFORM public.check_blueprint_image_resource_internal(doc,b.occasion);
 PERFORM public.check_blueprint_bitmap_resources_internal(doc,b.occasion);
 SELECT coalesce(jsonb_object_agg(x->>'id',x),'{}'),count(*) FILTER(WHERE x->>'kind'='seat') INTO node_index,seat_count FROM jsonb_array_elements(doc->'nodes') x;
 -- Membership is projected from the document, never trusted from an overlay.
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(doc->'selectionUnits','[]')) u WHERE
   (u->>'id')::uuid IS NULL OR jsonb_array_length(u->'nodeIds')=0 OR coalesce(u->>'kind','atomic')<>'atomic')
  OR EXISTS(SELECT member FROM jsonb_array_elements(coalesce(doc->'selectionUnits','[]')) u
   CROSS JOIN LATERAL jsonb_array_elements_text(u->'nodeIds') member GROUP BY member HAVING count(*)>1)
  OR EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(doc->'selectionUnits','[]')) u
   CROSS JOIN LATERAL jsonb_array_elements_text(u->'nodeIds') member
   WHERE coalesce(node_index->member->>'kind','')<>'seat') THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='BLUEPRINT_INVALID_SELECTION_UNITS'; END IF;
 SELECT coalesce(jsonb_object_agg(member,u->>'id'),'{}') INTO unit_index
 FROM jsonb_array_elements(coalesce(doc->'selectionUnits','[]')) u CROSS JOIN LATERAL jsonb_array_elements_text(u->'nodeIds') member;
 -- Keep the existing financial resource lock ordering, before spot row locks.
 PERFORM 1 FROM eshop.products WHERE occasion=b.occasion ORDER BY id FOR UPDATE;
 PERFORM 1 FROM public.inventory_pools WHERE id IN(SELECT ic.inventory_pool FROM public.inventory_contexts ic
  JOIN eshop.product_inventory_contexts pic ON pic.inventory_context=ic.id JOIN eshop.products p ON p.id=pic.product WHERE p.occasion=b.occasion) ORDER BY id FOR UPDATE;
 PERFORM 1 FROM public.inventory_contexts WHERE id IN(SELECT pic.inventory_context FROM eshop.product_inventory_contexts pic JOIN eshop.products p ON p.id=pic.product WHERE p.occasion=b.occasion) ORDER BY id FOR UPDATE;
 PERFORM 1 FROM eshop.spots WHERE blueprint=b.id ORDER BY id FOR UPDATE;
 IF EXISTS(SELECT change->>'nodeId' FROM jsonb_array_elements(coalesce(p_blueprint->'seatChanges','[]')) change GROUP BY change->>'nodeId' HAVING count(*)>1) THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='BLUEPRINT_DUPLICATE_SEAT_CHANGE'; END IF;
 FOR c IN SELECT * FROM jsonb_array_elements(coalesce(p_blueprint->'seatChanges','[]')) LOOP
  node:=(c->>'nodeId')::uuid;
  SELECT * INTO binding FROM eshop.blueprint_seat_bindings WHERE blueprint=b.id AND node_id=node;
  IF c->>'operation'='delete' THEN
   IF binding.node_id IS NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='BLUEPRINT_BINDING_NOT_FOUND',DETAIL=c::text; END IF;
   SELECT * INTO s FROM eshop.spots WHERE id=binding.spot;
   IF s.order_product_ticket IS NOT NULL OR (s.secret IS NOT NULL AND s.secret_expiration_time>clock_timestamp()) THEN
    RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='BLUEPRINT_SEAT_PROTECTED',DETAIL=c::text; END IF;
   DELETE FROM eshop.blueprint_seat_bindings WHERE blueprint=b.id AND node_id=node;
   DELETE FROM eshop.spots WHERE id=s.id;
   CONTINUE;
  END IF;
  IF c->>'operation' IS DISTINCT FROM 'upsert' OR coalesce(node_index->node::text->>'kind','')<>'seat' THEN
   RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='BLUEPRINT_INVALID_SEAT_CHANGE',DETAIL=c::text; END IF;
  IF NOT c ? 'productId' OR NOT c ? 'blocked' OR NOT c ? 'groupNodeId' OR NOT c ? 'selectionUnitId' THEN
   RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='BLUEPRINT_INCOMPLETE_SEAT_CHANGE',DETAIL=c::text; END IF;
  assignment_mode:=coalesce(c->>'productAssignmentMode','override');
  IF assignment_mode NOT IN ('inherit','override') OR NOT c ? 'productAssignmentMode' THEN RAISE check_violation USING MESSAGE='BLUEPRINT_INVALID_PRODUCT_ASSIGNMENT_MODE'; END IF;
  product_id:=(c->>'productId')::bigint; group_id:=(c->>'groupNodeId')::uuid; unit_id:=(c->>'selectionUnitId')::uuid; blocked_value:=(c->>'blocked')::boolean;
  IF blocked_value IS NULL OR (product_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM eshop.products WHERE id=product_id AND occasion=b.occasion)) THEN
   RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='BLUEPRINT_INVALID_PRODUCT',DETAIL=c::text; END IF;
  IF group_id IS NOT NULL AND coalesce(node_index->group_id::text->>'kind','') NOT IN ('group','table','furniture') THEN
   RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='BLUEPRINT_INVALID_GROUP',DETAIL=c::text; END IF;
  IF unit_id IS DISTINCT FROM (unit_index->>node::text)::uuid THEN
   RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='BLUEPRINT_UNIT_MEMBERSHIP_MISMATCH',DETAIL=c::text; END IF;
  spot_id:=(c->>'spotId')::bigint;
  IF binding.node_id IS NOT NULL AND spot_id IS DISTINCT FROM binding.spot THEN
   RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='BLUEPRINT_SPOT_IDENTITY_CHANGED',DETAIL=c::text; END IF;
  IF spot_id IS NOT NULL THEN
   SELECT * INTO s FROM eshop.spots WHERE id=spot_id AND blueprint=b.id AND occasion=b.occasion;
   IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='BLUEPRINT_SPOT_SCOPE_MISMATCH',DETAIL=c::text; END IF;
   IF (s.order_product_ticket IS NOT NULL OR (s.secret IS NOT NULL AND s.secret_expiration_time>clock_timestamp()))
    AND (s.product IS DISTINCT FROM product_id OR s.title IS DISTINCT FROM c->>'title'
     OR coalesce(binding.blocked,false) IS DISTINCT FROM blocked_value OR binding.selection_unit IS DISTINCT FROM unit_id OR binding.group_node IS DISTINCT FROM group_id OR binding.product_assignment_mode IS DISTINCT FROM assignment_mode) THEN
    RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='BLUEPRINT_SEAT_PROTECTED',DETAIL=c::text; END IF;
   UPDATE eshop.spots SET product=product_id,title=c->>'title',updated_at=now() WHERE id=spot_id
    AND (product IS DISTINCT FROM product_id OR title IS DISTINCT FROM c->>'title');
  ELSE
   INSERT INTO eshop.spots(blueprint,occasion,product,title) VALUES(b.id,b.occasion,product_id,c->>'title') RETURNING id INTO spot_id;
  END IF;
  INSERT INTO eshop.blueprint_seat_bindings(blueprint,node_id,spot,selection_unit,group_node,blocked,product_assignment_mode)
   VALUES(b.id,node,spot_id,unit_id,group_id,blocked_value,assignment_mode)
   ON CONFLICT(blueprint,node_id) DO UPDATE SET selection_unit=excluded.selection_unit,group_node=excluded.group_node,blocked=excluded.blocked,product_assignment_mode=excluded.product_assignment_mode;
 END LOOP;
 IF EXISTS(SELECT 1 FROM eshop.blueprint_seat_bindings sb WHERE sb.blueprint=b.id AND coalesce(node_index->sb.node_id::text->>'kind','')<>'seat')
  OR (SELECT count(*) FROM eshop.blueprint_seat_bindings sb WHERE sb.blueprint=b.id)<>seat_count
  OR EXISTS(SELECT 1 FROM eshop.blueprint_seat_bindings sb WHERE sb.blueprint=b.id AND sb.selection_unit IS DISTINCT FROM
   (unit_index->>sb.node_id::text)::uuid) THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='BLUEPRINT_BINDING_SET_MISMATCH'; END IF;
 IF EXISTS(SELECT 1 FROM eshop.blueprint_seat_bindings sb WHERE sb.blueprint=b.id AND sb.group_node IS NOT NULL AND coalesce(node_index->sb.group_node::text->>'kind','') NOT IN ('group','table','furniture')) THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='BLUEPRINT_INVALID_GROUP'; END IF;
 FOR c IN SELECT * FROM jsonb_array_elements(coalesce(p_blueprint->'groupProductChanges','[]')) LOOP
  IF NOT c ? 'productId' THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='BLUEPRINT_INCOMPLETE_GROUP_CHANGE',DETAIL=c::text; END IF;
  node:=(c->>'groupNodeId')::uuid; product_id:=(c->>'productId')::bigint;
  IF coalesce(node_index->node::text->>'kind','') NOT IN ('table','group','furniture')
   OR (product_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM eshop.products WHERE id=product_id AND occasion=b.occasion)) THEN
   RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='BLUEPRINT_INVALID_GROUP_PRODUCT',DETAIL=c::text; END IF;
  DELETE FROM eshop.blueprint_group_products WHERE blueprint=b.id AND group_node=node;
  IF product_id IS NOT NULL THEN INSERT INTO eshop.blueprint_group_products VALUES(b.id,node,product_id); END IF;
 END LOOP;
 DELETE FROM eshop.blueprint_group_products gp WHERE blueprint=b.id AND NOT node_index ? gp.group_node::text;
 IF EXISTS(SELECT 1 FROM eshop.blueprint_seat_bindings sb JOIN eshop.spots bound_spot ON bound_spot.id=sb.spot LEFT JOIN eshop.blueprint_group_products gp ON gp.blueprint=sb.blueprint AND gp.group_node=sb.group_node WHERE sb.blueprint=b.id AND sb.product_assignment_mode='inherit' AND (sb.group_node IS NULL OR gp.product IS NULL)) THEN RAISE check_violation USING MESSAGE='BLUEPRINT_INHERITED_PRODUCT_MISMATCH'; END IF;
 FOR c IN SELECT * FROM jsonb_array_elements(coalesce(p_blueprint->'areaBindingChanges','[]')) LOOP
  node:=(c->>'nodeId')::uuid; product_id:=(c->>'productId')::bigint;
  DELETE FROM eshop.blueprint_area_bindings WHERE blueprint=b.id AND node_id=node;
  IF c->>'operation'='delete' THEN CONTINUE; END IF;
  IF c->>'operation' IS DISTINCT FROM 'upsert' OR coalesce(node_index->node::text->>'kind','')<>'capacityArea'
   OR NOT EXISTS(SELECT 1 FROM eshop.product_inventory_contexts pic JOIN eshop.products p ON p.id=pic.product JOIN public.inventory_contexts ic ON ic.id=pic.inventory_context JOIN public.inventory_pools ip ON ip.id=ic.inventory_pool WHERE pic.product=product_id AND pic.inventory_context=(c->>'inventoryContextId')::bigint AND p.occasion=b.occasion AND ip.occasion=b.occasion) THEN
   RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='BLUEPRINT_INVALID_AREA_BINDING',DETAIL=c::text; END IF;
  IF c ? 'capacity' THEN
   capacity_int:=(c->>'capacity')::bigint;
   IF capacity_int IS NULL OR capacity_int<0 OR capacity_int>1000000 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='BLUEPRINT_INVALID_CAPACITY'; END IF;
   SELECT ip.* INTO pool FROM public.inventory_pools ip JOIN public.inventory_contexts ic ON ic.inventory_pool=ip.id WHERE ic.id=(c->>'inventoryContextId')::bigint;
   PERFORM public.update_inventory_pool_bundle(jsonb_build_object('pool',jsonb_build_object(
    'id',pool.id,'occasion',pool.occasion,'title',pool.title,
    'description',pool.description,'type',pool.type,'data',pool.data,
    'sellable_capacity',capacity_int)));
  END IF;
  INSERT INTO eshop.blueprint_area_bindings VALUES(b.id,node,(c->>'inventoryContextId')::bigint,product_id);
 END LOOP;
 IF EXISTS(SELECT 1 FROM eshop.blueprint_area_bindings ab WHERE blueprint=b.id AND coalesce(node_index->ab.node_id::text->>'kind','')<>'capacityArea') THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='BLUEPRINT_AREA_BINDING_SET_MISMATCH'; END IF;
 UPDATE eshop.blueprints SET layout=doc,layout_text_resource_ids=text_ids,layout_revision=layout_revision+1,updated_at=now(),title=coalesce(p_blueprint->>'title',title) WHERE id=b.id RETURNING * INTO b;
 result:=public.blueprint_binding_projection_internal(b.id)||jsonb_build_object('code',200,'blueprint_id',b.id,'layout_revision',b.layout_revision,
  'document_hash',encode(extensions.digest(convert_to(doc::text,'UTF8'),'sha256'),'hex'));
 IF octet_length(result::text)>4194304 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='BLUEPRINT_RESULT_TOO_LARGE'; END IF;
 RETURN result;
END $$;

-- Source: database/functions/events/save_event_domain_command_internal_v1.sql
CREATE OR REPLACE FUNCTION public.save_event_domain_command_internal_v1(p_occasion bigint, p_command_id uuid, p_expected_version bigint, p_event jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path=public,extensions
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_event_id bigint := (p_event->>'id')::bigint;
  v_version bigint;
  v_begin jsonb;
  v_commit jsonb;
  v_data jsonb;
  v_current jsonb;
  v_requested jsonb;
  v_response jsonb;
  v_program jsonb;
  v_hash text;
  v_changed boolean := true;
  v_is_publishable boolean;
  v_parent_ids bigint[];
  v_role_ids bigint[];
BEGIN
  IF v_actor IS NULL OR NOT public.can_write_schedule(p_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='occasion editor required';
  END IF;
  SELECT NOT o.is_hidden INTO v_is_publishable
  FROM public.occasions o WHERE o.id=p_occasion;
  IF v_is_publishable IS NULL THEN
    RAISE invalid_parameter_value USING MESSAGE='occasion not found';
  END IF;
  IF p_event IS NULL OR jsonb_typeof(p_event)<>'object'
     OR octet_length(p_event::text)>131072
     OR EXISTS (SELECT 1 FROM jsonb_object_keys(p_event) key WHERE key NOT IN
       ('id','title','startTime','endTime','maxParticipants','description',
        'placeId','splitForMenWomen','isGroupEvent','isHidden','type','data',
        'order','parentEventIds','eventRoleIds'))
     OR NOT (p_event ?& ARRAY['title','startTime','endTime','splitForMenWomen',
       'isGroupEvent','isHidden','order','parentEventIds','eventRoleIds'])
     OR jsonb_typeof(p_event->'parentEventIds')<>'array'
     OR jsonb_typeof(p_event->'eventRoleIds')<>'array'
     OR jsonb_array_length(p_event->'parentEventIds')>1000
     OR jsonb_array_length(p_event->'eventRoleIds')>1000
     OR length(p_event->>'title') NOT BETWEEN 1 AND 500
     OR (p_event->>'startTime')::timestamptz >= (p_event->>'endTime')::timestamptz
     OR COALESCE((p_event->>'maxParticipants')::bigint,0)<0 THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid event aggregate';
  END IF;

  SELECT COALESCE(array_agg(value::bigint ORDER BY value::bigint),'{}')
    INTO v_parent_ids FROM jsonb_array_elements_text(p_event->'parentEventIds');
  SELECT COALESCE(array_agg(value::bigint ORDER BY value::bigint),'{}')
    INTO v_role_ids FROM jsonb_array_elements_text(p_event->'eventRoleIds');
  v_requested:=jsonb_build_object(
    'id',v_event_id,'title',p_event->>'title',
    'startTime',(p_event->>'startTime')::timestamptz,
    'endTime',(p_event->>'endTime')::timestamptz,
    'maxParticipants',(p_event->>'maxParticipants')::bigint,
    'description',p_event->>'description',
    'placeId',(p_event->>'placeId')::bigint,
    'splitForMenWomen',(p_event->>'splitForMenWomen')::boolean,
    'isGroupEvent',(p_event->>'isGroupEvent')::boolean,
    'isHidden',(p_event->>'isHidden')::boolean,'type',p_event->>'type',
    'data',p_event->'data','order',(p_event->>'order')::bigint,
    'parentEventIds',to_jsonb(v_parent_ids),'eventRoleIds',to_jsonb(v_role_ids));

  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'occasion',p_occasion,'expectedVersion',p_expected_version,'event',p_event)::text,
    'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,'event.save',
    p_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  PERFORM 1 FROM public.places WHERE id=(p_event->>'placeId')::bigint AND occasion=p_occasion FOR KEY SHARE;
  PERFORM 1 FROM public.role_info WHERE id=ANY(v_role_ids) AND occasion=p_occasion ORDER BY id FOR KEY SHARE;
  PERFORM 1 FROM public.events WHERE id=ANY(v_parent_ids||ARRAY[v_event_id]) AND occasion=p_occasion ORDER BY id FOR UPDATE;

  IF v_event_id IS NOT NULL THEN
    PERFORM 1 FROM public.events e WHERE e.id=v_event_id AND e.occasion=p_occasion
      FOR UPDATE;
    IF NOT FOUND THEN
      v_response:=jsonb_build_object('status','rejected','code',404,
        'data',jsonb_build_object('eventId',v_event_id),
        'mutation',jsonb_build_object('commandId',p_command_id,'receiptId',p_command_id,
          'commitId',NULL,'replayed',false,'occurredAt',clock_timestamp()),
        'sync',jsonb_build_object('replacements','[]'::jsonb));
      RETURN public.finish_client_mutation_v1(p_command_id,v_response,NULL);
    END IF;
    INSERT INTO public.client_aggregate_versions
      (aggregate_type,scope_type,scope_id,aggregate_id,version)
    VALUES ('event','occasion',p_occasion,v_event_id::text,0)
    ON CONFLICT DO NOTHING;
    SELECT version INTO v_version FROM public.client_aggregate_versions
      WHERE aggregate_type='event' AND scope_type='occasion'
        AND scope_id=p_occasion AND aggregate_id=v_event_id::text FOR UPDATE;
    v_current:=public.get_event_command_data_v1(v_event_id);
    IF p_expected_version IS DISTINCT FROM v_version THEN
      v_response:=jsonb_build_object('status','conflict','code',409,
        'data',jsonb_build_object('version',v_version,'event',v_current),
        'mutation',jsonb_build_object('commandId',p_command_id,'receiptId',p_command_id,
          'commitId',NULL,'replayed',false,'occurredAt',clock_timestamp()),
        'sync',jsonb_build_object('replacements','[]'::jsonb));
      RETURN public.finish_client_mutation_v1(p_command_id,v_response,NULL);
    END IF;
    v_changed:=v_current IS DISTINCT FROM v_requested;
  ELSIF p_expected_version IS NOT NULL THEN
    RAISE invalid_parameter_value USING MESSAGE='new event must not have an expected version';
  END IF;

  IF cardinality(v_parent_ids)<>cardinality(ARRAY(SELECT DISTINCT unnest(v_parent_ids)))
     OR cardinality(v_role_ids)<>cardinality(ARRAY(SELECT DISTINCT unnest(v_role_ids)))
     OR (v_event_id IS NOT NULL AND v_event_id=ANY(v_parent_ids))
     OR EXISTS (
       SELECT 1
       FROM unnest(v_parent_ids) AS parent(parent_id)
       LEFT JOIN public.events e
         ON e.id=parent.parent_id AND e.occasion=p_occasion
       WHERE e.id IS NULL
     )
     OR EXISTS (
       SELECT 1
       FROM unnest(v_role_ids) AS requested_role(role_id)
       LEFT JOIN public.role_info r
         ON r.id=requested_role.role_id AND r.occasion=p_occasion
       WHERE r.id IS NULL
     )
     OR ((p_event->>'placeId') IS NOT NULL AND NOT EXISTS (
       SELECT 1 FROM public.places p WHERE p.id=(p_event->>'placeId')::bigint
         AND p.occasion=p_occasion)) THEN
    RAISE invalid_parameter_value USING MESSAGE='event aggregate contains cross-scope references';
  END IF;


  IF NOT v_changed THEN
    v_response:=jsonb_build_object('status','unchanged','code',200,
      'data',jsonb_build_object('version',v_version,'event',v_current),
      'mutation',jsonb_build_object('commandId',p_command_id,'receiptId',p_command_id,
        'commitId',NULL,'replayed',false,'occurredAt',clock_timestamp()),
      'sync',jsonb_build_object('replacements','[]'::jsonb));
    RETURN public.finish_client_mutation_v1(p_command_id,v_response,NULL);
  END IF;

  IF v_event_id IS NULL THEN
    INSERT INTO public.events(title,start_time,end_time,max_participants,description,
      place,split_for_men_women,is_group_event,is_hidden,occasion,type,data,"order")
    VALUES (p_event->>'title',(p_event->>'startTime')::timestamptz,
      (p_event->>'endTime')::timestamptz,(p_event->>'maxParticipants')::bigint,
      p_event->>'description',(p_event->>'placeId')::bigint,
      (p_event->>'splitForMenWomen')::boolean,(p_event->>'isGroupEvent')::boolean,
      (p_event->>'isHidden')::boolean,p_occasion,p_event->>'type',p_event->'data',
      (p_event->>'order')::bigint) RETURNING id INTO v_event_id;
    v_version:=1;
    INSERT INTO public.client_aggregate_versions
      (aggregate_type,scope_type,scope_id,aggregate_id,version)
    VALUES ('event','occasion',p_occasion,v_event_id::text,v_version);
  ELSE
    UPDATE public.events SET title=p_event->>'title',
      start_time=(p_event->>'startTime')::timestamptz,
      end_time=(p_event->>'endTime')::timestamptz,
      max_participants=(p_event->>'maxParticipants')::bigint,
      description=p_event->>'description',place=(p_event->>'placeId')::bigint,
      split_for_men_women=(p_event->>'splitForMenWomen')::boolean,
      is_group_event=(p_event->>'isGroupEvent')::boolean,
      is_hidden=(p_event->>'isHidden')::boolean,type=p_event->>'type',
      data=p_event->'data',"order"=(p_event->>'order')::bigint,updated_at=now()
    WHERE id=v_event_id;
    UPDATE public.client_aggregate_versions SET version=version+1,updated_at=clock_timestamp()
      WHERE aggregate_type='event' AND scope_type='occasion'
        AND scope_id=p_occasion AND aggregate_id=v_event_id::text
      RETURNING version INTO v_version;
  END IF;
  DELETE FROM public.event_groups WHERE event_child=v_event_id;
  INSERT INTO public.event_groups(event_parent,event_child)
    SELECT parent.parent_id,v_event_id
    FROM unnest(v_parent_ids) AS parent(parent_id);
  DELETE FROM public.event_roles WHERE event=v_event_id;
  INSERT INTO public.event_roles(event,role)
    SELECT v_event_id,requested_role.role_id
    FROM unnest(v_role_ids) AS requested_role(role_id);

  v_data:=jsonb_build_object('version',v_version,
    'event',public.get_event_command_data_v1(v_event_id));
  RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,
    'event.save','program',jsonb_build_array(jsonb_build_object(
      'entityType','event','entityId',v_event_id,
      'operation',CASE WHEN v_current IS NULL THEN 'insert' ELSE 'update' END,
      'safeLabel',left(p_event->>'title',240),
      'changedFields',jsonb_build_array('aggregate'))),
    CASE WHEN v_is_publishable THEN ARRAY['program_catalog'] ELSE '{}'::text[] END,
    '[]','[]',v_data);
END;
$function$
;

-- Source: database/functions/events/save_event_speakers_client_sync_v1.sql
CREATE OR REPLACE FUNCTION public.save_event_speakers_client_sync_v1(p_occasion bigint, p_event bigint, p_command_id uuid, p_expected_version bigint, p_speaker_ids bigint[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_actor uuid:=auth.uid(); v_version bigint; v_begin jsonb; v_hash text;
  v_current bigint[]; v_requested bigint[];
  v_publishable boolean; v_event_hidden boolean;
BEGIN
  IF v_actor IS NULL OR NOT public.can_write_schedule(p_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='occasion editor required'; END IF;
  SELECT COALESCE(array_agg(requested_speaker.speaker_id
      ORDER BY requested_speaker.speaker_id),'{}'::bigint[])
    INTO v_requested
    FROM unnest(COALESCE(p_speaker_ids,'{}'::bigint[]))
      AS requested_speaker(speaker_id);
  IF cardinality(v_requested)<>cardinality(ARRAY(SELECT DISTINCT unnest(v_requested)))
    OR cardinality(v_requested)>1000 OR EXISTS (
      SELECT 1
      FROM unnest(v_requested) AS requested_speaker(speaker_id)
      LEFT JOIN public.speakers s
        ON s.id=requested_speaker.speaker_id AND s.occasion=p_occasion
      WHERE s.id IS NULL) THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid event speakers'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object('occasion',p_occasion,
    'eventId',p_event,'expectedVersion',p_expected_version,
    'speakerIds',to_jsonb(v_requested))::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,'program.event_speakers.save',
    p_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  SELECT e.is_hidden,NOT o.is_hidden INTO v_event_hidden,v_publishable
    FROM public.events e JOIN public.occasions o ON o.id=e.occasion
    WHERE e.id=p_event AND e.occasion=p_occasion FOR UPDATE OF e;
  IF v_event_hidden IS NULL THEN RETURN public.complete_client_mutation_outcome_v1(
    p_command_id,'rejected',404,jsonb_build_object('version',0,'eventId',p_event,
      'speakerIds','[]'::jsonb)); END IF;
  INSERT INTO public.client_aggregate_versions
    (aggregate_type,scope_type,scope_id,aggregate_id,version)
  VALUES ('event','occasion',p_occasion,p_event::text,0) ON CONFLICT DO NOTHING;
  SELECT version INTO v_version FROM public.client_aggregate_versions
    WHERE aggregate_type='event' AND scope_type='occasion'
    AND scope_id=p_occasion AND aggregate_id=p_event::text FOR UPDATE;
  SELECT COALESCE(array_agg(es.speaker ORDER BY es.speaker),'{}') INTO v_current
    FROM public.event_speakers es WHERE es.event=p_event;
  IF p_expected_version IS DISTINCT FROM v_version THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'conflict',409,
      jsonb_build_object('version',v_version,'eventId',p_event,
        'speakerIds',to_jsonb(v_current))); END IF;
  IF v_current=v_requested THEN RETURN public.complete_client_mutation_outcome_v1(
    p_command_id,'unchanged',200,jsonb_build_object('version',v_version,
      'eventId',p_event,'speakerIds',to_jsonb(v_current))); END IF;
  DELETE FROM public.event_speakers WHERE event=p_event;
  INSERT INTO public.event_speakers(event,speaker)
    SELECT p_event,requested_speaker.speaker_id
    FROM unnest(v_requested) AS requested_speaker(speaker_id);
  UPDATE public.client_aggregate_versions SET version=version+1,
    updated_at=clock_timestamp() WHERE aggregate_type='event'
    AND scope_type='occasion' AND scope_id=p_occasion AND aggregate_id=p_event::text
    RETURNING version INTO v_version;
  RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,
    'program.event_speakers.save','program',jsonb_build_array(jsonb_build_object(
      'entityType','event_speakers','entityId',p_event,'operation','update',
      'safeLabel','Event speakers','changedFields',jsonb_build_array('speakerIds'))),
    CASE WHEN v_publishable AND NOT v_event_hidden THEN ARRAY['program_catalog']
      ELSE '{}'::text[] END,'[]','[]',jsonb_build_object('version',v_version,
      'eventId',p_event,'speakerIds',to_jsonb(v_requested)));
END; $function$
;

-- Source: database/functions/icons/save_icon_client_sync_v1.sql
-- Occasion-shaped released-client adapter; unit ownership is canonical.
CREATE OR REPLACE FUNCTION public.save_icon_client_sync_v1(p_occasion bigint,p_command_id uuid,p_icon jsonb) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE u bigint; old_receipt jsonb; old_hash text;
BEGIN
 SELECT unit INTO u FROM public.occasions WHERE id=p_occasion;
 IF u IS NULL THEN RAISE invalid_parameter_value USING MESSAGE='occasion unit required'; END IF;
 -- Preserve receipts produced by the former occasion-scoped command.
 IF EXISTS(SELECT 1 FROM public.client_mutation_receipts WHERE command_id=p_command_id
   AND command_name='map.icon.save') THEN
  IF auth.uid() IS NULL OR NOT public.can_write_unit_icons(u) THEN
   RAISE insufficient_privilege USING MESSAGE='unit editor required'; END IF;
  old_hash:=encode(extensions.digest(convert_to(jsonb_build_object('occasion',p_occasion,'icon',p_icon)::text,'UTF8'),'sha256'),'hex');
  old_receipt:=public.begin_client_mutation_v1(p_command_id,'map.icon.save',p_occasion,auth.uid(),old_hash);
  IF old_receipt->>'disposition'='replay' THEN RETURN old_receipt->'response'; END IF;
  RAISE serialization_failure USING MESSAGE='incomplete legacy icon intent';
 END IF;
 RETURN public.save_unit_icon_client_sync_v1(u,p_command_id,p_icon);
END $$;

-- Source: database/functions/information/save_information_client_sync_v1.sql
CREATE OR REPLACE FUNCTION public.save_information_client_sync_v1(p_occasion bigint, p_command_id uuid, p_expected_version bigint, p_information jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_actor uuid:=auth.uid(); v_id bigint; v_hidden_id bigint; v_old_hidden_id bigint;
  v_version bigint; v_begin jsonb; v_hash text; v_current jsonb;
  v_requested jsonb; v_entity jsonb; v_commit jsonb; v_public jsonb;
  v_response jsonb; v_is_publishable boolean; v_old_is_hidden boolean;
  v_new_is_hidden boolean; v_affects_public boolean;
BEGIN
  IF v_actor IS NULL OR NOT public.can_write_information(p_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='occasion editor required';
  END IF;
  SELECT NOT o.is_hidden INTO v_is_publishable FROM public.occasions o
    WHERE o.id=p_occasion;
  IF v_is_publishable IS NULL THEN
    RAISE invalid_parameter_value USING MESSAGE='occasion not found';
  END IF;
  PERFORM public.validate_information_content_internal_v1(p_information,false);
  v_id:=(p_information->>'id')::bigint;
  v_new_is_hidden:=(p_information->>'isHidden')::boolean;
  v_requested:=jsonb_build_object('id',v_id,'title',p_information->>'title',
    'description',p_information->>'description','type',p_information->>'type',
    'isHidden',v_new_is_hidden,'order',(p_information->>'order')::bigint,
    'data',p_information->'data','hiddenData',p_information->'hiddenData');
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'occasion',p_occasion,'expectedVersion',p_expected_version,
    'information',p_information)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,'content.information.save',
    p_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;

  IF v_id IS NOT NULL THEN
    PERFORM 1 FROM public.information i WHERE i.id=v_id AND i.occasion=p_occasion
      FOR UPDATE;
    IF NOT FOUND THEN
      RETURN public.complete_client_mutation_outcome_v1(p_command_id,
        'rejected',404,jsonb_build_object('version',0,'information',NULL));
    END IF;
    INSERT INTO public.client_aggregate_versions
      (aggregate_type,scope_type,scope_id,aggregate_id,version)
    VALUES ('information','occasion',p_occasion,v_id::text,0) ON CONFLICT DO NOTHING;
    SELECT version INTO v_version FROM public.client_aggregate_versions
      WHERE aggregate_type='information' AND scope_type='occasion'
      AND scope_id=p_occasion AND aggregate_id=v_id::text FOR UPDATE;
    SELECT jsonb_build_object('id',i.id,'title',i.title,'description',i.description,
      'type',i.type,'isHidden',i.is_hidden,'order',i."order",'data',i.data,
      'hiddenData',ih.data),i.is_hidden,i.information_hidden
      INTO v_current,v_old_is_hidden,v_old_hidden_id
    FROM public.information i LEFT JOIN public.information_hidden ih
      ON ih.id=i.information_hidden WHERE i.id=v_id;
    IF p_expected_version IS DISTINCT FROM v_version THEN
      RETURN public.complete_client_mutation_outcome_v1(p_command_id,
        'conflict',409,jsonb_build_object('version',v_version,'information',
          public.get_information_command_data_v1(v_id)));
    END IF;
  ELSIF p_expected_version IS NOT NULL THEN
    RAISE invalid_parameter_value USING MESSAGE='new information must not have expected version';
  END IF;

  IF v_current IS NOT DISTINCT FROM v_requested THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,
      'unchanged',200,jsonb_build_object('version',v_version,'information',
        public.get_information_command_data_v1(v_id)));
  END IF;

  IF p_information->>'type'='game' THEN
    IF v_old_hidden_id IS NULL THEN
      INSERT INTO public.information_hidden(data,occasion)
      VALUES (p_information->'hiddenData',p_occasion) RETURNING id INTO v_hidden_id;
    ELSE
      UPDATE public.information_hidden SET data=p_information->'hiddenData'
      WHERE id=v_old_hidden_id AND occasion=p_occasion RETURNING id INTO v_hidden_id;
      IF v_hidden_id IS NULL THEN
        RAISE invalid_parameter_value USING MESSAGE='cross-scope hidden information';
      END IF;
    END IF;
  END IF;
  IF v_id IS NULL THEN
    INSERT INTO public.information(title,description,type,is_hidden,"order",data,
      information_hidden,occasion)
    VALUES (p_information->>'title',p_information->>'description',
      p_information->>'type',v_new_is_hidden,(p_information->>'order')::bigint,
      p_information->'data',v_hidden_id,p_occasion) RETURNING id INTO v_id;
    v_version:=1;
    INSERT INTO public.client_aggregate_versions
      (aggregate_type,scope_type,scope_id,aggregate_id,version)
    VALUES ('information','occasion',p_occasion,v_id::text,v_version);
  ELSE
    UPDATE public.information SET title=p_information->>'title',
      description=p_information->>'description',type=p_information->>'type',
      is_hidden=v_new_is_hidden,"order"=(p_information->>'order')::bigint,
      data=p_information->'data',information_hidden=v_hidden_id,
      updated_at=clock_timestamp() WHERE id=v_id;
    UPDATE public.client_aggregate_versions SET version=version+1,
      updated_at=clock_timestamp() WHERE aggregate_type='information'
      AND scope_type='occasion' AND scope_id=p_occasion AND aggregate_id=v_id::text
      RETURNING version INTO v_version;
    IF v_old_hidden_id IS NOT NULL AND v_hidden_id IS NULL THEN
      DELETE FROM public.information_hidden WHERE id=v_old_hidden_id
        AND occasion=p_occasion;
    END IF;
  END IF;
  v_entity:=public.get_information_command_data_v1(v_id)||
    jsonb_build_object('aggregate_version',v_version);
  v_affects_public:=NOT COALESCE(v_old_is_hidden,true) OR NOT v_new_is_hidden;
  RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,
    'content.information.save','content',jsonb_build_array(jsonb_build_object(
      'entityType','information','entityId',v_id,
      'operation',CASE WHEN v_current IS NULL THEN 'insert' ELSE 'update' END,
      'safeLabel',left(p_information->>'title',240),
      'changedFields',jsonb_build_array('aggregate'))),
    CASE WHEN v_is_publishable AND v_affects_public THEN ARRAY['content_catalog']
      ELSE '{}'::text[] END,'[]','[]',
    jsonb_build_object('version',v_version,'information',v_entity));
END; $function$
;

-- Source: database/functions/inventory/save_inventory_pool_client_sync_v1.sql
CREATE OR REPLACE FUNCTION public.save_inventory_pool_client_sync_v1(p_occasion bigint, p_command_id uuid, p_expected_version bigint, p_bundle jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path=public,extensions
AS $function$
DECLARE
  v_actor uuid:=auth.uid(); v_pool_id bigint:=(p_bundle#>>'{pool,id}')::bigint;
  v_version bigint; v_begin jsonb; v_hash text; v_result jsonb;
  v_commit jsonb; v_response jsonb; v_private_impacts jsonb;
  v_current_command_data jsonb; v_requested_command_data jsonb;
  v_product_ids bigint[]; v_product_id bigint;
  v_actor_private_revision bigint; v_actor_private_payload jsonb;
BEGIN
  IF v_actor IS NULL OR NOT public.can_write_orders(p_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='occasion order editor required';
  END IF;
  IF p_bundle IS NULL OR jsonb_typeof(p_bundle)<>'object'
    OR octet_length(p_bundle::text)>1048576
    OR EXISTS (SELECT 1 FROM jsonb_object_keys(p_bundle) key
      WHERE key NOT IN ('pool','contexts'))
    OR jsonb_typeof(p_bundle->'pool')<>'object'
    OR EXISTS (SELECT 1 FROM jsonb_object_keys(p_bundle->'pool') key
      WHERE key NOT IN ('id','title','sellable_capacity','occasion',
        'description','type','data'))
    OR (p_bundle ? 'contexts' AND p_bundle->'contexts'<>'null'::jsonb AND jsonb_typeof(p_bundle->'contexts')<>'array')
    OR jsonb_array_length(CASE WHEN jsonb_typeof(p_bundle->'contexts')='array' THEN p_bundle->'contexts' ELSE '[]'::jsonb END)>2000
    OR (p_bundle#>>'{pool,occasion}')::bigint IS DISTINCT FROM p_occasion
    OR (v_pool_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.inventory_pools ip
      WHERE ip.id=v_pool_id AND ip.occasion=p_occasion))
    OR EXISTS (SELECT 1 FROM jsonb_array_elements(CASE WHEN jsonb_typeof(p_bundle->'contexts')='array' THEN p_bundle->'contexts' ELSE '[]'::jsonb END) c
      WHERE jsonb_typeof(c)<>'object' OR EXISTS (
        SELECT 1 FROM jsonb_object_keys(c) key
        WHERE key NOT IN ('id','inventory_pool','block_date','title','order','data'))
      OR ((c->>'id') IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM public.inventory_contexts ic
        WHERE ic.id=(c->>'id')::bigint AND ic.inventory_pool=v_pool_id))) THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid or cross-scope inventory aggregate';
  END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object('occasion',p_occasion,
    'expectedVersion',p_expected_version,'bundle',p_bundle)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,'inventory.pool.save',
    p_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;

  IF v_pool_id IS NOT NULL THEN
    v_product_ids:=public.lock_pool_product_dependencies_internal_v1(v_pool_id);
    PERFORM 1 FROM public.inventory_pools ip WHERE ip.id=v_pool_id
      AND ip.occasion=p_occasion FOR UPDATE;
    INSERT INTO public.client_aggregate_versions
      (aggregate_type,scope_type,scope_id,aggregate_id,version)
    VALUES ('inventory_pool','occasion',p_occasion,v_pool_id::text,0)
    ON CONFLICT DO NOTHING;
    SELECT version INTO v_version FROM public.client_aggregate_versions
      WHERE aggregate_type='inventory_pool' AND scope_type='occasion'
        AND scope_id=p_occasion AND aggregate_id=v_pool_id::text FOR UPDATE;
    IF p_expected_version IS DISTINCT FROM v_version THEN
      v_response:=jsonb_build_object('status','conflict','code',409,
        'data',jsonb_build_object('version',v_version,
          'bundle',public.get_inventory_pool_bundle(v_pool_id)),
        'mutation',jsonb_build_object('commandId',p_command_id,'receiptId',p_command_id,
          'commitId',NULL,'replayed',false,'occurredAt',clock_timestamp()),
        'sync',jsonb_build_object('replacements','[]'::jsonb));
      RETURN public.finish_client_mutation_v1(p_command_id,v_response,NULL);
    END IF;

    IF NOT p_bundle ? 'contexts' OR p_bundle->'contexts'='null'::jsonb THEN
      p_bundle:=jsonb_set(p_bundle,'{contexts}',coalesce((SELECT jsonb_agg(jsonb_build_object(
        'id',ic.id,'inventory_pool',ic.inventory_pool,'block_date',ic.block_date,'title',ic.title,'order',ic."order",'data',ic.data)
        ORDER BY ic."order",ic.id) FROM public.inventory_contexts ic WHERE ic.inventory_pool=v_pool_id),'[]'));
    END IF;
    SELECT jsonb_build_object(
      'pool',jsonb_build_object('id',ip.id,'title',ip.title,
        'sellable_capacity',ip.sellable_capacity,'occasion',ip.occasion,
        'description',ip.description,'type',ip.type,'data',ip.data),
      'contexts',COALESCE((SELECT jsonb_agg(jsonb_build_object(
        'id',ic.id,'inventory_pool',ic.inventory_pool,
        'block_date',ic.block_date,'title',ic.title,'order',ic."order",
        'data',ic.data) ORDER BY ic."order",ic.id)
        FROM public.inventory_contexts ic
        WHERE ic.inventory_pool=ip.id),'[]'::jsonb))
      INTO v_current_command_data
    FROM public.inventory_pools ip WHERE ip.id=v_pool_id;
    SELECT jsonb_build_object(
      'pool',jsonb_build_object('id',(p_bundle#>>'{pool,id}')::bigint,
        'title',p_bundle#>>'{pool,title}',
        'sellable_capacity',(p_bundle#>>'{pool,sellable_capacity}')::bigint,
        'occasion',(p_bundle#>>'{pool,occasion}')::bigint,
        'description',p_bundle#>>'{pool,description}',
        'type',p_bundle#>>'{pool,type}','data',p_bundle#>'{pool,data}'),
      'contexts',COALESCE((SELECT jsonb_agg(jsonb_build_object(
        'id',(c->>'id')::bigint,'inventory_pool',v_pool_id,
        'block_date',(c->>'block_date')::date,'title',c->>'title',
        'order',(c->>'order')::bigint,'data',c->'data')
        ORDER BY (c->>'order')::bigint,(c->>'id')::bigint)
        FROM jsonb_array_elements(CASE WHEN jsonb_typeof(p_bundle->'contexts')='array' THEN p_bundle->'contexts' ELSE '[]'::jsonb END) c),'[]'::jsonb))
      INTO v_requested_command_data;
    IF v_current_command_data = v_requested_command_data THEN
      v_response:=jsonb_build_object('status','unchanged','code',200,
        'data',jsonb_build_object('version',v_version,
          'bundle',public.get_inventory_pool_bundle(v_pool_id)),
        'mutation',jsonb_build_object('commandId',p_command_id,
          'receiptId',p_command_id,'commitId',NULL,'replayed',false,
          'occurredAt',clock_timestamp()),
        'sync',jsonb_build_object('replacements','[]'::jsonb));
      RETURN public.finish_client_mutation_v1(p_command_id,v_response,NULL);
    END IF;
  ELSIF p_expected_version IS NOT NULL THEN
    RAISE invalid_parameter_value USING MESSAGE='new inventory pool must not have expected version';
  END IF;

  IF NOT p_bundle ? 'contexts' OR p_bundle->'contexts'='null'::jsonb THEN
    p_bundle:=jsonb_set(p_bundle,'{contexts}','[]'); END IF;
  v_result:=public.update_inventory_pool_bundle_internal_v1(p_bundle);
  FOREACH v_product_id IN ARRAY coalesce(v_product_ids,'{}'::bigint[]) LOOP
    PERFORM public.advance_ticketing_authoring_version_internal_v1('product',p_occasion,v_product_id);
  END LOOP;
  IF v_result ? 'code' AND COALESCE((v_result->>'code')::integer,500)<>200 THEN
    RAISE EXCEPTION 'inventory aggregate handler failed: %',v_result->>'message';
  END IF;
  v_pool_id:=(v_result#>>'{pool,id}')::bigint;
  IF v_pool_id IS NULL THEN RAISE EXCEPTION 'inventory handler returned no pool id'; END IF;
  IF v_version IS NULL THEN
    v_version:=1;
    INSERT INTO public.client_aggregate_versions
      (aggregate_type,scope_type,scope_id,aggregate_id,version)
    VALUES ('inventory_pool','occasion',p_occasion,v_pool_id::text,v_version);
  ELSE
    UPDATE public.client_aggregate_versions SET version=version+1,
      updated_at=clock_timestamp() WHERE aggregate_type='inventory_pool'
      AND scope_type='occasion' AND scope_id=p_occasion AND aggregate_id=v_pool_id::text
      RETURNING version INTO v_version;
  END IF;
  SELECT COALESCE(jsonb_agg(jsonb_build_object('component','private_inventory',
    'userId',ou."user")),'[]'::jsonb) INTO v_private_impacts
    FROM public.occasion_users ou WHERE ou.occasion=p_occasion;
  v_commit:=public.record_client_sync_commit_v1(p_occasion,'inventory.pool.save',
    'inventory',jsonb_build_array(jsonb_build_object('entityType','inventory_pool',
      'entityId',v_pool_id,'operation',CASE WHEN (p_bundle#>>'{pool,id}') IS NULL
        THEN 'insert' ELSE 'update' END,'safeLabel',left(v_result#>>'{pool,title}',240),
      'changedFields',jsonb_build_array('aggregate'))),'{}',v_private_impacts,
    '[]','user',NULL);
  SELECT s.source_revision INTO STRICT v_actor_private_revision
  FROM public.client_sync_private_scopes s
  WHERE s.component='private_inventory' AND s.occasion=p_occasion
    AND s.user_id=v_actor;
  v_actor_private_payload:=public.get_user_inventory_for_occasion_v1(p_occasion);
  v_result:=v_result||jsonb_build_object('aggregate_version',v_version);
  v_response:=jsonb_build_object('status','applied','code',200,
    'data',jsonb_build_object('version',v_version,'bundle',v_result),
    'mutation',jsonb_build_object('commandId',p_command_id,'receiptId',p_command_id,
      'commitId',v_commit->>'commitId','replayed',false,'occurredAt',v_commit->>'occurredAt'),
    'sync',jsonb_build_object('replacements',jsonb_build_array(
      jsonb_build_object('component','private_inventory',
        'revision',v_actor_private_revision,'payload',v_actor_private_payload))));
  RETURN public.finish_client_mutation_v1(p_command_id,v_response,
    (v_commit->>'commitId')::uuid);
END; $function$;

-- Source: database/functions/news/save_news_client_sync_v1.sql
CREATE OR REPLACE FUNCTION public.save_news_client_sync_v1(p_occasion bigint, p_command_id uuid, p_expected_version bigint, p_news jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_actor uuid:=auth.uid(); v_id bigint; v_version bigint; v_begin jsonb;
  v_hash text; v_current jsonb; v_entity jsonb; v_is_publishable boolean;
BEGIN
  IF v_actor IS NULL OR NOT public.can_write_news(p_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='occasion editor required';
  END IF;
  SELECT NOT o.is_hidden INTO v_is_publishable FROM public.occasions o
    WHERE o.id=p_occasion;
  IF v_is_publishable IS NULL THEN
    RAISE invalid_parameter_value USING MESSAGE='occasion not found';
  END IF;
  IF p_news IS NULL OR jsonb_typeof(p_news)<>'object'
    OR EXISTS (SELECT 1 FROM jsonb_object_keys(p_news) key
      WHERE key NOT IN ('id','message'))
    OR NOT (p_news ? 'message')
    OR octet_length(COALESCE(p_news->>'message','')) NOT BETWEEN 1 AND 524288 THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid news';
  END IF;
  v_id:=(p_news->>'id')::bigint;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'occasion',p_occasion,'expectedVersion',p_expected_version,
    'news',p_news)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,'content.news.save',
    p_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  IF v_id IS NOT NULL THEN
    SELECT jsonb_build_object('id',n.id,'message',n.message) INTO v_current
    FROM public.news n WHERE n.id=v_id AND n.occasion=p_occasion FOR UPDATE;
    IF v_current IS NULL THEN
      RETURN public.complete_client_mutation_outcome_v1(p_command_id,
        'rejected',404,jsonb_build_object('version',0,'news',NULL));
    END IF;
    INSERT INTO public.client_aggregate_versions
      (aggregate_type,scope_type,scope_id,aggregate_id,version)
    VALUES ('news','occasion',p_occasion,v_id::text,0) ON CONFLICT DO NOTHING;
    SELECT version INTO v_version FROM public.client_aggregate_versions
      WHERE aggregate_type='news' AND scope_type='occasion'
      AND scope_id=p_occasion AND aggregate_id=v_id::text FOR UPDATE;
    IF p_expected_version IS DISTINCT FROM v_version THEN
      SELECT to_jsonb(n)||jsonb_build_object('aggregate_version',v_version)
        INTO v_entity FROM public.news n WHERE n.id=v_id;
      RETURN public.complete_client_mutation_outcome_v1(p_command_id,
        'conflict',409,jsonb_build_object('version',v_version,'news',v_entity));
    END IF;
    IF v_current=jsonb_build_object('id',v_id,'message',p_news->>'message') THEN
      SELECT to_jsonb(n)||jsonb_build_object('aggregate_version',v_version)
        INTO v_entity FROM public.news n WHERE n.id=v_id;
      RETURN public.complete_client_mutation_outcome_v1(p_command_id,
        'unchanged',200,jsonb_build_object('version',v_version,'news',v_entity));
    END IF;
    UPDATE public.news SET message=p_news->>'message',updated_at=clock_timestamp()
      WHERE id=v_id;
    UPDATE public.client_aggregate_versions SET version=version+1,
      updated_at=clock_timestamp() WHERE aggregate_type='news'
      AND scope_type='occasion' AND scope_id=p_occasion AND aggregate_id=v_id::text
      RETURNING version INTO v_version;
  ELSE
    IF p_expected_version IS NOT NULL THEN
      RAISE invalid_parameter_value USING MESSAGE='new news must not have expected version';
    END IF;
    INSERT INTO public.news(message,created_by,occasion)
    VALUES (p_news->>'message',v_actor,p_occasion) RETURNING id INTO v_id;
    v_version:=1;
    INSERT INTO public.client_aggregate_versions
      (aggregate_type,scope_type,scope_id,aggregate_id,version)
    VALUES ('news','occasion',p_occasion,v_id::text,v_version);
  END IF;
  SELECT to_jsonb(n)||jsonb_build_object('aggregate_version',v_version)
    INTO v_entity FROM public.news n WHERE n.id=v_id;
  RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,
    'content.news.save','content',jsonb_build_array(jsonb_build_object(
      'entityType','news','entityId',v_id,
      'operation',CASE WHEN v_current IS NULL THEN 'insert' ELSE 'update' END,
      'safeLabel','News','changedFields',jsonb_build_array('message'))),
    CASE WHEN v_is_publishable THEN ARRAY['content_catalog'] ELSE '{}'::text[] END,
    '[]','[]',jsonb_build_object('version',v_version,'news',v_entity));
END; $function$
;

-- Source: database/functions/others/save_occasion_client_sync_v1.sql
-- Occasion settings are edited from the unit workspace. Keep the explicit
-- wrapper authorization aligned with both that UI contract and the trusted
-- update_occasion_internal_v1 implementation, which authorizes the target
-- unit editor before changing the aggregate.
CREATE OR REPLACE FUNCTION public.save_occasion_client_sync_v1(
  p_occasion bigint,
  p_command_id uuid,
  p_expected_version bigint,
  p_config jsonb
) RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
  v_config jsonb;
  v_data jsonb;
  v_enabled boolean;
  v_hidden boolean;
  v_unit bigint;
BEGIN
  SELECT
    COALESCE((o.data->>'client_sync_v1')::boolean, false),
    o.is_hidden,
    o.unit
  INTO v_enabled, v_hidden, v_unit
  FROM public.occasions o
  WHERE o.id = p_occasion;

  IF auth.uid() IS NULL OR NOT public.can_edit_occasion(p_occasion,(p_config->>'unit')::bigint) THEN
    RAISE insufficient_privilege USING MESSAGE = 'occasion editor required';
  END IF;

  IF v_enabled
    AND NOT v_hidden
    AND COALESCE((p_config->>'is_hidden')::boolean, false)
  THEN
    RAISE object_not_in_prerequisite_state
      USING MESSAGE = 'disable client_sync_v1 before hiding occasion';
  END IF;

  -- A layout-only command must not manufacture data/features or run general settings effects.
  IF p_config ? 'ticket_layout_change' AND p_config - ARRAY['id','ticket_layout_change']='{}'::jsonb THEN
    IF NOT public.can_edit_ticket_layout(p_occasion) THEN
      RAISE insufficient_privilege USING MESSAGE='unit editor required';
    END IF;
    RETURN public.save_occasion_domain_command_internal_v1(
      p_occasion,p_command_id,p_expected_version,p_config);
  END IF;

  v_data := CASE
    WHEN jsonb_typeof(p_config->'data') = 'object' THEN p_config->'data'
    ELSE '{}'::jsonb
  END;
  v_config := jsonb_set(
    p_config,
    '{data}',
    jsonb_set(
      v_data,
      '{client_sync_v1}',
      to_jsonb(COALESCE(v_enabled, false)),
      true
    ),
    true
  );

  RETURN public.save_occasion_domain_command_internal_v1(
    p_occasion,
    p_command_id,
    p_expected_version,
    v_config
  );
END;
$$;

-- Source: database/functions/others/save_occasion_domain_command_internal_v1.sql
-- The public save wrapper and the settings UI allow unit editors. The renamed
-- canonical domain command retained its older occasion-only guard, so it must
-- accept the same role before it reaches update_occasion_internal_v1.
CREATE OR REPLACE FUNCTION public.save_occasion_domain_command_internal_v1(
  p_occasion bigint,
  p_command_id uuid,
  p_expected_version bigint,
  p_config jsonb
) RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_version bigint;
  v_begin jsonb;
  v_hash text;
  v_entity jsonb;
  v_old_hidden boolean;
  v_new_hidden boolean;
  v_old_unit bigint;
  v_new_unit bigint;
  v_features jsonb;
  v_fanout_units bigint[] := '{}';
BEGIN
  SELECT o.unit INTO v_old_unit
  FROM public.occasions o
  WHERE o.id = p_occasion;

  IF v_actor IS NULL OR NOT public.can_edit_occasion(p_occasion,(p_config->>'unit')::bigint) THEN
    RAISE insufficient_privilege USING MESSAGE = 'occasion editor required';
  END IF;

  IF p_config IS NULL OR jsonb_typeof(p_config) <> 'object'
    OR octet_length(p_config::text) > 1048576
    OR (p_config->>'id')::bigint IS DISTINCT FROM p_occasion
    OR EXISTS (
      SELECT 1
      FROM jsonb_object_keys(p_config) key
      WHERE key NOT IN (
        'id', 'start_time', 'end_time', 'is_open', 'is_hidden', 'is_promoted',
        'link', 'title', 'description', 'data', 'services', 'organization',
        'unit', 'features', 'form_link', 'has_orders', 'stats', 'ticket_layout_change'
      )
    )
  THEN
    RAISE invalid_parameter_value USING MESSAGE = 'invalid occasion aggregate';
  END IF;

  v_hash := encode(extensions.digest(convert_to(jsonb_build_object(
    'occasion', p_occasion,
    'expectedVersion', p_expected_version,
    'config', p_config
  )::text, 'UTF8'), 'sha256'), 'hex');
  v_begin := public.begin_client_mutation_v1(
    p_command_id,
    'occasion.config.save',
    p_occasion,
    v_actor,
    v_hash
  );
  IF v_begin->>'disposition' = 'replay' THEN
    RETURN v_begin->'response';
  END IF;

  IF NOT (p_config ? 'ticket_layout_change' AND p_config-ARRAY['id','ticket_layout_change']='{}'::jsonb) THEN
    PERFORM 1 FROM public.forms WHERE occasion=p_occasion ORDER BY id FOR UPDATE;
  END IF;

  SELECT o.is_hidden, o.unit INTO v_old_hidden, v_old_unit
  FROM public.occasions o
  WHERE o.id = p_occasion
  FOR UPDATE;
  IF NOT FOUND THEN
    RETURN public.complete_client_mutation_outcome_v1(
      p_command_id,
      'rejected',
      404,
      jsonb_build_object('version', 0, 'occasion', NULL)
    );
  END IF;

  INSERT INTO public.client_aggregate_versions(
    aggregate_type, scope_type, scope_id, aggregate_id, version
  ) VALUES ('occasion', 'occasion', p_occasion, p_occasion::text, 0)
  ON CONFLICT DO NOTHING;
  SELECT version INTO v_version
  FROM public.client_aggregate_versions
  WHERE aggregate_type = 'occasion'
    AND scope_type = 'occasion'
    AND scope_id = p_occasion
    AND aggregate_id = p_occasion::text
  FOR UPDATE;
  IF p_expected_version IS DISTINCT FROM v_version THEN
    SELECT to_jsonb(o) || jsonb_build_object('aggregate_version', v_version)
    INTO v_entity
    FROM public.occasions o
    WHERE o.id = p_occasion;
    RETURN public.complete_client_mutation_outcome_v1(
      p_command_id,
      'conflict',
      409,
      jsonb_build_object('version', v_version, 'occasion', v_entity)
    );
  END IF;

  IF p_config ? 'ticket_layout_change' AND p_config - ARRAY['id','ticket_layout_change']='{}'::jsonb THEN
    IF NOT public.can_edit_ticket_layout(p_occasion) THEN
      RAISE insufficient_privilege USING MESSAGE='unit editor required';
    END IF;
    SELECT features INTO v_features FROM public.occasions WHERE id=p_occasion;
    v_features:=public.merge_ticket_layout_features(v_features,v_features,p_config->'ticket_layout_change');
    v_features:=public.merge_ticket_appearance_internal_v1(p_occasion,v_features,p_config#>'{ticket_layout_change,appearance}');
    PERFORM public.validate_ticket_layout_references(p_occasion,f->'layout')
      FROM jsonb_array_elements(v_features) f WHERE f->>'code'='ticket' AND f ? 'layout';
    UPDATE public.occasions SET features=v_features,updated_at=clock_timestamp() WHERE id=p_occasion;
  ELSE
    PERFORM public.update_occasion_internal_v1(p_config);
  END IF;
  UPDATE public.client_aggregate_versions
  SET version = version + 1, updated_at = clock_timestamp()
  WHERE aggregate_type = 'occasion'
    AND scope_type = 'occasion'
    AND scope_id = p_occasion
    AND aggregate_id = p_occasion::text
  RETURNING version INTO v_version;
  SELECT to_jsonb(o) || jsonb_build_object('aggregate_version', v_version)
  INTO v_entity
  FROM public.occasions o
  WHERE o.id = p_occasion;

  v_new_hidden := (v_entity->>'is_hidden')::boolean;
  v_new_unit := (v_entity->>'unit')::bigint;
  IF NOT v_old_hidden THEN
    v_fanout_units := array_append(v_fanout_units, v_old_unit);
  END IF;
  IF NOT v_new_hidden AND v_new_unit IS DISTINCT FROM v_old_unit THEN
    v_fanout_units := array_append(v_fanout_units, v_new_unit);
  ELSIF NOT v_new_hidden AND v_old_hidden THEN
    v_fanout_units := array_append(v_fanout_units, v_new_unit);
  END IF;

  RETURN public.complete_client_mutation_applied_v1(
    p_command_id,
    p_occasion,
    'occasion.config.save',
    'configuration',
    jsonb_build_array(jsonb_build_object(
      'entityType', 'occasion',
      'entityId', p_occasion,
      'operation', 'update',
      'safeLabel', left(v_entity->>'title', 240),
      'changedFields', jsonb_build_array('configuration')
    )),
    CASE WHEN v_old_hidden AND NOT v_new_hidden THEN ARRAY[
      'occasion_config', 'program_catalog', 'map_catalog', 'content_catalog',
      'live_public'
    ] ELSE ARRAY['occasion_config'] END,
    '[]',
    '[]',
    jsonb_build_object('version', v_version, 'occasion', v_entity),
    CASE WHEN NOT v_new_hidden THEN ARRAY['occasion_config'] ELSE '{}'::text[] END,
    '[]',
    'user',
    NULL,
    '[]',
    v_fanout_units
  );
END;
$$;

-- Source: database/functions/occasion_setup/drafts.sql
CREATE OR REPLACE FUNCTION public.save_occasion_setup_draft(p_id uuid, p_expected_revision bigint, p_data jsonb, p_step integer)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions AS $$
DECLARE d public.occasion_setup_drafts;
BEGIN
  SELECT * INTO d FROM public.occasion_setup_drafts WHERE id = p_id FOR UPDATE;
  IF NOT FOUND OR auth.uid() IS NULL OR NOT public.can_create_occasion(d.unit) THEN
    RAISE EXCEPTION 'Draft access denied' USING ERRCODE = '42501';
  END IF;
  IF d.data ? 'finalizedOccasion' THEN RAISE invalid_parameter_value USING MESSAGE='Draft already finalized'; END IF;
  p_data := p_data - 'finalizedOccasion' - 'finalizeResponse';
  IF p_data IS NULL OR jsonb_typeof(p_data) <> 'object' OR octet_length(p_data::text) > 262144 OR p_step IS NULL OR p_step NOT BETWEEN 0 AND 6 THEN
    RAISE EXCEPTION 'Invalid draft' USING ERRCODE = '22023'; END IF;
  IF d.data ? 'copy_locale' THEN p_data := jsonb_set(p_data,'{copy_locale}',d.data->'copy_locale'); END IF;
  IF p_data ? 'copy_locale' AND p_data->>'sourceId' IS NOT NULL
     AND coalesce((p_data->>'copy_title_edited')::boolean,false)=false AND coalesce(p_data->>'title','')='' THEN
    IF NOT public.can_copy_occasion_source((p_data->>'sourceId')::bigint) OR NOT EXISTS(SELECT 1 FROM public.occasions WHERE id=(p_data->>'sourceId')::bigint AND organization=d.organization) THEN
      RAISE insufficient_privilege USING MESSAGE='Copy source denied'; END IF;
    IF d.revision=p_expected_revision+1 AND d.data->>'sourceId'=p_data->>'sourceId' THEN
      p_data := jsonb_set(p_data,'{title}',d.data->'title');
    ELSE
      p_data := jsonb_set(p_data,'{title}',to_jsonb(public.copy_occasion_title_internal(
        (SELECT title FROM public.occasions WHERE id=(p_data->>'sourceId')::bigint),p_data->>'copy_locale')));
    END IF;
  END IF;
  IF d.revision = p_expected_revision + 1 AND d.data = p_data AND d.current_step = p_step THEN RETURN to_jsonb(d); END IF;
  IF d.revision IS DISTINCT FROM p_expected_revision THEN
    RAISE EXCEPTION 'Draft changed in another session' USING ERRCODE = '40001'; END IF;
  PERFORM public.admit_occasion_draft_v1(auth.uid(),d.unit,d.organization,octet_length(p_data::text),false,false);
  UPDATE public.occasion_setup_drafts SET data = p_data, current_step = p_step,
    revision = revision + 1, updated_at = now() WHERE id = p_id RETURNING * INTO d;
  RETURN to_jsonb(d);
END $$;

-- Source: database/functions/users/save_occasion_user_for_edit.sql
-- Released grid facade. Baseline is read under the membership lock.
CREATE OR REPLACE FUNCTION public.save_occasion_user_for_edit(input_data jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE oc bigint:=(input_data->>'occasion')::bigint; usr uuid:=(input_data->>'user')::uuid; ver bigint; r jsonb;
BEGIN
 IF auth.uid() IS NULL OR NOT(public.can_manage_occasion_participants(oc)) THEN RETURN jsonb_build_object('code',403); END IF;
 PERFORM 1 FROM public.user_info WHERE id=usr FOR UPDATE;
 PERFORM 1 FROM public.occasion_users WHERE occasion=oc AND "user"=usr FOR UPDATE;
 IF NOT FOUND THEN RETURN jsonb_build_object('code',404); END IF;
 SELECT coalesce(v.version,0) INTO ver FROM (SELECT 1) seed LEFT JOIN public.client_aggregate_versions v
 ON v.aggregate_type='occasion_user' AND v.scope_type='occasion' AND v.scope_id=oc AND v.aggregate_id=usr::text;
 input_data:=jsonb_set(input_data,'{data}',CASE WHEN jsonb_typeof(input_data->'data')='object' THEN (input_data->'data')-'is_invited' ELSE '{}' END);
 r:=public.save_profile_client_sync_v1(oc,usr,extensions.gen_random_uuid(),ver,input_data);
 RETURN jsonb_build_object('code',r->'code','message',r#>'{data,message}');
END $$;

-- Source: database/functions/users/save_occasion_user_for_edit.sql
CREATE OR REPLACE FUNCTION public.save_occasion_user_for_edit_internal_v1(input_data jsonb)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
    v_occasion bigint := (input_data->>'occasion')::bigint;
    v_user uuid := (input_data->>'user')::uuid;
    v_unit bigint;
    v_data jsonb := CASE WHEN jsonb_typeof(input_data->'data') = 'object'
                         THEN input_data->'data' ELSE '{}'::jsonb END;
    v_services jsonb := CASE WHEN jsonb_typeof(input_data->'services') = 'object'
                             THEN input_data->'services' ELSE '{}'::jsonb END;
    v_catalog jsonb;
    v_existing_services jsonb;
    v_code text;
    v_global_before jsonb;
BEGIN
    SELECT o.unit,
           CASE WHEN jsonb_typeof(o.services) = 'object'
                THEN o.services ELSE '{}'::jsonb END
      INTO v_unit, v_catalog
      FROM public.occasions o
     WHERE o.id = v_occasion;

    IF v_unit IS NULL THEN
        RETURN jsonb_build_object('code', 404, 'message', 'Occasion not found');
    END IF;

    -- Keep the write boundary at occasion management level. In particular,
    -- a unit editor must not gain the ability to assign manager/editor flags
    -- through this SECURITY DEFINER function.
    IF NOT public.can_manage_occasion_participants(v_occasion) THEN
        RETURN jsonb_build_object('code', 403, 'message', 'Not authorized to update occasion users');
    END IF;

    SELECT CASE WHEN jsonb_typeof(ou.services) = 'object'
                THEN ou.services ELSE '{}'::jsonb END
      INTO v_existing_services
      FROM public.occasion_users ou
     WHERE ou.occasion = v_occasion AND ou."user" = v_user;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('code', 404, 'message', 'Occasion user not found');
    END IF;

    -- Every assigned accommodation code must still exist in this occasion's
    -- catalog. This keeps the grid select and persisted service data aligned.
    FOR v_code IN
        SELECT key FROM jsonb_each(
            CASE WHEN jsonb_typeof(v_services->'accommodation') = 'object'
                 THEN v_services->'accommodation' ELSE '{}'::jsonb END
        )
    LOOP
        IF NOT EXISTS (
            SELECT 1
              FROM jsonb_array_elements(
                  CASE WHEN jsonb_typeof(v_catalog->'accommodation') = 'array'
                       THEN v_catalog->'accommodation' ELSE '[]'::jsonb END
              ) item
             WHERE item->>'code' = v_code
        ) AND NOT COALESCE((
            -- Historical assignments can outlive a removed catalog item.
            -- Preserve such a code on unrelated edits, but never allow a new
            -- unknown code to be introduced.
            jsonb_typeof(v_existing_services->'accommodation') = 'object'
            AND (v_existing_services->'accommodation') ? v_code
        ), false) THEN
            RETURN jsonb_build_object('code', 400, 'message', 'Unknown accommodation code: ' || v_code);
        END IF;
    END LOOP;

    SELECT to_jsonb(ui) INTO v_global_before FROM public.user_info ui WHERE id=v_user FOR UPDATE;
    UPDATE public.user_info
       SET data = COALESCE(user_info.data, '{}'::jsonb)
                  || public.get_user_profile_data_patch(v_data),
           name = COALESCE(v_data->>'name', user_info.name),
           surname = COALESCE(v_data->>'surname', user_info.surname),
           sex = COALESCE(v_data->>'sex', user_info.sex),
           phone = CASE
               WHEN v_data ? 'phone' THEN v_data->>'phone'
               ELSE user_info.phone
           END,
           birth_date = CASE
               WHEN v_data ? 'birthDate'
                   THEN NULLIF(v_data->>'birthDate', '')::date
               ELSE user_info.birth_date
           END
     WHERE id = v_user;

    PERFORM public.publish_user_profile_change_internal_v1(v_user,v_occasion,v_global_before);

    UPDATE public.occasion_users
       SET data = v_data,
           -- A grid may edit only one service family. Merge top-level service
           -- keys so changing accommodation never erases food (and vice versa).
           -- An explicitly supplied empty object still clears that family.
           services = COALESCE(occasion_users.services, '{}'::jsonb) || v_services,
           role = CASE WHEN input_data ? 'role' THEN (input_data->>'role')::int ELSE role END,
           is_editor = COALESCE((input_data->>'is_editor')::boolean, is_editor),
           is_editor_view = COALESCE((input_data->>'is_editor_view')::boolean, is_editor_view),
           is_editor_order = COALESCE((input_data->>'is_editor_order')::boolean, is_editor_order),
           is_editor_order_view = COALESCE((input_data->>'is_editor_order_view')::boolean, is_editor_order_view),
           is_cleaning_crew = COALESCE((input_data->>'is_cleaning_crew')::boolean, is_cleaning_crew),
           is_cleaning_blocked = COALESCE((input_data->>'is_cleaning_blocked')::boolean, is_cleaning_blocked),
           is_receptionist = COALESCE((input_data->>'is_receptionist')::boolean, is_receptionist),
           is_approver = COALESCE((input_data->>'is_approver')::boolean, is_approver),
           is_approved = COALESCE((input_data->>'is_approved')::boolean, is_approved),
           is_manager = COALESCE((input_data->>'is_manager')::boolean, is_manager)
     WHERE occasion = v_occasion AND "user" = v_user;

    RETURN jsonb_build_object('code', 200, 'message', 'Occasion user updated');
EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('code', 500, 'message', SQLERRM);
END;
$$;

-- Source: database/functions/groups/legacy_group_facades.sql
CREATE OR REPLACE FUNCTION public.save_place_location(p_place_id bigint,p_lat double precision,p_lng double precision)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE oc bigint; version bigint; result jsonb;
BEGIN
 IF auth.uid() IS NULL THEN RETURN jsonb_build_object('code',401); END IF;
 SELECT occasion INTO oc FROM public.places WHERE id=p_place_id;
 IF NOT FOUND THEN RETURN jsonb_build_object('code',404); END IF;
 IF NOT public.can_move_map_place(oc,p_place_id) THEN
  RETURN jsonb_build_object('code',403); END IF;
 PERFORM public.lock_group_occasion_internal_v1(oc);
 SELECT coalesce(v.version,0) INTO version FROM (SELECT 1) seed LEFT JOIN public.client_aggregate_versions v
 ON v.aggregate_type='place' AND v.scope_type='occasion' AND v.scope_id=oc AND v.aggregate_id=p_place_id::text;
 BEGIN
  result:=public.move_place_client_sync_v1(oc,p_place_id,extensions.gen_random_uuid(),version,p_lat,p_lng);
 EXCEPTION WHEN insufficient_privilege THEN RETURN jsonb_build_object('code',403); END;
 RETURN jsonb_build_object('code',result->'code','data',jsonb_build_object('id',p_place_id));
END $$;

-- Source: database/functions/users/save_profile_client_sync_v1.sql
-- Canonical profile command: receipt, version and companion effects have one owner.
CREATE OR REPLACE FUNCTION public.save_profile_client_sync_v1(p_occasion bigint, p_user uuid, p_command_id uuid, p_expected_version bigint, p_profile jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path=public,extensions
AS $function$
DECLARE v_actor uuid:=auth.uid(); v_version bigint; v_begin jsonb; v_hash text;
  v_before jsonb; v_after jsonb; v_result jsonb; v_replacements jsonb:='[]'::jsonb;
BEGIN
  IF v_actor IS NULL OR NOT public.can_manage_occasion_participants(p_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='occasion manager required'; END IF;
  IF p_profile IS NULL OR jsonb_typeof(p_profile)<>'object'
    OR octet_length(p_profile::text)>262144
    OR (p_profile->>'occasion')::bigint IS DISTINCT FROM p_occasion
    OR (p_profile->>'user')::uuid IS DISTINCT FROM p_user THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid occasion user profile'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object('occasion',p_occasion,
    'userId',p_user,'expectedVersion',p_expected_version,
    'profile',p_profile)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,'profile.user.save',
    p_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  PERFORM 1 FROM public.user_info WHERE id=p_user FOR UPDATE;
  PERFORM 1 FROM public.occasion_users ou WHERE ou.occasion=p_occasion
    AND ou."user"=p_user FOR UPDATE;
  IF NOT FOUND THEN RETURN public.complete_client_mutation_outcome_v1(p_command_id,
    'rejected',404,jsonb_build_object('version',0,'profile',NULL)); END IF;
  INSERT INTO public.client_aggregate_versions
    (aggregate_type,scope_type,scope_id,aggregate_id,version)
  VALUES ('occasion_user','occasion',p_occasion,p_user::text,0) ON CONFLICT DO NOTHING;
  SELECT version INTO v_version FROM public.client_aggregate_versions
    WHERE aggregate_type='occasion_user' AND scope_type='occasion'
    AND scope_id=p_occasion AND aggregate_id=p_user::text FOR UPDATE;
  v_before:=public.get_occasion_user_command_data_v1(p_occasion,p_user);
  IF p_expected_version IS DISTINCT FROM v_version THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'conflict',409,
      jsonb_build_object('version',v_version,'profile',v_before)); END IF;
  v_result:=public.save_occasion_user_for_edit_internal_v1(p_profile);
  IF COALESCE((v_result->>'code')::integer,500)<>200 THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'rejected',
      COALESCE((v_result->>'code')::integer,400),jsonb_build_object(
        'version',v_version,'profile',v_before,'message',v_result->>'message'));
  END IF;
  v_after:=public.get_occasion_user_command_data_v1(p_occasion,p_user);
  IF v_after IS NOT DISTINCT FROM v_before THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'unchanged',200,
      jsonb_build_object('version',v_version,'profile',v_after)); END IF;
  UPDATE public.client_aggregate_versions SET version=version+1,
    updated_at=clock_timestamp() WHERE aggregate_type='occasion_user'
    AND scope_type='occasion' AND scope_id=p_occasion AND aggregate_id=p_user::text
    RETURNING version INTO v_version;
  IF v_actor=p_user THEN v_replacements:=jsonb_build_array(jsonb_build_object(
    'component','private_profile','userId',p_user,
    'payload',public.get_private_profile_payload_v1(p_occasion,p_user))); END IF;
  -- Companion-owner invalidation is part of the mutation, never a replay follow-up.
  PERFORM public.impact_companion_owners_v1(p_occasion,ARRAY[p_user],'profile.companion_identity.changed');
  RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,
    'profile.user.save','profile',jsonb_build_array(jsonb_build_object(
      'entityType','occasion_user','entityId',p_user,'operation','update',
      'safeLabel','Occasion user','changedFields',jsonb_build_array('profile','rights','services'))),
    '{}',jsonb_build_array(jsonb_build_object('component','private_profile',
      'userId',p_user)),'[]',jsonb_build_object('version',v_version,'profile',v_after),
    '{}','[]','user',NULL,v_replacements);
END; $function$
;

-- Source: database/functions/inventory/save_resource_client_sync_v1.sql
CREATE OR REPLACE FUNCTION public.save_resource_client_sync_v1(p_occasion bigint, p_command_id uuid, p_expected_version bigint, p_resource jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path=public,extensions
AS $function$
DECLARE v_actor uuid:=auth.uid(); v_id bigint:=(p_resource->>'id')::bigint;
  v_pool bigint:=(p_resource->>'inventory_pool')::bigint; v_version bigint; v_origin_pool bigint;
  v_begin jsonb; v_hash text; v_current jsonb; v_entity jsonb;
  v_impacts jsonb; v_replacements jsonb:='[]'::jsonb;
BEGIN
  -- No booking rules and an empty rule document have the same domain meaning.
  IF p_resource->'booking_rules'='null'::jsonb THEN
    p_resource:=jsonb_set(p_resource,'{booking_rules}','{}'); END IF;
  IF v_actor IS NULL OR NOT public.can_write_orders(p_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='occasion order editor required'; END IF;
  IF p_resource IS NULL OR jsonb_typeof(p_resource)<>'object'
    OR octet_length(p_resource::text)>131072
    OR EXISTS (SELECT 1 FROM jsonb_object_keys(p_resource) key WHERE key NOT IN
      ('id','title','capacity','booking_rules','inventory_pool'))
    OR v_pool IS NULL OR length(btrim(COALESCE(p_resource->>'title',''))) NOT BETWEEN 1 AND 500
    OR coalesce((p_resource->>'capacity')::integer,-1) NOT BETWEEN 0 AND 1000000
    OR jsonb_typeof(COALESCE(p_resource->'booking_rules','{}'))<>'object' THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid resource aggregate'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object('occasion',p_occasion,
    'expectedVersion',p_expected_version,'resource',p_resource)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,'inventory.resource.save',
    p_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  IF NOT EXISTS(SELECT 1 FROM public.inventory_pools WHERE id=v_pool AND occasion=p_occasion) THEN
    RAISE invalid_parameter_value USING MESSAGE='inventory pool is outside occasion'; END IF;
  IF v_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.resources WHERE id=v_id AND occasion=p_occasion) THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'rejected',404,jsonb_build_object('version',0,'resource',NULL)); END IF;
  v_origin_pool:=public.lock_resource_pools_internal_v1(v_id,v_pool);
  PERFORM 1 FROM public.inventory_pools ip WHERE ip.id=v_pool
    AND ip.occasion=p_occasion FOR UPDATE;
  IF NOT FOUND THEN RAISE invalid_parameter_value USING MESSAGE='inventory pool is outside occasion'; END IF;
  IF v_id IS NOT NULL THEN
    SELECT to_jsonb(r) INTO v_current FROM public.resources r WHERE r.id=v_id
      AND r.occasion=p_occasion FOR UPDATE;
    IF v_current IS NULL THEN RETURN public.complete_client_mutation_outcome_v1(
      p_command_id,'rejected',404,jsonb_build_object('version',0,'resource',NULL)); END IF;
    INSERT INTO public.client_aggregate_versions
      (aggregate_type,scope_type,scope_id,aggregate_id,version)
    VALUES ('resource','occasion',p_occasion,v_id::text,0) ON CONFLICT DO NOTHING;
    SELECT version INTO v_version FROM public.client_aggregate_versions
      WHERE aggregate_type='resource' AND scope_type='occasion'
        AND scope_id=p_occasion AND aggregate_id=v_id::text FOR UPDATE;
    IF p_expected_version IS DISTINCT FROM v_version THEN
      RETURN public.complete_client_mutation_outcome_v1(p_command_id,'conflict',409,
        jsonb_build_object('version',v_version,'resource',v_current||
          jsonb_build_object('aggregate_version',v_version))); END IF;
    IF jsonb_build_object('title',v_current->>'title','capacity',(v_current->>'capacity')::integer,
      'booking_rules',COALESCE(v_current->'booking_rules','{}'),
      'inventory_pool',(v_current->>'inventory_pool')::bigint)=jsonb_build_object(
      'title',p_resource->>'title','capacity',(p_resource->>'capacity')::integer,
      'booking_rules',COALESCE(p_resource->'booking_rules','{}'),
      'inventory_pool',v_pool) THEN RETURN public.complete_client_mutation_outcome_v1(
        p_command_id,'unchanged',200,jsonb_build_object('version',v_version,
          'resource',v_current||jsonb_build_object('aggregate_version',v_version))); END IF;
    PERFORM 1 FROM eshop.spots WHERE resource=v_id OR resource_slot IN(SELECT id FROM public.resource_slots WHERE resource=v_id) ORDER BY id FOR UPDATE;
    IF (v_origin_pool IS DISTINCT FROM v_pool AND EXISTS(SELECT 1 FROM eshop.spots
      WHERE (resource=v_id OR resource_slot IN(SELECT id FROM public.resource_slots WHERE resource=v_id))
      AND (order_product_ticket IS NOT NULL OR (secret IS NOT NULL AND secret_expiration_time>clock_timestamp()))))
      OR EXISTS(SELECT 1 FROM eshop.spots WHERE (resource=v_id OR resource_slot IN(SELECT id FROM public.resource_slots WHERE resource=v_id))
        AND (order_product_ticket IS NOT NULL OR (secret IS NOT NULL AND secret_expiration_time>clock_timestamp()))
        GROUP BY inventory_context HAVING count(*)>(p_resource->>'capacity')::integer) THEN
      RETURN public.complete_client_mutation_outcome_v1(p_command_id,'rejected',409,
        jsonb_build_object('version',v_version,'resourceId',v_id,'message','resource capacity or move conflicts with reserved spots')); END IF;
    IF v_origin_pool IS DISTINCT FROM v_pool THEN
      DELETE FROM eshop.spots WHERE resource=v_id OR resource_slot IN(SELECT id FROM public.resource_slots WHERE resource=v_id);
    END IF;
    UPDATE public.resources SET title=p_resource->>'title',
      capacity=(p_resource->>'capacity')::integer,
      booking_rules=COALESCE(p_resource->'booking_rules','{}'),inventory_pool=v_pool,
      updated_at=clock_timestamp() WHERE id=v_id;
    UPDATE public.client_aggregate_versions SET version=version+1,
      updated_at=clock_timestamp() WHERE aggregate_type='resource'
      AND scope_type='occasion' AND scope_id=p_occasion AND aggregate_id=v_id::text
      RETURNING version INTO v_version;
  ELSE
    IF p_expected_version IS NOT NULL THEN
      RAISE invalid_parameter_value USING MESSAGE='new resource must not have expected version'; END IF;
    INSERT INTO public.resources(occasion,inventory_pool,title,capacity,booking_rules)
    VALUES (p_occasion,v_pool,p_resource->>'title',(p_resource->>'capacity')::integer,
      COALESCE(p_resource->'booking_rules','{}')) RETURNING id INTO v_id;
    v_version:=1;
    INSERT INTO public.client_aggregate_versions
      (aggregate_type,scope_type,scope_id,aggregate_id,version)
    VALUES ('resource','occasion',p_occasion,v_id::text,v_version);
  END IF;
  IF v_origin_pool IS NOT NULL AND v_origin_pool IS DISTINCT FROM v_pool THEN
    PERFORM public.adjust_spot_capacity_for_pool(v_origin_pool);
  END IF;
  PERFORM public.adjust_spot_capacity_for_pool(v_pool);
  PERFORM public.advance_ticketing_authoring_version_internal_v1('inventory_pool',p_occasion,v_pool);
  IF v_origin_pool IS NOT NULL AND v_origin_pool IS DISTINCT FROM v_pool THEN
    PERFORM public.advance_ticketing_authoring_version_internal_v1('inventory_pool',p_occasion,v_origin_pool);
  END IF;
  SELECT to_jsonb(r)||jsonb_build_object('aggregate_version',v_version)
    INTO v_entity FROM public.resources r WHERE r.id=v_id;
  SELECT COALESCE(jsonb_agg(jsonb_build_object('component','private_inventory',
    'userId',ou."user")),'[]'::jsonb) INTO v_impacts
    FROM public.occasion_users ou WHERE ou.occasion=p_occasion;
  IF EXISTS (SELECT 1 FROM public.occasion_users ou WHERE ou.occasion=p_occasion
    AND ou."user"=v_actor) THEN v_replacements:=jsonb_build_array(jsonb_build_object(
      'component','private_inventory','userId',v_actor,
      'payload',public.get_user_inventory_for_occasion_v1(p_occasion))); END IF;
  RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,
    'inventory.resource.save','inventory',jsonb_build_array(jsonb_build_object(
      'entityType','resource','entityId',v_id,
      'operation',CASE WHEN v_current IS NULL THEN 'insert' ELSE 'update' END,
      'safeLabel',left(p_resource->>'title',240),'changedFields',jsonb_build_array('aggregate'))),
    '{}',v_impacts,'[]',jsonb_build_object('version',v_version,'resource',v_entity),
    '{}','[]','user',NULL,v_replacements);
END; $function$;

-- Source: database/functions/speakers/save_speaker_client_sync_v1.sql
CREATE OR REPLACE FUNCTION public.save_speaker_client_sync_v1(p_occasion bigint, p_command_id uuid, p_expected_version bigint, p_speaker jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path = public, extensions
AS $function$
DECLARE
  v_actor uuid:=auth.uid(); v_id bigint; v_version bigint; v_begin jsonb;
  v_hash text; v_current jsonb; v_requested jsonb; v_entity jsonb;
  v_topic_ids bigint[]; v_old_hidden boolean; v_new_hidden boolean;
  v_publishable boolean; v_content_impact boolean; v_program_impact boolean;
BEGIN
  IF v_actor IS NULL OR NOT public.can_write_speakers(p_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='occasion editor required';
  END IF;
  SELECT NOT o.is_hidden INTO v_publishable FROM public.occasions o WHERE o.id=p_occasion;
  IF v_publishable IS NULL THEN RAISE invalid_parameter_value USING MESSAGE='occasion not found'; END IF;
  IF p_speaker IS NULL OR jsonb_typeof(p_speaker)<>'object'
    OR octet_length(p_speaker::text)>786432
    OR EXISTS (SELECT 1 FROM jsonb_object_keys(p_speaker) key WHERE key NOT IN
      ('id','title','subtitle','description','image','order','is_hidden','data','topics'))
    OR NOT (p_speaker ?& ARRAY['title','order','is_hidden','data','topics'])
    OR jsonb_typeof(p_speaker->'topics')<>'array'
    OR jsonb_array_length(p_speaker->'topics')>1000
    OR length(btrim(COALESCE(p_speaker->>'title',''))) NOT BETWEEN 1 AND 200
    OR octet_length(COALESCE(p_speaker->>'description',''))>524288
    OR octet_length(COALESCE((p_speaker->'data')::text,''))>131072 THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid speaker aggregate';
  END IF;
  SELECT COALESCE(array_agg(value::bigint ORDER BY value::bigint),'{}')
    INTO v_topic_ids FROM jsonb_array_elements_text(p_speaker->'topics');
  IF cardinality(v_topic_ids)<>cardinality(ARRAY(SELECT DISTINCT unnest(v_topic_ids)))
    OR EXISTS (
      SELECT 1
      FROM unnest(v_topic_ids) AS requested_topic(topic_id)
      LEFT JOIN public.speaker_topics t
        ON t.id=requested_topic.topic_id AND t.occasion=p_occasion
      WHERE t.id IS NULL
    ) THEN
    RAISE invalid_parameter_value USING MESSAGE='speaker contains invalid topics';
  END IF;
  v_id:=(p_speaker->>'id')::bigint;
  v_new_hidden:=(p_speaker->>'is_hidden')::boolean;
  v_requested:=jsonb_build_object('id',v_id,'title',p_speaker->>'title',
    'subtitle',p_speaker->>'subtitle','description',p_speaker->>'description',
    'image',p_speaker->>'image','order',(p_speaker->>'order')::bigint,
    'is_hidden',v_new_hidden,'data',p_speaker->'data','topics',to_jsonb(v_topic_ids));
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object('occasion',p_occasion,
    'expectedVersion',p_expected_version,'speaker',p_speaker)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,'content.speaker.save',
    p_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  IF v_id IS NOT NULL THEN
    PERFORM 1 FROM public.speakers s WHERE s.id=v_id AND s.occasion=p_occasion FOR UPDATE;
    IF NOT FOUND THEN RETURN public.complete_client_mutation_outcome_v1(p_command_id,
      'rejected',404,jsonb_build_object('version',0,'speaker',NULL)); END IF;
    INSERT INTO public.client_aggregate_versions
      (aggregate_type,scope_type,scope_id,aggregate_id,version)
    VALUES ('speaker','occasion',p_occasion,v_id::text,0) ON CONFLICT DO NOTHING;
    SELECT version INTO v_version FROM public.client_aggregate_versions
      WHERE aggregate_type='speaker' AND scope_type='occasion'
      AND scope_id=p_occasion AND aggregate_id=v_id::text FOR UPDATE;
    SELECT jsonb_build_object('id',s.id,'title',s.title,'subtitle',s.subtitle,
      'description',s.description,'image',s.image,'order',s."order",
      'is_hidden',s.is_hidden,'data',s.data,'topics',COALESCE((SELECT jsonb_agg(
        l.topic ORDER BY l.topic) FROM public.speaker_topic_links l
        WHERE l.speaker=s.id),'[]'::jsonb)),s.is_hidden
      INTO v_current,v_old_hidden FROM public.speakers s WHERE s.id=v_id;
    IF p_expected_version IS DISTINCT FROM v_version THEN
      RETURN public.complete_client_mutation_outcome_v1(p_command_id,'conflict',409,
        jsonb_build_object('version',v_version,'speaker',
          public.get_speaker_command_data_v1(v_id)||jsonb_build_object(
            'aggregate_version',v_version))); END IF;
  ELSIF p_expected_version IS NOT NULL THEN
    RAISE invalid_parameter_value USING MESSAGE='new speaker must not have expected version';
  END IF;
  IF v_current IS NOT DISTINCT FROM v_requested THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'unchanged',200,
      jsonb_build_object('version',v_version,'speaker',
        public.get_speaker_command_data_v1(v_id)||jsonb_build_object(
          'aggregate_version',v_version)));
  END IF;
  IF v_id IS NULL THEN
    INSERT INTO public.speakers(occasion,title,subtitle,description,image,"order",is_hidden,data)
    VALUES (p_occasion,p_speaker->>'title',p_speaker->>'subtitle',
      p_speaker->>'description',p_speaker->>'image',(p_speaker->>'order')::bigint,
      v_new_hidden,p_speaker->'data') RETURNING id INTO v_id;
    v_version:=1;
    INSERT INTO public.client_aggregate_versions
      (aggregate_type,scope_type,scope_id,aggregate_id,version)
    VALUES ('speaker','occasion',p_occasion,v_id::text,v_version);
  ELSE
    UPDATE public.speakers SET title=p_speaker->>'title',subtitle=p_speaker->>'subtitle',
      description=p_speaker->>'description',image=p_speaker->>'image',
      "order"=(p_speaker->>'order')::bigint,is_hidden=v_new_hidden,data=p_speaker->'data'
      WHERE id=v_id;
    UPDATE public.client_aggregate_versions SET version=version+1,
      updated_at=clock_timestamp() WHERE aggregate_type='speaker'
      AND scope_type='occasion' AND scope_id=p_occasion AND aggregate_id=v_id::text
      RETURNING version INTO v_version;
  END IF;
  DELETE FROM public.speaker_topic_links WHERE speaker=v_id;
  INSERT INTO public.speaker_topic_links(speaker,topic)
    SELECT v_id,requested_topic.topic_id
    FROM unnest(v_topic_ids) AS requested_topic(topic_id);
  v_entity:=public.get_speaker_command_data_v1(v_id)||
    jsonb_build_object('aggregate_version',v_version);
  v_program_impact:=v_old_hidden IS DISTINCT FROM v_new_hidden AND EXISTS (
    SELECT 1 FROM public.event_speakers es JOIN public.events e ON e.id=es.event
    WHERE es.speaker=v_id AND NOT e.is_hidden);
  v_content_impact:=NOT COALESCE(v_old_hidden,true) OR NOT v_new_hidden;
  RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,
    'content.speaker.save','content',jsonb_build_array(jsonb_build_object(
      'entityType','speaker','entityId',v_id,
      'operation',CASE WHEN v_current IS NULL THEN 'insert' ELSE 'update' END,
      'safeLabel',left(p_speaker->>'title',240),'changedFields',jsonb_build_array('aggregate'))),
    CASE WHEN v_publishable THEN CASE WHEN v_content_impact
      THEN ARRAY['content_catalog'] ELSE '{}'::text[] END||CASE WHEN v_program_impact
      THEN ARRAY['program_catalog'] ELSE '{}'::text[] END ELSE '{}'::text[] END,
    '[]','[]',jsonb_build_object('version',v_version,'speaker',v_entity));
END; $function$
;

-- Source: database/functions/speakers/save_speaker_topic_client_sync_v1.sql
CREATE OR REPLACE FUNCTION public.save_speaker_topic_client_sync_v1(p_occasion bigint, p_command_id uuid, p_expected_version bigint, p_topic jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path = public, extensions
AS $function$
DECLARE v_actor uuid:=auth.uid(); v_id bigint; v_version bigint; v_begin jsonb;
  v_hash text; v_current jsonb; v_entity jsonb; v_publishable boolean;
  v_old_hidden boolean; v_new_hidden boolean; v_content_impact boolean;
BEGIN
  IF v_actor IS NULL OR NOT public.can_write_speakers(p_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='occasion editor required'; END IF;
  SELECT NOT o.is_hidden INTO v_publishable FROM public.occasions o WHERE o.id=p_occasion;
  IF p_topic IS NULL OR jsonb_typeof(p_topic)<>'object'
    OR EXISTS (SELECT 1 FROM jsonb_object_keys(p_topic) key WHERE key NOT IN
      ('id','title','order','is_hidden')) OR NOT (p_topic ?& ARRAY['title','order','is_hidden'])
    OR length(btrim(COALESCE(p_topic->>'title',''))) NOT BETWEEN 1 AND 200 THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid speaker topic'; END IF;
  v_id:=(p_topic->>'id')::bigint; v_new_hidden:=(p_topic->>'is_hidden')::boolean;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object('occasion',p_occasion,
    'expectedVersion',p_expected_version,'topic',p_topic)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,'content.speaker_topic.save',
    p_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  IF v_id IS NOT NULL THEN
    SELECT to_jsonb(t),t.is_hidden INTO v_current,v_old_hidden FROM public.speaker_topics t
      WHERE t.id=v_id AND t.occasion=p_occasion FOR UPDATE;
    IF v_current IS NULL THEN RETURN public.complete_client_mutation_outcome_v1(p_command_id,
      'rejected',404,jsonb_build_object('version',0,'topic',NULL)); END IF;
    INSERT INTO public.client_aggregate_versions
      (aggregate_type,scope_type,scope_id,aggregate_id,version)
    VALUES ('speaker_topic','occasion',p_occasion,v_id::text,0) ON CONFLICT DO NOTHING;
    SELECT version INTO v_version FROM public.client_aggregate_versions
      WHERE aggregate_type='speaker_topic' AND scope_type='occasion'
      AND scope_id=p_occasion AND aggregate_id=v_id::text FOR UPDATE;
    IF p_expected_version IS DISTINCT FROM v_version THEN
      RETURN public.complete_client_mutation_outcome_v1(p_command_id,'conflict',409,
        jsonb_build_object('version',v_version,'topic',v_current||
          jsonb_build_object('aggregate_version',v_version))); END IF;
    IF jsonb_build_object('id',v_id,'occasion',p_occasion,'title',v_current->>'title',
      'order',(v_current->>'order')::bigint,'is_hidden',(v_current->>'is_hidden')::boolean)
      = jsonb_build_object('id',v_id,'occasion',p_occasion,'title',p_topic->>'title',
      'order',(p_topic->>'order')::bigint,'is_hidden',v_new_hidden) THEN
      RETURN public.complete_client_mutation_outcome_v1(p_command_id,'unchanged',200,
        jsonb_build_object('version',v_version,'topic',v_current||
          jsonb_build_object('aggregate_version',v_version))); END IF;
    UPDATE public.speaker_topics SET title=p_topic->>'title',
      "order"=(p_topic->>'order')::bigint,is_hidden=v_new_hidden,
      updated_at=clock_timestamp() WHERE id=v_id
      RETURNING to_jsonb(speaker_topics.*) INTO v_entity;
    UPDATE public.client_aggregate_versions SET version=version+1,
      updated_at=clock_timestamp() WHERE aggregate_type='speaker_topic'
      AND scope_type='occasion' AND scope_id=p_occasion AND aggregate_id=v_id::text
      RETURNING version INTO v_version;
  ELSE
    IF p_expected_version IS NOT NULL THEN
      RAISE invalid_parameter_value USING MESSAGE='new topic must not have expected version'; END IF;
    INSERT INTO public.speaker_topics(occasion,title,"order",is_hidden)
    VALUES (p_occasion,p_topic->>'title',(p_topic->>'order')::bigint,v_new_hidden)
    RETURNING id,to_jsonb(speaker_topics.*) INTO v_id,v_entity;
    v_version:=1;
    INSERT INTO public.client_aggregate_versions
      (aggregate_type,scope_type,scope_id,aggregate_id,version)
    VALUES ('speaker_topic','occasion',p_occasion,v_id::text,v_version);
  END IF;
  v_entity:=v_entity||jsonb_build_object('aggregate_version',v_version);
  v_content_impact:=NOT COALESCE(v_old_hidden,true) OR NOT v_new_hidden;
  RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,
    'content.speaker_topic.save','content',jsonb_build_array(jsonb_build_object(
      'entityType','speaker_topic','entityId',v_id,
      'operation',CASE WHEN v_current IS NULL THEN 'insert' ELSE 'update' END,
      'safeLabel',left(p_topic->>'title',240),'changedFields',jsonb_build_array('aggregate'))),
    CASE WHEN v_publishable AND v_content_impact THEN ARRAY['content_catalog'] ELSE '{}'::text[] END,
    '[]','[]',jsonb_build_object('version',v_version,'topic',v_entity));
END; $function$
;

-- Source: database/functions/units/save_unit_client_sync_v1.sql
CREATE OR REPLACE FUNCTION public.save_unit_client_sync_v1(p_unit bigint, p_command_id uuid, p_expected_version bigint, p_unit_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_actor uuid:=auth.uid(); v_begin jsonb; v_hash text; v_version bigint;
  v_before jsonb; v_after jsonb; v_commit public.client_commits%ROWTYPE;
BEGIN
  IF v_actor IS NULL OR NOT public.can_manage_unit_configuration(p_unit) THEN
    RAISE insufficient_privilege USING MESSAGE='unit manager required'; END IF;
  IF p_unit_data IS NULL OR jsonb_typeof(p_unit_data)<>'object'
    OR EXISTS (SELECT 1 FROM jsonb_object_keys(p_unit_data) key
      WHERE key NOT IN ('id','title','data'))
    OR (p_unit_data->>'id')::bigint IS DISTINCT FROM p_unit
    OR nullif(btrim(p_unit_data->>'title'),'') IS NULL
    OR length(p_unit_data->>'title')>30
    OR jsonb_typeof(COALESCE(p_unit_data->'data','{}'::jsonb))<>'object'
    OR octet_length(p_unit_data::text)>262144 THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid unit aggregate'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'unit',p_unit,'expectedVersion',p_expected_version,
    'data',p_unit_data)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_unit_client_mutation_v1(p_command_id,'unit.config.save',
    p_unit,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  SELECT jsonb_build_object('id',u.id,'title',u.title,'data',u.data)
    INTO v_before FROM public.units u WHERE u.id=p_unit FOR UPDATE;
  IF v_before IS NULL THEN RETURN public.complete_client_mutation_outcome_v1(
    p_command_id,'rejected',404,jsonb_build_object('version',0,'unit',NULL)); END IF;
  INSERT INTO public.client_aggregate_versions
    (aggregate_type,scope_type,scope_id,aggregate_id,version)
  VALUES ('unit','unit',p_unit,p_unit::text,0) ON CONFLICT DO NOTHING;
  SELECT version INTO v_version FROM public.client_aggregate_versions
    WHERE aggregate_type='unit' AND scope_type='unit'
      AND scope_id=p_unit AND aggregate_id=p_unit::text FOR UPDATE;
  IF p_expected_version IS DISTINCT FROM v_version THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'conflict',409,
      jsonb_build_object('version',v_version,'unit',v_before||
        jsonb_build_object('aggregate_version',v_version))); END IF;
  v_after:=jsonb_build_object('id',p_unit,'title',p_unit_data->>'title',
    'data',COALESCE(p_unit_data->'data','{}'::jsonb));
  IF v_before=v_after THEN RETURN public.complete_client_mutation_outcome_v1(
    p_command_id,'unchanged',200,jsonb_build_object('version',v_version,
      'unit',v_before||jsonb_build_object('aggregate_version',v_version))); END IF;
  PERFORM public.update_unit_internal_v1(
    p_unit,p_unit_data->>'title',COALESCE(p_unit_data->'data','{}'::jsonb));
  UPDATE public.client_aggregate_versions SET version=version+1,
    updated_at=clock_timestamp() WHERE aggregate_type='unit' AND scope_type='unit'
    AND scope_id=p_unit AND aggregate_id=p_unit::text RETURNING version INTO v_version;
  INSERT INTO public.client_commits
    (unit,actor_id,actor_display,actor_kind,source,change_class)
  SELECT p_unit,v_actor,nullif(concat_ws(' ',ui.name,ui.surname),''),'user',
    'unit.config.save','configuration' FROM public.user_info ui WHERE ui.id=v_actor
  RETURNING * INTO v_commit;
  INSERT INTO public.client_commit_items
    (commit_id,item_index,entity_type,entity_id,operation,safe_label,changed_fields)
  VALUES (v_commit.commit_id,0,'unit',p_unit::text,'update',
    left(p_unit_data->>'title',240),ARRAY['configuration']);
  PERFORM public.fanout_unit_catalog_v1(v_commit.commit_id,p_unit);
  RETURN public.finish_client_mutation_v1(p_command_id,jsonb_build_object(
    'status','applied','code',200,'data',jsonb_build_object('version',v_version,
      'unit',v_after||jsonb_build_object('aggregate_version',v_version)),
    'mutation',jsonb_build_object('commandId',p_command_id,'receiptId',p_command_id,
      'commitId',v_commit.commit_id,'replayed',false,'occurredAt',v_commit.occurred_at),
    'sync',jsonb_build_object('replacements','[]'::jsonb)),v_commit.commit_id);
END; $function$
;

-- Source: database/functions/icons/save_unit_icon_client_sync_v1.sql
CREATE OR REPLACE FUNCTION public.save_unit_icon_client_sync_v1(p_unit bigint, p_command_id uuid, p_icon jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path=public,extensions
AS $function$
DECLARE
  v_actor uuid:=auth.uid();  v_organization bigint; v_id bigint;
  v_begin jsonb; v_hash text; v_commit jsonb; v_icon jsonb; v_response jsonb;
BEGIN
  SELECT u.organization INTO v_organization FROM public.units u WHERE u.id=p_unit;
  IF v_actor IS NULL OR p_unit IS NULL OR NOT public.can_write_unit_icons(p_unit) THEN
    RAISE insufficient_privilege USING MESSAGE='unit editor required';
  END IF;
  IF p_icon IS NULL OR jsonb_typeof(p_icon)<>'object'
    OR EXISTS (SELECT 1 FROM jsonb_object_keys(p_icon) key WHERE key NOT IN ('link','svg'))
    OR NOT (p_icon ?& ARRAY['link','svg'])
    OR length(p_icon->>'link') NOT BETWEEN 1 AND 200
    OR octet_length(COALESCE(p_icon->>'svg','')) NOT BETWEEN 1 AND 51200 THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid icon';
  END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object('unit',p_unit,
    'icon',p_icon)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_unit_client_mutation_v1(p_command_id,'unit.icon.save',p_unit,
    v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  INSERT INTO public.icons(link,data,organization,unit,created_by)
  VALUES (p_icon->>'link',p_icon->>'svg',v_organization,p_unit,v_actor)
  RETURNING id INTO v_id;
  INSERT INTO public.client_aggregate_versions
    (aggregate_type,scope_type,scope_id,aggregate_id,version)
  VALUES ('icon','unit',p_unit,v_id::text,1);
  SELECT to_jsonb(i)||jsonb_build_object('aggregate_version',1)
    INTO v_icon FROM public.icons i WHERE i.id=v_id;
  v_response:=public.complete_unit_mutation_internal_v1(p_command_id,p_unit,'unit.icon.save','icon',v_id,'insert',jsonb_build_object('icon',v_icon));
  PERFORM public.fanout_unit_map_catalog_internal_v1((v_response#>>'{mutation,commitId}')::uuid,p_unit);
  RETURN v_response;
END; $function$

;

-- Source: database/functions/information/unit_information.sql
CREATE OR REPLACE FUNCTION public.save_unit_information_client_sync_v1(p_unit bigint,p_command_id uuid,p_expected_version bigint,p_information jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE actor uuid:=auth.uid(); ident bigint; ver bigint; before_row jsonb; after_row jsonb; begun jsonb; hash text;
BEGIN
 IF actor IS NULL OR NOT public.can_write_unit_information(p_unit) THEN RAISE insufficient_privilege USING MESSAGE='unit editor required'; END IF;
 PERFORM public.validate_information_content_internal_v1(p_information,true);
 ident:=(p_information->>'id')::bigint;
 hash:=encode(extensions.digest(convert_to(jsonb_build_object('unit',p_unit,'expectedVersion',p_expected_version,'information',p_information)::text,'UTF8'),'sha256'),'hex');
 begun:=public.begin_unit_client_mutation_v1(p_command_id,'unit.information.save',p_unit,actor,hash);
 IF begun->>'disposition'='replay' THEN RETURN begun->'response'; END IF;
 IF ident IS NOT NULL THEN
  SELECT to_jsonb(i) INTO before_row FROM public.information i WHERE i.id=ident AND i.unit=p_unit AND i.occasion IS NULL FOR UPDATE;
  IF before_row IS NULL THEN RETURN public.complete_client_mutation_outcome_v1(p_command_id,'rejected',404,'{}'); END IF;
  IF before_row->>'type'='game' OR before_row->>'information_hidden' IS NOT NULL THEN RAISE invalid_parameter_value USING MESSAGE='unit games unsupported'; END IF;
  INSERT INTO public.client_aggregate_versions(aggregate_type,scope_type,scope_id,aggregate_id,version)
  VALUES('information','unit',p_unit,ident::text,0) ON CONFLICT DO NOTHING;
  SELECT version INTO ver FROM public.client_aggregate_versions WHERE aggregate_type='information' AND scope_type='unit' AND scope_id=p_unit AND aggregate_id=ident::text FOR UPDATE;
  IF p_expected_version IS DISTINCT FROM ver THEN RETURN public.complete_client_mutation_outcome_v1(p_command_id,'conflict',409,jsonb_build_object('version',ver,'information',before_row)); END IF;
  IF jsonb_build_object('title',before_row->'title','description',before_row->'description','type',before_row->'type','isHidden',before_row->'is_hidden','order',before_row->'order','data',before_row->'data')
   =p_information-'id'-'hiddenData' THEN RETURN public.complete_client_mutation_outcome_v1(p_command_id,'unchanged',200,jsonb_build_object('version',ver,'information',before_row)); END IF;
  UPDATE public.information SET title=p_information->>'title',description=p_information->>'description',type=p_information->>'type',
   is_hidden=(p_information->>'isHidden')::boolean,"order"=(p_information->>'order')::bigint,data=p_information->'data',updated_at=clock_timestamp() WHERE id=ident;
  UPDATE public.client_aggregate_versions SET version=version+1,updated_at=clock_timestamp() WHERE aggregate_type='information' AND scope_type='unit' AND scope_id=p_unit AND aggregate_id=ident::text RETURNING version INTO ver;
 ELSE
  IF p_expected_version IS NOT NULL THEN RAISE invalid_parameter_value USING MESSAGE='new information cannot have version'; END IF;
  INSERT INTO public.information(unit,title,description,type,is_hidden,"order",data)
  VALUES(p_unit,p_information->>'title',p_information->>'description',p_information->>'type',(p_information->>'isHidden')::boolean,(p_information->>'order')::bigint,p_information->'data') RETURNING id INTO ident;
  ver:=1;INSERT INTO public.client_aggregate_versions(aggregate_type,scope_type,scope_id,aggregate_id,version) VALUES('information','unit',p_unit,ident::text,ver);
 END IF;
 SELECT to_jsonb(i)||jsonb_build_object('aggregate_version',ver) INTO after_row FROM public.information i WHERE id=ident;
 RETURN public.complete_unit_mutation_internal_v1(p_command_id,p_unit,'unit.information.save','information',ident,CASE WHEN before_row IS NULL THEN 'insert' ELSE 'update' END,jsonb_build_object('version',ver,'information',after_row));
END $$;

-- Source: database/functions/organization_verification/profile_commands.sql
CREATE OR REPLACE FUNCTION public.save_unit_legal_profile(p_unit bigint,p_expected_revision bigint,p_profile jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE p public.unit_legal_profiles; n public.unit_legal_profiles; org bigint; k text; v text;
 errors jsonb:='{}'; normalized jsonb; old_values jsonb; checksum integer:=0; i integer;
BEGIN
 SELECT organization INTO org FROM public.units WHERE id=p_unit FOR UPDATE;
 IF auth.uid() IS NULL OR org IS NULL OR NOT public.can_manage_unit_legal_profile(p_unit) THEN
  RAISE EXCEPTION 'Legal profile write denied' USING ERRCODE='42501';
 END IF;
 SELECT * INTO p FROM public.unit_legal_profiles WHERE unit_id=p_unit FOR UPDATE;
 IF p_expected_revision IS DISTINCT FROM coalesce(p.revision,0) THEN
  RETURN jsonb_build_object('code',409,'errorCode','REVISION_CONFLICT','profile',public.get_unit_legal_profile(p_unit)->'profile');
 END IF;
 IF jsonb_typeof(p_profile) IS DISTINCT FROM 'object' THEN
  RETURN jsonb_build_object('code',422,'errorCode','INVALID_PROFILE','fieldErrors',jsonb_build_object('profile','OBJECT_REQUIRED'));
 END IF;
 FOR k IN SELECT jsonb_object_keys(p_profile) LOOP
  IF k<>ALL(ARRAY['legalName','countryCode','registrationNumber','vatId','address','contactEmail','phone','website']) THEN errors:=errors||jsonb_build_object(k,'UNKNOWN_FIELD'); END IF;
  IF k<>'address' AND jsonb_typeof(p_profile->k) NOT IN ('string','null') THEN errors:=errors||jsonb_build_object(k,'TEXT_REQUIRED'); END IF;
 END LOOP;
 IF p_profile ? 'address' AND jsonb_typeof(p_profile->'address') IS DISTINCT FROM 'object' THEN
  errors:=errors||jsonb_build_object('address','OBJECT_REQUIRED');
 ELSE
  FOR k IN SELECT jsonb_object_keys(coalesce(p_profile->'address','{}')) LOOP
   IF k<>ALL(ARRAY['street','city','postalCode']) THEN errors:=errors||jsonb_build_object('address.'||k,'UNKNOWN_FIELD'); END IF;
   IF jsonb_typeof(p_profile->'address'->k) NOT IN ('string','null') THEN errors:=errors||jsonb_build_object('address.'||k,'TEXT_REQUIRED'); END IF;
  END LOOP;
 END IF;
 IF errors<>'{}' THEN RETURN jsonb_build_object('code',422,'errorCode','INVALID_PROFILE','fieldErrors',errors); END IF;
 n.legal_name:=btrim(coalesce(p_profile->>'legalName',''));
 n.country_code:=upper(btrim(coalesce(p_profile->>'countryCode','')));
 n.registration_number:=btrim(coalesce(p_profile->>'registrationNumber',''));
 n.vat_id:=btrim(coalesce(p_profile->>'vatId',''));
 n.street:=btrim(coalesce(p_profile#>>'{address,street}',''));
 n.city:=btrim(coalesce(p_profile#>>'{address,city}',''));
 n.postal_code:=btrim(coalesce(p_profile#>>'{address,postalCode}',''));
 n.contact_email:=lower(btrim(coalesce(p_profile->>'contactEmail','')));
 n.phone:=btrim(coalesce(p_profile->>'phone',''));
 n.website:=btrim(coalesce(p_profile->>'website',''));
 normalized:=jsonb_build_object('legalName',n.legal_name,'countryCode',n.country_code,'registrationNumber',n.registration_number,
 'vatId',n.vat_id,'address',jsonb_build_object('street',n.street,'city',n.city,'postalCode',n.postal_code),
 'contactEmail',n.contact_email,'phone',n.phone,'website',n.website);
 FOR k,v IN SELECT key,value#>>'{}' FROM jsonb_each(normalized-'address') LOOP
  IF length(v)>(CASE k WHEN 'legalName' THEN 200 WHEN 'contactEmail' THEN 254 WHEN 'website' THEN 500 WHEN 'phone' THEN 40 WHEN 'countryCode' THEN 2 ELSE 50 END)
   OR v ~ '[[:cntrl:]]' THEN errors:=errors||jsonb_build_object(k,'INVALID_LENGTH_OR_CHARACTERS'); END IF;
 END LOOP;
 IF length(n.street)>200 OR length(n.city)>100 OR length(n.postal_code)>20 OR (n.street||n.city||n.postal_code) ~ '[[:cntrl:]]' THEN errors:=errors||jsonb_build_object('address','INVALID_ADDRESS'); END IF;
 IF n.country_code<>'' AND n.country_code !~ '^[A-Z]{2}$' THEN errors:=errors||jsonb_build_object('countryCode','INVALID_COUNTRY'); END IF;
 IF n.registration_number<>'' AND n.country_code='CZ' THEN
  IF n.registration_number !~ '^[0-9]{8}$' THEN errors:=errors||jsonb_build_object('registrationNumber','INVALID_CZ_ICO');
  ELSE
   FOR i IN 1..7 LOOP checksum:=checksum+substring(n.registration_number,i,1)::integer*(9-i); END LOOP;
   IF ((11-checksum%11)%10)<>substring(n.registration_number,8,1)::integer THEN errors:=errors||jsonb_build_object('registrationNumber','INVALID_CZ_ICO'); END IF;
  END IF;
 END IF;
 IF n.contact_email<>'' AND n.contact_email !~ '^[^[:space:]@]+@[^[:space:]@]+[.][^[:space:]@]+$' THEN errors:=errors||jsonb_build_object('contactEmail','INVALID_EMAIL'); END IF;
 IF n.phone<>'' AND n.phone !~ '^[+0-9][0-9 ()-]{2,39}$' THEN errors:=errors||jsonb_build_object('phone','INVALID_PHONE'); END IF;
 IF n.website<>'' AND n.website !~ '^https://[A-Za-z0-9]([A-Za-z0-9.-]*[A-Za-z0-9])?(:[0-9]{1,5})?([/?#][^[:space:]<>]*)?$' THEN errors:=errors||jsonb_build_object('website','HTTPS_REQUIRED'); END IF;
 IF errors<>'{}' THEN RETURN jsonb_build_object('code',422,'errorCode','INVALID_PROFILE','fieldErrors',errors); END IF;
 old_values:=(public.get_unit_legal_profile(p_unit)->'profile')-ARRAY['unitId','revision','status','submittedAt','verifiedAt','feedbackToApplicant','reviewNote','reviewSource'];
 IF normalized=old_values AND (p.reviewed_organization_id IS NULL OR p.reviewed_organization_id=org) THEN
  RETURN jsonb_build_object('code',200,'outcome','unchanged','profile',public.get_unit_legal_profile(p_unit)->'profile');
 END IF;
 INSERT INTO public.unit_legal_profiles(unit_id,revision,legal_name,country_code,registration_number,vat_id,street,city,postal_code,contact_email,phone,website)
 VALUES(p_unit,coalesce(p.revision,0)+1,n.legal_name,n.country_code,n.registration_number,n.vat_id,n.street,n.city,n.postal_code,n.contact_email,n.phone,n.website)
 ON CONFLICT(unit_id) DO UPDATE SET revision=excluded.revision,status='unverified',legal_name=excluded.legal_name,
 country_code=excluded.country_code,registration_number=excluded.registration_number,vat_id=excluded.vat_id,
 street=excluded.street,city=excluded.city,postal_code=excluded.postal_code,contact_email=excluded.contact_email,
 phone=excluded.phone,website=excluded.website,submitted_at=NULL,submitted_by=NULL,reviewed_at=NULL,reviewed_by=NULL,
 reviewed_organization_id=NULL,feedback_to_applicant=NULL,review_note=NULL,review_source=NULL;
 INSERT INTO public.unit_legal_profile_audit(unit_id,organization_id,revision,actor_id,action,snapshot)
 SELECT p_unit,org,revision,auth.uid(),'save',to_jsonb(t) FROM public.unit_legal_profiles t WHERE unit_id=p_unit;
 RETURN jsonb_build_object('code',200,'outcome','applied','profile',public.get_unit_legal_profile(p_unit)->'profile');
END $$;

-- Source: database/functions/groups/save_user_group_client_sync_v1.sql
CREATE OR REPLACE FUNCTION public.save_user_group_client_sync_v1(p_occasion bigint, p_command_id uuid, p_expected_version bigint, p_group jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_actor uuid:=auth.uid(); v_id bigint; v_version bigint; v_begin jsonb;
  v_hash text; v_current jsonb; v_requested jsonb; v_entity jsonb;
  v_participants jsonb; v_current_participants jsonb;
  v_old_users uuid[]; v_new_users uuid[];
  v_old_place bigint; v_old_private boolean:=false; v_place_id bigint;
  v_private_place jsonb; v_place_version bigint; v_private_impacts jsonb;
  v_current_place jsonb; v_requested_place jsonb; v_place_changed boolean:=false;
  v_actor_replacements jsonb:='[]'::jsonb;
BEGIN
 PERFORM public.assert_canonical_mutation_write_release_internal_v1(p_occasion);
  v_id:=(p_group->>'id')::bigint;
  IF v_actor IS NULL OR NOT public.can_write_group(p_occasion,v_id) THEN
    RAISE insufficient_privilege USING MESSAGE='group editor required';
  END IF;
  IF p_group IS NULL OR jsonb_typeof(p_group)<>'object'
    OR octet_length(p_group::text)>524288
    OR EXISTS (SELECT 1 FROM jsonb_object_keys(p_group) key WHERE key NOT IN
      ('id','title','description','type','placeId','privatePlace','participants'))
    OR NOT (p_group ?& ARRAY['title','participants'])
    OR jsonb_typeof(p_group->'participants')<>'array'
    OR jsonb_array_length(p_group->'participants')>5000
    OR length(btrim(COALESCE(p_group->>'title',''))) NOT BETWEEN 1 AND 500
    OR octet_length(COALESCE(p_group->>'description',''))>262144 THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid group aggregate';
  END IF;
  SELECT COALESCE(jsonb_agg(jsonb_build_object('userId',x.user_id,
    'isAdmin',COALESCE(x.is_admin,false)) ORDER BY x.user_id),'[]'::jsonb),
    COALESCE(array_agg(x.user_id ORDER BY x.user_id),'{}'::uuid[])
    INTO v_participants,v_new_users
  FROM jsonb_to_recordset(p_group->'participants') x(user_id uuid,is_admin boolean);
  IF jsonb_array_length(p_group->'participants')<>cardinality(v_new_users)
    OR cardinality(v_new_users)<>cardinality(ARRAY(SELECT DISTINCT unnest(v_new_users)))
    OR EXISTS (SELECT 1 FROM unnest(v_new_users) id LEFT JOIN public.occasion_users ou
      ON ou."user"=id AND ou.occasion=p_occasion WHERE ou."user" IS NULL) THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid group participants';
  END IF;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_group->'participants') x WHERE jsonb_typeof(x)<>'object' OR x->>'user_id' IS NULL OR EXISTS(SELECT 1 FROM jsonb_object_keys(x) k WHERE k NOT IN ('user_id','is_admin')))
    OR (p_group->>'placeId' IS NOT NULL AND p_group->'privatePlace' IS NOT NULL AND p_group->'privatePlace'<>'null'::jsonb) THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid group participants or place choice'; END IF;
  v_private_place:=p_group->'privatePlace';
  IF v_private_place IS NOT NULL AND v_private_place<>'null'::jsonb AND (
    jsonb_typeof(v_private_place)<>'object'
    OR EXISTS (SELECT 1 FROM jsonb_object_keys(v_private_place) key WHERE key NOT IN
      ('id','title','description','coordinates','order','icon'))
    OR length(btrim(COALESCE(v_private_place->>'title',''))) NOT BETWEEN 1 AND 500
    OR jsonb_typeof(v_private_place->'coordinates')<>'object'
    OR octet_length(v_private_place::text)>131072) THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid private group place';
  END IF;
  IF v_private_place IS NOT NULL AND v_private_place<>'null'::jsonb THEN
    IF jsonb_typeof(v_private_place#>'{coordinates,latLng,lat}') IS DISTINCT FROM 'number'
      OR jsonb_typeof(v_private_place#>'{coordinates,latLng,lng}') IS DISTINCT FROM 'number'
      OR (v_private_place#>>'{coordinates,latLng,lat}')::double precision NOT BETWEEN -90 AND 90
      OR (v_private_place#>>'{coordinates,latLng,lng}')::double precision NOT BETWEEN -180 AND 180
      OR (v_private_place->>'icon' IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.icons i JOIN public.occasions o ON o.id=p_occasion AND i.organization=o.organization WHERE i.id=(v_private_place->>'icon')::bigint AND (i.unit=o.unit OR i.unit IS NULL))) THEN
      RAISE invalid_parameter_value USING MESSAGE='invalid private coordinates or icon'; END IF;
  END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object('occasion',p_occasion,
    'expectedVersion',p_expected_version,'group',p_group)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,'profile.group.save',
    p_occasion,v_actor,v_hash);
  PERFORM public.lock_group_occasion_internal_v1(p_occasion);
  IF v_actor IS NULL OR NOT public.can_write_group(p_occasion,v_id) THEN
    RAISE insufficient_privilege USING MESSAGE='group editor required';
  END IF;
  IF EXISTS(SELECT 1 FROM unnest(v_new_users) id LEFT JOIN public.occasion_users ou ON ou.occasion=p_occasion AND ou."user"=id WHERE ou."user" IS NULL) THEN RAISE invalid_parameter_value USING MESSAGE='invalid group participants after lock'; END IF;
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  IF v_id IS NOT NULL THEN
    PERFORM 1 FROM public.user_group_info g WHERE g.id=v_id
      AND g.occasion=p_occasion FOR UPDATE;
    IF NOT FOUND THEN RETURN public.complete_client_mutation_outcome_v1(
      p_command_id,'rejected',404,jsonb_build_object('version',0,'group',NULL)); END IF;
    SELECT g.place,COALESCE(p.is_hidden AND p.type='group',false),
      public.get_user_group_command_data_v1(g.id)
      INTO v_old_place,v_old_private,v_current
    FROM public.user_group_info g LEFT JOIN public.places p ON p.id=g.place
    WHERE g.id=v_id;
    SELECT COALESCE(array_agg(ug."user" ORDER BY ug."user"),'{}'::uuid[]),
      COALESCE(jsonb_agg(jsonb_build_object('userId',ug."user",
        'isAdmin',ug.is_admin) ORDER BY ug."user"),'[]'::jsonb)
      INTO v_old_users,v_current_participants FROM public.user_groups ug
      WHERE ug."group"=v_id;
    INSERT INTO public.client_aggregate_versions
      (aggregate_type,scope_type,scope_id,aggregate_id,version)
    VALUES ('user_group','occasion',p_occasion,v_id::text,0) ON CONFLICT DO NOTHING;
    SELECT version INTO v_version FROM public.client_aggregate_versions
      WHERE aggregate_type='user_group' AND scope_type='occasion'
      AND scope_id=p_occasion AND aggregate_id=v_id::text FOR UPDATE;
    IF p_expected_version IS DISTINCT FROM v_version THEN
      RETURN public.complete_client_mutation_outcome_v1(p_command_id,'conflict',409,
        jsonb_build_object('version',v_version,'group',v_current)); END IF;
  ELSIF p_expected_version IS NOT NULL THEN
    RAISE invalid_parameter_value USING MESSAGE='new group must not have expected version';
  END IF;
  IF v_private_place IS NOT NULL AND v_private_place<>'null'::jsonb THEN
    v_place_id:=(v_private_place->>'id')::bigint;
    IF v_place_id IS NULL THEN
      INSERT INTO public.places(title,description,type,coordinates,is_hidden,"order",icon,occasion)
      VALUES (v_private_place->>'title',v_private_place->>'description','group',
        v_private_place->'coordinates',true,(v_private_place->>'order')::bigint,
        (v_private_place->>'icon')::bigint,p_occasion) RETURNING id INTO v_place_id;
      v_place_version:=1;
      v_place_changed:=true;
      INSERT INTO public.client_aggregate_versions
        (aggregate_type,scope_type,scope_id,aggregate_id,version)
      VALUES ('place','occasion',p_occasion,v_place_id::text,v_place_version);
    ELSE
      PERFORM 1 FROM public.places p WHERE p.id=v_place_id AND p.occasion=p_occasion
        AND p.type='group' AND p.is_hidden FOR UPDATE;
      IF NOT FOUND OR v_id IS NULL OR NOT v_old_private
        OR v_place_id IS DISTINCT FROM v_old_place THEN
        RAISE invalid_parameter_value USING MESSAGE='private place is not owned by group';
      END IF;
      PERFORM public.assert_group_place_owner_internal_v1(p_occasion,v_id,v_place_id,false);
      INSERT INTO public.client_aggregate_versions
        (aggregate_type,scope_type,scope_id,aggregate_id,version)
      VALUES ('place','occasion',p_occasion,v_place_id::text,0) ON CONFLICT DO NOTHING;
      SELECT jsonb_build_object('id',p.id,'title',p.title,
        'description',p.description,'coordinates',p.coordinates,
        'order',p."order",'icon',p.icon) INTO v_current_place
      FROM public.places p WHERE p.id=v_place_id;
      v_requested_place:=jsonb_build_object('id',v_place_id,
        'title',v_private_place->>'title','description',v_private_place->>'description',
        'coordinates',v_private_place->'coordinates',
        'order',(v_private_place->>'order')::bigint,
        'icon',(v_private_place->>'icon')::bigint);
      v_place_changed:=v_current_place IS DISTINCT FROM v_requested_place;
      IF v_place_changed THEN
        UPDATE public.places SET title=v_private_place->>'title',
          description=v_private_place->>'description',coordinates=v_private_place->'coordinates',
          "order"=(v_private_place->>'order')::bigint,icon=(v_private_place->>'icon')::bigint
          WHERE id=v_place_id;
        UPDATE public.client_aggregate_versions SET version=version+1,
          updated_at=clock_timestamp() WHERE aggregate_type='place'
          AND scope_type='occasion' AND scope_id=p_occasion
          AND aggregate_id=v_place_id::text RETURNING version INTO v_place_version;
      ELSE
        SELECT version INTO v_place_version FROM public.client_aggregate_versions
        WHERE aggregate_type='place' AND scope_type='occasion'
          AND scope_id=p_occasion AND aggregate_id=v_place_id::text;
      END IF;
    END IF;
  ELSE
    v_place_id:=(p_group->>'placeId')::bigint;
    IF v_place_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.places p
      WHERE p.id=v_place_id AND p.occasion=p_occasion
        AND (NOT p.is_hidden OR (p.id=v_old_place AND p.type='group' AND v_old_private))) THEN
      RAISE invalid_parameter_value USING MESSAGE='invalid shared group place';
    END IF;
  END IF;
  v_requested:=jsonb_build_object('id',v_id,'title',p_group->>'title',
    'description',p_group->>'description','type',p_group->>'type',
    'place',v_place_id,'participants',v_participants);
  IF v_current IS NOT NULL AND jsonb_build_object('id',v_id,
      'title',v_current->>'title','description',v_current->>'description',
      'type',v_current->>'type','place',(v_current->>'place')::bigint,
      'participants',v_current_participants)=v_requested
      AND NOT v_place_changed THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'unchanged',200,
      jsonb_build_object('version',v_version,'group',v_current));
  END IF;
  IF v_old_private AND v_old_place IS DISTINCT FROM v_place_id THEN
    PERFORM public.assert_group_place_owner_internal_v1(p_occasion,v_id,v_old_place,true);
  END IF;
  IF v_id IS NULL THEN
    INSERT INTO public.user_group_info(title,description,type,place,occasion)
    VALUES (p_group->>'title',p_group->>'description',p_group->>'type',v_place_id,p_occasion)
    RETURNING id INTO v_id;
    v_version:=1;
    INSERT INTO public.client_aggregate_versions
      (aggregate_type,scope_type,scope_id,aggregate_id,version)
    VALUES ('user_group','occasion',p_occasion,v_id::text,v_version);
  ELSE
    UPDATE public.user_group_info SET title=p_group->>'title',
      description=p_group->>'description',type=p_group->>'type',place=v_place_id
      WHERE id=v_id;
    UPDATE public.client_aggregate_versions SET version=version+1,
      updated_at=clock_timestamp() WHERE aggregate_type='user_group'
      AND scope_type='occasion' AND scope_id=p_occasion AND aggregate_id=v_id::text
      RETURNING version INTO v_version;
  END IF;
  PERFORM public.write_user_group_members_internal_v1(p_occasion,v_id,p_group->'participants',true);
  IF v_old_private AND v_old_place IS DISTINCT FROM v_place_id THEN
    IF EXISTS (SELECT 1 FROM public.user_group_info g WHERE g.id<>v_id
      AND g.place=v_old_place) THEN
      RAISE foreign_key_violation USING MESSAGE='private group place has another owner';
    END IF;
    DELETE FROM public.places WHERE id=v_old_place;
    DELETE FROM public.client_aggregate_versions WHERE aggregate_type='place'
      AND scope_type='occasion' AND scope_id=p_occasion AND aggregate_id=v_old_place::text;
  END IF;
  v_private_impacts:=public.group_profile_impacts_internal_v1(p_occasion,COALESCE(v_old_users,'{}'::uuid[])||v_new_users);
  v_entity:=public.get_user_group_command_data_v1(v_id)||
    jsonb_build_object('aggregate_version',v_version);
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(v_private_impacts) x WHERE x->>'userId'=v_actor::text) THEN
    v_actor_replacements:=jsonb_build_array(jsonb_build_object(
      'component','private_profile','userId',v_actor,
      'payload',public.get_private_profile_payload_v1(p_occasion,v_actor)));
  END IF;
  RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,
    'profile.group.save','profile',jsonb_build_array(jsonb_build_object(
      'entityType','user_group','entityId',v_id,
      'operation',CASE WHEN v_current IS NULL THEN 'insert' ELSE 'update' END,
      'safeLabel',left(p_group->>'title',240),'changedFields',jsonb_build_array('aggregate'))),
    '{}',v_private_impacts,'[]',jsonb_build_object('version',v_version,'group',v_entity),
    '{}','[]','user',NULL,v_actor_replacements);
END; $function$
;

-- Source: database/functions/scanning/settings.sql
-- Same-occasion editing rights only; a scan code never grants configuration access.
CREATE OR REPLACE FUNCTION public.scanner_can_manage_settings_internal(p_occasion bigint)
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,extensions AS $$
 SELECT public.scanner_settings_rule(auth.uid() IS NOT NULL,public.get_is_editor_on_occasion(p_occasion),public.can_write_orders(p_occasion));
$$;

-- Source: database/functions/eshop/select_spot.sql
CREATE OR REPLACE FUNCTION public.select_spot_single_internal_v1(form_key uuid,secret_id uuid,spot_id bigint,selecting boolean)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE bp bigint; occ bigint; org bigint; un bigint; s eshop.spots; policy jsonb; scopes jsonb; costs jsonb; r jsonb; held bigint; duration_seconds integer; form_data jsonb; form_open boolean; fid bigint;
BEGIN
 IF secret_id IS NULL OR selecting IS NULL THEN RETURN jsonb_build_object('code',400,'message','Invalid reservation'); END IF;
 SELECT f.blueprint,f.occasion,o.organization,o.unit,f.id,f.is_open INTO bp,occ,org,un,fid,form_open FROM public.forms f
 JOIN public.occasions o ON o.id=f.occasion WHERE f.key=form_key;
 IF bp IS NULL THEN RETURN jsonb_build_object('code',404,'message','Form blueprint not found'); END IF;
 PERFORM public.check_occasion_writable(occ);
 -- A buyer's active inventory is serialized before the individual spot lock.
 PERFORM pg_advisory_xact_lock(hashtextextended('hold:'||secret_id::text,0));
 SELECT * INTO s FROM eshop.spots WHERE id=spot_id AND blueprint=bp FOR UPDATE;
 IF NOT FOUND THEN RETURN jsonb_build_object('code',404,'message','Spot not found'); END IF;
 IF s.order_product_ticket IS NOT NULL THEN RETURN jsonb_build_object('code',409,'message','Spot is already ordered'); END IF;
 IF s.secret_expiration_time<=clock_timestamp() THEN
  UPDATE eshop.spots SET secret=NULL,secret_expiration_time=NULL WHERE id=spot_id;
  s.secret:=NULL; s.secret_expiration_time:=NULL;
 END IF;
 IF s.secret IS NOT NULL AND s.secret IS DISTINCT FROM secret_id THEN
  RETURN jsonb_build_object('code',403,'message','Spot is held by another buyer'); END IF;
 IF NOT selecting THEN
  UPDATE eshop.spots SET secret=NULL,secret_expiration_time=NULL,updated_at=now() WHERE id=spot_id;
  RETURN jsonb_build_object('code',200,'message','Spot deselected');
 END IF;
 -- A retry cannot move the original expiration, including after another tab reload.
 IF s.secret=secret_id THEN RETURN jsonb_build_object('code',200,'message','Spot selected','expiresAt',s.secret_expiration_time); END IF;
 r:=public.blueprint_hold_admission_internal(fid,ARRAY[s.id],secret_id);
 IF (r->>'code')::integer<>200 THEN RETURN r; END IF;
 IF selecting AND public.can_write_orders(occ) IS NOT TRUE THEN
  form_data:=public.get_effective_form_data(fid);
  IF form_open IS NOT TRUE OR
   (coalesce(form_data#>>'{schedule,start_time}',form_data->>'start_time'))::timestamptz>clock_timestamp() OR
   (coalesce(form_data#>>'{schedule,end_time}',form_data->>'end_time'))::timestamptz<clock_timestamp() THEN
   RETURN jsonb_build_object('code',403,'message','Form is not open'); END IF;
 END IF;
 policy:=public.abuse_effective_rules_v1('spot.hold',un,org);
 scopes:=jsonb_build_object('recipient',secret_id,'unit',un,'organization',org);
 FOR r IN SELECT value FROM jsonb_array_elements(policy->'rules') ORDER BY value->>'rule_key' LOOP
  PERFORM pg_advisory_xact_lock(hashtextextended('abuse:'||(r->>'rule_key')||':'||(scopes->>(r->>'scope_kind')),0));
 END LOOP;
 SELECT count(*) INTO held FROM eshop.spots WHERE secret=secret_id AND secret_expiration_time>clock_timestamp() AND order_product_ticket IS NULL;
 costs:=jsonb_build_object('hold.active.buyer',held+1);
 PERFORM public.abuse_charge_v1(policy,scopes,costs);
 SELECT (x->>'base_limit')::integer INTO duration_seconds FROM jsonb_array_elements(public.abuse_effective_rules_v1('hold.duration',un,org)->'rules') x;
 IF duration_seconds IS NULL THEN RAISE configuration_limit_exceeded USING MESSAGE='abuse_policy_missing'; END IF;
 UPDATE eshop.spots SET secret=secret_id,secret_expiration_time=clock_timestamp()+make_interval(secs=>duration_seconds),updated_at=now() WHERE id=spot_id RETURNING * INTO s;
 RETURN jsonb_build_object('code',200,'message','Spot selected','expiresAt',s.secret_expiration_time);
END $$;

-- Source: database/functions/events/set_event_attendance_client_sync_v1.sql
CREATE OR REPLACE FUNCTION public.set_event_attendance_client_sync_v1(p_event_id bigint, p_participant_id uuid, p_action text, p_command_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_actor uuid:=auth.uid(); v_occasion bigint; v_event public.events%ROWTYPE;
  v_begin jsonb; v_hash text; v_response jsonb; v_commit jsonb;
  v_private_revision bigint; v_live_revision bigint; v_private_payload jsonb;
  v_live_payload jsonb; v_code integer; v_registration_start timestamptz;
  v_feature jsonb; v_limit integer; v_count bigint; v_group bigint;
  v_is_male boolean; v_changed boolean:=false; v_status text;
  v_needs_occasion_join boolean:=false; v_profile_revision bigint;
  v_profile_payload jsonb; v_private_impacts jsonb; v_items jsonb;
  v_is_publishable boolean; v_companion_owner uuid;
BEGIN
  IF p_action NOT IN ('sign_in','sign_out') OR p_participant_id IS NULL THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid attendance command';
  END IF;
  SELECT r.occasion INTO v_occasion FROM public.client_mutation_receipts r WHERE r.command_id=p_command_id
    AND r.actor_id=v_actor AND r.command_name='event.attendance.'||p_action;
  IF NOT FOUND THEN
  SELECT e.occasion,NOT o.is_hidden INTO v_occasion,v_is_publishable
  FROM public.events e JOIN public.occasions o ON o.id=e.occasion
  WHERE e.id=p_event_id;
  ELSE
    SELECT NOT is_hidden INTO v_is_publishable FROM public.occasions WHERE id=v_occasion;
  END IF;
  IF v_actor IS NULL OR v_occasion IS NULL OR NOT (
    v_actor=p_participant_id OR EXISTS (SELECT 1 FROM public.user_companions c
      WHERE c.occasion=v_occasion AND c."user"=v_actor AND c.companion=p_participant_id AND COALESCE((public.get_companion_feature_policy_v1(v_occasion)->>'is_enabled')::boolean,false))
    OR public.can_write_schedule(v_occasion)) THEN
    RAISE insufficient_privilege USING MESSAGE='participant attendance permission required';
  END IF;
  SELECT c."user" INTO v_companion_owner FROM public.user_companions c
    JOIN public.occasion_users ou ON ou."user"=c."user" AND ou.occasion=v_occasion
    WHERE c.occasion=v_occasion AND c.companion=p_participant_id ORDER BY c."user" LIMIT 1;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object('eventId',p_event_id,
    'participantId',p_participant_id,'action',p_action)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,'event.attendance.'||p_action,
    v_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(
    'attendance-user:'||p_participant_id::text||':'||v_occasion::text,0));
  FOR v_group IN SELECT ee."group" FROM public.exclusive_events ee
      WHERE ee.event=p_event_id ORDER BY ee."group" LOOP
    PERFORM pg_advisory_xact_lock(hashtextextended(
      'attendance-group:'||v_group::text,0));
  END LOOP;
  SELECT * INTO STRICT v_event FROM public.events e WHERE e.id=p_event_id
    AND e.occasion=v_occasion FOR UPDATE;

  IF p_action='sign_out' THEN
    IF NOT EXISTS (SELECT 1 FROM public.event_users eu
      WHERE eu.event=p_event_id AND eu."user"=p_participant_id) THEN
      v_status:='unchanged'; v_code:=404;
    ELSIF clock_timestamp() > v_event.end_time THEN
      v_status:='rejected'; v_code:=201;
    ELSE
      DELETE FROM public.event_users WHERE event=p_event_id AND "user"=p_participant_id;
      v_changed:=true; v_code:=200;
    END IF;
  ELSE
    IF NOT EXISTS (SELECT 1 FROM public.occasion_users ou
      WHERE ou.occasion=v_occasion AND ou."user"=p_participant_id) THEN
      IF v_actor=p_participant_id AND EXISTS (SELECT 1 FROM public.occasions o
        WHERE o.id=v_occasion AND o.is_open) THEN
        v_needs_occasion_join:=true;
      END IF;
      IF NOT v_needs_occasion_join THEN
        v_status:='rejected'; v_code:=403;
      END IF;
    END IF;
    IF v_code IS NULL AND EXISTS (SELECT 1 FROM public.event_users eu
      WHERE eu.event=p_event_id AND eu."user"=p_participant_id) THEN
      v_status:='unchanged'; v_code:=103;
    END IF;
    IF v_code IS NULL AND clock_timestamp() > v_event.end_time THEN
      v_status:='rejected'; v_code:=100;
    END IF;

    IF v_code IS NULL AND COALESCE((v_event.data->>'is_counseling_slot')::boolean,false) THEN
      SELECT f INTO v_feature FROM public.occasions o,
        LATERAL jsonb_array_elements(o.features) f
      WHERE o.id=v_occasion AND f->>'code'='counseling' LIMIT 1;
      IF v_feature IS NULL OR COALESCE((v_feature->>'is_enabled')::boolean,false)=false THEN
        v_status:='rejected'; v_code:=108;
      ELSE
        v_registration_start:=(v_feature->>'registration_start_time')::timestamptz;
        IF v_registration_start IS NOT NULL AND clock_timestamp()<v_registration_start THEN
          v_status:='rejected'; v_code:=104;
        END IF;
        v_limit:=COALESCE((v_feature->>'max_active_bookings')::integer,1);
        IF v_code IS NULL AND v_limit>0 THEN
          SELECT count(*) INTO v_count FROM public.event_users eu
          JOIN public.events e ON e.id=eu.event
          WHERE eu."user"=p_participant_id AND e.occasion=v_occasion
            AND COALESCE((e.data->>'is_counseling_slot')::boolean,false)
            AND e.end_time>clock_timestamp();
          IF v_count>=v_limit THEN v_status:='rejected'; v_code:=109; END IF;
        END IF;
      END IF;
    ELSIF v_code IS NULL THEN
      SELECT f INTO v_feature FROM public.occasions o,
        LATERAL jsonb_array_elements(o.features) f
      WHERE o.id=v_occasion AND f->>'code'='workshops' LIMIT 1;
      IF v_feature IS NOT NULL THEN
        IF COALESCE((v_feature->>'is_enabled')::boolean,false)=false THEN
          v_status:='rejected'; v_code:=108;
        ELSE
          v_registration_start:=(v_feature->>'start_time')::timestamptz;
          IF v_registration_start IS NOT NULL AND clock_timestamp()<v_registration_start THEN
            v_status:='rejected'; v_code:=104;
          END IF;
        END IF;
      END IF;
    END IF;

    IF v_code IS NULL AND EXISTS (
      SELECT 1 FROM public.exclusive_events target
      JOIN public.exclusive_events occupied ON occupied."group"=target."group"
      JOIN public.event_users eu ON eu.event=occupied.event
      WHERE target.event=p_event_id AND eu."user"=p_participant_id) THEN
      v_status:='rejected'; v_code:=102;
    END IF;
    IF v_code IS NULL AND EXISTS (
      SELECT 1 FROM public.event_users eu JOIN public.events e ON e.id=eu.event
      WHERE eu."user"=p_participant_id AND e.id<>p_event_id
        AND e.start_time<v_event.end_time AND e.end_time>v_event.start_time) THEN
      v_status:='rejected'; v_code:=107;
    END IF;
    IF v_code IS NULL AND COALESCE(v_event.max_participants,0)>0 THEN
      SELECT count(*) INTO v_count FROM public.event_users eu WHERE eu.event=p_event_id;
      IF v_event.split_for_men_women THEN
        SELECT COALESCE(u.sex='male',false) INTO v_is_male
          FROM public.user_info u WHERE u.id=p_participant_id;
        SELECT count(*) INTO v_count FROM public.event_users eu
          JOIN public.user_info u ON u.id=eu."user" WHERE eu.event=p_event_id
            AND (u.sex='male')=v_is_male;
        IF v_count>=v_event.max_participants/2 THEN
          v_status:='rejected'; v_code:=CASE WHEN v_is_male THEN 105 ELSE 106 END;
        END IF;
      ELSIF v_count>=v_event.max_participants THEN
        v_status:='rejected'; v_code:=101;
      END IF;
    END IF;
    IF v_code IS NULL THEN
      IF v_needs_occasion_join THEN
        PERFORM public.add_user_to_occasion_internal_v1(v_occasion,p_participant_id);
        IF NOT EXISTS (SELECT 1 FROM public.occasion_users ou
          WHERE ou.occasion=v_occasion AND ou."user"=p_participant_id) THEN
          RAISE EXCEPTION 'occasion membership handler did not create membership';
        END IF;
      END IF;
      INSERT INTO public.event_users(event,"user") VALUES(p_event_id,p_participant_id);
      v_changed:=true; v_code:=200;
    END IF;
  END IF;

  IF NOT v_changed THEN
    v_response:=jsonb_build_object('status',v_status,'code',v_code,
      'data',jsonb_build_object('eventId',p_event_id,'participantId',p_participant_id,
        'isSignedIn',EXISTS(SELECT 1 FROM public.event_users eu
          WHERE eu.event=p_event_id AND eu."user"=p_participant_id),
        'eventsRegistrationStart',v_registration_start),
      'mutation',jsonb_build_object('commandId',p_command_id,'receiptId',p_command_id,
        'commitId',NULL,'replayed',false,'occurredAt',clock_timestamp()),
      'sync',jsonb_build_object('replacements','[]'::jsonb));
    RETURN public.finish_client_mutation_v1(p_command_id,v_response,NULL);
  END IF;

  v_items:=jsonb_build_array(jsonb_build_object(
      'entityType','event_attendance','entityId',p_event_id||':'||p_participant_id::text,
      'operation','update','safeLabel','Event attendance',
      'changedFields',jsonb_build_array('is_signed_in')));
  v_private_impacts:=jsonb_build_array(jsonb_build_object(
    'component','private_program','userId',p_participant_id));
  IF v_companion_owner IS NOT NULL THEN
    v_private_impacts:=v_private_impacts||jsonb_build_array(jsonb_build_object(
      'component','private_profile','userId',v_companion_owner));
  END IF;
  IF v_needs_occasion_join THEN
    v_items:=v_items||jsonb_build_array(jsonb_build_object(
      'entityType','occasion_membership','entityId',p_participant_id,
      'operation','insert','safeLabel','Occasion membership',
      'changedFields',jsonb_build_array('occasion')));
    v_private_impacts:=v_private_impacts||jsonb_build_array(jsonb_build_object(
      'component','private_profile','userId',p_participant_id));
  END IF;
  v_commit:=public.record_client_sync_commit_v1(v_occasion,
    'event.attendance.'||p_action,'attendance',v_items,
    CASE WHEN v_is_publishable THEN ARRAY['live_public'] ELSE '{}'::text[] END,
    v_private_impacts,CASE WHEN v_is_publishable THEN jsonb_build_array(
      jsonb_build_object('component','live_public','entityId',p_event_id))
      ELSE '[]'::jsonb END,'user',NULL);
  SELECT source_revision INTO v_private_revision FROM public.client_sync_private_scopes
    WHERE component='private_program' AND occasion=v_occasion AND user_id=p_participant_id;
  IF v_needs_occasion_join OR v_companion_owner IS NOT NULL THEN
    SELECT source_revision INTO STRICT v_profile_revision
    FROM public.client_sync_private_scopes
    WHERE component='private_profile' AND occasion=v_occasion
      AND user_id=COALESCE(v_companion_owner,p_participant_id);
    v_profile_payload:=public.get_private_profile_payload_v1(
      v_occasion,COALESCE(v_companion_owner,p_participant_id));
  END IF;
  SELECT jsonb_build_object(
    'signedIn',COALESCE(jsonb_agg(eu.event ORDER BY eu.event),'[]'::jsonb),
    'saved',(SELECT COALESCE(jsonb_agg(es.event ORDER BY es.event),'[]'::jsonb)
      FROM public.event_users_saved es JOIN public.events e ON e.id=es.event
      WHERE es."user"=p_participant_id AND e.occasion=v_occasion))
    INTO v_private_payload FROM public.event_users eu JOIN public.events e ON e.id=eu.event
    WHERE eu."user"=p_participant_id AND e.occasion=v_occasion;
  IF v_is_publishable THEN
    SELECT source_revision INTO v_live_revision FROM public.client_sync_scopes
      WHERE component='live_public' AND scope_type='occasion' AND scope_id=v_occasion;
    INSERT INTO public.event_public_state
      (occasion,event,participant_count,saved_count,remaining_capacity,revision,projected_at)
    SELECT v_occasion,v_event.id,count(DISTINCT eu."user"),count(DISTINCT es."user"),
      CASE WHEN v_event.max_participants IS NULL THEN NULL
        ELSE GREATEST(v_event.max_participants-count(DISTINCT eu."user"),0) END,
      v_live_revision,clock_timestamp()
    FROM (SELECT 1) seed LEFT JOIN public.event_users eu ON eu.event=v_event.id
    LEFT JOIN public.event_users_saved es ON es.event=v_event.id
    ON CONFLICT (occasion,event) DO UPDATE SET
      participant_count=EXCLUDED.participant_count,saved_count=EXCLUDED.saved_count,
      remaining_capacity=EXCLUDED.remaining_capacity,revision=EXCLUDED.revision,
      projected_at=EXCLUDED.projected_at;
    SELECT jsonb_build_object(
      'events',COALESCE(jsonb_agg(jsonb_build_object('eventId',s.event,
        'participantCount',s.participant_count,'savedCount',s.saved_count,
        'remainingCapacity',s.remaining_capacity) ORDER BY s.event),'[]'::jsonb),
      'cleaning',(SELECT COALESCE(jsonb_agg(jsonb_build_object('placeId',c.place,
        'status',c.status,'openReportCount',c.open_report_count) ORDER BY c.place),'[]'::jsonb)
        FROM public.cleaning_public_state c WHERE c.occasion=v_occasion))
      INTO v_live_payload FROM public.event_public_state s JOIN public.events e ON e.id=s.event
      WHERE s.occasion=v_occasion AND NOT e.is_hidden;
  END IF;
  v_response:=jsonb_build_object('status','applied','code',200,
    'data',jsonb_build_object('eventId',p_event_id,'participantId',p_participant_id,
      'isSignedIn',p_action='sign_in'),
    'mutation',jsonb_build_object('commandId',p_command_id,'receiptId',p_command_id,
      'commitId',v_commit->>'commitId','replayed',false,'occurredAt',v_commit->>'occurredAt'),
    'sync',jsonb_build_object('replacements',
      CASE WHEN v_is_publishable THEN jsonb_build_array(jsonb_build_object(
        'component','live_public','revision',v_live_revision,
        'payload',v_live_payload)) ELSE '[]'::jsonb END ||
      CASE WHEN v_actor=p_participant_id THEN jsonb_build_array(jsonb_build_object(
        'component','private_program','revision',v_private_revision,
        'payload',v_private_payload)) ELSE '[]'::jsonb END ||
        CASE WHEN v_needs_occasion_join OR v_companion_owner=v_actor
          THEN jsonb_build_array(jsonb_build_object(
          'component','private_profile','revision',v_profile_revision,
          'payload',v_profile_payload)) ELSE '[]'::jsonb END));
  RETURN public.finish_client_mutation_v1(p_command_id,v_response,
    (v_commit->>'commitId')::uuid);
END; $function$
;

-- Source: database/functions/speakers/set_event_speakers.sql
CREATE OR REPLACE FUNCTION public.set_event_speakers(p_event bigint,p_speakers bigint[])
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE oc bigint; ver bigint; result jsonb;
BEGIN
 SELECT occasion INTO oc FROM public.events WHERE id=p_event;
 IF oc IS NULL THEN RETURN jsonb_build_object('code',404); END IF;
 IF public.can_write_speakers(oc) IS NOT TRUE THEN RETURN jsonb_build_object('code',403); END IF;
 PERFORM 1 FROM public.events WHERE id=p_event FOR UPDATE;
 SELECT coalesce(v.version,0) INTO ver FROM (SELECT 1) seed LEFT JOIN public.client_aggregate_versions v
 ON v.aggregate_type='event' AND v.scope_type='occasion' AND v.scope_id=oc AND v.aggregate_id=p_event::text;
 result:=public.save_event_speakers_client_sync_v1(oc,p_event,extensions.gen_random_uuid(),ver,p_speakers);
 RETURN jsonb_build_object('code',result->'code');
EXCEPTION WHEN invalid_parameter_value THEN RETURN jsonb_build_object('code',400);
END $$;

-- Source: database/functions/organization/unit_app_landing.sql
CREATE OR REPLACE FUNCTION public.set_unit_app_landing(
  p_unit bigint, p_occasion bigint, p_expected_occasion bigint)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
  v_org bigint;
  v_data jsonb;
  v_current bigint;
BEGIN
  SELECT organization INTO v_org FROM public.units WHERE id = p_unit;
  IF v_org IS NULL OR NOT public.can_manage_unit_app_landing(p_unit) THEN
    RAISE insufficient_privilege USING MESSAGE = 'Access denied';
  END IF;
  SELECT data INTO v_data FROM public.organizations WHERE id = v_org FOR UPDATE;
  IF NOT coalesce((v_data->>'IS_APP_SUPPORTED')::boolean, false) THEN
    RAISE invalid_parameter_value USING MESSAGE = 'Application is not enabled';
  END IF;
  v_current := (v_data->>'DEFAULT_OCCASION')::bigint;
  IF v_current IS DISTINCT FROM p_expected_occasion THEN
    RAISE serialization_failure USING MESSAGE = 'App landing changed. Refresh and try again.';
  END IF;
  IF p_occasion IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.occasions WHERE id = p_occasion
      AND unit = p_unit AND organization = v_org AND is_open = true
  ) THEN
    RAISE invalid_parameter_value USING MESSAGE = 'Choose an open occasion in this unit';
  END IF;
  -- The representative occasion is a separate application setting; preserve it.
  UPDATE public.organizations
    SET data = (coalesce(data, '{}'::jsonb) - 'DEFAULT_OCCASION')
      || CASE WHEN p_occasion IS NULL THEN '{}'::jsonb
         ELSE jsonb_build_object('DEFAULT_OCCASION', p_occasion) END
    WHERE id = v_org;
  RETURN public.get_unit_app_landing(p_unit);
END;
$$;

-- Source: database/functions/eshop_orders/storno_order_client_sync_v1.sql
CREATE OR REPLACE FUNCTION public.storno_order_client_sync_v1(p_order bigint, p_command_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path = public, extensions
AS $function$
DECLARE v_actor uuid:=auth.uid(); v_occasion bigint; v_begin jsonb; v_hash text;
  v_before_users uuid[]; v_unchanged boolean:=false;
BEGIN
  PERFORM public.lock_blueprint_scope_internal(ARRAY[(SELECT occasion FROM eshop.orders WHERE id=p_order)]);
  SELECT o.occasion INTO v_occasion FROM eshop.orders o WHERE o.id=p_order;
  IF v_actor IS NULL OR v_occasion IS NULL
    OR NOT public.can_write_orders(v_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='order editor required'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'order',p_order)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,
    'inventory.order.cancel',v_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  -- A committed cancellation needs only a receipt, without another admission.
  IF (SELECT state FROM eshop.orders WHERE id=p_order)='storno' THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'unchanged',200,
      jsonb_build_object('orderId',p_order));
  END IF;
  BEGIN
    -- Preserve admission -> domain locks, also relative to deletion. If another
    -- cancellation wins while waiting, roll back this attempt's admission.
    PERFORM public.admit_order_mutation_v1(v_occasion,(SELECT count(*) FROM eshop.order_product_ticket WHERE "order"=p_order));
    PERFORM public.lock_order_capacity_scope_internal(ARRAY[p_order]);
    IF (SELECT state FROM eshop.orders WHERE id=p_order)='storno' THEN
      RAISE SQLSTATE 'P0C01' USING MESSAGE='cancellation already committed'; END IF;
    SELECT COALESCE(array_agg(ou."user"),'{}'::uuid[]) INTO v_before_users
      FROM public.occasion_users ou WHERE ou.occasion=v_occasion;
    PERFORM public.update_order_and_tickets_to_storno_ws_internal_v1(p_order);
  EXCEPTION WHEN SQLSTATE 'P0C01' THEN v_unchanged:=true;
  END;
  IF v_unchanged THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'unchanged',200,
      jsonb_build_object('orderId',p_order));
  END IF;
  RETURN public.complete_profile_inventory_membership_mutation_v1(
    p_command_id,v_occasion,'inventory.order.cancel',
    jsonb_build_array(jsonb_build_object('entityType','order','entityId',p_order,
      'operation','update','safeLabel','Order cancellation',
      'changedFields',jsonb_build_array('state','tickets','membership','allocations'))),
    v_before_users,jsonb_build_object('orderId',p_order));
END; $function$;

-- Source: database/functions/eshop_orders/storno_tickets_bulk.sql
CREATE OR REPLACE FUNCTION public.storno_tickets_bulk_internal_v1(p_ticket_ids BIGINT[], p_send_email BOOLEAN DEFAULT TRUE)
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
    v_order_id BIGINT;
    v_occasion_id BIGINT;
    v_tickets_in_order BIGINT[];
    v_tickets_to_cancel_in_order BIGINT[];
    v_remaining_count INT;
    v_ticket_id_to_remove BIGINT;
    v_original_data JSONB;
    v_updated_tickets_json JSONB;
    v_ticket_elem JSONB;
    v_product_elem JSONB;
    v_removed_price NUMERIC(10, 2);
    v_current_price NUMERIC(10, 2);
BEGIN
    PERFORM public.lock_blueprint_scope_internal(ARRAY(SELECT DISTINCT occasion FROM eshop.tickets WHERE id=ANY(p_ticket_ids)));
    PERFORM public.check_blueprint_selection_units_internal(ARRAY(SELECT s.id FROM eshop.spots s JOIN eshop.order_product_ticket opt ON opt.id=s.order_product_ticket WHERE opt.ticket=ANY(p_ticket_ids)));
    PERFORM public.lock_order_capacity_scope_internal(ARRAY(SELECT DISTINCT "order" FROM eshop.order_product_ticket WHERE ticket=ANY(p_ticket_ids)));
    -- 1. Identify all unique orders involved in this batch AND their occasion
    -- We need the occasion ID to perform the security check
    FOR v_order_id, v_occasion_id IN
        SELECT DISTINCT o.id, o.occasion
        FROM eshop.tickets t
        JOIN eshop.order_product_ticket opt ON t.id = opt.ticket
        JOIN eshop.orders o ON opt."order" = o.id
        WHERE t.id = ANY(p_ticket_ids)
        ORDER BY o.id
    LOOP
        -- 2. SECURITY CHECK
        -- Verify that the current user has editor permissions on the occasion associated with the order.
        IF NOT public.can_write_orders(v_occasion_id) THEN
            RAISE EXCEPTION 'Permission denied to storno tickets for order % on occasion %', v_order_id, v_occasion_id;
        END IF;

        -- Repeated selected tickets in an otherwise active order are a no-op.
        IF NOT EXISTS(SELECT 1 FROM eshop.order_product_ticket opt JOIN eshop.tickets t ON t.id=opt.ticket
          WHERE opt."order"=v_order_id AND t.id=ANY(p_ticket_ids) AND t.state IS DISTINCT FROM 'storno') THEN
          CONTINUE;
        END IF;
        PERFORM public.check_order_is_mutable(v_order_id);
        -- Serialize cancellations on the same order before counting survivors.
        PERFORM 1 FROM eshop.orders WHERE id = v_order_id FOR UPDATE;

        -- 3. Get all active tickets currently in this order
        SELECT ARRAY_AGG(t.id)
        INTO v_tickets_in_order
        FROM eshop.tickets t
        JOIN eshop.order_product_ticket opt ON t.id = opt.ticket
        WHERE opt."order" = v_order_id
        AND (t.state IS NULL OR t.state != 'storno');

        -- 4. Get intersection: Tickets in this order that we want to cancel
        SELECT ARRAY_AGG(id)
        INTO v_tickets_to_cancel_in_order
        FROM UNNEST(v_tickets_in_order) AS id
        WHERE id = ANY(p_ticket_ids);

        -- A replay or a selection containing only cancelled tickets has no effect.
        IF coalesce(cardinality(v_tickets_to_cancel_in_order), 0) = 0 THEN
            CONTINUE;
        END IF;

        -- 5. Calculate how many would remain
        v_remaining_count := array_length(v_tickets_in_order, 1) - array_length(v_tickets_to_cancel_in_order, 1);

        -- -----------------------------------------------------
        -- SCENARIO A: Full Order Cancellation
        -- -----------------------------------------------------
        IF v_remaining_count <= 0 THEN
            -- Helper function to cancel the entire order
            PERFORM public.cancel_order_domain_internal_v1(v_order_id,p_send_email);

        -- -----------------------------------------------------
        -- SCENARIO B: Partial Cancellation (Modify Order)
        -- -----------------------------------------------------
        ELSE
            -- 1. Mark specific tickets as storno in DB
            PERFORM internal_storno_tickets_221(v_tickets_to_cancel_in_order);

            -- 2. Fetch Order Data
            SELECT data, price INTO v_original_data, v_current_price
            FROM eshop.orders WHERE id = v_order_id;

            v_updated_tickets_json := '[]'::JSONB;
            v_removed_price := 0;

            -- 3. Rebuild JSON data, filtering out cancelled tickets and summing price to remove
            FOR v_ticket_elem IN SELECT * FROM jsonb_array_elements(v_original_data->'tickets')
            LOOP
                v_ticket_id_to_remove := (v_ticket_elem->>'id')::BIGINT;

                -- If this ticket is one of the ones being cancelled
                IF v_ticket_id_to_remove = ANY(v_tickets_to_cancel_in_order) THEN
                    -- Sum up price to deduct
                    FOR v_product_elem IN SELECT * FROM jsonb_array_elements(v_ticket_elem->'products')
                    LOOP
                        v_removed_price := v_removed_price + COALESCE((v_product_elem->>'price')::NUMERIC, 0);
                    END LOOP;
                ELSE
                    -- Keep this ticket in the new JSON
                    v_updated_tickets_json := v_updated_tickets_json || v_ticket_elem;
                END IF;
            END LOOP;

            -- Fence unsent snapshots of the previous ticket set, and keep the
            -- payment amount aligned with the new order total.
            PERFORM public.cancel_order_email_intents(v_order_id);
            UPDATE eshop.payment_info SET amount=GREATEST(0, COALESCE(v_current_price,0)-v_removed_price)
            WHERE id=(SELECT payment_info FROM eshop.orders WHERE id=v_order_id);

            -- 4. Update Order (Data & Price)
            UPDATE eshop.orders
            SET
                data = v_original_data || JSONB_BUILD_OBJECT('tickets', v_updated_tickets_json),
                price = GREATEST(0, COALESCE(v_current_price, 0) - v_removed_price),
                email_payment_version = email_payment_version + 1,
                updated_at = NOW()
            WHERE id = v_order_id;

            -- Refresh only this order's existing reminder schedule for its new amount.
            PERFORM public.set_payment_deadline(pi.id,pi.deadline)
            FROM eshop.payment_info pi JOIN eshop.orders o ON o.payment_info=pi.id
            WHERE o.id=v_order_id AND o.state='ordered' AND pi.deadline IS NOT NULL;

            -- Existing delivery policy prepares the surviving tickets if their
            -- paid order has not finished sending yet; sent orders stay untouched.
            PERFORM public.enqueue_paid_order_tickets(v_order_id);

            -- 5. Insert ONE history record for this modification
            INSERT INTO eshop.orders_history (
                "order",
                data,
                state,
                price,
                created_at
            )
            VALUES (
                v_order_id,
                v_original_data || JSONB_BUILD_OBJECT('tickets', v_updated_tickets_json),
                (SELECT state FROM eshop.orders WHERE id=v_order_id),
                GREATEST(0, COALESCE(v_current_price, 0) - v_removed_price),
                NOW()
            );
        END IF;
    END LOOP;
END;
$$;

-- Source: database/functions/eshop_orders/storno_tickets_client_sync_v1.sql
CREATE OR REPLACE FUNCTION public.storno_tickets_client_sync_v1(
  p_tickets bigint[],p_command_id uuid
) RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = public, extensions AS $$
DECLARE v_request_tickets bigint[]:=p_tickets; v_actor uuid:=auth.uid(); v_occasion bigint; v_begin jsonb; v_hash text;
  v_unchanged boolean:=false; v_before_users uuid[]; v_changed_orders bigint[]; v_cancelled jsonb; v_updated jsonb;
BEGIN
  p_tickets:=ARRAY(SELECT DISTINCT id FROM unnest(p_tickets) id ORDER BY id);
  PERFORM public.lock_blueprint_scope_internal(ARRAY(SELECT DISTINCT occasion FROM eshop.tickets WHERE id=ANY(p_tickets)));
  IF cardinality(p_tickets)>(SELECT hard_cap FROM public.abuse_policy_rules WHERE rule_key='order.mutation.items') THEN RAISE SQLSTATE 'PT429' USING MESSAGE='abuse_limit_exceeded'; END IF;
  SELECT min(t.occasion) INTO v_occasion FROM eshop.tickets t
    WHERE t.id=ANY(p_tickets);
  IF v_actor IS NULL OR v_occasion IS NULL OR cardinality(p_tickets)=0
    OR (SELECT count(*) FROM eshop.tickets t
      WHERE t.id=ANY(p_tickets) AND t.occasion=v_occasion)
      <>cardinality(ARRAY(SELECT DISTINCT id FROM unnest(p_tickets) id))
    OR NOT public.can_write_orders(v_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='order editor required'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'tickets',v_request_tickets)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,
    'inventory.tickets.cancel',v_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  IF NOT EXISTS(SELECT 1 FROM eshop.tickets WHERE id=ANY(p_tickets) AND state IS DISTINCT FROM 'storno') THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'unchanged',200,
      jsonb_build_object('ticketIds',to_jsonb(p_tickets),'cancelledOrderIds','[]'::jsonb,'updatedOrders','[]'::jsonb));
  END IF;
  BEGIN
  PERFORM public.admit_order_mutation_v1(v_occasion,cardinality(p_tickets));
  SELECT COALESCE(array_agg(ou."user"),'{}'::uuid[]) INTO v_before_users
    FROM public.occasion_users ou WHERE ou.occasion=v_occasion;
  PERFORM public.lock_order_capacity_scope_internal(ARRAY(SELECT DISTINCT "order" FROM eshop.order_product_ticket WHERE ticket=ANY(p_tickets)));
  -- Lock in the same order as the bulk mutation, then capture only actual changes.
  PERFORM o.id FROM eshop.orders o WHERE o.id IN (
    SELECT opt."order" FROM eshop.order_product_ticket opt
    JOIN eshop.tickets t ON t.id=opt.ticket
    WHERE t.id=ANY(p_tickets)) ORDER BY o.id FOR UPDATE;
  SELECT array_agg(DISTINCT opt."order") INTO v_changed_orders
    FROM eshop.order_product_ticket opt JOIN eshop.tickets t ON t.id=opt.ticket
    WHERE t.id=ANY(p_tickets) AND t.state IS DISTINCT FROM 'storno';
  IF coalesce(cardinality(v_changed_orders),0)=0 THEN
    RAISE SQLSTATE 'P0C01' USING MESSAGE='cancellation already committed'; END IF;
  PERFORM public.storno_tickets_bulk_internal_v1(p_tickets, false);
  SELECT coalesce(jsonb_agg(o.id ORDER BY o.id) FILTER(WHERE o.state='storno'),'[]'::jsonb),
    coalesce(jsonb_agg(jsonb_build_object('id',o.id,'email',o.data->>'email') ORDER BY o.id)
      FILTER(WHERE o.state IS DISTINCT FROM 'storno'),'[]'::jsonb)
    INTO v_cancelled,v_updated FROM eshop.orders o WHERE o.id=ANY(v_changed_orders);
  EXCEPTION WHEN SQLSTATE 'P0C01' THEN v_unchanged:=true;
  END;
  IF v_unchanged THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'unchanged',200,
      jsonb_build_object('ticketIds',to_jsonb(p_tickets),'cancelledOrderIds','[]'::jsonb,'updatedOrders','[]'::jsonb));
  END IF;
  RETURN public.complete_profile_inventory_membership_mutation_v1(
    p_command_id,v_occasion,'inventory.tickets.cancel',
    jsonb_build_array(jsonb_build_object('entityType','ticket','entityId',NULL,
      'operation','update','safeLabel','Ticket cancellation',
      'changedFields',jsonb_build_array('state','membership','allocations'))),
    v_before_users,jsonb_build_object('ticketIds',to_jsonb(p_tickets),
      'cancelledOrderIds',v_cancelled,'updatedOrders',v_updated));
END; $$;

-- Source: database/functions/organization_verification/profile_commands.sql
CREATE OR REPLACE FUNCTION public.submit_unit_verification(p_unit bigint,p_expected_revision bigint)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE p public.unit_legal_profiles; org bigint; errors jsonb:='{}'; k text; v text;
BEGIN
 SELECT organization INTO org FROM public.units WHERE id=p_unit FOR UPDATE;
 IF auth.uid() IS NULL OR org IS NULL OR NOT public.can_manage_unit_legal_profile(p_unit) THEN
  RAISE EXCEPTION 'Legal profile submission denied' USING ERRCODE='42501';
 END IF;
 SELECT * INTO p FROM public.unit_legal_profiles WHERE unit_id=p_unit FOR UPDATE;
 IF p_expected_revision IS DISTINCT FROM coalesce(p.revision,0) THEN RETURN jsonb_build_object('code',409,'errorCode','REVISION_CONFLICT','profile',public.get_unit_legal_profile(p_unit)->'profile'); END IF;
 FOR k,v IN SELECT key,value#>>'{}' FROM jsonb_each(public.get_unit_legal_profile(p_unit)->'profile') WHERE key=ANY(ARRAY['legalName','countryCode','registrationNumber','contactEmail']) LOOP
  IF coalesce(v,'')='' THEN errors:=errors||jsonb_build_object(k,'REQUIRED'); END IF;
 END LOOP;
 IF coalesce(p.street,'')='' OR coalesce(p.city,'')='' OR coalesce(p.postal_code,'')='' THEN errors:=errors||jsonb_build_object('address','REQUIRED'); END IF;
 IF errors<>'{}' THEN RETURN jsonb_build_object('code',422,'errorCode','INCOMPLETE_PROFILE','fieldErrors',errors); END IF;
 IF p.status NOT IN ('unverified','rejected','revoked') THEN RETURN jsonb_build_object('code',422,'errorCode','INVALID_TRANSITION','fieldErrors','{}'::jsonb); END IF;
 UPDATE public.unit_legal_profiles SET revision=revision+1,status='pending',submitted_at=statement_timestamp(),submitted_by=auth.uid(),
 reviewed_at=NULL,reviewed_by=NULL,reviewed_organization_id=NULL,feedback_to_applicant=NULL,review_note=NULL,review_source=NULL WHERE unit_id=p_unit;
 INSERT INTO public.unit_legal_profile_audit(unit_id,organization_id,revision,actor_id,action,snapshot)
 SELECT p_unit,org,revision,auth.uid(),'submit',to_jsonb(t) FROM public.unit_legal_profiles t WHERE unit_id=p_unit;
 PERFORM public.enqueue_unit_verification_request(p_unit);
 RETURN jsonb_build_object('code',200,'outcome','applied','profile',public.get_unit_legal_profile(p_unit)->'profile');
END $$;

-- Source: database/functions/occasion_setup/form_link.sql
-- Suggestions consult the same global reservations (including tombstones) as
-- final writes. This is a preview, not a claim or an alternate allocator.
CREATE OR REPLACE FUNCTION public.suggest_occasion_setup_form_link(p_id uuid,p_title text,p_requested_link text DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE d public.occasion_setup_drafts; base text; candidate text; suffix integer:=1; year text;
BEGIN
 SELECT * INTO d FROM public.occasion_setup_drafts WHERE id=p_id;
 IF NOT FOUND OR auth.uid() IS NULL OR NOT public.can_create_occasion(d.unit) THEN
  RAISE insufficient_privilege USING MESSAGE='Draft access denied'; END IF;
 IF length(coalesce(p_title,''))>500 OR length(coalesce(p_requested_link,''))>80 THEN
  RAISE invalid_parameter_value USING MESSAGE='Invalid public link input'; END IF;
 base:=trim(both '-' from regexp_replace(public.f_unaccent(left(coalesce(p_title,''),500)),'[^a-z0-9]+','-','g'));
 base:=trim(trailing '-' from left(base,64));
 IF base='' THEN base:='akce'; END IF;
 year:=substring(coalesce(d.data->>'start',d.data->>'start_time','') from '^([0-9]{4})-');
 IF year IS NOT NULL AND base !~ '[0-9]{4}' THEN base:=base||'-'||year; END IF;
 candidate:=base;
 WHILE EXISTS(SELECT 1 FROM public.form_link_reservations WHERE slug=candidate) LOOP
  suffix:=suffix+1; candidate:=base||'-'||suffix;
  IF suffix>1000 THEN candidate:=base||'-'||left(replace(d.id::text,'-',''),8); EXIT; END IF;
 END LOOP;
 -- Deterministic bounded fallback, still checked rather than presumed free.
 IF EXISTS(SELECT 1 FROM public.form_link_reservations WHERE slug=candidate) THEN
  RAISE unique_violation USING MESSAGE='Public link suggestions exhausted'; END IF;
 RETURN jsonb_build_object('suggestion',candidate,'available',
  CASE WHEN p_requested_link IS NULL OR p_requested_link='' THEN NULL
  ELSE p_requested_link ~ '^[a-z0-9]+(-[a-z0-9]+)*$'
    AND NOT EXISTS(SELECT 1 FROM public.form_link_reservations WHERE slug=p_requested_link) END);
END $$;

-- Source: database/functions/eshop/swap_spot_tickets.sql
CREATE OR REPLACE FUNCTION public.swap_spot_pair_internal_v1(spot_id_1 BIGINT, spot_id_2 BIGINT)
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
    spot1 RECORD;
    spot2 RECORD;
    occasion_id_common BIGINT;
    has_permission BOOLEAN;
    now_time TIMESTAMP WITH TIME ZONE := NOW();
BEGIN
    -- 1. Input Validation
    IF spot_id_1 IS NULL OR spot_id_2 IS NULL THEN
        RAISE EXCEPTION 'Both spot_id_1 and spot_id_2 must be provided' USING ERRCODE = '22023';
    END IF;
    IF spot_id_1 = spot_id_2 THEN
        RAISE EXCEPTION 'Cannot swap a spot with itself' USING ERRCODE = '22023';
    END IF;

    PERFORM public.lock_spot_assignment_scope_internal_v1(ARRAY[spot_id_1,spot_id_2]);

    -- 2. Fetch Spot Data
    SELECT * INTO spot1 FROM eshop.spots WHERE id = spot_id_1 FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Spot 1 not found (ID: %)', spot_id_1 USING ERRCODE = 'P0002'; END IF;
    SELECT * INTO spot2 FROM eshop.spots WHERE id = spot_id_2 FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Spot 2 not found (ID: %)', spot_id_2 USING ERRCODE = 'P0002'; END IF;

    -- 3. Permission and Occasion Check
    IF spot1.occasion IS NULL OR spot2.occasion IS NULL THEN
         RAISE EXCEPTION 'Spots are missing occasion information' USING ERRCODE = '22004';
    END IF;
    IF spot1.occasion <> spot2.occasion THEN
        RAISE EXCEPTION 'Spots do not belong to the same occasion (Spot1: %, Spot2: %)', spot1.occasion, spot2.occasion USING ERRCODE = 'P0001';
    END IF;
    occasion_id_common := spot1.occasion;

    -- Check permission
    BEGIN
        SELECT can_write_orders(occasion_id_common) INTO has_permission;
    EXCEPTION
        WHEN undefined_function THEN RAISE EXCEPTION 'Permission check function can_write_orders() does not exist.' USING ERRCODE = '42883';
        WHEN OTHERS THEN RAISE EXCEPTION 'Error during permission check: %', SQLERRM;
    END;
    IF has_permission <> TRUE THEN
        RAISE EXCEPTION 'User is not authorized to edit order_ids for this occasion' USING ERRCODE = '42501';
    END IF;

    IF EXISTS(SELECT 1 FROM eshop.spots WHERE id IN(spot_id_1,spot_id_2)
      AND secret IS NOT NULL AND secret_expiration_time>clock_timestamp()) THEN
      RAISE object_not_in_prerequisite_state USING MESSAGE='SPOT_HELD'; END IF;
    -- Ticket locks follow the already locked order parents, in a stable order.
    PERFORM 1 FROM eshop.tickets WHERE id IN(SELECT ticket FROM eshop.order_product_ticket
      WHERE id IN(spot1.order_product_ticket,spot2.order_product_ticket)) ORDER BY id FOR UPDATE;

    -- 4. Main Swap Logic: Branch based on assignment status
    -- This logic is now greatly simplified by the helper functions.

    IF spot1.order_product_ticket IS NOT NULL AND spot2.order_product_ticket IS NOT NULL THEN
        -- ----------------------------------------------------------------
        -- CASE A: BOTH SPOTS ARE ASSIGNED
        -- ----------------------------------------------------------------

        -- Ticket 1 (from spot 1) moves to Spot 2, so it must adopt Spot 2's product.
        PERFORM public._swap_spots_update_ticket(spot1.order_product_ticket, spot2.product, spot_id_2);

        -- Ticket 2 (from spot 2) moves to Spot 1, so it must adopt Spot 1's product.
        PERFORM public._swap_spots_update_ticket(spot2.order_product_ticket, spot1.product, spot_id_1);

    ELSIF spot1.order_product_ticket IS NOT NULL OR spot2.order_product_ticket IS NOT NULL THEN
        -- ----------------------------------------------------------------
        -- CASE B/C: ONE SPOT IS ASSIGNED, ONE IS UNASSIGNED
        -- ----------------------------------------------------------------

        IF spot1.order_product_ticket IS NOT NULL THEN
            -- Spot 1 is assigned, Spot 2 is unassigned.
            -- Ticket 1 moves to Spot 2 and adopts Spot 2's product.
            PERFORM public._swap_spots_update_ticket(spot1.order_product_ticket, spot2.product, spot_id_2);
        ELSE
            -- Spot 2 is assigned, Spot 1 is unassigned.
            -- Ticket 2 moves to Spot 1 and adopts Spot 1's product.
            PERFORM public._swap_spots_update_ticket(spot2.order_product_ticket, spot1.product, spot_id_1);
        END IF;

    ELSE
        -- ----------------------------------------------------------------
        -- CASE D: BOTH SPOTS ARE UNASSIGNED
        -- ----------------------------------------------------------------
        -- Nothing to do.
        RETURN;
    END IF;

    -- 5. Final Spot Update
    -- This block runs for Cases A, B, and C.
    -- We ONLY swap the 'order_product_ticket' FK. The 'product' column
    -- on the spot (spot1.product, spot2.product) never changes.
    UPDATE eshop.spots
    SET
        order_product_ticket = CASE
            WHEN id = spot_id_1 THEN spot2.order_product_ticket -- Spot 1 gets Ticket 2
            WHEN id = spot_id_2 THEN spot1.order_product_ticket -- Spot 2 gets Ticket 1
        END
    WHERE id IN (spot_id_1, spot_id_2);

END;
$$;

-- Source: database/functions/blueprint/swap_spot_tickets_client_sync_v1.sql
CREATE OR REPLACE FUNCTION public.swap_spot_tickets_client_sync_v1(p_spot_1 bigint, p_spot_2 bigint, p_command_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path = public, extensions
AS $function$
DECLARE v_actor uuid:=auth.uid(); v_occasion bigint; v_begin jsonb; v_hash text;
  v_users uuid[];
BEGIN
  SELECT occasion INTO v_occasion FROM public.client_mutation_receipts WHERE command_id=p_command_id AND actor_id=v_actor AND command_name='inventory.spots.swap';
  IF NOT FOUND THEN
  SELECT min(s.occasion) INTO v_occasion FROM eshop.spots s
    WHERE s.id IN (p_spot_1,p_spot_2);
  END IF;
  IF v_actor IS NULL OR p_spot_1 IS NULL OR p_spot_2 IS NULL
    OR p_spot_1=p_spot_2 OR v_occasion IS NULL
    OR NOT public.can_write_orders(v_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='order editor required'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'spot1',p_spot_1,'spot2',p_spot_2)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,
    'inventory.spots.swap',v_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  IF (SELECT count(*) FROM eshop.spots s
      WHERE s.id IN (p_spot_1,p_spot_2) AND s.occasion=v_occasion)<>2
 THEN RAISE insufficient_privilege USING MESSAGE='foreign spot swap'; END IF;

  PERFORM public.lock_blueprint_scope_internal(ARRAY[v_occasion]);
  PERFORM public.lock_spot_assignment_scope_internal_v1(ARRAY[p_spot_1,p_spot_2]);
  SELECT COALESCE(array_agg(DISTINCT ou."user"),'{}'::uuid[]) INTO v_users
  FROM eshop.spots s JOIN eshop.order_product_ticket opt
    ON opt.id=s.order_product_ticket JOIN public.occasion_users ou
    ON ou.ticket=opt.ticket AND ou.occasion=v_occasion
  WHERE s.id IN (p_spot_1,p_spot_2);
  PERFORM public.swap_spot_tickets_internal_v1(p_spot_1,p_spot_2);
  RETURN public.complete_private_inventory_mutation_v1(p_command_id,v_occasion,
    'inventory.spots.swap',jsonb_build_array(jsonb_build_object(
      'entityType','spot_assignment','entityId',NULL,'operation','update',
      'safeLabel','Spot ticket swap','changedFields',jsonb_build_array(
        'order_product_ticket','product'))),v_users,jsonb_build_object(
          'spotIds',jsonb_build_array(p_spot_1,p_spot_2)));
END; $function$;

-- Source: database/functions/eshop/swap_spot_tickets.sql
CREATE OR REPLACE FUNCTION public.swap_spot_tickets_internal_v1(spot_id_1 bigint,spot_id_2 bigint)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE ids1 bigint[]; ids2 bigint[]; order_ids bigint[]; occ bigint; i integer;
BEGIN
 SELECT min(occasion) INTO occ FROM eshop.spots WHERE id IN(spot_id_1,spot_id_2);
 IF occ IS NULL OR (SELECT count(*) FROM eshop.spots WHERE id IN(spot_id_1,spot_id_2) AND occasion=occ)<>2 THEN
  RAISE EXCEPTION 'BLUEPRINT_SPOT_SCOPE_MISMATCH'; END IF;
 IF public.can_write_orders(occ) IS NOT TRUE THEN RAISE insufficient_privilege USING MESSAGE='order editor required'; END IF;
 PERFORM public.check_occasion_writable(occ);
 PERFORM public.lock_blueprint_scope_internal(ARRAY[occ]);
 ids1:=public.blueprint_selection_unit_spots_internal(spot_id_1);
 ids2:=public.blueprint_selection_unit_spots_internal(spot_id_2);
 IF cardinality(ids1)<>cardinality(ids2) OR ids1 && ids2 THEN RAISE EXCEPTION 'BLUEPRINT_UNIT_SIZE_MISMATCH'; END IF;
 PERFORM public.check_blueprint_selection_units_internal(ids1||ids2);
 SELECT array_agg(DISTINCT opt."order") INTO order_ids FROM eshop.spots s JOIN eshop.order_product_ticket opt ON opt.id=s.order_product_ticket WHERE s.id=ANY(ids1||ids2);
 PERFORM public.lock_order_capacity_scope_internal(order_ids);
 PERFORM public.lock_ticket_order_products_internal(o.id) FROM eshop.orders o WHERE id=ANY(order_ids) ORDER BY id;
 -- Destination products may differ from products currently held by those order_ids.
 PERFORM 1 FROM eshop.products WHERE id IN(SELECT product FROM eshop.spots WHERE id=ANY(ids1||ids2)) ORDER BY id FOR UPDATE;
 PERFORM 1 FROM eshop.payment_info WHERE id IN(SELECT payment_info FROM eshop.orders WHERE id=ANY(order_ids)) ORDER BY id FOR UPDATE;
 PERFORM 1 FROM eshop.spots WHERE id=ANY(ids1||ids2) ORDER BY id FOR UPDATE;
 IF EXISTS(SELECT 1 FROM eshop.spots s LEFT JOIN eshop.blueprint_seat_bindings b ON b.spot=s.id
  WHERE s.id=ANY(ids1||ids2) AND (b.blocked OR s.product IS NULL OR (s.secret IS NOT NULL AND s.secret_expiration_time>statement_timestamp()))) THEN
  RAISE EXCEPTION 'BLUEPRINT_SEAT_PROTECTED'; END IF;
 FOR i IN 1..cardinality(ids1) LOOP PERFORM public.swap_spot_pair_internal_v1(ids1[i],ids2[i]); END LOOP;
END $$;

-- Source: database/functions/activities/legacy_activity_facades.sql
-- Released legacy shapes remain adapters; the canonical lifecycle owns every write.
-- Two-step live publication cannot preserve atomicity and requires an upgrade.
CREATE OR REPLACE FUNCTION public.update_activities(p_occasion_id bigint,p_activities_data jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
BEGIN
 IF auth.uid() IS NULL OR NOT coalesce(public.can_write_activity_plan(p_occasion_id),false) THEN
  RETURN jsonb_build_object('code',403); END IF;
 RETURN jsonb_build_object('code',426,'message','Upgrade required for atomic activity publication');
END $$;

-- Source: database/functions/eshop_bank_accounts/update_bank_account.sql
CREATE OR REPLACE FUNCTION public.update_bank_account(
    p_id bigint,
    p_account_number text,
    p_title text,
    p_type text DEFAULT 'FIO',
    p_supported_currencies text[] DEFAULT NULL,
    p_account_number_human_readable text DEFAULT NULL,
    p_unit_id bigint DEFAULT NULL,
    p_creditor_name text DEFAULT NULL
)
RETURNS bigint
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
    v_id bigint;
    v_account_number text;
    v_operation_id uuid;
    v_request jsonb;
BEGIN
    PERFORM public.check_bank_account_writable(p_id);
    -- Prevent manual manipulation of CASH accounts
    IF p_type = 'CASH' THEN
        RAISE EXCEPTION 'CASH_ACCOUNT_MANUAL_UPDATE_FORBIDDEN';
    END IF;

    IF char_length(p_title)>120 THEN RAISE EXCEPTION 'BANK_ACCOUNT_TITLE_TOO_LONG'; END IF;

    -- Input normalization
    v_account_number := TRIM(p_account_number);

    IF p_id IS NULL THEN
        -- A new account has no account admin yet: a managed target unit is
        -- mandatory, and creation grants the second role atomically below.
        IF p_unit_id IS NULL THEN
            RAISE EXCEPTION 'A managed unit is required to create a bank account.' USING ERRCODE='42501';
        END IF;
        IF NOT public.can_manage_unit_bank_accounts(p_unit_id) THEN
            RAISE insufficient_privilege USING MESSAGE='User is not manager.';
        END IF;

        -- Check for duplicate account number on insert
        IF EXISTS (SELECT 1 FROM eshop.bank_accounts WHERE account_number = v_account_number) THEN
             RAISE EXCEPTION 'ACCOUNT_NUMBER_EXISTS';
        END IF;

        INSERT INTO eshop.bank_accounts (account_number, title, type, supported_currencies, account_number_human_readable, creditor_name)
        VALUES (v_account_number, p_title, p_type, p_supported_currencies, p_account_number_human_readable, nullif(trim(p_creditor_name), ''))
        RETURNING id INTO v_id;

        -- Automatically make the creator an Admin
        INSERT INTO eshop.bank_account_users (bank_account, "user", is_admin)
        VALUES (v_id, auth.uid(), true);

        -- Automatically link to unit if provided
        IF p_unit_id IS NOT NULL THEN
             INSERT INTO eshop.unit_bank_accounts (unit, bank_account, priority)
             VALUES (p_unit_id, v_id, 0);
        END IF;
    ELSE
        -- Check for duplicate account number on update (exclude current id)
        IF EXISTS (SELECT 1 FROM eshop.bank_accounts WHERE account_number = v_account_number AND id != p_id) THEN
             RAISE EXCEPTION 'ACCOUNT_NUMBER_EXISTS';
        END IF;

        -- Security Check: Caller must be an Admin of the bank account
        IF NOT public.can_manage_bank_account(p_id) THEN
            RAISE EXCEPTION 'Permission denied: Only bank account admins can update details.' USING ERRCODE='42501';
        END IF;

        PERFORM 1 FROM eshop.bank_accounts WHERE id=p_id FOR UPDATE;
        IF EXISTS (SELECT 1 FROM eshop.bank_sync_connections WHERE bank_account_id=p_id)
          AND EXISTS (SELECT 1 FROM eshop.bank_accounts WHERE id=p_id
            AND (account_number IS DISTINCT FROM v_account_number OR type IS DISTINCT FROM p_type)) THEN
          RAISE EXCEPTION 'BANK_SYNC_ACCOUNT_IDENTITY_IMMUTABLE';
        END IF;
        IF EXISTS(SELECT 1 FROM eshop.payment_reference_accounts a JOIN eshop.payment_reference_namespaces n ON n.id=a.namespace_id
          WHERE a.bank_account_id=p_id AND (n.canonical_account IS DISTINCT FROM public.canonical_payment_reference_account_internal(v_account_number)
           OR p_type='CASH')) THEN RAISE EXCEPTION 'PAYMENT_REFERENCE_ACCOUNT_IDENTITY_IMMUTABLE'; END IF;
        UPDATE eshop.bank_accounts
        SET
            account_number = v_account_number,
            title = p_title,
            type = p_type,
            supported_currencies = p_supported_currencies,
            account_number_human_readable = p_account_number_human_readable,
            creditor_name = nullif(trim(p_creditor_name), ''),
            updated_at = NOW()
        WHERE id = p_id
        RETURNING id INTO v_id;
    END IF;
    -- Local details and the durable remote update intent commit together.
    IF p_id IS NOT NULL AND EXISTS(SELECT 1 FROM eshop.bank_sync_connections WHERE bank_account_id=v_id) THEN
      v_operation_id := gen_random_uuid();
      v_request := jsonb_build_object('operation','update_details','operation_id',v_operation_id,'account_id',v_id);
      INSERT INTO eshop.bank_sync_operations(id,bank_account_id,actor,operation,payload_sha256,state,request)
        VALUES(v_operation_id,v_id,auth.uid(),'update_details',encode(extensions.digest(v_request::text,'sha256'),'hex'),'pending',v_request);
    END IF;
    RETURN v_id;
END;
$$;

-- Source: database/functions/eshop_bank_accounts/update_bank_account_user.sql
CREATE OR REPLACE FUNCTION public.update_bank_account_user(
    p_bank_account_id bigint,
    p_user_email text,
    p_is_admin boolean,
    p_is_support boolean
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
    v_user_id uuid;
BEGIN
    -- Security Check: Caller must be an Admin of the bank account
    IF NOT public.can_manage_bank_account(p_bank_account_id) THEN
        RAISE EXCEPTION 'Permission denied: Only bank account admins can manage users.' USING ERRCODE='42501';
    END IF;

    -- Find user by email (assuming email_readonly is populated and unique-ish for lookup)
    -- In a real app, might want a better user lookup, but this fits the pattern
    SELECT id INTO v_user_id FROM public.user_info WHERE email_readonly = p_user_email LIMIT 1;

    IF v_user_id IS NULL THEN
        RAISE EXCEPTION 'User not found';
    END IF;

    -- If both flags are false or null, remove the user
    IF (p_is_admin IS NULL OR p_is_admin = false) AND (p_is_support IS NULL OR p_is_support = false) THEN
        DELETE FROM eshop.bank_account_users
        WHERE bank_account = p_bank_account_id AND "user" = v_user_id;
    ELSE
        IF EXISTS (SELECT 1 FROM eshop.bank_account_users WHERE bank_account = p_bank_account_id AND "user" = v_user_id) THEN
            UPDATE eshop.bank_account_users
            SET is_admin = COALESCE(p_is_admin, false), is_support = COALESCE(p_is_support, false)
            WHERE bank_account = p_bank_account_id AND "user" = v_user_id;
        ELSE
            INSERT INTO eshop.bank_account_users (bank_account, "user", is_admin, is_support)
            VALUES (p_bank_account_id, v_user_id, COALESCE(p_is_admin, false), COALESCE(p_is_support, false));
        END IF;
    END IF;
END;
$$;

-- Source: database/functions/blueprint/update_blueprint_client_sync_v1.sql
CREATE OR REPLACE FUNCTION public.update_blueprint_client_sync_v1(
  p_blueprint jsonb,p_command_id uuid
) RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = public, extensions AS $$
DECLARE v_actor uuid:=auth.uid(); v_occasion bigint; v_blueprint bigint;
  v_begin jsonb; v_hash text; v_users uuid[]; v_result jsonb; v_reason text; v_detail text; v_issue jsonb;
BEGIN
  IF p_blueprint IS NULL OR jsonb_typeof(p_blueprint)<>'object'
    OR octet_length(p_blueprint::text)>8388608 THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid blueprint aggregate'; END IF;
  SELECT occasion INTO v_occasion FROM public.client_mutation_receipts WHERE command_id=p_command_id AND actor_id=v_actor AND command_name='inventory.blueprint.save';
  IF NOT FOUND THEN
  v_occasion:=NULLIF(p_blueprint->>'occasion','')::bigint;
  v_blueprint:=NULLIF(p_blueprint->>'id','')::bigint;
  IF v_blueprint IS NOT NULL THEN SELECT occasion INTO v_occasion FROM eshop.blueprints WHERE id=v_blueprint; END IF;
  ELSE v_blueprint:=NULLIF(p_blueprint->>'id','')::bigint; END IF;
  IF v_actor IS NULL OR v_occasion IS NULL
    OR public.can_write_blueprints(v_occasion) IS NOT TRUE THEN
    RAISE insufficient_privilege USING MESSAGE='blueprint editor required'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'occasion',v_occasion,'blueprint',p_blueprint)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,
    'inventory.blueprint.save',v_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  IF v_blueprint IS NOT NULL AND NOT EXISTS (SELECT 1 FROM eshop.blueprints b WHERE b.id=v_blueprint AND b.occasion=v_occasion) THEN RAISE insufficient_privilege USING MESSAGE='foreign blueprint'; END IF;
  PERFORM public.lock_blueprint_scope_internal(ARRAY[v_occasion]);
  SELECT COALESCE(array_agg(DISTINCT ou."user"),'{}'::uuid[]) INTO v_users
  FROM public.occasion_users ou JOIN eshop.order_product_ticket opt
    ON opt.ticket=ou.ticket JOIN eshop.spots s
    ON s.order_product_ticket=opt.id
  WHERE ou.occasion=v_occasion AND s.occasion=v_occasion;
  BEGIN
    IF p_blueprint->'layout' IS NULL OR p_blueprint->'layout'='null'::jsonb THEN RAISE check_violation USING MESSAGE='BLUEPRINT_LAYOUT_REQUIRED'; END IF;
    v_result:=public.save_blueprint_layout_internal_v1(p_blueprint);
  EXCEPTION WHEN check_violation OR raise_exception OR invalid_text_representation OR not_null_violation OR unique_violation OR foreign_key_violation THEN
    GET STACKED DIAGNOSTICS v_reason=MESSAGE_TEXT,v_detail=PG_EXCEPTION_DETAIL;
    v_issue:=jsonb_build_object('reason',v_reason);
    IF left(coalesce(v_detail,''),1)='{' THEN
      BEGIN v_issue:=v_issue||jsonb_strip_nulls(jsonb_build_object('nodeId',(v_detail::jsonb)->'nodeId','spotId',(v_detail::jsonb)->'spotId','groupNodeId',(v_detail::jsonb)->'groupNodeId'));
      EXCEPTION WHEN invalid_text_representation THEN NULL; END;
    END IF;
    v_result:=jsonb_build_object('code',409,'reason',CASE WHEN SQLSTATE IN ('23514','P0001') THEN v_reason ELSE 'BLUEPRINT_INVALID_INPUT' END,
      'issues',jsonb_build_array(v_issue),
      'layout_revision',(SELECT layout_revision FROM eshop.blueprints WHERE id=v_blueprint));
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'rejected',409,v_result);
  END;
  RETURN public.complete_private_inventory_mutation_v1(p_command_id,v_occasion,
    'inventory.blueprint.save',jsonb_build_array(jsonb_build_object(
      'entityType','blueprint','entityId',v_result->>'blueprint_id',
      'operation',CASE WHEN v_blueprint IS NULL THEN 'insert' ELSE 'update' END,
      'safeLabel',left(p_blueprint->>'title',240),'changedFields',jsonb_build_array(
        'layout','bindings'))),v_users,v_result);
END; $$;

-- Source: database/functions/others/update_email_template.sql
CREATE OR REPLACE FUNCTION public.update_email_template(p_data jsonb)
RETURNS void
SECURITY DEFINER
LANGUAGE plpgsql
SET search_path = public, extensions
AS $$
DECLARE
  v_occ   bigint;
  v_unit  bigint;
  v_org   bigint;
  v_code  text;
  v_existing_id bigint;
  v_actual_unit bigint;
  v_actual_org bigint;
BEGIN
  -- Extract values from input JSON.
  v_occ  := CASE WHEN p_data ? 'occasion' THEN (p_data ->> 'occasion')::bigint ELSE NULL END;
  v_unit := CASE WHEN p_data ? 'unit' THEN (p_data ->> 'unit')::bigint ELSE NULL END;
  v_org := (p_data ->> 'organization')::bigint;
  v_code := p_data ->> 'code';

  -- Resolve the actual hierarchy before authorizing template writes.
  IF v_occ IS NOT NULL THEN
    SELECT unit, organization INTO v_actual_unit, v_actual_org FROM public.occasions WHERE id=v_occ;
    IF NOT FOUND OR (v_unit IS NOT NULL AND v_unit IS DISTINCT FROM v_actual_unit)
        OR (v_org IS NOT NULL AND v_org IS DISTINCT FROM v_actual_org) THEN
      RAISE insufficient_privilege USING MESSAGE='Invalid email template hierarchy';
    END IF;
    v_unit := v_actual_unit;
    v_org := v_actual_org;
    IF NOT public.is_service_role() AND public.can_write_occasion_email_templates(v_occ) IS NOT TRUE THEN
      RAISE insufficient_privilege USING MESSAGE='Occasion template write denied';
    END IF;
  ELSIF v_unit IS NOT NULL THEN
    SELECT organization INTO v_actual_org FROM public.units WHERE id=v_unit;
    IF NOT FOUND OR (v_org IS NOT NULL AND v_org IS DISTINCT FROM v_actual_org) THEN
      RAISE insufficient_privilege USING MESSAGE='Invalid email template hierarchy';
    END IF;
    v_org := v_actual_org;
    IF NOT public.is_service_role() AND public.can_write_unit_email_templates(v_unit) IS NOT TRUE THEN
      RAISE insufficient_privilege USING MESSAGE='Unit template write denied';
    END IF;
  ELSIF NOT public.is_service_role() THEN
    IF v_org IS NULL OR public.can_manage_organization_email_templates(v_org) IS NOT TRUE THEN
      RAISE insufficient_privilege USING MESSAGE='Organization template write denied';
    END IF;
  END IF;

  -- An occasion override is identified by occasion + code. Ancestors are
  -- metadata, not identity; the partial unique index also fences concurrent saves.
  IF v_occ IS NOT NULL THEN
    INSERT INTO public.email_templates (html, occasion, subject, organization, code, unit, title)
    VALUES (p_data->>'html', v_occ, p_data->>'subject', v_org, v_code, v_unit, p_data->>'title')
    ON CONFLICT (occasion, code) WHERE occasion IS NOT NULL
    DO UPDATE SET html=EXCLUDED.html, subject=EXCLUDED.subject, title=EXCLUDED.title,
                  unit=EXCLUDED.unit, organization=EXCLUDED.organization;
    RETURN;
  END IF;

  -- Try to find an existing email template matching the given context and code.
  SELECT id
    INTO v_existing_id
  FROM public.email_templates
  WHERE
    ((occasion = v_occ) OR (occasion IS NULL AND v_occ IS NULL))
    AND ((unit = v_unit) OR (unit IS NULL AND v_unit IS NULL))
    AND ((organization = v_org) OR (organization IS NULL AND v_org IS NULL))
    AND code = v_code
  LIMIT 1;

  IF FOUND THEN
    -- Update the existing record.
    UPDATE public.email_templates
    SET
      html    = p_data ->> 'html',
      subject = p_data ->> 'subject',
      title   = p_data ->> 'title'
    WHERE id = v_existing_id;
  ELSE
    -- Insert a new record.
    INSERT INTO public.email_templates (
      html,
      occasion,
      subject,
      organization,
      code,
      unit,
      title
    )
    VALUES (
      p_data ->> 'html',
      v_occ,
      p_data ->> 'subject',
      v_org,
      v_code,
      v_unit,
      p_data ->> 'title'
    );
  END IF;
END;
$$;

-- Source: database/functions/others/update_entity_email_banner.sql
CREATE OR REPLACE FUNCTION public.update_entity_email_banner(p_entity_type text, p_entity_id bigint, p_banner_url text)
    returns void
    language plpgsql
    security definer
SET search_path = public, extensions
as
$$
declare
    v_org_id bigint;
    v_entity_title text;
    v_new_html text;
    v_before jsonb;
begin
    -- 1. Validate Entity Type and Permissions
    if p_entity_type = 'occasion' then
        if (public.can_write_occasion_email_templates(p_entity_id) IS NOT TRUE) then
            perform public.raise_error('permission_denied');
        end if;

        SELECT data INTO v_before FROM public.occasions WHERE id=p_entity_id FOR UPDATE;
        -- Update Occasion Data
        update public.occasions
        set data = jsonb_set(coalesce(data, '{}'), '{email_banner}', coalesce(to_jsonb(p_banner_url),'null'::jsonb))
        where id = p_entity_id
        returning organization, title into v_org_id, v_entity_title;

    elsif p_entity_type = 'unit' then
        if (public.can_write_unit_email_templates(p_entity_id) IS NOT TRUE) then
            perform public.raise_error('permission_denied');
        end if;

        SELECT data INTO v_before FROM public.units WHERE id=p_entity_id FOR UPDATE;
        -- Update Unit Data
        update public.units
        set data = jsonb_set(coalesce(data, '{}'), '{email_banner}', coalesce(to_jsonb(p_banner_url),'null'::jsonb))
        where id = p_entity_id
        returning organization, title into v_org_id, v_entity_title;

    else
        raise exception 'Invalid entity type: %', p_entity_type;
    end if;

    IF v_before IS DISTINCT FROM (CASE WHEN p_entity_type='occasion'
      THEN (SELECT data FROM public.occasions WHERE id=p_entity_id)
      ELSE (SELECT data FROM public.units WHERE id=p_entity_id) END) THEN
      INSERT INTO public.client_aggregate_versions(aggregate_type,scope_type,scope_id,aggregate_id,version)
      VALUES(p_entity_type,p_entity_type,p_entity_id,p_entity_id::text,1)
      ON CONFLICT(aggregate_type,scope_type,scope_id,aggregate_id) DO UPDATE
      SET version=public.client_aggregate_versions.version+1,updated_at=clock_timestamp();
    END IF;

    -- 2. Handle HTML Wrapper Logic
    if p_banner_url is not null then
        -- Construct Custom HTML
        v_new_html := '<div style="font-family: Arial, sans-serif; font-size: 16px; max-width: 680px; margin: 0 auto;">';
        v_new_html := v_new_html || '<div style="text-align: center;">';
        v_new_html := v_new_html || '<img src="' || p_banner_url || '" alt="' || coalesce(v_entity_title, 'Banner') || '" style="width: 100%; height: auto; display: block;">';
        v_new_html := v_new_html || '</div>';
        v_new_html := v_new_html || '<div style="margin-top: 10px; margin-bottom: 10px;">';
        v_new_html := v_new_html || '{{content}}';
        v_new_html := v_new_html || '</div></div>';

        -- Upsert Wrapper
        if p_entity_type = 'occasion' then
             -- For occasion, check existing wrapper
            if exists (select 1 from public.email_wrappers where occasion = p_entity_id) then
                update public.email_wrappers set html = v_new_html where occasion = p_entity_id;
            else
                insert into public.email_wrappers (occasion, organization, unit, title, html)
                values (p_entity_id, v_org_id, (select unit from occasions where id = p_entity_id), 'Occasion Banner Wrapper', v_new_html);
            end if;
        elsif p_entity_type = 'unit' then
             -- For unit (occasion is null)
            if exists (select 1 from public.email_wrappers where unit = p_entity_id and occasion is null) then
                update public.email_wrappers set html = v_new_html where unit = p_entity_id and occasion is null;
            else
                insert into public.email_wrappers (occasion, organization, unit, title, html)
                values (null, v_org_id, p_entity_id, 'Unit Banner Wrapper', v_new_html);
            end if;
        end if;
    else
        -- 3. Banner Removed -> Delete Wrapper
        if p_entity_type = 'occasion' then
            delete from public.email_wrappers where occasion = p_entity_id;
        elsif p_entity_type = 'unit' then
            delete from public.email_wrappers where unit = p_entity_id and occasion is null;
        end if;
    end if;
end;
$$;

-- Source: database/functions/eshop_forms/update_form_client_sync_v1.sql
CREATE OR REPLACE FUNCTION public.update_form_client_sync_v1(p_form jsonb, p_command_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path = public, extensions
AS $function$
DECLARE v_actor uuid:=auth.uid(); v_occasion bigint; v_form bigint;
  v_begin jsonb; v_hash text; v_version bigint; v_expected bigint; v_users uuid[]; v_result jsonb; v_check record; v_current bigint;
BEGIN
  IF p_form IS NULL OR jsonb_typeof(p_form)<>'object'
    OR octet_length(p_form::text)>4194304 THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid form aggregate'; END IF;
  v_occasion:=NULLIF(p_form->>'occasion','')::bigint;
  v_form:=NULLIF(p_form->>'id','')::bigint;
  IF v_actor IS NULL OR v_occasion IS NULL OR v_form IS NULL
    OR NOT public.can_write_orders(v_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='order editor required'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'occasion',v_occasion,'form',p_form)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,
    'inventory.form.save',v_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  IF NOT EXISTS(SELECT 1 FROM public.forms WHERE id=v_form AND occasion=v_occasion) THEN RAISE insufficient_privilege USING MESSAGE='foreign form'; END IF;
  -- Parent order matches checkout: form, product, blueprint, then seats.
  PERFORM 1 FROM public.forms WHERE id=v_form AND occasion=v_occasion FOR UPDATE;
  PERFORM 1 FROM eshop.product_types WHERE occasion=v_occasion ORDER BY id FOR UPDATE;
  PERFORM 1 FROM eshop.products WHERE occasion=v_occasion ORDER BY id FOR UPDATE;
  IF v_form IS NOT NULL THEN
    INSERT INTO public.client_aggregate_versions(aggregate_type,scope_type,scope_id,aggregate_id,version)
    VALUES('form','occasion',v_occasion,v_form::text,0) ON CONFLICT DO NOTHING;
    SELECT version INTO v_version FROM public.client_aggregate_versions
    WHERE aggregate_type='form' AND scope_type='occasion' AND scope_id=v_occasion AND aggregate_id=v_form::text FOR UPDATE;
  ELSE v_version:=0; END IF;
  -- Missing baseline remains an installed-client adapter, explicitly not MCP-ready.
  v_expected:=CASE WHEN p_form ? 'expected_aggregate_version' THEN (p_form->>'expected_aggregate_version')::bigint ELSE v_version END;
  IF v_expected IS DISTINCT FROM v_version THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'conflict',409,jsonb_build_object('aggregate_version',v_version)); END IF;
  -- These maps were frozen when the editor loaded. No read-before-write rebasing.
  -- Missing maps are the bounded released-client facade, not MCP-ready authoring.
  IF p_form ? 'expected_product_versions' OR p_form ? 'expected_product_type_versions' THEN
    IF jsonb_typeof(p_form->'expected_product_versions') IS DISTINCT FROM 'object'
      OR jsonb_typeof(p_form->'expected_product_type_versions') IS DISTINCT FROM 'object' THEN
      RAISE invalid_parameter_value USING MESSAGE='original product versions required'; END IF;
    FOR v_check IN
      SELECT DISTINCT 'product'::text kind, (p->>'id')::bigint id FROM jsonb_array_elements(coalesce(p_form->'form_fields','[]')) f
        CROSS JOIN LATERAL jsonb_array_elements(coalesce(nullif(f#>'{product_type,products}','null'),'[]')) p WHERE p->>'id' IS NOT NULL
      UNION SELECT 'product',value::bigint FROM jsonb_array_elements_text(coalesce(p_form->'deleted_product_ids','[]'))
      UNION SELECT DISTINCT 'product',p.id FROM eshop.products p JOIN public.form_fields ff ON ff.product_type=p.product_type
        WHERE ff.form=v_form AND ff.id IN (SELECT value::bigint FROM jsonb_array_elements_text(coalesce(p_form->'deleted_field_ids','[]')))
      UNION SELECT DISTINCT 'product_type',(f#>>'{product_type,id}')::bigint FROM jsonb_array_elements(coalesce(p_form->'form_fields','[]')) f
        WHERE f#>>'{product_type,id}' IS NOT NULL
      ORDER BY 1,2
    LOOP
      IF NOT (CASE v_check.kind WHEN 'product' THEN p_form->'expected_product_versions'
        ELSE p_form->'expected_product_type_versions' END) ? v_check.id::text THEN
        RAISE invalid_parameter_value USING MESSAGE='missing original product baseline'; END IF;
      IF (v_check.kind='product' AND NOT EXISTS(SELECT 1 FROM eshop.products WHERE id=v_check.id AND occasion=v_occasion))
        OR (v_check.kind='product_type' AND NOT EXISTS(SELECT 1 FROM eshop.product_types WHERE id=v_check.id AND occasion=v_occasion)) THEN
        RETURN public.complete_client_mutation_outcome_v1(p_command_id,'conflict',409,jsonb_build_object('entity_type',v_check.kind,'entity_id',v_check.id,'deleted',true)); END IF;
      SELECT coalesce(v.version,0) INTO v_current FROM (SELECT 1) seed LEFT JOIN public.client_aggregate_versions v
        ON v.aggregate_type=v_check.kind AND v.scope_type='occasion' AND v.scope_id=v_occasion AND v.aggregate_id=v_check.id::text;
      IF ((CASE v_check.kind WHEN 'product' THEN p_form->'expected_product_versions' ELSE p_form->'expected_product_type_versions' END)->>v_check.id::text)::bigint IS DISTINCT FROM v_current THEN
        RETURN public.complete_client_mutation_outcome_v1(p_command_id,'conflict',409,
          jsonb_build_object('aggregate_version',v_version,'entity_type',v_check.kind,'entity_id',v_check.id,'entity_version',v_current));
      END IF;
    END LOOP;
  END IF;
  SELECT COALESCE(array_agg(DISTINCT ou."user"),'{}'::uuid[]) INTO v_users
  FROM public.occasion_users ou JOIN eshop.order_product_ticket opt
    ON opt.ticket=ou.ticket JOIN eshop.products p ON p.id=opt.product
  WHERE ou.occasion=v_occasion AND p.occasion=v_occasion;
  BEGIN
    v_result:=public.update_form_internal_v1(p_form-'expected_aggregate_version'-'expected_product_versions'-'expected_product_type_versions');
    IF coalesce((v_result->>'code')::integer,500)<>200 THEN
      RAISE SQLSTATE 'P0F01' USING MESSAGE='authoring domain rejected'; END IF;
  EXCEPTION WHEN SQLSTATE 'P0F01' THEN NULL;
  END;
  IF coalesce((v_result->>'code')::integer,500)<>200 THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'rejected',
      CASE WHEN (v_result->>'code')::integer BETWEEN 100 AND 599 THEN (v_result->>'code')::integer ELSE 400 END,v_result); END IF;
  v_form:=(v_result->>'form_id')::bigint;
  INSERT INTO public.client_aggregate_versions(aggregate_type,scope_type,scope_id,aggregate_id,version)
    VALUES('form','occasion',v_occasion,v_form::text,1)
    ON CONFLICT(aggregate_type,scope_type,scope_id,aggregate_id) DO UPDATE
    SET version=public.client_aggregate_versions.version+1,updated_at=clock_timestamp()
    RETURNING version INTO v_version;
  v_result:=v_result||jsonb_build_object('aggregate_version',v_version,
    'product_versions',public.get_ticketing_product_versions_internal_v1(v_occasion,'product'),
    'product_type_versions',public.get_ticketing_product_versions_internal_v1(v_occasion,'product_type'));
  RETURN public.complete_private_inventory_mutation_v1(p_command_id,v_occasion,
    'inventory.form.save',jsonb_build_array(jsonb_build_object(
      'entityType','form','entityId',v_form,'operation','update',
      'safeLabel',left(p_form->>'title',240),'changedFields',jsonb_build_array(
        'configuration','products'))),v_users,v_result);
END; $function$;

-- Source: database/functions/eshop_forms/update_form.sql
CREATE OR REPLACE FUNCTION public.update_form_internal_v1(input_data JSONB)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
    ----------------------------------------------------------------------------
    -- Declarations
    ----------------------------------------------------------------------------
    result JSONB;
    deleted_fields BIGINT[];
    deleted_products BIGINT[];
    deletion_reason TEXT;
    deletion_row RECORD;

    form_id          BIGINT;               -- ID of the form being created/updated
    occasion_id      BIGINT;               -- ID of the occasion to which the form belongs
    now_ts           TIMESTAMPTZ := NOW(); -- Current timestamp for record updates

    link_param           TEXT;         -- Unique link for the form, must not conflict within the same org
    occasion_org         BIGINT;       -- Organization stored in the occasions table
    occasion_unit        BIGINT;       -- The 'unit' that must match for bank accounts
    conflict_check       INT;          -- Used for verifying uniqueness constraints
    deadline_val         BIGINT;       -- Field for validating form deadlines
    price_val            NUMERIC;      -- Field for validating product price

    bank_account_val     BIGINT;       -- Bank account from input_data
    bank_account_unit    BIGINT;       -- Unit of the bank account, must match occasion_unit

    v_seconds_before_deadline BIGINT; -- For calling the reminder queue function

    ----------------------------------------------------------------------------
    -- Since product_type data is now inside form_fields, we no longer read from
    -- a top-level product_types array. Instead, we will parse product_type objects
    -- directly from each form_field (if present).
    ----------------------------------------------------------------------------

    product_type_data    JSONB;        -- The JSONB data for product_type within a form_field
    product_type_id      BIGINT;       -- ID (new or existing) of the product_type
    product_type_occ     BIGINT;       -- For checking product_type's occasion

    products_data        JSONB;        -- JSONB array of products inside a product_type
    product_array_data   JSONB;        -- Rebuilt array of products
    product_data         JSONB;        -- Each product object from the products array
    product_id           BIGINT;       -- ID for a product (new or existing)
    product_occ          BIGINT;       -- Occasion check for an existing product

    ----------------------------------------------------------------------------
    -- form_fields data
    ----------------------------------------------------------------------------
    form_fields_data     JSONB := '[]'::JSONB; -- Final array of form_fields for the response
    field_data           JSONB;                -- Each form_field from input
    field_id             BIGINT;               -- ID for a form_field (new or existing)
    field_product_type   BIGINT;               -- Will store the final product_type.id for the form_field
    field_occ            BIGINT;               -- Verify product_type's occasion if referenced
BEGIN
    BEGIN
        /* All logic is inside this sub-block so we can catch exceptions similarly
           to how it's done in create_ticket_order, with a single EXCEPTION WHEN OTHERS THEN.
           We raise exceptions in JSON form, and if it's JSON, we return it as-is; otherwise,
           we build a default JSON error response. */

        ----------------------------------------------------------------------------
        -- Begin main logic
        ----------------------------------------------------------------------------

        -- Validate that input_data and essential fields exist
        IF input_data IS NULL THEN
            RAISE EXCEPTION '%',
                JSONB_BUILD_OBJECT('code', 4001, 'message', 'Input data is missing')::TEXT;
        END IF;

        IF input_data->>'occasion' IS NULL THEN
            RAISE EXCEPTION '%',
                JSONB_BUILD_OBJECT('code', 4002, 'message', 'Missing occasion ID in input data')::TEXT;
        END IF;

        occasion_id := (input_data->>'occasion')::BIGINT;
        IF occasion_id IS NULL THEN
            RAISE EXCEPTION '%',
                JSONB_BUILD_OBJECT('code', 4002, 'message', 'Invalid or missing occasion ID')::TEXT;
        END IF;

        -- Ensure user is authorized to edit this occasion
        IF NOT COALESCE(can_write_orders(occasion_id), false) THEN
            RAISE EXCEPTION '%',
                JSONB_BUILD_OBJECT('code', 403, 'message', 'User is not authorized to edit this occasion')::TEXT;
        END IF;

        -- Retrieve the occasion's organization and unit
        SELECT o.organization, o.unit
          INTO occasion_org, occasion_unit
          FROM public.occasions o
         WHERE o.id = occasion_id
         LIMIT 1;

        IF occasion_org IS NULL OR occasion_unit IS NULL THEN
            RAISE EXCEPTION '%',
                JSONB_BUILD_OBJECT('code', 4017, 'message', 'Occasion not found or missing required fields')::TEXT;
        END IF;

        IF NOT public.is_service_role() AND NOT public.can_author_forms(occasion_id) THEN RAISE insufficient_privilege USING MESSAGE='form editor required'; END IF;
        form_id := NULLIF(input_data->>'id','')::bigint;
        IF form_id IS NULL THEN
          INSERT INTO public.forms(created_at,occasion) VALUES(now_ts,occasion_id) RETURNING id INTO form_id;
          link_param := public.reserve_public_link_internal('form',form_id,input_data->>'link',true);
        ELSE
          IF NOT EXISTS (SELECT 1 FROM public.forms WHERE id=form_id AND occasion=occasion_id) THEN
            RAISE invalid_parameter_value USING MESSAGE='Form does not match occasion'; END IF;
          link_param := public.reserve_public_link_internal('form',form_id,input_data->>'link',false);
        END IF;

        -- Explicit removals are part of this save transaction, never inferred from
        -- omitted fields in partial/older-client payloads. Exceptions roll back the save.
        SELECT COALESCE(array_agg(value::bigint), '{}'::bigint[]) INTO deleted_fields
        FROM jsonb_array_elements_text(COALESCE(input_data->'deleted_field_ids', '[]'::jsonb));
        SELECT COALESCE(array_agg(value::bigint), '{}'::bigint[]) INTO deleted_products
        FROM jsonb_array_elements_text(COALESCE(input_data->'deleted_product_ids', '[]'::jsonb));

        IF EXISTS (SELECT 1 FROM unnest(deleted_fields) AS removed(id) WHERE NOT EXISTS (
            SELECT 1 FROM public.form_fields ff WHERE ff.id = removed.id AND ff.form = form_id))
          OR EXISTS (SELECT 1 FROM unnest(deleted_products) AS removed(id) WHERE NOT EXISTS (
            SELECT 1 FROM eshop.products p JOIN public.form_fields ff ON ff.product_type = p.product_type
            WHERE p.id = removed.id AND ff.form = form_id)) THEN
            RAISE EXCEPTION 'FORM_DELETE_changed';
        END IF;

        -- Removing the ticket container also removes its nested fields.
        IF EXISTS (SELECT 1 FROM public.form_fields ff WHERE ff.id = ANY(deleted_fields) AND ff.type = 'ticket') THEN
            SELECT deleted_fields || COALESCE(array_agg(ff.id), '{}'::bigint[]) INTO deleted_fields
            FROM public.form_fields ff WHERE ff.form = form_id AND ff.is_ticket_field;
        END IF;

        -- Serialize product-type references and product FK insertions before checking
        -- usage, including ON DELETE CASCADE inventory links.
        PERFORM 1 FROM eshop.product_types pt WHERE pt.id IN (
            SELECT ff.product_type FROM public.form_fields ff WHERE ff.id = ANY(deleted_fields)
            UNION SELECT p.product_type FROM eshop.products p WHERE p.id = ANY(deleted_products)
        ) ORDER BY pt.id FOR UPDATE;
        SELECT deleted_products || COALESCE(array_agg(p.id), '{}'::bigint[]) INTO deleted_products
        FROM eshop.products p JOIN public.form_fields ff ON ff.product_type = p.product_type
        WHERE ff.id = ANY(deleted_fields);
        PERFORM 1 FROM eshop.products p WHERE p.id = ANY(deleted_products) ORDER BY p.id FOR UPDATE;

        FOR deletion_row IN SELECT ff.* FROM public.form_fields ff WHERE ff.id = ANY(deleted_fields)
        LOOP
            SELECT CASE WHEN EXISTS (
          SELECT 1 FROM (
            SELECT current_order.id, current_order.form, current_order.data FROM eshop.orders current_order WHERE current_order.form = ff.form
          ) o
          WHERE o.form = ff.form AND (
            EXISTS (SELECT 1 FROM jsonb_array_elements(CASE WHEN jsonb_typeof(o.data->'fields') = 'array' THEN o.data->'fields' ELSE '[]'::jsonb END) answer
              WHERE answer ? ff.id::text AND answer->(ff.id::text) NOT IN ('null'::jsonb, '""'::jsonb, '[]'::jsonb, '{}'::jsonb))
            OR (ff.type = 'ticket' AND jsonb_path_exists(o.data, '$.tickets[*]'))
            OR (ff.type = 'note' AND ff.is_ticket_field AND jsonb_path_exists(o.data, '$.tickets[*] ? (@.note != null && @.note != "")'))
            OR (ff.type = 'ticket' AND EXISTS (SELECT 1 FROM eshop.order_product_ticket opt WHERE opt."order" = o.id AND opt.ticket IS NOT NULL))
            OR (ff.type = 'note' AND ff.is_ticket_field AND EXISTS (
              SELECT 1 FROM eshop.order_product_ticket opt JOIN eshop.tickets t ON t.id = opt.ticket
              WHERE opt."order" = o.id AND NULLIF(t.note, '') IS NOT NULL))
          )) OR EXISTS(SELECT 1 FROM eshop.tickets person CROSS JOIN LATERAL jsonb_array_elements(
            CASE WHEN jsonb_typeof(person.data->'fields')='array' THEN person.data->'fields' ELSE '[]' END) answer
            WHERE EXISTS(SELECT 1 FROM eshop.order_product_ticket x JOIN eshop.orders q ON q.id=x."order" WHERE x.ticket=person.id AND q.form=ff.form) AND answer ? ff.id::text AND answer->(ff.id::text) NOT IN ('null'::jsonb,'""'::jsonb,'[]'::jsonb,'{}'::jsonb))
           OR (ff.type='ticket' AND EXISTS(SELECT 1 FROM eshop.order_product_ticket x JOIN eshop.orders q ON q.id=x."order" WHERE x.ticket IS NOT NULL AND q.form=ff.form)) THEN 'responses'
        ELSE (
          SELECT reason FROM public.form_fields member
          JOIN eshop.products p ON p.product_type = member.product_type
          CROSS JOIN LATERAL (SELECT CASE
          WHEN EXISTS (SELECT 1 FROM eshop.order_product_ticket opt WHERE opt.product = p.id)
            OR EXISTS (SELECT 1 FROM eshop.orders o WHERE o.occasion = p.occasion
              AND jsonb_path_exists(o.data, '$.tickets[*].products[*] ? (@.id == $id)', jsonb_build_object('id', p.id))) THEN 'orders'
          WHEN EXISTS (SELECT 1 FROM eshop.spots s WHERE s.product = p.id) THEN 'blueprint'
          WHEN EXISTS (SELECT 1 FROM eshop.product_inventory_contexts pic WHERE pic.product = p.id) THEN 'inventory'
          WHEN (SELECT count(*) FROM public.form_fields ref WHERE ref.product_type = p.product_type) > 1 THEN 'shared'
        END AS reason) usage
          WHERE (member.id = ff.id OR (ff.type = 'ticket' AND member.form = ff.form AND member.is_ticket_field))
            AND reason IS NOT NULL
          ORDER BY p.id LIMIT 1
        ) END INTO deletion_reason
            FROM public.form_fields ff WHERE ff.id = deletion_row.id;
            IF deletion_reason IS NOT NULL THEN
                RAISE EXCEPTION 'FORM_DELETE_%', deletion_reason;
            END IF;
        END LOOP;
        FOR deletion_row IN SELECT p.* FROM eshop.products p WHERE p.id = ANY(deleted_products)
        LOOP
            SELECT CASE
          WHEN EXISTS (SELECT 1 FROM eshop.order_product_ticket opt WHERE opt.product = p.id)
            OR EXISTS (SELECT 1 FROM eshop.orders o WHERE o.occasion = p.occasion
              AND jsonb_path_exists(o.data, '$.tickets[*].products[*] ? (@.id == $id)', jsonb_build_object('id', p.id))) THEN 'orders'
          WHEN EXISTS (SELECT 1 FROM eshop.spots s WHERE s.product = p.id) THEN 'blueprint'
          WHEN EXISTS (SELECT 1 FROM eshop.product_inventory_contexts pic WHERE pic.product = p.id) THEN 'inventory'
          WHEN (SELECT count(*) FROM public.form_fields ref WHERE ref.product_type = p.product_type) > 1 THEN 'shared'
        END INTO deletion_reason
            FROM eshop.products p WHERE p.id = deletion_row.id;
            IF deletion_reason IS NOT NULL THEN
                RAISE EXCEPTION 'FORM_DELETE_%', deletion_reason;
            END IF;
        END LOOP;
        IF EXISTS (SELECT 1 FROM jsonb_array_elements(COALESCE(input_data->'form_fields', '[]'::jsonb)) f
            WHERE (f->>'id')::bigint = ANY(deleted_fields))
          OR EXISTS (SELECT 1 FROM jsonb_array_elements(COALESCE(input_data->'form_fields', '[]'::jsonb)) f,
            jsonb_array_elements(COALESCE(NULLIF(f->'product_type'->'products', 'null'::jsonb), '[]'::jsonb)) p
            WHERE (p->>'id')::bigint = ANY(deleted_products)) THEN
            RAISE EXCEPTION 'FORM_DELETE_changed';
        END IF;
        DELETE FROM public.form_fields ff WHERE ff.id = ANY(deleted_fields);
        DELETE FROM eshop.planned_changes WHERE subject_id=ANY(deleted_products) AND change_type IN('products.price','products.is_hidden') AND NOT applied;
        DELETE FROM eshop.products p WHERE p.id = ANY(deleted_products);
        DELETE FROM public.client_aggregate_versions WHERE aggregate_type='product' AND scope_type='occasion'
          AND scope_id=occasion_id AND aggregate_id=ANY(ARRAY(SELECT id::text FROM unnest(deleted_products) id));

        ----------------------------------------------------------------------------
        -- Process form_fields array from input_data if present
        -- Each form_field may contain a product_type object. If so, we insert/update
        -- the product_type and its products, then set the resulting product_type.id
        -- in the form_field.
        ----------------------------------------------------------------------------
        IF (input_data->'form_fields') IS NOT NULL THEN
            form_fields_data := '[]'::JSONB;

            FOR field_data IN SELECT * FROM JSONB_ARRAY_ELEMENTS(input_data->'form_fields')
            LOOP
                field_id := NULLIF(field_data->>'id', '')::BIGINT;

                ----------------------------------------------------------------------------
                -- product_type logic now lives here, inside each form_field
                ----------------------------------------------------------------------------
                product_type_data := field_data->'product_type';  -- This is JSONB (could be null)
                IF field_data->>'type' = 'ticket' AND field_data#>>'{data,max_tickets}' IS NOT NULL THEN
                    IF (field_data#>>'{data,max_tickets}')::numeric < 1 OR
                       (field_data#>>'{data,max_tickets}')::numeric > public.ticket_order_limit() OR
                       trunc((field_data#>>'{data,max_tickets}')::numeric) <> (field_data#>>'{data,max_tickets}')::numeric THEN
                        RAISE EXCEPTION '%', JSONB_BUILD_OBJECT('code', 400,
                            'message', 'Invalid maximum tickets per order',
                            'limit', public.ticket_order_limit())::TEXT;
                    END IF;
                END IF;
                field_product_type := NULL;                        -- We'll store numeric ID here if we have a product_type

                IF product_type_data IS NOT NULL AND product_type_data::TEXT <> 'null' THEN
                    -- Attempt to parse the product_type.id if it exists
                    product_type_id := NULLIF(product_type_data->>'id', '')::BIGINT;

                    IF product_type_id IS NULL THEN
                        ----------------------------------------------------------------------------
                        -- New product_type
                        ----------------------------------------------------------------------------
                        INSERT INTO eshop.product_types (
                            created_at,
                            updated_at,
                            occasion,
                            title,
                            description,
                            type,
                            data
                        )
                        VALUES (
                            now_ts,
                            now_ts,
                            occasion_id,
                            product_type_data->>'title',
                            product_type_data->>'description',
                            product_type_data->>'type',
                            product_type_data->'data'
                        )
                        RETURNING id INTO product_type_id;

                        product_type_data := jsonb_set(
                            product_type_data,
                            '{id}',
                            TO_JSONB(product_type_id)
                        );
                    ELSE
                        ----------------------------------------------------------------------------
                        -- Existing product_type: check existence and occasion
                        ----------------------------------------------------------------------------
                        SELECT pt.occasion
                          INTO product_type_occ
                          FROM eshop.product_types pt
                         WHERE pt.id = product_type_id
                         LIMIT 1;

                        IF NOT FOUND THEN
                            RAISE EXCEPTION '%',
                                JSONB_BUILD_OBJECT(
                                    'code', 4006,
                                    'message', 'Product type not found',
                                    'details', product_type_data
                                )::TEXT;
                        END IF;

                        IF product_type_occ <> occasion_id THEN
                            RAISE EXCEPTION '%',
                                JSONB_BUILD_OBJECT(
                                    'code', 4007,
                                    'message', 'product_type occasion does not match form occasion',
                                    'product_type_occasion', product_type_occ,
                                    'form_occasion', occasion_id,
                                    'details', product_type_data
                                )::TEXT;
                        END IF;

                        PERFORM 1 FROM public.occasions WHERE id=occasion_id FOR UPDATE;
                        UPDATE eshop.product_types
                           SET
                               updated_at = now_ts,
                               title = product_type_data->>'title',
                               description = product_type_data->>'description',
                               type = product_type_data->>'type',
                               data = product_type_data->'data'
                         WHERE id = product_type_id;
                    END IF;

                    ----------------------------------------------------------------------------
                    -- Process products within this product_type, if any
                    ----------------------------------------------------------------------------
                    PERFORM public.advance_ticketing_authoring_version_internal_v1('product_type',occasion_id,product_type_id);
                    products_data := product_type_data->'products';
                    IF products_data IS NOT NULL AND products_data::TEXT <> 'null' THEN
                        product_array_data := '[]'::JSONB;

                        FOR product_data IN SELECT * FROM JSONB_ARRAY_ELEMENTS(products_data)
                        LOOP
                            product_id := NULLIF(product_data->>'id', '')::BIGINT;

                            -- Validate product price must be > 0
                            price_val := COALESCE(NULLIF(product_data->>'price',''), '0')::NUMERIC;
                            IF price_val < 0 THEN
                                RAISE EXCEPTION '%',
                                    JSONB_BUILD_OBJECT(
                                        'code', 4015,
                                        'message', 'Product price must be greater or equal to zero',
                                        'details', product_data
                                    )::TEXT;
                            END IF;

                            IF product_id IS NULL THEN
                                ----------------------------------------------------------------------------
                                -- New product
                                ----------------------------------------------------------------------------
                                PERFORM public.validate_product_price(price_val,product_data->'data',left(product_data->>'currency_code',3));
                                INSERT INTO eshop.products (
                                    created_at,
                                    updated_at,
                                    product_type,
                                    occasion,
                                    title,
                                    description,
                                    price,
                                    currency_code,
                                    data,
                                    is_hidden,
                                    "order",
                                    maximum
                                )
                                VALUES (
                                    now_ts,
                                    now_ts,
                                    product_type_id,
                                    occasion_id,
                                    product_data->>'title',
                                    product_data->>'description',
                                    price_val,
                                    left(product_data->>'currency_code', 3),
                                    product_data->'data',
                                    COALESCE((product_data->>'is_hidden')::BOOLEAN, false),
                                    NULLIF(product_data->>'order','')::BIGINT,
                                    NULLIF(product_data->>'maximum','')::BIGINT
                                )
                                RETURNING id INTO product_id;

                                product_data := jsonb_set(product_data, '{id}', TO_JSONB(product_id));
                            ELSE
                                ----------------------------------------------------------------------------
                                -- Existing product: must match the same occasion and product_type
                                ----------------------------------------------------------------------------
                                SELECT p.occasion
                                  INTO product_occ
                                  FROM eshop.products p
                                 WHERE p.id = product_id
                                   AND p.product_type = product_type_id
                                 LIMIT 1;

                                IF NOT FOUND THEN
                                    RAISE EXCEPTION '%',
                                        JSONB_BUILD_OBJECT(
                                            'code', 4008,
                                            'message', 'Product not found or does not match product_type',
                                            'details', product_data
                                        )::TEXT;
                                END IF;

                                IF product_occ <> occasion_id THEN
                                    RAISE EXCEPTION '%',
                                        JSONB_BUILD_OBJECT(
                                            'code', 4009,
                                            'message', 'Product occasion does not match form occasion',
                                            'product_occasion', product_occ,
                                            'form_occasion', occasion_id,
                                            'details', product_data
                                        )::TEXT;
                                END IF;

                                PERFORM public.validate_product_price_update(product_id,price_val,product_data->'data',left(product_data->>'currency_code',3));
                                UPDATE eshop.products
                                   SET
                                       updated_at = now_ts,
                                       title = product_data->>'title',
                                       description = product_data->>'description',
                                       price = price_val,
                                       currency_code = left(product_data->>'currency_code', 3),
                                       data = product_data->'data',
                                       is_hidden = COALESCE((product_data->>'is_hidden')::BOOLEAN, false),
                                       "order" = NULLIF(product_data->>'order','')::BIGINT,
                                       maximum = NULLIF(product_data->>'maximum','')::BIGINT
                                 WHERE id = product_id
                                   AND product_type = product_type_id;
                            END IF;

                            PERFORM public.advance_ticketing_authoring_version_internal_v1('product',occasion_id,product_id);
                            product_array_data := product_array_data || product_data;
                        END LOOP;

                        product_type_data := jsonb_set(
                            product_type_data,
                            '{products}',
                            product_array_data
                        );
                    END IF;

                    ----------------------------------------------------------------------------
                    -- Store product_type_id in field_product_type for the form_fields table
                    ----------------------------------------------------------------------------
                    field_product_type := product_type_id;

                    ----------------------------------------------------------------------------
                    -- Merge updated product_type_data back into the field_data
                    ----------------------------------------------------------------------------
                    field_data := jsonb_set(field_data, '{product_type}', product_type_data);
                END IF;

                ----------------------------------------------------------------------------
                -- Insert or update the form_field itself
                ----------------------------------------------------------------------------
                IF field_id IS NOT NULL THEN
                    -- Update existing form_field
                    UPDATE public.form_fields
                       SET
                           title = field_data->>'title',
                           description = field_data->>'description',
                           data = field_data->'data',
                           type = field_data->>'type',
                           is_required = COALESCE((field_data->>'is_required')::BOOLEAN, false),
                           is_hidden = COALESCE((field_data->>'is_hidden')::BOOLEAN, false),
                           "order" = NULLIF(field_data->>'order','')::BIGINT,
                           product_type = field_product_type,
                           is_ticket_field = COALESCE((field_data->>'is_ticket_field')::BOOLEAN, false),
                           form = form_id
                     WHERE id = field_id
                       AND form = form_id;

                    IF NOT FOUND THEN
                        RAISE EXCEPTION '%',
                            JSONB_BUILD_OBJECT(
                                'code', 4012,
                                'message', 'No matching form_field found to update (or does not belong to this form)',
                                'details', field_data
                            )::TEXT;
                    END IF;
                ELSE
                    -- Insert new form_field
                    INSERT INTO public.form_fields (
                        created_at,
                        title,
                        description,
                        data,
                        type,
                        is_required,
                        form,
                        is_hidden,
                        "order",
                        product_type,
                        is_ticket_field
                    )
                    VALUES (
                        now_ts,
                        field_data->>'title',
                        field_data->>'description',
                        field_data->'data',
                        field_data->>'type',
                        COALESCE((field_data->>'is_required')::BOOLEAN, false),
                        form_id,
                        COALESCE((field_data->>'is_hidden')::BOOLEAN, false),
                        NULLIF(field_data->>'order','')::BIGINT,
                        field_product_type,
                        COALESCE((field_data->>'is_ticket_field')::BOOLEAN, false)
                    )
                    RETURNING id INTO field_id;

                    field_data := jsonb_set(field_data, '{id}', TO_JSONB(field_id));
                END IF;

                form_fields_data := form_fields_data || field_data;
            END LOOP;
        END IF;

        ----------------------------------------------------------------------------
        -- Validate that deadline_duration_seconds is zero, positive, or null
        ----------------------------------------------------------------------------
        IF (input_data->'data'->>'reminder_interval_seconds')::bigint < 0 THEN
            RAISE EXCEPTION 'reminder_interval_seconds must be zero or higher or null';
        END IF;
        deadline_val := NULLIF(input_data->>'deadline_duration_seconds','')::BIGINT;
        IF deadline_val IS NOT NULL AND deadline_val < 0 THEN
            RAISE EXCEPTION '%',
                JSONB_BUILD_OBJECT(
                    'code', 4016,
                    'message', 'deadline_duration_seconds must be zero or higher or null'
                )::TEXT;
        END IF;

        ----------------------------------------------------------------------------
        -- Validate bank_account belongs to the same unit as the occasion, if provided
        ----------------------------------------------------------------------------
        bank_account_val := NULLIF(input_data->>'bank_account','')::BIGINT;
        IF bank_account_val IS NOT NULL THEN
            SELECT ba.unit
              INTO bank_account_unit
              FROM eshop.unit_bank_accounts ba
             WHERE ba.bank_account = bank_account_val
               AND ba.unit = occasion_unit
             LIMIT 1;

            IF NOT FOUND THEN
                RAISE EXCEPTION '%',
                    JSONB_BUILD_OBJECT(
                        'code', 4020,
                        'message', 'Bank account not found',
                        'bank_account', bank_account_val
                    )::TEXT;
            END IF;

            IF bank_account_unit <> occasion_unit THEN
                RAISE EXCEPTION '%',
                    JSONB_BUILD_OBJECT(
                        'code', 4021,
                        'message', 'Bank account does not belong to the same unit as the occasion',
                        'bank_account_unit', bank_account_unit,
                        'occasion_unit', occasion_unit
                    )::TEXT;
            END IF;
        END IF;

        ----------------------------------------------------------------------------
        -- Update the main form record with all validated fields
        ----------------------------------------------------------------------------
        IF input_data->>'blueprint' IS NOT NULL AND NOT EXISTS(
          SELECT 1 FROM eshop.blueprints WHERE id=(input_data->>'blueprint')::bigint AND occasion=occasion_id) THEN
          RAISE EXCEPTION '%',jsonb_build_object('code',403,'message','Foreign blueprint')::text; END IF;
        PERFORM public.check_form_capacity_settings_internal(form_id,input_data);
        UPDATE public.forms
           SET
               participant_capacity = CASE WHEN input_data ? 'participant_capacity' THEN (input_data->>'participant_capacity')::integer ELSE participant_capacity END,
               waitlist_enabled = CASE WHEN input_data ? 'waitlist_enabled' THEN (input_data->>'waitlist_enabled')::boolean ELSE waitlist_enabled END,
               show_remaining_capacity = CASE WHEN input_data ? 'show_remaining_capacity' THEN (input_data->>'show_remaining_capacity')::boolean ELSE show_remaining_capacity END,
               waitlist_offer_duration_seconds = CASE WHEN input_data ? 'waitlist_offer_duration_seconds' THEN (input_data->>'waitlist_offer_duration_seconds')::integer ELSE waitlist_offer_duration_seconds END,
               capacity_revision = capacity_revision+1,
               title = CASE WHEN input_data ? 'title' THEN input_data->>'title' ELSE title END,
               data = CASE WHEN input_data ? 'data' THEN input_data->'data' ELSE data END,
               header = CASE WHEN input_data ? 'header' THEN input_data->>'header' ELSE header END,
               header_off = CASE WHEN input_data ? 'header_off' THEN input_data->>'header_off' ELSE header_off END,
               link = link_param,
               blueprint = CASE WHEN input_data ? 'blueprint' THEN NULLIF(input_data->>'blueprint','')::BIGINT ELSE blueprint END,
               bank_account = CASE WHEN input_data ? 'bank_account' THEN bank_account_val ELSE bank_account END,
               deadline_duration_seconds = CASE WHEN input_data ? 'deadline_duration_seconds' THEN deadline_val ELSE deadline_duration_seconds END,
               is_open = CASE WHEN input_data ? 'is_open' THEN (input_data->>'is_open')::boolean ELSE is_open END
         WHERE id = form_id;

        ----------------------------------------------------------------------------
        -- After updating the form, requeue payment reminders for the whole occasion
        -- as the form's settings (e.g., is_reminder_enabled) might have changed.
        ----------------------------------------------------------------------------
        -- First, find the 'seconds_before_deadline' setting from the occasion's 'form' feature.
        SELECT (elem->>'reminder_interval_seconds')::BIGINT
          INTO v_seconds_before_deadline
          FROM public.occasions, jsonb_array_elements(features) AS elem
         WHERE id = occasion_id
           AND elem->>'code' = 'form'
         LIMIT 1;

        -- If the setting is found, call the function to rebuild the reminder queue.
        PERFORM public.queue_payment_reminders(occasion_id, COALESCE(v_seconds_before_deadline,86400));

        ----------------------------------------------------------------------------
        -- Prepare a success response
        ----------------------------------------------------------------------------
        result := JSONB_BUILD_OBJECT(
            'code', 200,
            'message', 'Form updated successfully',
            'form_id', form_id,
            'link', link_param,
            'form_fields', form_fields_data
        );

    EXCEPTION WHEN raise_exception THEN
        -- Catch any exception and attempt to parse it as JSON; if not JSON, wrap it in our own JSON.
        result := CASE
            WHEN left(SQLERRM, 1) = '{' THEN SQLERRM::JSONB
            ELSE JSONB_BUILD_OBJECT('code', 5001, 'message', SQLERRM)
        END;
    END;

    RETURN result;
END;
$$;

-- Source: database/functions/inventory/update_inventory_pool_bundle_internal_v1.sql
CREATE OR REPLACE FUNCTION public.update_inventory_pool_bundle_internal_v1(p_bundle_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
    v_pool_data jsonb := p_bundle_data->'pool';
    v_pool_id bigint;
    v_occasion_id bigint;

    -- Context variables
    v_context_data jsonb;
    v_context_id bigint;
    v_context_ids_from_input bigint[] := ARRAY[]::bigint[];

    result jsonb;
BEGIN
    -- Resolve occasion ID from the input data. It's required for both create and update.
    v_occasion_id := (v_pool_data->>'occasion')::bigint;
    IF v_occasion_id IS NULL THEN
        RAISE EXCEPTION '%', jsonb_build_object('code', 'B001', 'message', 'Occasion ID is required.')::text;
    END IF;

    -- Permission check
    IF NOT can_write_orders(v_occasion_id) THEN
        RAISE EXCEPTION '%', jsonb_build_object('code', 403, 'message', 'User is not authorized to edit this occasion.')::text;
    END IF;

    -- 1. Upsert the main inventory_pool record
    v_pool_id := (v_pool_data->>'id')::bigint;

    IF v_pool_id IS NULL THEN
        -- Create a new pool if ID is not provided
        INSERT INTO public.inventory_pools (title, occasion, sellable_capacity, description, type, data, created_at, updated_at)
        VALUES (
            v_pool_data->>'title',
            v_occasion_id,
            (v_pool_data->>'sellable_capacity')::bigint,
            v_pool_data->>'description',
            v_pool_data->>'type',
            v_pool_data->'data',
            now(),
            now()
        ) RETURNING id INTO v_pool_id;
    ELSE
        PERFORM 1 FROM public.inventory_pools WHERE id=v_pool_id AND occasion=v_occasion_id FOR UPDATE;
        IF NOT FOUND THEN RAISE EXCEPTION 'Inventory pool scope mismatch'; END IF;
        PERFORM 1 FROM public.inventory_contexts WHERE inventory_pool=v_pool_id ORDER BY id FOR UPDATE;
        IF (v_pool_data->>'sellable_capacity')::bigint < (SELECT count(*) FROM eshop.spots s JOIN public.inventory_contexts ic ON ic.id=s.inventory_context
          WHERE ic.inventory_pool=v_pool_id AND (s.order_product_ticket IS NOT NULL OR (s.secret IS NOT NULL AND s.secret_expiration_time>clock_timestamp()))) THEN
          RAISE EXCEPTION 'INVENTORY_CAPACITY_BELOW_COMMITTED'; END IF;
        -- Update the existing pool
        UPDATE public.inventory_pools
        SET
            title = v_pool_data->>'title',
            sellable_capacity = (v_pool_data->>'sellable_capacity')::bigint,
            description = v_pool_data->>'description',
            type = v_pool_data->>'type',
            data = v_pool_data->'data',
            updated_at = now()
        WHERE id = v_pool_id;
    END IF;

    -- NOTE: Resource and Slot management logic has been removed as requested.

    -- 2. Upsert/Delete Inventory Contexts
    IF jsonb_typeof(p_bundle_data->'contexts') = 'array' THEN
        FOR v_context_data IN SELECT * FROM jsonb_array_elements(p_bundle_data->'contexts')
        LOOP
            v_context_id := (v_context_data->>'id')::bigint;
            IF v_context_id IS NULL THEN
                -- Create new context, now including the 'data' field
                INSERT INTO public.inventory_contexts (inventory_pool, block_date, title, "order", data)
                VALUES (v_pool_id, (v_context_data->>'block_date')::date, v_context_data->>'title', (v_context_data->>'order')::bigint, v_context_data->'data')
                RETURNING id INTO v_context_id;
            ELSE
                -- Update existing context, now including the 'data' field
                UPDATE public.inventory_contexts
                SET
                    block_date = (v_context_data->>'block_date')::date,
                    title = v_context_data->>'title',
                    "order" = (v_context_data->>'order')::bigint,
                    data = v_context_data->'data' -- Added this line
                WHERE id = v_context_id;
            END IF;
            v_context_ids_from_input := array_append(v_context_ids_from_input, v_context_id);
        END LOOP;
        -- Deleting a context must not detach a sold or currently held spot.
        PERFORM 1 FROM eshop.spots WHERE inventory_context IN (SELECT id FROM public.inventory_contexts
          WHERE inventory_pool=v_pool_id AND id<>ALL(v_context_ids_from_input)) ORDER BY id FOR UPDATE;
        IF EXISTS(SELECT 1 FROM eshop.spots WHERE inventory_context IN (SELECT id FROM public.inventory_contexts
          WHERE inventory_pool=v_pool_id AND id<>ALL(v_context_ids_from_input))
          AND (order_product_ticket IS NOT NULL OR (secret IS NOT NULL AND secret_expiration_time>clock_timestamp()))) THEN
          RAISE check_violation USING MESSAGE='INVENTORY_CONTEXT_IN_USE'; END IF;
        -- Delete contexts that were removed in the UI for this pool
        DELETE FROM public.inventory_contexts WHERE inventory_pool = v_pool_id AND id <> ALL(v_context_ids_from_input);
    END IF;

    -- 3. Create or delete spots for the inventory pool based on its resources and contexts.
    -- The function is executed, and its integer return value is discarded.
    PERFORM adjust_spot_capacity_for_pool(v_pool_id);

    -- Return the fully updated bundle by calling the get function
    RETURN get_inventory_pool_bundle(v_pool_id);
END;
$function$;

-- Source: database/functions/others/update_occasion.sql
CREATE OR REPLACE FUNCTION public.update_occasion_internal_v1(input_data JSONB)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
SET search_path = public, extensions
 AS $$
 DECLARE
     updated_occ public.occasions;
     occ_id BIGINT;
     now TIMESTAMPTZ := NOW();
     final_unit BIGINT;

     -- Variable for the determined support flag
     is_app_supported BOOLEAN;

     -- Variable to help find the organization to check settings
     v_org_id BIGINT;

     -- Variables for feature handling
     new_blueprint_id BIGINT;
     v_form_id BIGINT;
     v_form_blueprint BIGINT;
     v_form_settings JSONB;
     v_form_link TEXT;
     v_reminder_interval_seconds BIGINT;
     v_email_order record;

     input_features JSONB;
     old_features JSONB;
     processed_features JSONB;
     feature JSONB;
     form_feature_found BOOLEAN;
 BEGIN
     -- Validate input data. Raise an exception if it's missing or empty.
     IF input_data IS NULL OR input_data = '{}'::jsonb THEN
         RAISE EXCEPTION 'Input data is missing or empty';
     END IF;

     -- 1. Identify the Organization ID
     IF (input_data->>'id') IS NOT NULL THEN
         -- Case A: UPDATE - Get organization from the existing occasion
         SELECT organization INTO v_org_id
         FROM public.occasions
         WHERE id = (input_data->>'id')::BIGINT;
     ELSE
         -- Case B: INSERT - Try to get organization from input
         v_org_id := (input_data->>'organization')::BIGINT;

         -- Case C: INSERT fallback - If org is missing, try to get it via the Unit
         IF v_org_id IS NULL AND (input_data->>'unit') IS NOT NULL THEN
            SELECT organization INTO v_org_id
            FROM public.units
            WHERE id = (input_data->>'unit')::BIGINT;
         END IF;
     END IF;

     -- 2. Fetch the setting from public.organizations.data
     -- Defaults to TRUE if the organization or the key is not found to ensure backward compatibility
     IF v_org_id IS NOT NULL THEN
         SELECT COALESCE((data->>'IS_APP_SUPPORTED')::BOOLEAN, false)
         INTO is_app_supported
         FROM public.organizations
         WHERE id = v_org_id;
     ELSE
         is_app_supported := false;
     END IF;

     -- Ensure is_app_supported is not null (redundant safety check)
     is_app_supported := COALESCE(is_app_supported, false);

     --
     -- Prepare features based on is_app_supported flag
     --
     input_features := COALESCE(input_data->'features', '[]'::jsonb);
     processed_features := '[]'::jsonb;

     IF NOT is_app_supported THEN
         -- If the app is not supported, we must enable the 'form' feature.
         form_feature_found := false;
         -- Loop through existing features to find and enable the form feature
         FOR feature IN SELECT * FROM jsonb_array_elements(input_features)
         LOOP
             IF feature->>'code' = 'form' THEN
                 -- If form feature exists, ensure it is enabled
                 feature := feature || '{"is_enabled": true}';
                 form_feature_found := true;
             END IF;
             processed_features := processed_features || feature;
         END LOOP;

         -- If the form feature was not found in the original array, add it.
         IF NOT form_feature_found THEN
             processed_features := processed_features || '{"code": "form", "is_enabled": true}';
         END IF;
     ELSE
         -- If app is supported, use features as they were provided.
         processed_features := input_features;
     END IF;

     -- Determine if this is an UPDATE or INSERT based on the presence of an 'id'
     occ_id := (input_data->>'id')::BIGINT;

     IF occ_id IS NOT NULL THEN
         PERFORM public.check_occasion_writable(occ_id);
         -- This is an UPDATE operation

         -- Check for the existence of the occasion and get its current unit
         SELECT unit, features INTO final_unit, old_features FROM public.occasions WHERE id = occ_id FOR UPDATE;
         IF NOT FOUND THEN
             RAISE EXCEPTION 'Occasion with ID % not found', occ_id;
         END IF;

         processed_features := public.merge_ticket_layout_features(old_features, processed_features, input_data->'ticket_layout_change');
         PERFORM public.validate_ticket_layout_references(occ_id, f->'layout') FROM jsonb_array_elements(processed_features) f WHERE f->>'code'='ticket' AND f ? 'layout';

         -- Determine the final unit, allowing it to be updated.
         final_unit := COALESCE((input_data->>'unit')::BIGINT, final_unit);

         -- Security check: ensure the current user has editor rights on the target unit.
         IF NOT public.can_edit_occasion(occ_id,final_unit) THEN
             RAISE insufficient_privilege USING MESSAGE = 'unit editor required';
         END IF;

         IF (input_data ? 'organization' AND (input_data->>'organization')::bigint IS DISTINCT FROM v_org_id)
           OR NOT EXISTS(SELECT 1 FROM public.units WHERE id=final_unit AND organization=v_org_id) THEN
           RAISE insufficient_privilege USING MESSAGE='Occasion tenant cannot change'; END IF;

         UPDATE public.occasions
            SET updated_at  = now,
                title       = COALESCE(input_data->>'title', title),
                description = COALESCE(input_data->>'description', description),
                link        = public.reserve_public_link_internal('occasion',occ_id,input_data->>'link',false),
                data        = COALESCE(input_data->'data', data),
                is_hidden   = COALESCE((input_data->>'is_hidden')::BOOLEAN, is_hidden),
                is_open     = COALESCE((input_data->>'is_open')::BOOLEAN, is_open),
                is_promoted = COALESCE((input_data->>'is_promoted')::BOOLEAN, is_promoted),
                start_time  = COALESCE((input_data->>'start_time')::TIMESTAMPTZ, start_time),
                end_time    = COALESCE((input_data->>'end_time')::TIMESTAMPTZ, end_time),
                organization = COALESCE((input_data->>'organization')::BIGINT, organization),
                services    = COALESCE(input_data->'services', services),
                unit        = final_unit,
                is_order_synchronization_enabled=COALESCE((input_data->>'is_order_synchronization_enabled')::boolean,is_order_synchronization_enabled),
                features    = processed_features -- Use the processed features
          WHERE id = occ_id
          RETURNING * INTO updated_occ;

     ELSE
         -- This is an INSERT operation

         -- For new occasions, the 'unit' field is mandatory.
         final_unit := (input_data->>'unit')::BIGINT;
         IF final_unit IS NULL THEN
             RAISE EXCEPTION 'The "unit" field is required for new occasions';
         END IF;

         -- Security check for the new occasion's unit.
         IF NOT public.can_create_occasion(final_unit) THEN
             RAISE insufficient_privilege USING MESSAGE = 'unit editor required';
         END IF;

         -- We still need to default 'reminder_is_enabled' for the 'form' feature if not specified.
         -- We do this on the already processed_features array.
         input_features := processed_features; -- Use the result from the is_app_supported logic
         processed_features := '[]'::jsonb;
         FOR feature IN SELECT * FROM jsonb_array_elements(input_features)
         LOOP
             -- If the current feature is the 'form' feature
             IF feature->>'code' = 'form' THEN
                 -- And if 'reminder_is_enabled' is NOT specified, default it to true.
                 IF NOT (feature ? 'reminder_is_enabled') THEN
                     feature := feature || '{"reminder_is_enabled": true}';
                 END IF;
             END IF;
             processed_features := processed_features || feature::jsonb;
         END LOOP;

         processed_features := public.merge_ticket_layout_features('[]', processed_features, input_data->'ticket_layout_change', true);

         INSERT INTO public.occasions(
             created_at, updated_at, title, description, link, data,
             is_hidden, is_open, is_promoted, start_time, end_time, organization,
             services, unit, features
         )
         VALUES(
             now, now,
             COALESCE(input_data->>'title', ''),
             COALESCE(input_data->>'description', ''),
             '',
             COALESCE(input_data->'data', '{}'::jsonb),
             COALESCE((input_data->>'is_hidden')::BOOLEAN, false),
             COALESCE((input_data->>'is_open')::BOOLEAN, true),
             COALESCE((input_data->>'is_promoted')::BOOLEAN, false),
             (input_data->>'start_time')::TIMESTAMPTZ,
             (input_data->>'end_time')::TIMESTAMPTZ,
             (input_data->>'organization')::BIGINT,
             COALESCE(input_data->'services', '{}'::jsonb),
             final_unit,
             processed_features
         )
         RETURNING * INTO updated_occ;

         -- Set the occ_id from the newly created record for subsequent logic
         occ_id := updated_occ.id;
         UPDATE public.occasions SET link=public.reserve_public_link_internal('occasion',occ_id,input_data->>'link',true) WHERE id=occ_id RETURNING * INTO updated_occ;
     END IF;

     -- Enabling the blueprint feature must not bypass form capacity/waitlist guards,
     -- including when the stored blueprint already exists.
     IF jsonb_path_exists(updated_occ.features, '$[*] ? (@.code == "blueprint" && @.is_enabled == true)') THEN
       FOR v_form_id IN SELECT id FROM public.forms WHERE occasion=occ_id ORDER BY id LOOP
         PERFORM public.check_form_capacity_settings_internal(v_form_id, '{"blueprint":1}'::jsonb);
       END LOOP;
     END IF;

     PERFORM public.validate_ticket_layout_references(occ_id, f->'layout') FROM jsonb_array_elements(processed_features) f WHERE f->>'code'='ticket' AND f ? 'layout';
     --
     -- Post-update/insert feature handling
     --

     -- Check if form feature is enabled and handle related logic.
     -- This will now be triggered if is_app_supported was false (based on organization settings).
     IF jsonb_path_exists(updated_occ.features, '$[*] ? (@.code == "form" && @.is_enabled == true)') THEN
         -- Extract the settings for the 'form' feature from the newly saved data
         SELECT elem INTO v_form_settings
         FROM jsonb_array_elements(updated_occ.features) AS elem
         WHERE elem->>'code' = 'form';

         -- Create a default form if one doesn't exist for the occasion
         IF NOT EXISTS (SELECT 1 FROM public.forms WHERE occasion = occ_id) THEN
             v_form_link := NULLIF(btrim(input_data->>'form_link'), '');
             IF input_data->>'id' IS NULL THEN
               PERFORM public.create_initial_occasion_form_internal_v1(occ_id,v_form_link,'Registration');
             ELSE
               PERFORM public.create_form(occ_id,v_form_link,'Registration');
             END IF;
         END IF;

         -- Check if reminders are enabled within the form feature
         IF (v_form_settings->>'reminder_is_enabled')::boolean IS TRUE THEN
             -- Get the reminder interval, defaulting to 1 day (86400 seconds) if not specified
             v_reminder_interval_seconds := COALESCE(
                 (v_form_settings->>'reminder_interval_seconds')::bigint,
                 86400
             );
             -- Call the function to queue payment reminders for all relevant orders

         END IF;
     END IF;

     -- Revalidate in-flight reminders after every relevant occasion update.
     PERFORM public.queue_payment_reminders(occ_id,coalesce(v_reminder_interval_seconds,86400));
     IF updated_occ.is_order_synchronization_enabled THEN
       FOR v_email_order IN SELECT id FROM eshop.orders WHERE occasion=occ_id AND state='paid' LOOP
         PERFORM public.enqueue_paid_order_tickets(v_email_order.id);
       END LOOP;
     END IF;
     -- Check if the blueprint feature is enabled in the final, saved state
     IF jsonb_path_exists(updated_occ.features, '$[*] ? (@.code == "blueprint" && @.is_enabled == true)') THEN
         -- Find the associated form to attach the blueprint to
         SELECT id, blueprint INTO v_form_id, v_form_blueprint
           FROM public.forms
          WHERE occasion = occ_id
          LIMIT 1;

         -- If a form exists and it doesn't already have a blueprint, create one.
         IF FOUND AND v_form_blueprint IS NULL THEN
             INSERT INTO eshop.blueprints(occasion, organization, created_at, updated_at,layout)
             VALUES (occ_id, COALESCE(updated_occ.organization, 1), now, now,
              '{"schemaVersion":1,"symbolSetVersion":1,"canvas":{"x":0,"y":0,"width":1120,"height":2080,"fill":"#ffffffff"},"defaultTextStyle":{"fontId":"builtin:roboto-unpacked:24438383f80387edbbd3a199d7b257258db7003f5b291a7d3fb6fa89483ae57f","size":24,"color":"#222222FF"},"nodes":[]}'::jsonb)
             RETURNING id INTO new_blueprint_id;

             UPDATE public.forms
                SET blueprint = new_blueprint_id,
                    updated_at = now
              WHERE id = v_form_id;
             INSERT INTO public.client_aggregate_versions(aggregate_type,scope_type,scope_id,aggregate_id,version)
             VALUES('form','occasion',occ_id,v_form_id::text,1)
             ON CONFLICT(aggregate_type,scope_type,scope_id,aggregate_id) DO UPDATE
             SET version=public.client_aggregate_versions.version+1,updated_at=clock_timestamp();
         END IF;
     END IF;
 END;
 $$;

-- Source: database/functions/eshop_orders/update_order_and_tickets_to_paid_ws.sql
CREATE OR REPLACE FUNCTION public.update_order_and_tickets_to_paid_ws(order_id bigint)
RETURNS jsonb SECURITY DEFINER
SET search_path = public, extensions AS $$
DECLARE
    occasion_id bigint;
BEGIN
    -- Retrieve the occasion associated with the order
    SELECT occasion INTO occasion_id FROM eshop.orders WHERE id = order_id;

    -- Check if the order exists and has an associated occasion
    IF occasion_id IS NULL THEN
        RAISE EXCEPTION 'Order not found or no associated occasion.';
    END IF;

    -- Verify if the user is an editor on the occasion
    IF NOT can_write_orders(occasion_id) THEN
        RAISE EXCEPTION 'User is not authorized to edit this occasion.';
    END IF;

    -- Manual marking changes state only. The explicit Send action owns delivery.
    RETURN public.mark_order_and_tickets_paid_internal_v1(order_id);
EXCEPTION WHEN OTHERS THEN
    -- Handle any exceptions
    RETURN jsonb_build_object(
        'code', 500,
        'message', SQLERRM,
        'detail', coalesce(SQLERRM, 'An unexpected error occurred')
    );
END;
$$ LANGUAGE plpgsql;

-- Source: database/functions/eshop_orders/update_order_and_tickets_to_sent_ws.sql
CREATE OR REPLACE FUNCTION update_order_and_tickets_to_sent_ws(order_id bigint, ticket_ids bigint[])
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
    v_occasion_id bigint;
BEGIN
    SELECT occasion INTO v_occasion_id
    FROM eshop.orders
    WHERE id = order_id;

    IF v_occasion_id IS NULL THEN
        RAISE EXCEPTION 'Order not found or no associated occasion.';
    END IF;

    IF (SELECT can_write_orders(v_occasion_id)) <> TRUE THEN
        RAISE EXCEPTION 'User is not editor.';
    END IF;

    RETURN update_order_and_tickets_to_sent(order_id, ticket_ids);
END;
$$;

-- Source: database/functions/eshop_orders/update_order_and_tickets_to_storno_ws.sql
CREATE OR REPLACE FUNCTION public.update_order_and_tickets_to_storno_ws_internal_v1(order_id bigint)
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
    occasion_id bigint;
BEGIN
    PERFORM public.lock_blueprint_scope_internal(ARRAY[(SELECT occasion FROM eshop.orders WHERE id=order_id)]);
    -- Retrieve the occasion associated with the order
    SELECT occasion INTO occasion_id FROM eshop.orders WHERE id = order_id;

    -- Check if the order exists and has an associated occasion
    IF occasion_id IS NULL THEN
        RAISE EXCEPTION 'Order not found or no associated occasion.';
    END IF;

    -- Verify if the user is an editor on the occasion
    IF (SELECT can_write_orders(occasion_id)) <> TRUE THEN
        RAISE EXCEPTION 'User is not editor.';
    END IF;

    PERFORM public.lock_order_capacity_scope_internal(ARRAY[order_id]);
    -- Use the same parent lock order as ticket cancellation.
    PERFORM 1 FROM eshop.orders WHERE id=order_id FOR UPDATE;

    -- Call the original function to update the order and tickets
    PERFORM update_order_and_tickets_to_storno_221(order_id);
END;
$$;

-- Source: database/functions/eshop_orders/update_order_note_hidden.sql
CREATE OR REPLACE FUNCTION public.update_order_note_hidden(order_id bigint, new_note_hidden text)
    RETURNS jsonb SECURITY DEFINER
SET search_path = public, extensions AS $$
    DECLARE
        occasion_id bigint;
    BEGIN
        -- Retrieve the occasion_id from the order
        SELECT occasion INTO occasion_id FROM eshop.orders WHERE id = order_id;

        -- Check if occasion_id was successfully retrieved
        IF occasion_id IS NULL THEN
            RETURN jsonb_build_object('code', 404, 'message', 'Order not found or occasion not specified');
        END IF;

        -- Check if the user has the right to edit the given occasion
        IF (can_write_orders(occasion_id)) <> TRUE THEN
            -- Return an error if the user is not authorized
            RETURN jsonb_build_object('code', 403, 'message', 'User is not authorized to edit this occasion');
        END IF;

        PERFORM public.lock_order_capacity_scope_internal(ARRAY[order_id]);
        IF (SELECT state FROM eshop.orders WHERE id=order_id)<>'waitlisted' THEN
          PERFORM public.check_order_is_mutable(order_id);
        END IF;

        -- Proceed to update note_hidden if the user is authorized
        UPDATE eshop.orders
        SET note_hidden = new_note_hidden, updated_at = now()
        WHERE id = order_id;

        -- Check if the update was successful
        IF FOUND THEN
            RETURN jsonb_build_object('code', 200, 'message', 'Update successful');
        ELSE
            RETURN jsonb_build_object('code', 404, 'message', 'Order not found');
        END IF;
    END;
    $$ LANGUAGE plpgsql;

-- Source: database/functions/eshop_orders/update_order_responses.sql
CREATE OR REPLACE FUNCTION public.update_order_responses(
    p_order_id BIGINT,
    responses JSONB
)
RETURNS void
SECURITY DEFINER
LANGUAGE plpgsql
SET search_path = public, extensions
AS $$
DECLARE
    v_occasion_id BIGINT;
    v_order_form_id BIGINT;
    v_current_state text;
    v_current_data JSONB;
    v_new_data JSONB;
    v_field_definitions JSONB;
    v_current_fields_map JSONB;
    v_merged_fields_map JSONB;
    v_new_fields_array JSONB;

    v_field_id_text TEXT;
    v_field_type TEXT;
    v_new_value JSONB;

    v_updated_order_state TEXT;
    v_updated_order_price NUMERIC(10, 2);
    v_updated_order_data JSONB;
BEGIN
    -- Fetch the order's current data, occasion, and form ID
    SELECT
        o.data,
        o.occasion,
        o.form,
        o.state
    INTO
        v_current_data,
        v_occasion_id,
        v_order_form_id,
        v_current_state
    FROM eshop.orders o
    WHERE o.id = p_order_id;

    -- Raise an exception if the SELECT INTO returned no row
    IF v_occasion_id IS NULL THEN
        RAISE EXCEPTION 'Order not found: %', p_order_id;
    END IF;

    -- Check if the current user has order editing permissions for this occasion
    IF (SELECT can_write_orders(v_occasion_id)) <> TRUE THEN
        RAISE EXCEPTION 'User does not have permission to edit this order.';
    END IF;

    -- Reject the terminal state before form validation, without reversing
    -- the form -> order lock order used by form-field removal.
    IF v_current_state='storno' THEN
        RAISE EXCEPTION 'ORDER_CANCELLED: Cancelled orders are read-only' USING ERRCODE='55000';
    END IF;

    -- Raise an exception if the order is not linked to a form
    IF v_order_form_id IS NULL THEN
        RAISE EXCEPTION 'Order % has no associated form.', p_order_id;
    END IF;

    -- Coordinate response validation/writes with form saves and field removal.
    PERFORM 1 FROM public.forms WHERE id = v_order_form_id FOR SHARE;
    PERFORM public.check_order_is_mutable(p_order_id);
    SELECT data INTO v_current_data FROM eshop.orders WHERE id=p_order_id;

    -- Fetch all field definitions for this form into a JSONB map { "field_id": "field_type" }
    SELECT jsonb_object_agg(ff.id::text, ff.type)
    INTO v_field_definitions
    FROM public.form_fields ff
    WHERE ff.form = v_order_form_id;

    -- Raise an exception if the form has no fields
    IF v_field_definitions IS NULL THEN
        RAISE EXCEPTION 'No form fields found for form %', v_order_form_id;
    END IF;

    -- FIX: Use a LATERAL join to explicitly reference the columns from jsonb_each,
    -- resolving the "ambiguous column 'value'" error.
    SELECT jsonb_object_agg(je.key, je.value)
    INTO v_current_fields_map
    FROM jsonb_array_elements(v_current_data -> 'fields') AS jae(field_object),
         LATERAL jsonb_each(jae.field_object) AS je(key, value);

    -- Start with the current order data
    v_new_data := v_current_data;

    -- Merge the existing fields map with the new responses. New responses overwrite old ones.
    v_merged_fields_map := COALESCE(v_current_fields_map, '{}'::jsonb) || responses;

    -- Iterate through only the *incoming* responses to handle updates and nulls
    FOR v_field_id_text, v_new_value IN SELECT * FROM jsonb_each(responses)
    LOOP
        -- Get the type of the field being updated
        v_field_type := v_field_definitions ->> v_field_id_text;

        -- Validate that the field ID exists on this order's form
        IF v_field_type IS NULL THEN
            RAISE EXCEPTION 'Field ID % not found on form %', v_field_id_text, v_order_form_id;
        END IF;

        -- Handle null values: remove the key from the top level and from the merged map
        IF v_new_value IS NULL OR v_new_value = 'null'::jsonb THEN

            -- Remove from the map that will build the 'fields' array
            v_merged_fields_map := v_merged_fields_map - v_field_id_text;

            -- Remove top-level duplicated fields
            IF v_field_type = 'name' THEN
                v_new_data := v_new_data - 'name';
            ELSIF v_field_type = 'surname' THEN
                v_new_data := v_new_data - 'surname';
            ELSIF v_field_type = 'email' THEN
                v_new_data := v_new_data - 'email';
            ELSIF v_field_type = 'phone' THEN
                v_new_data := v_new_data - 'phone';
            END IF;

        -- Handle non-null values: update the top-level keys
        ELSE

            -- Update top-level duplicated fields
            IF v_field_type = 'name' THEN
                v_new_data := v_new_data || jsonb_build_object('name', v_new_value);
            ELSIF v_field_type = 'surname' THEN
                v_new_data := v_new_data || jsonb_build_object('surname', v_new_value);
            ELSIF v_field_type = 'email' THEN
                v_new_data := v_new_data || jsonb_build_object('email', v_new_value);
            ELSIF v_field_type = 'phone' THEN
                v_new_data := v_new_data || jsonb_build_object('phone', v_new_value);
            END IF;

        END IF;
    END LOOP;

    -- Rebuild the 'fields' array from the (now null-stripped) merged map
    -- It converts { "id": "val" } back to [ {"id": "val"} ]
    SELECT jsonb_agg(jsonb_build_object(key, value))
    INTO v_new_fields_array
    FROM jsonb_each(v_merged_fields_map);

    -- Set the new 'fields' array in the main data object
    v_new_data := jsonb_set(
        v_new_data,
        '{fields}',
        COALESCE(v_new_fields_array, '[]'::jsonb)
    );

    -- Update the order in the database
    UPDATE eshop.orders
    SET
        data = v_new_data,
        updated_at = NOW()
    WHERE
        id = p_order_id
    RETURNING
        state, price, data
    INTO
        v_updated_order_state, v_updated_order_price, v_updated_order_data;

    -- Save the change to the orders_history table
    INSERT INTO eshop.orders_history (
        "order",
        state,
        price,
        data,
        created_at
    )
    VALUES (
        p_order_id,
        v_updated_order_state,
        v_updated_order_price,
        v_updated_order_data,
        NOW()
    );

END;
$$;

-- Source: database/functions/organization/update_organization_admin.sql
CREATE OR REPLACE FUNCTION public.update_organization_admin(
  organization_id bigint,
  title text,
  data jsonb,
  phone_prefixes text[]
)
RETURNS SETOF public.organizations
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions
AS $$
BEGIN
  IF update_organization_admin.data ? 'ONESIGNAL_REST_API_KEY' THEN
    RAISE invalid_parameter_value
      USING MESSAGE = 'OneSignal REST API key is managed server-side';
  END IF;

  IF update_organization_admin.data ? 'IS_GOOGLE_LOGIN_ENABLED'
     AND jsonb_typeof(update_organization_admin.data->'IS_GOOGLE_LOGIN_ENABLED') IS DISTINCT FROM 'boolean' THEN
    RAISE invalid_parameter_value USING MESSAGE = 'Google login setting must be boolean';
  END IF;

  -- Verify admin status
  IF public.can_manage_organization_settings(organization_id) THEN
    -- Update the organization record
    RETURN QUERY
    UPDATE organizations
    SET 
      title = COALESCE(update_organization_admin.title, organizations.title),
      data = organizations.data || update_organization_admin.data,
      phone_prefixes = COALESCE(
        update_organization_admin.phone_prefixes,
        organizations.phone_prefixes
      )
    WHERE id = organization_id
    RETURNING organizations.id, organizations.created_at,
      organizations.updated_at,
      organizations.data - 'ONESIGNAL_REST_API_KEY',
      organizations.title, organizations.phone_prefixes;

    -- Project the organization switch onto operator-provisioned clients in the
    -- same transaction. Unprovisioned platforms must never become available.
    IF update_organization_admin.data ? 'IS_GOOGLE_LOGIN_ENABLED' THEN
      UPDATE public.external_login_clients c
      SET enabled = c.provisioned AND
          (update_organization_admin.data->>'IS_GOOGLE_LOGIN_ENABLED')::boolean
      WHERE c.organization = organization_id;
    END IF;
  ELSE
    RAISE EXCEPTION 'Access Denied: User is not an admin of this organization.';
  END IF;
END;
$$;

-- Source: database/functions/eshop/update_product_client_sync_v1.sql
CREATE OR REPLACE FUNCTION public.update_product_client_sync_v1(p_product jsonb, p_command_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path=public,extensions
AS $function$
DECLARE v_actor uuid:=auth.uid(); v_product bigint; v_occasion bigint;
  v_begin jsonb; v_hash text; v_users uuid[]; v_version bigint; v_expected bigint;
BEGIN
  IF p_product IS NULL OR jsonb_typeof(p_product)<>'object'
    OR octet_length(p_product::text)>524288 THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid product aggregate'; END IF;
  v_product:=NULLIF(p_product->>'id','')::bigint;
  SELECT occasion INTO v_occasion FROM public.client_mutation_receipts WHERE command_id=p_command_id AND actor_id=v_actor AND command_name='inventory.product.save';
  IF NOT FOUND THEN
  IF v_product IS NOT NULL THEN
    SELECT p.occasion INTO v_occasion FROM eshop.products p WHERE p.id=v_product;
  ELSE
    SELECT pt.occasion INTO v_occasion FROM eshop.product_types pt
      WHERE pt.id=NULLIF(p_product->>'product_type','')::bigint;
  END IF;
  END IF;
  IF v_actor IS NULL OR v_occasion IS NULL
    OR NOT public.can_write_orders(v_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='order editor required'; END IF;
  IF jsonb_typeof(p_product->'inventory_contexts')='array' THEN
    p_product:=jsonb_set(p_product,'{inventory_contexts}',coalesce((SELECT jsonb_agg(c ORDER BY (c->>'inventory_context_id')::bigint)
      FROM jsonb_array_elements(p_product->'inventory_contexts') c),'[]')); END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'occasion',v_occasion,'product',p_product)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,
    'inventory.product.save',v_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  IF v_product IS NOT NULL THEN
    SELECT COALESCE(array_agg(DISTINCT ou."user"),'{}'::uuid[]) INTO v_users
    FROM eshop.order_product_ticket opt JOIN public.occasion_users ou
      ON ou.ticket=opt.ticket AND ou.occasion=v_occasion
    WHERE opt.product=v_product;
  ELSE v_users:='{}'::uuid[]; END IF;
  -- Context replacement recalculates allocations: acquire the same outer order
  -- parents before saving a product, never product then order in this command.
  PERFORM public.lock_product_order_dependencies_internal_v1(v_product);
  IF v_product IS NOT NULL THEN
    PERFORM 1 FROM eshop.products WHERE id=v_product AND occasion=v_occasion FOR UPDATE;
    SELECT coalesce(v.version,0) INTO v_version FROM (SELECT 1) seed
    LEFT JOIN public.client_aggregate_versions v ON v.aggregate_type='product'
    AND v.scope_type='occasion' AND v.scope_id=v_occasion AND v.aggregate_id=v_product::text;
    -- Released scalar facades may omit this control until their explicit upgrade gate.
    v_expected:=CASE WHEN p_product ? 'expected_aggregate_version'
      THEN (p_product->>'expected_aggregate_version')::bigint ELSE v_version END;
    IF v_expected IS DISTINCT FROM v_version THEN
      RETURN public.complete_client_mutation_outcome_v1(p_command_id,'conflict',409,
        jsonb_build_object('productId',v_product,'aggregate_version',v_version)); END IF;
  ELSIF p_product->>'expected_aggregate_version' IS NOT NULL THEN
    RAISE invalid_parameter_value USING MESSAGE='new product cannot have expected version';
  END IF;
  v_product:=public.update_product_internal_v1(p_product-'expected_aggregate_version');
  SELECT version INTO v_version FROM public.client_aggregate_versions WHERE aggregate_type='product'
    AND scope_type='occasion' AND scope_id=v_occasion AND aggregate_id=v_product::text;
  RETURN public.complete_private_inventory_mutation_v1(p_command_id,v_occasion,
    'inventory.product.save',jsonb_build_array(jsonb_build_object(
      'entityType','product','entityId',v_product,'operation',
      CASE WHEN p_product->>'id' IS NULL THEN 'insert' ELSE 'update' END,
      'safeLabel',left(p_product->>'title',240),'changedFields',jsonb_build_array(
        'configuration','contexts'))),v_users,jsonb_build_object('productId',v_product,'aggregate_version',v_version));
END; $function$;

-- Source: database/functions/inventory/update_product_inventory_contexts_client_sync_v1.sql
CREATE OR REPLACE FUNCTION public.update_product_inventory_contexts_client_sync_v1(p_product_id bigint, p_contexts jsonb, p_command_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path=public,extensions
AS $function$
DECLARE v_actor uuid:=auth.uid(); v_occasion bigint; v_begin jsonb; v_hash text;
  v_users uuid[]; v_expected bigint; v_version bigint; v_versioned boolean:=false;
BEGIN
  IF jsonb_typeof(p_contexts)='object' THEN
    IF jsonb_typeof(p_contexts->'contexts') IS DISTINCT FROM 'array'
      OR NOT p_contexts ? 'expected_aggregate_version'
      OR EXISTS(SELECT 1 FROM jsonb_object_keys(p_contexts) k WHERE k NOT IN ('contexts','expected_aggregate_version')) THEN
      RAISE invalid_parameter_value USING MESSAGE='invalid context revision envelope'; END IF;
    v_versioned:=true;v_expected:=(p_contexts->>'expected_aggregate_version')::bigint;
    p_contexts:=p_contexts->'contexts';
  END IF;
  SELECT occasion INTO v_occasion FROM public.client_mutation_receipts WHERE command_id=p_command_id AND actor_id=v_actor AND command_name='inventory.product.contexts';
  IF NOT FOUND THEN
  SELECT p.occasion INTO v_occasion FROM eshop.products p WHERE p.id=p_product_id;
  END IF;
  IF v_actor IS NULL OR v_occasion IS NULL OR p_contexts IS NULL
    OR jsonb_typeof(p_contexts)<>'array' OR jsonb_array_length(p_contexts)>1000
    OR octet_length(p_contexts::text)>1048576
    OR NOT public.can_write_orders(v_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='inventory editor required'; END IF;
  SELECT coalesce(jsonb_agg(c ORDER BY (c->>'inventory_context_id')::bigint),'[]') INTO p_contexts FROM jsonb_array_elements(p_contexts) c;
  v_hash:=encode(extensions.digest(convert_to((jsonb_build_object(
    'productId',p_product_id,'contexts',p_contexts) || CASE WHEN v_versioned THEN jsonb_build_object('expectedVersion',v_expected) ELSE '{}'::jsonb END)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,
    'inventory.product.contexts',v_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  IF EXISTS (SELECT 1 FROM jsonb_array_elements(p_contexts) c
      LEFT JOIN public.inventory_contexts ic
        ON ic.id=(c->>'inventory_context_id')::bigint
      LEFT JOIN public.inventory_pools ip ON ip.id=ic.inventory_pool
      WHERE ip.occasion IS DISTINCT FROM v_occasion
        OR COALESCE((c->>'quantity')::integer,0)<0)
 THEN RAISE insufficient_privilege USING MESSAGE='foreign inventory context'; END IF;

  SELECT COALESCE(array_agg(DISTINCT ou."user"),'{}'::uuid[]) INTO v_users
  FROM eshop.order_product_ticket opt JOIN public.occasion_users ou
    ON ou.ticket=opt.ticket AND ou.occasion=v_occasion
  WHERE opt.product=p_product_id;
  PERFORM public.lock_product_order_dependencies_internal_v1(p_product_id);
  PERFORM 1 FROM eshop.products WHERE id=p_product_id AND occasion=v_occasion FOR UPDATE;
  SELECT coalesce(v.version,0) INTO v_version FROM (SELECT 1) seed LEFT JOIN public.client_aggregate_versions v
    ON v.aggregate_type='product' AND v.scope_type='occasion' AND v.scope_id=v_occasion AND v.aggregate_id=p_product_id::text;
  IF v_versioned AND v_expected IS DISTINCT FROM v_version THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'conflict',409,
      jsonb_build_object('productId',p_product_id,'aggregate_version',v_version)); END IF;
  PERFORM public.update_product_inventory_contexts_internal_v1(
    p_product_id,p_contexts);
  RETURN public.complete_private_inventory_mutation_v1(p_command_id,v_occasion,
    'inventory.product.contexts',jsonb_build_array(jsonb_build_object(
      'entityType','product_inventory_context','entityId',p_product_id,
      'operation','update','safeLabel','Product inventory contexts',
      'changedFields',jsonb_build_array('contexts'))),v_users,
    jsonb_build_object('productId',p_product_id,'aggregate_version',v_version+1));
END; $function$;

-- Source: database/functions/eshop_orders/update_scan_code.sql
CREATE OR REPLACE FUNCTION update_scan_code(
    occasion_link TEXT,
    new_scan_code TEXT
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
    v_occasion_id BIGINT;
    occasions_hidden_id BIGINT;
BEGIN
    -- 1. Retrieve occasion_id using occasion_link
    SELECT id
    INTO v_occasion_id
    FROM public.occasions
    WHERE id = public.resolve_occasion_link_internal(occasion_link);

    -- 2. Check if occasion_link is valid
    IF v_occasion_id IS NULL THEN
        RETURN jsonb_build_object(
            'code', 404,
            'message', 'Occasion link does not exist.'
        );
    END IF;

    -- 3. Verify if the user is an editor on the occasion
    IF NOT can_write_orders(v_occasion_id) THEN
        RETURN jsonb_build_object(
            'code', 403,
            'message', 'User is not authorized to edit this occasion.'
        );
    END IF;

    PERFORM 1 FROM public.scanner_settings WHERE scanner_settings.occasion_id=v_occasion_id FOR UPDATE;
    UPDATE public.scanner_settings SET epoch=epoch+1 WHERE scanner_settings.occasion_id=v_occasion_id;
    -- 4. Check if occasions_hidden exists for the occasion
    SELECT o.occasion_hidden
    INTO occasions_hidden_id
    FROM public.occasions o
    WHERE o.id = v_occasion_id;

    IF occasions_hidden_id IS NOT NULL THEN
        -- Update existing scan_code
        UPDATE public.occasions_hidden
        SET secret = new_scan_code
        WHERE id = occasions_hidden_id;
    ELSE
        -- Insert new occasions_hidden record
        INSERT INTO public.occasions_hidden (secret)
        VALUES (new_scan_code)
        RETURNING id INTO occasions_hidden_id;

        -- Update the occasion to link to the new occasions_hidden
        UPDATE public.occasions
        SET occasion_hidden = occasions_hidden_id
        WHERE id = v_occasion_id;
    END IF;

    -- 5. Return a success message
    RETURN jsonb_build_object(
        'code', 200,
        'message', 'Scan code updated successfully.'
    );

EXCEPTION
    WHEN OTHERS THEN
        -- Handle any unexpected exceptions
        RETURN jsonb_build_object(
            'code', 500,
            'message', 'An unexpected error occurred.',
            'detail', SQLERRM
        );
END;
$$;

-- Source: database/functions/user_services/update_service_item_client_sync_v1.sql
CREATE OR REPLACE FUNCTION public.update_service_item_client_sync_v1(p_occasion bigint, p_type text, p_code text, p_title text, p_reference bigint, p_command_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_actor uuid:=auth.uid(); v_begin jsonb; v_hash text; v_result jsonb;
  v_before jsonb; v_after jsonb;
BEGIN
  IF v_actor IS NULL OR p_type NOT IN ('food','accommodation')
    OR nullif(btrim(p_code),'') IS NULL OR length(p_code)>100
    OR length(COALESCE(p_title,''))>500
    OR NOT public.can_write_service_items(p_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='occasion manager required'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'occasion',p_occasion,'type',p_type,'code',p_code,'title',p_title,
    'reference',p_reference)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,
    'occasion.service.update',p_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  SELECT o.services INTO v_before FROM public.occasions o
    WHERE o.id=p_occasion FOR UPDATE;
  v_result:=public.update_service_item_internal_v1(
    p_occasion,p_type,p_code,p_title,p_reference);
  IF COALESCE((v_result->>'code')::integer,500)<>200 THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'rejected',
      404,v_result); END IF;
  SELECT o.services INTO v_after FROM public.occasions o WHERE o.id=p_occasion;
  IF v_before IS NOT DISTINCT FROM v_after THEN
    RETURN public.complete_client_mutation_outcome_v1(
      p_command_id,'unchanged',200,v_result); END IF;
  INSERT INTO public.client_aggregate_versions(aggregate_type,scope_type,scope_id,aggregate_id,version)
  VALUES('occasion','occasion',p_occasion,p_occasion::text,1)
  ON CONFLICT(aggregate_type,scope_type,scope_id,aggregate_id) DO UPDATE
  SET version=public.client_aggregate_versions.version+1,updated_at=clock_timestamp();
  RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,
    'occasion.service.update','configuration',jsonb_build_array(jsonb_build_object(
      'entityType','occasion_service','entityId',p_code,'operation','update',
      'safeLabel',left(p_title,240),'changedFields',jsonb_build_array('services'))),
    ARRAY['occasion_config'],'[]','[]',v_result);
END; $function$
;

-- Source: database/functions/user_services/update_service_item.sql
CREATE OR REPLACE FUNCTION public.update_service_item_internal_v1(oc bigint, type text, code text, new_title text, new_reference bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  updated_services JSONB;
BEGIN

  IF (SELECT can_write_service_items(oc)) <> TRUE THEN
    RETURN jsonb_build_object('code', 403);
  END IF;

  -- Check if the code exists within the specified type
  IF NOT EXISTS (
    SELECT 1
    FROM public.occasions,
         jsonb_array_elements(occasions.services->type) AS item
    WHERE occasions.id = oc
      AND (item->>'code') = code
  ) THEN
    -- If code does not exist, return an error response
    RETURN jsonb_build_object(
      'code', 404,
      'message', 'Service item not found'
    );
  END IF;

  -- Update the specified service item
  updated_services := (
    SELECT jsonb_agg(
      CASE
        WHEN (item->>'code') = code THEN
          item || jsonb_build_object('title', new_title, 'reference', new_reference)
        ELSE
          item
      END
    )
    FROM public.occasions,
         jsonb_array_elements(occasions.services->type) AS item
    WHERE occasions.id = oc
  );

  -- Apply the updated services JSON to the specified type
  UPDATE public.occasions
  SET services = jsonb_set(
    services,
    ARRAY[type],
    updated_services,
    true
  )
  WHERE id = oc;

  -- Return success response
  RETURN jsonb_build_object(
    'code', 200,
    'message', 'Service item updated successfully'
  );
END;
$function$
;

-- Source: database/functions/speakers/update_speaker.sql
-- Legacy partial patch adapter. Omitted fields survive; explicit nullable fields clear.
CREATE OR REPLACE FUNCTION public.update_speaker(p_occasion bigint,p_speaker jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE v_id bigint:=(p_speaker->>'id')::bigint; v_version bigint; v_payload jsonb; r jsonb;
BEGIN
 IF auth.uid() IS NULL OR NOT public.can_write_speakers(p_occasion) THEN
  RETURN jsonb_build_object('code',403); END IF;
 IF v_id IS NOT NULL THEN
  PERFORM 1 FROM public.speakers WHERE id=v_id AND occasion=p_occasion FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('code',404); END IF;
  v_payload:=public.get_speaker_command_data_v1(v_id);
  SELECT coalesce(v.version,0) INTO v_version FROM (SELECT 1) seed
   LEFT JOIN public.client_aggregate_versions v ON v.aggregate_type='speaker'
   AND v.scope_type='occasion' AND v.scope_id=p_occasion AND v.aggregate_id=v_id::text;
 ELSE v_payload:=jsonb_build_object('title','','order',0,'is_hidden',false)||jsonb_build_object('data','{}'::jsonb,'topics','[]'::jsonb); END IF;
 v_payload:=v_payload||p_speaker;
 -- Historical patch API ignores foreign topic IDs and collapses duplicates.
 -- Canonical callers validate their full aggregate strictly.
 IF p_speaker ? 'topics' THEN
  v_payload:=jsonb_set(v_payload,'{topics}',coalesce((SELECT jsonb_agg(t.id ORDER BY t.id)
   FROM public.speaker_topics t WHERE t.occasion=p_occasion AND t.id IN
    (SELECT value::bigint FROM jsonb_array_elements_text(p_speaker->'topics'))),'[]'));
 END IF;
 IF nullif(btrim(v_payload->>'title'),'') IS NULL THEN RETURN jsonb_build_object('code',400); END IF;
 r:=public.save_speaker_client_sync_v1(p_occasion,extensions.gen_random_uuid(),v_version,jsonb_build_object('id',v_payload->'id','title',v_payload->'title','subtitle',v_payload->'subtitle','description',v_payload->'description','image',v_payload->'image','order',v_payload->'order','is_hidden',v_payload->'is_hidden','data',v_payload->'data','topics',v_payload->'topics'));
 RETURN jsonb_build_object('code',r->'code','data',r#>'{data,speaker}');
END $$;

-- Source: database/functions/speakers/update_speaker_topic.sql
